window.HB_TR["ezekiel"]["ks"]=["1.\\tوۅنۍ سپد یہ ترہمہِ ؤریس منز، ژوٗرمہِ ریتس منز، ریتہ کس پٲنژمس دۅہس منز، ییلہ بہٕ {اوس} دریائے چیبر کِس بٹھس پیٹھ قٲدن منز اوسس، {یُس} آسمانن آو یلہٕ تہٕ میہ وچھ خدایہ سند وژن۔ {قیدی: ہیب۔ قید}\n2. ریتہٕ کِس پوٗنٛژمِس {دۄہ} مَنٛز، یُس بادشاہ یہویاچین سٕندِ قٲد گژھنُک پٲنژِم ؤری اوس،\n3.\\tخداوند سُند کلام آو واضح پٲٹھۍ، بوزی سٕندِس نیچوِس پادٕرۍ حزقی ایلس سٍتـ̡ دٔریاوٕ چبار کِس بٔٹھِس سٍتـ̡ چالدانن ہٕندِس سرزمینس مَنٛز۔ تہٕ خداوند سُند اَتھٕ اوس أمِس پیٹھ۔ {حزقی ایل: حب۔ Jehezkel}\n4.\\tتہ میہ وچھ تہ وچھ شمال کِنۍ اکھ واو دراو اکھ بوٚڈ اوبر، تہ اکھ نار دراو پانس اندۍ پکھۍ، تہ اتھ اندۍ پکھۍ اکھ چمک، تہ اتھ منز دراو امبر رنگک رنگ، نارس منز۔ {انفولڈنگ...: ہیب۔ پان رٔٹُن}\n5.\\tتہِ دراو ژۅن جاندارن ہنز شکل۔ تہٕ یہٕ {اوس} تہنز شکل۔ تمن ٲس أکس انسان سٕنٛز شکل۔\n6. تہٕ پریتھ أکِس ٲسۍ ژور بُتھ، تہٕ پرٮ۪تھ أکِس ٲسۍ ژور پَکھ۔\n7.\\tتہٕ تِہندِ کھۅر ٲسۍ سیدِ سیود کھۅر۔ تہٕ یِمن ہٕندٮ۪ن کھۅرن ہُند تُل اوس بَچھرِ ہٕندِس کھورِ ہٕندِس تِلٕکۍ پٲٹھۍچمکان۔ {سید...: ہیب۔ اکھ سیود کھۄر}\n8.\\tتہٕ {تِمَن} ٲسِس ژۅشونی طرفن پَکھہٕ تَل أکِس شخٕص سٕندِس اتھہٕ سٍتـ̡ تہٕ یمن ژۄن ٲسۍ بُتھ تہٕ پنکھ۔\n9.\\tتِہٕندِ پَکھہٕ {ٲس} اکھ أکِس سٍتۍ رٔلِتھ۔ ییلہ تم گٔیہِ نہٕ پھیرۍ۔ تِم گٔیہِ پرٛٮ۪تھ أکِس سیوٚد برٛونٛہہ کُن۔\n10.\\tیِمن ہٕندِس بُتھِس ہُند ہشر اوس یِمن ژۅن ہُند بُتھ تہٕ دٔچھنِس طرفہٕ اوس شیر سُند بُتھ: تہٕ یِمن ژۅن اوس کھوورِ طرفہٕ أکِس بیلُک بُتھ ۔ یمن ژۅشونی تہِ اوس عقاب سُند بُتھ تہِ۔\n11.\\tیتھہ پاٹھۍ ٲسۍ تہند بُتھ تہ پکھہ ٲسۍ ہیرِ کُن پھہلٲوتھ۔ پرٮ۪تھ أکِس {ٲس} زٕ {پَکھ} ٲسۍ اکھ أکِس سٍتۍ رٔلِتھ، تہٕ دۄن ہٕندِس جسمس ؤلِتھ۔ {پھیلاونہٕ آمُت...: یا، ہیرِ کُن تقسیٖم کٔرِتھ}\n12. تہٕ تِم گٔیہِ پرٮ۪تھ أکِس سیوٚد برونہہ کُن: روح کوٚت کُن گژھُن، تِم گٔیہِ تِم گٔیہِ۔ {تہٕ} ییٚلہ تم گٔیہٕ نہٕ پھیرٕ۔\n13.\\tیُتھ زن جاندارن ہٕنزِ شکلہِ ہُند تعلق چھُ، تِہُند ظہور اوس نارٕکۍ دزنہٕ والٮ۪ن ہٕندۍ پٲٹھۍ، {تہٕ} چراغن ہٕندِس ظہورٕکۍ پٲٹھۍ: یہِ اوس جاندارن منز ہیوٚر بۄن گژھان۔ تہٕ نار اوس چمک، تہٕ نارٕ منٛزٕ دراو بجلی درج۔\n14.\\tتہٕ زندٕ مخلوق ژٔلِتھ ژٔلِتھ واپس۔\n15.\\tوۅنۍ ییلہ میہ جاندار وُچھمُت، وُچھ زُوٕ زُوٕ زمینس پیٹھ ژۅن بُتھِن سٍتـ̡ اکھ چکر۔\n16.\\tچکرِ ہُند ظہور تہٕ تِہنز کٲم ٲس بیرل کِس رنگس ہیوٗ تہٕ تِمن ژۅشونی ہٕنز ظاہری شکلہٕ تہٕ تِہنز کٲم ٲس یِتھٕ پٲٹھۍ زِ یہ اوس چکرس منز اکھ چکر۔\n17.\\tییلہ تم گٔیہ، تم گٔیہِ ژۅشونی طرفن کُن: {تہٕ} ییلہ تم گٔیہِ نہٕ پھیرِ۔\n18.\\tیِمن ہٕنزِ وٲج ٲس تِتھۍ تھدِ زِ تِم ٲس خوفناک۔ تہٕ تِہٕندِ وٲج ٲسۍ ژورن اندۍ اندۍ أچھن سٍتۍ بٔرِتھ۔ {تہٕ تہنز حلقہٕ: یا، تہٕ تہنز سٹریکس}\n19.\\tتہٕ ییلہ جاندار گٔیہ، چکرٕ گٔیہِ تِمن نِش: تہٕ ییلہ جاندار زمینہٕ پیٹھٕ تُلنہٕ آیہ، چکرٕ تُلنہٕ۔\n20.\\tروح کُنہِ تہِ گژھُن، تِم گٔیہِ تتہِ گژھُن، تتہِ اوس تِہُند روح گژھُن۔ تہٕ چکر آیہ تِمن خلاف تُلنہٕ: تکیازِ زندٕ مخلوق سُند روح اوس چکرس منز۔ {of...: یا، زندگی ہُند}\n21.\\tییلہ یم گٔیہ، {یِم} گٔیہِ۔ تہٕ ییلہ تم کھڑا گٔیہ، {یِم} کھڑا گٔیہِ۔ تہٕ ییلہ یم زمینہِ پیٹھٕ تُلنہٕ آیہ، چکرٕ آیہ تِمن خلاف تُلنہٕ: تکیازِ زندٕ مخلوق سُند روح اوس چکرس منز۔ {of...: یا، زندگی ہُند}\n22. تہٕ زندٕ مخلوق سٕندِس کلس پیٹھ آسمانچ ہشر ٲس خوفناک کرسٹلک رنگک پٲٹھۍ، یُس تہندِس کلس پیٹھ پھٔہلِتھ اوس۔\n23. تہٕ آسمانس تل ٲسۍ تہند پکھہ سید، اکھ بییِس کُن: پریتھ اکس ٲس زٕ، یُس اتھ طرفہٕ ؤلِتھ اوس، تہٕ پرٮ۪تھ أکِس ٲسۍ زٕ، یُس تتھ طرفہٕ تہندِس جسمس ؤلِتھ اوس۔\n24.\\tتہٕ ییلہ تِم گٔیہِ، مے بوز تِہٕندٮ۪ن پَکھن ہُند شور، بٔڈۍ آبہٕ ہٕندۍ پٲٹھۍ، خداتعالیٰ سٕنز آواز، کتھ باتھہِ ہٕنز آواز، میزبان سٕندِ شورٕکۍ پٲٹھۍ: ییلہ تِم کھڑا گٔیہِ، تِمو تروو پَنٕنۍ پَکھہٕ۔\n25.\\tتہِ ٲس آسمانہ منزہ اکھ آواز یُس تہندِس کلس پیٹھ {اوس}، ییلہ تم کھڑا ٲسۍ، {تہِ} ٲس پنٕنۍ پکھہ ترٲومژ۔\n26.\\tتہٕ آسمانس پیٹھ یُس تہندِس کلس پیٹھ {اوس} تختٕچ شکلہٕ، یُس نیلم کٔنہِ ہُند ظہور اوس، تہٕ تخت کِس شکلس پیٹھ اوس ہشر یتھ پیٹھ ہیرِ کُنہِ انسان سُند ظہور اوس۔\n27.\\tتہ میہ وچھ عنبر رنگ، اتھ اندۍ اندۍ اندۍ نارک ظہور، امۍ سنزن لنگن ہندِ ظہور پیٹھہ تہِ ہیرِ کُن تہ بۅنہ کنہِ تہِ وُچھ میہ یہ نارک ظٲہر تہ اتھ اندۍ گاش۔\n28.\\tیتھے پاٹھۍ چھہ کمانک ظہور یُس رودِ ہندس دۅہس منز اوٚبرس منز آسان چھہ، تتھے پاٹھۍ چھہ اندۍ پکھۍ گاشک ظہور۔ یہِ اوس خداوند سٕندِ جلال ہُند ظہوٗر۔ تہٕ ییلہ میہ یہ وُچھ، بہٕ پیوٚو بُتھِس پیٹھ، تہٕ بوز اَکہِ سٕنز آواز یُس بولان اوس۔","1. تہٕ تٔمۍ ووٚن میہ زِ اے انسان سٕندِس بچے، پننین قدمن پیٹھ کھڑا گژھ تہٕ بہٕ کٔرٕ ژے سٍتـ̡ کتھ کرنہٕ۔\n2. تہٕ روح ژاو میہ اندر ییلہ تٔمۍ میہ سٍتـ̡ کتھ کٔر، تہٕ تھووُن میٲنس قدمن پیٹھ، تہٕ مے بوز سُہ یُس میانہِ سٍتـ̡ کتھ کران اوس۔\n3. تہٕ تٔمۍ ووٚن مے، اے انسانہٕ سٕندِس نیٚچو، بہٕ چُھس ژے بنی اِسرٲیلِس نِش سوزان، أکِس باغی قومس کُن یٔمۍ میانہِ خلاف بغاوت کٔرمٕژ چھِ: تِمو تہٕ تِہندیو مٲلو چھِ از تام میانہِ خلاف زیادتی کٔرمٕژ۔ {قوم: ہیب۔ قوم}\n4.\\tتکیازِ تِم چھہِ گستاخ شُرۍ تہٕ ضدی شُرۍ۔ بہٕ چھُس ژےٚ تِمن نِش سوزان۔ تہٕ تُہۍ گژھِو تِمن وَنُن، یِتھٕ پٲٹھۍ چُھ خداوند خدایہ وَنان۔ {بے باک: ہیب۔ بُتھِ ہُند سخٕت}\n5. تہٕ تِم بوزن، یا کیا تِم برداش، (تکیازِ تِم چھِ اکھ باغی گرٕ،) توتہِ گژھہِ معلوم زِ تِمن مَنٛز چُھ اکھ پیغمبر۔\n6.\\tتہٕ تُہۍ گژھ نہٕ تِمن نِش کھوژُن، تہندِس کلامَس سٍتـ̡ گژھ نہٕ کھوژُن، تہندِس کلامَس سٍتـ̡ گژھ نہٕ کھوژُن، چاہے تِمن سٍتـ̡ تہندِس کلامَس سٍتـ̡ کھوژُھن، تہٕ تِمن ہٕندِس نظرس سٍتـ̡ گژھ نہٕ خوفزدٕ، یێلہِ تہٕ تِمن ہٕندِس نظرس سٍتـ̡ گژھ نہٕ خوفزدٕ، یێلہِ تہٕ تِمن ہٕندِس نظرس سٍتـ̡ گژھ نہٕ خوفزدٕ، یێلہِ تہٕ تِمن ہٕندِس نظرس سٍتـ̡ گژھ نہٕ خوفزدٕ۔ {بریئرز...: یا، باغی}\n7.\\tتہٕ تِمن سٍتـ̡ میٲنۍ کتھ کٔرٕن، چاہے تِم بوزِن یا تِم برداش کرٕن، کیازِ تِم چِھ واریاہ زیادٕ باغی ۔ {زیادٕ...: ہیب۔ بغاوت}\n8.\\tمگر ژے چُھہ یُس بہٕ ژے ونان چُھس بوزُن۔ تَمہِ باغی گرٕکۍ پٲٹھۍ گژھ نہٕ بغاوت کٔرِتھ: پَنُن چُھس کھولُن، تہٕ یُس بہٕ ژے دِوان چُھس کھٮ۪وان۔\n9.\\tتہٕ ییلہ میہ وُچھ، وُچھ، اَکھ اَتھٕ آو میہ کُن سوزنہٕ۔ تہٕ لو، اَتھ منز اوس اَکہِ کتابہِ ہُند رول {اوس}؛\n10. تہٕ تٔمۍ پھٔہلٲو یہ میانہِ برونہہ کُن۔ تہٕ یہٕ اوس {اوس} اندر تہٕ نیبر لیکھنہٕ آمُت: تہٕ {اتہِ} اوس اتھ منز لیکھنہٕ آمُت، ماتم تہٕ ماتم تہٕ افسوس۔","1.\\tبییہِ ووٚن میہ زِ یُس ژے لٔبِتھ کھیوٚو۔ یہ رول کھیوٚو تہٕ گژھ اسرٲیلِس گرس سٍتـ̡ کتھ کرنہٕ۔\n2.\\tتہ میہ کھول پنن چُھ، تہ تمۍ دیت میہ یہ رول کھیوان۔\n3. تہٕ تٔمۍ ووٚن مے اے انسان سٕندِس نیٚچو، پنُن یٔڈ کھٮ۪وان تہٕ پنٕنۍ یٔڈ بٔرِتھ یُس بہٕ ژے دِوان چھُس۔ امہ پتہ کھیوٚو میہ {یہ}؛ تہٕ یہ اوس میٲنس ٲسس منز مٹھاس خٲطرٕ ماچھ ہیو آسان۔\n4. تہٕ تٔمۍ ووٚن مے، اِنسان سٕندِس نیٚچُو، گژھ تہٕ اِسرٲیلِس کِس گرس تام واتناوُن تہٕ تِمن سٍتـ̡ کتھ کٔرٕنـ̡ ۔\n5.\\tتکیازِ ژے چُھہ نہٕ أکِس عجیب کتھ باتھہِ تہٕ سخت زبانہِ ہٕندِس لُکن خٲطرٕ سوزنہٕ آمُت، {بٔلکہ} اسرٲیلِس کِس گرس مَنٛز۔ {of a...: Heb. وُٹھُک سوٚن، تہٕ زبنہِ ہُند گوٚب}\n6.\\tعجیب بول چال تہ سخت زبانۍ ہندین واریاہن لوکن ہندِ خاطرہ چھہ نہ، یہند لفظ ژیہ نہ سمجھ یوان چھہ۔ یقینا، اگر مے ژےٚ تِمن نِش سوزمُت آسہٕ تِم آسہٕ تۅہہِ بوزان۔ {of a...: Heb. وُٹھ سوٚن، تہٕ زبانہِ ہُند گوٚب} {یقینا...: یا، اگر میہ ژیہ سوزمُت آسہ ہا، بیترِ، کیا تِمو آسہ نہٕ تۅہہ بوزمُت؟}\n7. مگر اسرٲیلُک گرٕ چُھہ نہٕ تۅہہِ ہٕنز کتھ بوزان۔ تِکیازِ تِم چِھ نہٕ میانہِ کتھ بوزان: تکیازِ سارِنٕے اِسرٲیلِکۍ گرٕ چِھہ گستاخ تہٕ سخت دِل۔ {بے باک...: ہیب۔ ڈٮ۪کہٕ سختی تہٕ دِلُک سخت}\n8. وچھ مے چُھس تُہند بُتھ تِہندِس بُتھِس سٍتـ̡ مضبوٗط تہٕ تُہند ڈٮ۪کہٕ چُھہ تِہندِس ڈٮ۪کہٕ سٍتـ̡ مضبوٗط کورمُت۔\n9.\\tیِمن ہٕندِس نظرس سٍتۍ گژھ نہٕ خوفزدہ تہٕ نہ گژھ تِمن ہٕندِس نظرس سٍتۍ خوفزد، حالانکہ تِم چھِ اکھ باغی گرٕ ۔\n10. اَمہِ علاوٕ ووٚن تٔمۍ میانہِ سٍتـ̡ یُس بہٕ ژے سٍتـ̡ کتھ کرِ، سُہ چُھہ ژے سٍتـ̡ کٔرِتھ تہٕ بوزُن۔\n11. تہٕ گژھ تِمن نِش قٲد کرنہٕ نِش، پننین لوکن ہٕندِس شُرین نِش، تہٕ تِمن سٍتـ̡ کتھ کرٕن، تہٕ تِمن وَنُن یِتھٕ پٲٹھـ̡ خداوند خدا چُھ فرماوان۔ کیا تِم بوزن، کِنہ تِم برداش۔\n12. اَمہِ پَتہٕ تُل روٝحَن تُل، تہٕ بوز پانس پَتہٕ کُن اکھ بٔڈ دَرٕچ آواز، {وَن}، خداوند سُند جلال گژھہِ تٔمۍ سٕنزِ جایہِ پیٹھ۔\n13.\\t{میہ بوز} تہِ چھہ اکھ أکِس سیتۍ واٹھ دِنہٕ والٮ۪ن جاندارن ہٕندٮ۪ن پکھن ہُند شور تہٕ یِمن خلاف چکرَن ہُند شور تہٕ اکھ زبردست تیز رفتارُک شور۔ {چھوُن: ہیب۔ بوسہ دِنہٕ}\n14. یێمہِ روحن تھوٚد میہ تھوٚد، تہٕ نِیوو بہٕ تلخی سٍتـ̡ پننہِ روحہٕ کِس گرمی سٍتـ̡ مگر خداوند سُند اَتھٕ اوس میٲنس پیٹھ مضبوط۔ {تلخی منز: ہیب۔ کڑوا} {گرمی: ہیب۔ گرم شرارت}\n15.\\tپتہٕ ووت بہٕ تِمن نِش تِمن نِش یُس دریائے چیبر کِس بٔٹھِس منز روزان اوس، تہٕ بہٕ ووت تِمن منز سَتن دۅہن حٲران روزان۔\n16. تہٕ سَتن دۅہن پتہٕ سپُد یہِ سپدِتھ زِ خداوند سُند کلام آو میہ نِش وَنُن،\n17.\\tاِنسان سٕندِس نیچو، مے بنوو ژے اسرٲیلِس گرُک چوکیدار، تێمہِ کِنۍ بوز میانہِ کُنہ\n18.\\tییلہ بہٕ بدکارن ونان چھُس، ژیہ گژھہِ یقینا مرُن۔ تہٕ ژے دِژ نہٕ أمِس تنبیہٕ دِنہٕ، تہٕ نہ کتھ کٔرِتھ بدکارن تٔمۍ سٕنزِ بدکار وتہِ نِش خبردار کرنہٕ خٲطرٕ، تٔمۍ سٕنز زُو بچاونہٕ خٲطرٕ۔ یۅہے بدکار {انسان} گژھہِ پننہِ بدکاری منز مرُن۔ مگر تٔمۍ سُند خون، میہ آسہٕ تۅہہِ ہٕندِس اتھس منز۔\n19.\\tتوتہِ یێلہِ ژے بدکارن خبردار کٔرِو، تہٕ سُہ پنہٕ نِس بدکارس نِش پتھ کُن نیرِ، تہٕ سُہ گژھہِ پننہِ بدکاری سٍتـ̡ مرُن۔ مگر ژے کٔر پنُن روح بچٲومُت۔\n20. دُبارٕ، یێلہِ اَکھ نیک انسان پَنٕنِس نیکی نِش پتھ پھیرِ، تہٕ بےٚ بُنیاد کرِ، تہٕ بہٕ چُھس أمِس برونہہ کُن ٹھوکر تراوُن، سُہ گژھہِ مَرُن: کیازِ ژے چُھہ نہٕ أمِس تنبیہ دِژمٕژ، سُہ گژھہِ پنہٕ نِس گۅنہٕ سٍتـ̡ مَرُن، تہٕ یُس تٔمۍ سٕندِ پاکیزگی سٍتـ̡ یُس تٔمِس کٔرمُت چُھ، سُہ گژھہِ نہٕ یاد تھاونہٕ۔ مگر تٔمۍ سُند خون، میہ آسہٕ تۅہہِ ہٕندِس اتھس منز۔ {نیکی یُس: ہیب۔ نیکی }\n21. بہر حال اگر ژے نیک انسانس خبردار کرِ، زِ نیک گۅناہ چُھ نہٕ کران، تہٕ سُہ چُھ نہٕ گناہ کران، سُہ روزِ یقینا زندٕ، کیازِکہِ أمِس چُھ خبردار کرنہٕ آمُت۔ تہٕ چُھ ژے پنُن روح بچٲومُت۔\n22. تہٕ خداوند سُند اَتھٕ اوس میہ پیٹھ۔ تہٕ تٔمۍ ووٚن مےٚ، ووٚتھ، میدانس مَنٛز گژھ تہٕ بہٕ کَرٕ تتہِ ژے سٍتـ̡ کتھ کرنہٕ۔\n23. اَمہِ پَتہٕ ووٚتھ، تہٕ ووت میدانس مَنٛز، تہٕ وُچھ، خداوند سُند جلال اوس اَتہِ کھڑا یُس میہ چبار کِس دریاوس نِش وُچھمُت اوس، تہٕ بہٕ پیوٚو پننِس بُتھِس پیٹھ۔\n24.\\tتێلہِ گۆو روح میٲنس اندر اژُن، تہٕ تھووُن میہ پننین قدمن پیٹھ، تہٕ کوٚرُن میہ سٍتـ̡ کتھ تہٕ وونُن، گژھ پنُن پان پنہٕ نِس گرس منز بند۔\n25. مگر اے انسان سٕندِس نیٚچو، وُچھ تِم ژےٚ پٲٹھۍ، تہٕ تِمن سٍتـ̡ بندھ، تہٕ تُہۍ گژھِ نہٕ تِمن مَنٛز نیرُن:\n26.\\tتہٕ بہٕ کٔرٕ چانۍ زبان چانہِ ٲسِس چھتس سٍتـ̡ ژٔٹِتھ تہٕ تِمن ہٕندِ خٲطرٕ گژھ نہٕ ملامت کٔرِتھ، تکیازِ تِم چھِ اکھ باغی گرٕ۔ {اکھ ریلیفورن: ہیب۔ اکھ انسان ملامت کران}\n27. مگر یێلہِ بہٕ ژے سٍتـ̡ کتھ کرٕن، بہٕ کَرٕ تُہُند بوش تہٕ تِمن وَنُن، یِتھٕ پٲٹھـ̡ خداوند خدا چُھ فرماوان۔ یُس بوزان چُھ، سُہ بوزُن۔ تہٕ یُس صبر کرِ، سُہ گژھہِ برداش: کیازِ تِم چھِ اکھ باغی گرٕ۔","1. توے تہِ، انسان سٕندِس نیٚچو، پانس برونہہ کُن تھووُن اکھ ٹائل، تہٕ اتھ پیٹھ تراوُن شہر، {حتیٰ کہ} یروشلم:\n2. تہٕ اتھ خلاف کرُن محاصرہٕ، تہٕ اتھ خلاف اکھ قلعہ بناوُن، تہٕ اتھ خلاف تراوُن پہاڑ۔ اَتھ خٕلاف تہِ تھٲوِو خٲمٕ، تہٕ اَتھ اندۍ پکھۍ کٔرِو {بَٹِرِنگ} کٔرِتھ۔ {بیٹرِنگ...: چیف لیڈرز}\n3. امہِ علاوٕ نِیُن پانس نِش اکھ ششتٕرُک پین، تہٕ اتھ تھٲوِو پانس تہٕ شہرس درمِیان ششتٕرٕچ دیوار، تہٕ اتھ کُن تھووُن پنُن بُتھ، تہٕ یِیہِ یِیہِ محاصرٕ کرنہٕ، تہٕ تُہۍ کٔرِو اَتھ گھیرٕ کرنہٕ۔ یہِ آسہِ اَکھ نشانہٕ یُس اِسرٲیلِس کُن آسہِ۔ {an...: یا، اکھ فلیٹ پلیٹ، یا، سلائس}\n4. تہٕ پَنٕنِس کھوورِ طرفہٕ تہٕ کٔرِو اِسرٲیلِیُک گُناہ اَتھ پٲٹھۍ، یِمن دۅہن مُطٲبِق یِمن دۅہن تہٕ یِمن ہٕندِس گُناہ سٍتـ̡ دِیُو۔\n5. تکیازِ مے چُھہ تِہٕندِس بدکارٕکۍ ؤری دۅہن ہٕندِ تعدادٕ مطٲبق تریہ ہتھ نتھ دۅہن ہٕندِ حسابہٕ تہٕ تِمن ہٕندِس گناہ ہٕندِس عٔلمہٕ سٍتـ̡ تہٕ تِمن ہٕندِس گُناہ سٍتـ̡ تہٕ تِمن ہٕندِس گُناہ سٍتـ̡ دِژمٕتـ̡ ۔\n6. تہٕ یێلہِ ژے یِم پوٗرٕ کٔرِو، دُبارٕ پَنٕنِس دٔچھنِس طرفہٕ لٔگِتھ، تہٕ ژٕ پۯاوٕ یہوداہ کِس گرٕچ بدکاری ژتٲجی دۅہہٕ: مے چُھہ ژے أکِس ؤریس خٲطرٕ پرٮ۪تھ دۅہہٕ مقرر کورمُت۔ {پرٮ۪تھ کُن...: ہیب۔ ؤری خٲطرٕ اکھ دۄہ، ؤری خٲطرٕ اکھ دۄہ}\n7. تێمہِ کِنۍ گژھ توے پنُن بُتھ یروشلم کِس محاصرس کُن تھووُن، تہٕ پنٕنۍ نٔر گژھہِ نِش نیرنہٕ، تہٕ تێہہ کرٕ اتھ خلاف پیشن گوئی۔\n8. تہٕ وُچھِتھ بہٕ ژے پیٹھ لٔگِتھ لٔگِتھ تہٕ ژے کٔرِو نہٕ اَکہِ طرفہٕ بییِس طرفہٕ پھیرٕن، یوتام نہٕ ژے پنٕنۍ محاصرٕکۍ دۅہ ختم کرِ۔ {اکہ پیٹھ...: ہیب۔ چانہِ طرفہٕ چُھہ پننہِ طرفہٕ\n9.\\tکٕنٕک، جو، پھلۍ، دال، تہٕ باجرا تہٕ پھپھ تہٕ أکِس بانس مَنٛز تھووُن تہٕ اَمہ سٍتـ̡ بٔنِتھ بٔنِتھ، یێلہِ دۅہن ہٕندِس تعدادس مُطٲبق یێلہِ تہٕ تُہۍ کٔرِو تریہ ہتھ نَمتھ دۅہہٕ کھٮ۪وان۔ {فِچس: یا، ہجہٕ}\n10.\\tتہٕ تُہند ماز یُس ژے کھٮ۪وان چُھہ، سُہ گژھہِ وزنہٕ سٍتـ̡ وُہ شیکل دوہس سٍتـ̡ کھٮ۪نہٕ۔\n11.\\tژیہ پییہ آب تہِ پییُن، ہِنُک شیٚیِم حصہٕ۔\n12.\\tتہٕ ژے کھیوٚو یہِ وَشکہٕ کِس پٲٹھۍ، تہٕ تِمن ہٕندِس نظرِ برونہہ کُن نیرن وٲلِس گُہرس سٍتـ̡ بینہٕ۔\n13. تہٕ خداوند ووٚن زِ یِتھٕ پٲٹھـ̡ گژھن بنی اسرٲیلـ̡ غیر قومن مَنٛز پنُن ناپاک روٹی کھٮ۪ن، یێلہِ بہٕ تِمن کُن کڈِ۔\n14. اَمہِ پَتہٕ ووٚن مے، اے خدا! وچھ میون روح چُھ نہٕ آلودہ گومُت: تکیازِ پننہ جوانی پیٹھٕ وُنیُک تام چُھس نہٕ مے سُہ کھیوٚمُت یُس پانس نِش مران چُھ، یا ٹُکرٕ ٹُکرٕ چُھس پھٹمُت۔ نہ آو میٲنس ٲسس منز مکروہ ماز تہِ۔\n15.\\tاَمہِ پتہٕ ووٚن میہ زِ مے چُھس ژے گاو ہُند گُبر انسانہٕ سٕندِ گُرِ خٲطرٕ دِژمُت، تہٕ ژٕ کٔرِکھ اَمہ سٍتۍ پنٕنۍ روٹی تیار۔\n16. بییہِ ووٚن تٔمۍ مے، اِنسان سٕندِس نیٚچو، وُچھ بہٕ یروشلمس مَنٛز روٹی ہُند لاٹھہٕ پھُٹراوُن، تہٕ تِم کھیون وزن سٍتـ̡ تہٕ احتیاط سان۔ تہٕ تِم چِھ پیمائش کٔرِتھ آب چیوان، تہٕ حیرانگی سٍتۍ:\n17. تاکہ تِم گژھن روٹی تہٕ آب یژھان، تہٕ اکھ أکِس سٍتـ̡ حیران گژھن، تہٕ پننہِ بدکاری ہٕندِ خٲطرٕ کھٮ۪نہٕ۔","1.\\tتہٕ ژے اِنسان سٕندِس نیچو، نٲیدٕ سُند ریزر رٔٹِتھ تہٕ پانس کَلس تہٕ داڑھس پیٹھ تراوُن، تہٕ تُہۍ رٔٹِو توازنہٕ تہٕ کٔرِو مَس بٲگراونہٕ۔\n2.\\tشہرس منز گژھہِ تریم حصہٕ نارٕ سٍتۍ زالُن، ییلہ محاصرٕکۍ دۅہ پورٕ گژھن: تہٕ تریم حصہٕ نِیُن، تہٕ تریم حصہٕ کرُن شراپہٕ سٍتۍ، تہٕ تریم حصہٕ ژیہ ہوہس منز پھٔہلِتھ۔ تہٕ بہٕ کٔڑٕ تِمن پتہٕ تلوار۔\n3.\\tتُہۍ تہِ کٔرِو تِمن ہٕندِس تعدادس منز کینہہ تہِ نِن، تہٕ یِم لٲگِتھ پنہٕ نِس لباسس منز۔ {سکرٹس: ہیب۔ ونگس}\n4.\\tیِم دُبارٕ نِتھ نارس مَنٛز تراوُن تہٕ نارس مَنٛز زالُن۔ {تکیازِ} اَمہِ سٍتـ̡ گژھہِ سارِنٕے اِسرٲیلِس مَنٛز نار دِنہٕ۔\n5. یِتھٕ پٲٹھـ̡ چُھ خداوند خدا فرماوان۔ یہِ {چُھ} یروشلم: مے چُھ یہِ قومن تہٕ ملکن مَنٛز قٲیم کورمُت یِم اتھ اندۍ پٔکھۍ چھِ۔\n6.\\tتہٕ تٔمۍ بدلٲوۍ میانہِ فٲصلن قومن کھوتہٕ زیادٕ بدکاری، تہٕ میانین قونونن چھِ تِمو مُلکو کھوتہٕ زیادٕ بدکار بنوومت، تکیازِ تِمو چُھ میانین فٲصلن تہٕ میانین قونونن نِش انکار کورمُت، تِمو چُھ نہٕ تمن منز پکان ۔\n7. تێمہِ کِنۍ چُھ خداوند خدا یِتھٕ پٲٹھۍ وَنان۔ تکیازِ تۅہہ کٔر تمن قومن کھوتہ زیادٕ ضرب یُس پانس اندۍ پکھۍ چھہِ، {تہٕ} چُھہ نہٕ میانین قونونن منز پٔکۍمٕتۍ، نہ چُھکھ میٲنۍ فیصلہٕ مطٲبق عمل کورمُت، تہٕ نہ چُھکھ تمن قومن ہٕندِس فیصلن مطٲبق یُس تۅہہِ اندۍ پکھۍ چِھہ؛\n8. تَمہِ کِنۍ چُھ خداوند خدا یِتھٕ پٲٹھۍ وَنان۔ وُچھِو، بہٕ تہِ چُھس ژے خلاف، تہٕ قومن ہٕندِس نظرس منز کرٕ ژے درمیان فیصلہٕ۔\n9. تہٕ بہٕ کَرٕ ژے سٍتـ̡ سُہ یُس نہٕ میہ کورمُت چُھ، تہٕ یێمہِ سٍتـ̡ بہٕ چُھس نہٕ یِتھُے کٔرِتھ، تہٕ یێلہِ تہٕ بہٕ تہٕ یِتھٕ پٲٹھۍ کٔرِتھ تہٕ تێلہِ سارِنٕے مُشکِلَن ہٕندِ وجہ سٍتـ̡\n10. تێمہِ کِنۍ گژھن باپ تہٕ نیچو کھٮ۪ن تہٕ نیچو کھٮ۪ن پننین مٲلن کھٮ۪ن۔ تہٕ بہٕ کٔرٕ ژے سٍتـ̡ فیصلہٕ، تہٕ ژے سٍتـ̡ سارِنٕے ہواہن مَنٛز پھٔہلِتھ بہٕ\n11. یێمہِ کِنۍ چُھس بہٕ زندٕ روزان، خداوند خدا چُھ فرماوان۔ پٔزۍ پٲٹھۍ، کیازِ ژے چُھہ پنٕنـ̡ سارِنٕے ناپسندیدٕ چیزو سٍتـ̡ تہٕ پنٕنـ̡ سارِنٕے ناپاک سٍتـ̡ میانہِ مقدس مقامس ناپاک کورمُت، تێلہِ کٔرٕ بہٕ تہٕ ژے کم کرنہٕ۔ نہ گژھہِ میانہِ اچھ تہ نہ گژھہِ میہ کانہہ رحم۔\n12.\\tتۅہہِ ہُند تریم حصہ گژھہِ وبا سٍتـ̡ مرُن، تہٕ قحط سٍتـ̡ گژھہِ تۅہہِ سٍتـ̡ ژٔلِتھ تہٕ تریم حصہٕ گژھہِ ژے اندۍ پکھۍ تلوار سٍتـ̡ پییہِ۔ تہٕ بہٕ ترٛیٚیِم حصہٕ سارنٕے ہواہن منٛز پھٔہلِتھ، تہٕ بہٕ کٔڑٕ تِمن پتہٕ تلوار۔\n13. یِتھٕ پٲٹھـ̡ گژھہِ میون غصہٕ ختم تہٕ بہٕ کرٕ پنُن غصہٕ تِمن پیٹھ آرام تہٕ بہٕ روزِ تسکین تہٕ تِمن گژھہِ پتاہ زِ میہ چُھہ خداوندِ پننہِ جوشس سٍتـ̡ کتھ کٔرمٕژ، یێلہِ بہٕ تِمن منز پنُن غصہٕ پورٕ کورمُت۔\n14.\\tامہِ علاوہ کٔرٕ بہٕ ژے ضایع تہٕ تِمن قومن مَنٛز اکھ ملامت یِم تۅہہِ اندۍ پٔکھۍ چھِ، سارِنٕے یِمن ہٕندِس نظرس منز۔\n15.\\tیێلہِ آسہِ یہِ تۅہہِ اندۍ پکھۍ یِمن قومن ہٕندِ خٲطرٕ اکھ ملامت تہٕ طعنہٕ، اکھ ہدایت تہٕ حیرانگی ہٕندِس سٍتـ̡ یێلہِ بہٕ ژے سٍتـ̡ غصہٕ تہٕ غصہٕ سٍتـ̡ تہٕ غصہٕ سٍتـ̡ تہٕ غصس سٍتـ̡ تہٕ غصہٕ سٍتـ̡ تہٕ غصہٕ سٍتـ̡ تہٕ غٲلب ملامت کٔرِتھ فیصلہٕ دِنہٕ۔ میہ چُھہ خداوند کتھ کٔرمٕژ۔\n16.\\tییلہ بہٕ تِمن پیٹھ قحطٕکۍ بد کار تیر سوزِ، یُس تِمن ہٕندِس تباہی خٲطرٕ آسہِ، یُس بہٕ ژے تباہ کرنہٕ خٲطرٕ سوزِ، تہٕ بہٕ کرٕ ژے پیٹھ قحطہٕ ہُریر، تہٕ تُہند روٹی پھُٹراوُن:\n17. یِتھے پٲٹھۍ سوزٕ بہٕ ژےٚ قحط تہٕ بد کار درندٕ، تہٕ تِم کرِ ژےٚ غم۔ تہٕ وبا تہٕ خوُن گژھہِ ژے منز۔ تہٕ بہٕ اَننہٕ ژےٚ تلوار۔ میہ چُھہ خداوند کتھ کٔرمٕژ۔","1. تہٕ خداوند سُند کلام آو میہ نِش،\n2. اِنسان سٕندِس بُتھِس کُن کٔرِو پَنُن بُتھ اِسرٲیلِس کُن تہٕ تِمن خلاف پیشن گویی کٔرِو،\n3. تہٕ وَنُن، اے اسرٲیلٕکۍ پہاڑ، خداوند خدا سُند کلام بوزو۔ یِتھٕ پٲٹھۍ چُھ خداوند خدایہ پہاڑن تہٕ بالن تہٕ دریاوَن تہٕ وادین کُن فرماوان۔ وچھ بہ، {حتیٰ کہ} بہٕ، اَنہٕ ژےٚ پیٹھ تلوار، تہٕ بہٕ کرٕ چانہِ تھدِ جاے تباہ۔\n4. تہٕ تُہٕندِ قربان گاہ گژھن ویران تہٕ تُہٕنزِ شکلہٕ یِن پھُٹراونہٕ، تہٕ بہٕ ترٛاوٕ تُہند مارنہٕ آمُت {انسان} تہٕ تہندٮ۪ن بتن برونہہ کُن۔ {تصویٖرٕ: یا، آفتاب تصویٖرٕ}\n5. تہٕ بہٕ تراوٕ بنی اسرٲیلن ہٕنزِ لاشہٕ تِہندِ بُتن برونہہ کُن۔ تہٕ بہٕ کٔرٕ چانۍ أڈجہ چانہِ قربان گاہن اندۍ پکھۍ۔ {lay: Heb. دِو}\n6. تُہٕندِس سارِنٕے مکانَن مَنٛز گژھن شہر تباہ کرنہٕ تہٕ تھدِ جایہِ گژھن ویران کرنہٕ۔ یُتھ زن تُہند قربان گاہ گژھن تباہ کرنہٕ تہٕ ویران کرنہٕ، تہٕ تُہند بُت گژھن پھُٹراونہٕ تہٕ بند کرنہٕ، تہٕ تُہند مجسمہٕ گژھن ژٹنہٕ، تہٕ تہنز کٲم گژھن ختم کرنہٕ۔ {تصویٖرٕ: یا، آفتاب تصویٖرٕ}\n7. تہٕ مقتول گژھہِ توے منز، تہٕ ژیہ گژھہِ معلوم زِ بہٕ چُھس خداوند ۔\n8.\\tتوتہِ تراوٕ بہٕ اکھ باقی، یُس قومن منز تلوار نِش بچِتھ روزِ، ییلہ تم ملکن منز پھٔٹِتھ گژھِ۔\n9. تہٕ یُس تہٕ یُس ژلہٕ نِش ژلان چُھ، تِمن قومن مَنٛز یێلہِ تِم قٲد کرنہٕ یِن، کیازِ بہٕ چُھس تِہٕندِس بدکار دِلس سٍتـ̡ پھُٹمُت، یُس میانہِ نِش ژٔلِتھ چُھ، تہٕ تِمن ہٕنزِ أچھن سٍتـ̡ یُس تِمن بُتن ہٕندِس پَتہٕ پَتہٕ کٔرِتھ چُھ، تہٕ تِمن ہٕندِس بُرِس سٍتـ̡ یِم تِمن سارِنٕے بُرِین سٍتـ̡ کٔرِمٕژ چھِ۔\n10.\\tتہٕ تِمن گژھہِ معلوم زِ بہٕ چُھس خداوند چُھس، {تہٕ یہ} چُھس نہٕ بیکار ووٚنمُت زِ بہٕ کرٕ تِمن سٍتـ̡ یہِ بُرٕ کٔرِتھ۔\n11. یِتھٕ پٲٹھـ̡ چُھ خداوند خدا فرماوان۔ پنہٕ نِس اَتھٕ سٍتـ̡ لٔج تہٕ کھورِ سٍتـ̡ ٹھپہٕ دِیُو، تہٕ وَنُن زِ اِسرٲیلِس ہٕندِس گرٕ سٍتـ̡ سارِنٕے بد کار گٔیہِ! تِکیازِ تِم گژھن تلوار سٍتۍ، قحطہٕ سٍتۍ، تہٕ وباہن سٍتۍ۔\n12. یُس دوٗر آسہِ سُہ مَرُن وُپھٕ سٍتـ̡ تہٕ یُس نزدیکی آسہِ سُہ گژھہِ تلوار سٍتۍ پیوٚو۔ تہٕ یُس روزِ تہٕ یُس محاصرٕ آسہِ سُہ گژھہِ قحط سٍتۍ مرُن: یِتھٕ پٲٹھۍ کٔرٕ بہٕ تِمن پیٹھ پنُن قہر پورٕ۔\n13. تیلہِ گژھہِ ژیہ پتاہ زِ بہٕ چُھس خداوند آسان، یێلہِ تِہٕندِس مارنہٕ آمٕژ {انسان} آسہِ تِہندین قربان گاہن اندۍ اندۍ اندۍ اند، پرٮ۪تھ تھدِ بالس پیٹھ، بالن ہٕندِس سارنٕے تینتٲلِس پیٹھ، تہٕ پرٮ۪تھ سبز کُلِس تلہ تہٕ پرٮ۪تھ گٔنِس کُلِس تل، سُہ جاے ییتہِ تِمو پننین سارِنٕے بُتن مٔٹھۍ مزہ دِوان آسہِ۔\n14. یِتھے پٲٹھۍ کٔرٕ بہٕ تِمن پیٹھ پنُن اتھٕ پھٔہلٲوِتھ، تہٕ زمینہٕ ویران بناوُن، ہاں، دبلتھس کُن بیابان کھۅتہٕ زیادٕ ویران تہٕ تِمن گژھہِ معلوم زِ بہٕ چُھس خداوند ۔ {مزید ...: یا، بیابان نِش ویران گژھُن}","1. اَمہِ علاوٕ آو خداوند سُند کلام میانہِ نِش وَنُن،\n2. یێلہِ چُھہ یێلہِ خداوند خداوند اسرٲیلِس سٍتـ̡ ونان چُھہ؛ اکھ اند، اختتام چُھ زمینہٕ کِس ژۄن کونن پیٹھ یوان۔\n3. وۅنۍ چُھہ ژے پیٹھ ٲخر، تہٕ بہٕ تراوٕ ژے پیٹھ پنُن غصہٕ، تہٕ کرٕ تۅہہِ ہٕندِس طریقس مطٲبق فیصلہ تہٕ تہٕ کرٕ تۅہہِ سارِنٕے بد عملن ہُند بدلہٕ۔ {معاوضہ: ہیب۔ دِو}\n4. تہٕ میٲنۍ أچھ تراوِ نہٕ ژے تہٕ نہ کرٕ میہ رحم تہٕ، مگر بہٕ کٔرٕ چانہِ وتہِ ہُند بدلہٕ، تہٕ تۅہہِ گژھہِ پتاہ زِ بہٕ چُھس خداوند چُھس۔\n5. یِتھٕ پٲٹھـ̡ چُھ خداوند خدا فرماوان۔ اکھ بُر، اکھ بُر، وُچھِو، آو آمُت۔\n6. اَکھ اَکھ اِنتِظام چُھ، اَکھ اِنتِظام چُھہ آمُت: سُہ چُھہ تُہٕندِس خٲطرٕ وُچھان۔ وچھو یہ آو آمُت۔ {وچھو: ہیب۔ بیدار گژھُن}\n7. اے زمینس منز روزن وٲلۍ، صبحُک ووت ژے نِش، مصیبت ہُند دۅہ آو نزدیک، تہٕ پہاڑن ہُند دُبارٕ چُھہ نہٕ۔ {آواز...: یا، گونج}\n8. وۅنۍ کٔرٕ بہٕ جلدے ژے پیٹھ پنُن قہر تہٕ ژے پیٹھ پنُن غصہٕ پورٕ، تہٕ بہٕ کرٕ تۅہہِ ہٕندِس طریقس مطٲبق فیصلہ تہٕ تہٕ کرٕ ژے سارِنٕے ناپسندیدگی ہُند بدلہٕ۔\n9. تہٕ میٲنۍ أچھ روزِ نہٕ رحم، تہٕ نہ گژھہِ میہ رحم: بہٕ دِیہ ژے چانہِ طریقو مُطٲبق تہٕ تۅہہِ ہٕندِس مُطٲبق تہٕ تۅہہِ ہٕندِس مُطٲبق بدلہٕ۔ تہٕ ژیہ گژھہِ پتاہ زِ بہٕ چُھس خداوند یُس ماران چُھ۔ {تم مطٲبق: ہیب۔ توے پیٹھ، وغیرہ}\n10. وُچھو دۅہہ، وُچھِو، سُہ چُھ آمُت: صُبح چُھہ نیران۔ لٔر پھوٚلۍ، غرور چھُ پھوٚلمُت۔\n11. تشدد چُھ بدکاری ہٕندِس لٔرِس مَنٛز وۅتھنہٕ آمُت: یِمو منزٕ گژھِ نہٕ کانہہ تہِ روزُن، نہ تِمن ہٕندِس بٔڑِس سٍتـ̡ تہٕ تِمن ہٕندِس کُنہِ تہِ سٍتـ̡ روزُن۔ {تِہُند: یا، تِہُند ہنگامہ خیز شخص: ہیب۔ ہنگامہ آرائی}\n12.\\tوق آو آمُت، دۅہ آو نزدیک: خٔریٖدارس گژھہِ نہ خۅش گژھُن، تہٕ نہ کٕنَن وول گژھہِ ماتم کٔرِتھ، تکیازِ سارِنٕے بٔڈِس پیٹھ چھُ قہر {چُھ}۔\n13.\\tتکیازِ کٕنُن وول گژھِ نہ تتھ چیزس کُن واپس، یُس کٕننہٕ آمُت آسہِ، یُس نہٕ وُنہِ تہِ زندٕ آسہِ، تکیازِ وژنُک {چُھ} سارِنٕے بٔڈِس سٍتۍ واپس، {یُس} واپس۔ نہ کرِ کانہہ تہِ پننہِ زندگی ہنزِ بدکاری منز پانس مضبوط۔ {حالانکہ تم ...: ہیب۔ حالانکہ تہنز زندگی ٲس وُنہِ تہِ زندن منز} {منز...: یا، یمۍ سٕنز زندگی تٔمۍ سٕندِس بدکارس منز} {بدکاری: ہیب۔ تٔمۍ سٕنٛز بدکاری }\n14.\\tتِمو چُھ سارِنٕے تیار کرنہٕ مۅکھہٕ بُنیاد دِژمُت۔ مگر کانہہ تہِ چھہ نہ جنگس منز گژھان: تکیازِ میون قہر چھہ سارِنٕے بٔڈس پیٹھ۔\n15.\\tتلوار {چُھ} نیبر، تہٕ وبا تہٕ قحطس اندر: یُس {کھہَر} چُھہ سُہ تلوار سٍتـ̡ مرُن۔ تہٕ یُس شہرس مَنٛز چُھ، قحط تہٕ وبا چُھ أمِس کھٮ۪وان۔\n16.\\tمگر یِمو نِش ژلنہٕ یِنہٕ وٲلِس سٍتـ̡ گژھن تہٕ وادی ہٕندِس کۅترَن ہٕندۍ پٲٹھۍ، سارِنٕے گژھن پننہِ بدکاری ہٕندِ خٲطرٕ ماتم کَران۔\n17.\\tسارِنٕے اَتھٕ گژھن کمزور تہٕ سارِنٕے کۅٹھہٕ گژھن کمزور۔ {کمزور گژھُن...: ہیب۔ آبس منز گژھو}\n18.\\tتِم تہِ لٔگِتھ تہٕ وحشت کرِ تِمن ؤلِتھ۔ تہٕ سارِنٕے بُتھِس پیٹھ گژھہِ شرم تہٕ سارِنٕے کلَن پیٹھ گنج۔\n19. تِم گژھن سڑکن مَنٛز رۄپہٕ تراوُن، تہٕ تِہُند سۄنہٕ یِن ہُند رۄپہٕ تہٕ سۄنہٕ خداوند سٕندِ قہر کِس دۅہہٕ سٍتـ̡ تِمن ہٕندِس رۄپہٕ سٍتـ̡ نجات دِتھ، تِم ہێکہِ نہٕ پَنٕنـ̡ رۄپہٕ تہٕ سٍتـ̡ بٔرِتھ، تِکیازِ یہِ چُھہ تِہٕنزِ بدکٲری ہُند رُکاوٹ۔ {ہٹاونہٕ آمُت: Heb. جدایی خٲطرٕ، یا، ناپاکی} {یہٕ چُھ...: یا، تہنز بدکاری چِھ تہنز ٹھوکر}\n20.\\tیوٚت تام تٔمۍ سٕندِس زیورٕچ خوبصورتی ہٕنز کتھ چھ، تٔمۍ کٔر سُہ شاندارس منز، مگر تِمو بنٲو تِمن ہٕندِس مکروہ چیزن ہٕنز شکلہٕ، تہٕ اَتھ مَنٛز بَنوو تِمن ہٕندِس مکروہ چیزن ہٕنز شکلہٕ، تێلہِ چھُ مے یِمن نِش دوٗر تھوومُت۔ {یہ دور سیٹ کٔرتھ...: یا، بنوو تمن خٲطرٕ اکھ ناپاک چیز}\n21. تہٕ بہٕ دِیہٕ یہِ شکارٕ خٲطرٕ اَپرٮ۪ن ہٕندِس اتھس منز، تہٕ دِیہٕ زمینہٕ کِس بدکارس لوُٹنہٕ خٲطرٕ۔ تہٕ تم کرن اتھ آلودہ۔\n22.\\tمیون بُتھ تہِ چھُس تِمن نِش پھیُر، تہٕ تِم کٔرِن میون راز {جاے} آلودہ کرنہٕ، تکیازِ ڈاکو گژھن اَتھ منز اژان تہٕ اتھ ناپاک کٔرِن۔ {ڈاکو: یا، چور}\n23.\\tزنجیر بناوُن: تکیازِ زمین چھیہ خونریز جُرمو سٍتۍ بٔرِتھ تہٕ شہر چھہ تشددٕ سٍتۍ بٔرِتھ۔\n24. اَمہِ مۄکھٕ بہٕ اَننہٕ بدترین کافر، تہٕ تِمن ہٕندِس گرس پیٹھ قبضہ کرُن: بہٕ کرٕ طاقتورن ہٕنز شان و شوکت تہِ بند کرنہٕ۔ تہٕ تِہٕنزِ مُقدس جاے یِن ناپاک کرنہٕ۔ {تِہُند مُقدس...: یا تِم گژھن پنٕنۍ مقدس مقامن ہٕندِس وٲرثس منز}\n25. تباہی چھے یوان۔ تہٕ تِم گژھن امن ژھارن، تہٕ {تتہِ آسہِ نہٕ}۔ {تباہی: ہیب۔ کَٹُن کَرُن}\n26. شرارت گژھہِ شرارت تہٕ افواہ گژھہِ افواہ پیٹھ۔ اَمہ پتہٕ گژھن تِم پیغمبر سُند وژن ژھاران۔ مگر شریعت گژھہِ پادٕرۍ سٕندِ نِش ختم، تہٕ پرانین ہٕندِ مشورٕ دِنہٕ۔\n27.\\tبادشاہ گژھہِ ماتم تہٕ شہزادٕ گژھہِ ویرٲنی ہٕندِس پلوس سٍتـ̡ تہٕ زمینہٕ کین لوکن ہٕندِ اتھہٕ گژھہِ پریشان: بہٕ کرٕ تِمن سٍتـ̡ تہنزِ وتہِ پَتہٕ تہٕ تہندِ صحرا مطٲبق بہٕ تِمن ہُند فیصلہ کرُن۔ تہٕ تِمن گژھہِ پتاہ زِ بہٕ چُھس خداوند ۔ {مطٲبق...: ہیب۔ تہندٮ۪ن فٲصلن سۭتۍ}","1. تہٕ یہ سپُد شیٚیِمہِ ؤریس منز، شیٚیِمہِ ریتس مَنٛز، ریتہٕ کِس پٲنژمِس دۅہس مَنٛز، یێلہِ بہٕ بِہتھ پننِس گرس مَنٛز، تہٕ یہوداہٕکۍ زِٹھۍ بِہتھ بِہتھ تہٕ خداوند خدایہ سُند اَتھٕ آو میٲنس پیٹھ۔\n2.\\tاَمہ پتہٕ وُچھ میہ نارُک ظہور ہیوٗ ہِش تہٕ تٔمۍ سٕندِس کمرس ہٕندِس ظہوٗر سٍتـ̡ بۄن کُن نار۔ تہٕ تٔمۍ سٕنزِ کمرہ پیٹھٕ تہِ ہیوٚر کُن، چمکُک ظٲہر ہٕندۍ پٲٹھۍ، عنبر رنگک پٲٹھۍ۔\n3.\\tتہٕ تٔمۍ کٔر اَتھٕچ شکلہٕ تہٕ رٔٹِتھ میٲنِس کلہٕ کِس تالہٕ سٍتۍ۔ تہٕ روحن تُل میہ زمینس تہٕ آسمانس درمِیان تہٕ واتنوو میہ خدایہ سٕندِس وژنس منز یروشلمس منز، أنٛدرِم دروازٕ کِس دروازس تام یُس شمالس کُن وچھان چُھ۔ یتہِ {اوس} حسدٕچ تصویرٕچ نشست، یُس حسدُک پٲدٕ کران چھُ۔\n4. تہٕ وُچھِو، اسرٲیلِکِس خدایہِ سُند جلال اوس تَتہِ یُس میہ میدانس مَنٛز وُچھمُت اوس۔\n5. تمہ پتہ ووٚن میہ اے انسان سٕندِ فرزند، پنٕنۍ أچھ تُلِو وۅنۍ شمالس کُن وتہِ۔ چنانچہ میہ تُل پننۍ اچھ شمالس کُن تہ وچھن شمالس کُن قربان گاہ کس دروازس پیٹھ حسدچ یہ تصویر۔\n6.\\tتٔمۍ ووٚن میہ تہِ زِ یێلہِ چُھہ تِم کیا کران چھِ؟ {حتیٰ کہ} یُس بٔڈ مکروہ یُس اسرٲیلُک گرٕ یێتہِ کران چُھ، یُس بہٕ پَنُن مقدس مقامہٕ نِش دوٗر گژھُن؟ مگر بییہِ پھیُر، {تہٕ} وُچھِو توے بٔڈۍ بٔڈۍ گۅنم وُچھان۔\n7.\\tتہٕ سُہ أنۍ میہ دربار کِس دروازس پیٹھ۔ تہٕ ییلہ میہ وچھ دیوارس منز اکھ سوراخ۔\n8.\\tاَمہِ پتہٕ ووٚن میہ اے انسانہٕ سٕندِس نیچو، دیوارس مَنٛز کھٔنِتھ تہٕ ییلہ میہ دیوارس منز کھٔنِتھ وُچھمُت چھُ، وُچھُن اکھ دروازٕ۔\n9.\\tتہٕ تٔمۍ ووٚن میہ اژُن، اژُن تہٕ وُچھِو یِم بدکار بد کار یِم تِم یَتہِ کران چھِ۔\n10.\\tتہ میہ وُچھ اندر تہ وُچھمُت۔ تہٕ وُچھِو پرٮ۪تھ قٕسمٕچ نژٕنۍ چیز، تہٕ مکروہ درندٕ، تہٕ اِسرٲیلٕکۍ گرٕ سٕندِ سارِنٕے بُت، یِم اندۍ پٔکھۍ دیوارس پیٹھ تراونہٕ آمٕتۍ۔\n11. تہٕ تِمن برونہہ کنہِ ٲسۍ اسرٲیلِکۍ گرٕ کِس پرانہِ ہٕندِس ستتھ نفر کھڑا تہٕ یِمن منز اوس شافان سُند نیچو جازنیاہ کھڑا تہٕ پرٮ۪تھ أکِس اتھس منز پنُن باوُر ہیتھ ۔ تہٕ اگربُک اکھ گوٚٹ اوٚبر ووٚتھ تھوٚد۔\n12.\\tتێلہِ ووٚن میہ زِ اے انسان سٕندِس نیچو، کیا ژے وُچھمُت زِ اسرٲیلِکۍ گرٕ قدیم کیا چِھ انہِ گٹہِ منز کران، پرٮ۪تھ کانہہ انسان چُھ پننہِ تصویرن ہٕندِس کمرس مَنٛز؟ تِکیازِ تِم چھِ ونان زِ خداوند چُھ نہٕ اسہِ وُچھان۔ خداوند چُھ زمینہٕ ترٲومُت۔\n13.\\tتٔمۍ ووٚن میہ تہِ، ژے پھیُر بییہِ اکہِ لٹہِ، {تہٕ} ژے وُچھکھ امہِ کھوتہٕ زیادٕ مکروہ یُس تِم کران چھِ۔\n14.\\tتێلہِ اوٚن میہ رب سٕندِس گرٕ کِس دروازس پیٹھ یُس شمالس کُن اوس۔ تہٕ وچھ زنانہٕ بِہتھ تموز خٲطرٕ روان ٲس۔\n15.\\tاَمہِ پتہٕ ووٚن تٔمۍ مےٚ وُچھمُت، اے انسان سٕندِس نیٚچوِس کیا وُچھمُت؟ بییہِ پھیُر، {تہٕ} وُچھِو یِمو کھۅتہٕ زیادٕ بٔڈۍ مُکرِ۔\n16. تہٕ سُہ أنۍ میہ خداوند سٕندِس گرٕ کِس اندرمِس آنگنس مَنٛز، تہٕ وُچھ خداوند سٕندِس مندرٕ کِس دروازس پیٹھ، برآمدس تہٕ قربان گاہس درمِیان ٲس تقریباً پانژھ تہٕ وُہ نفر، یِمن ہٕنز پٔٹھۍ رب سٕندِس مندرس کُن تہٕ مشرقس کُن بُتھ ٲسۍ۔ تہٕ تِم ٲسۍ مشرقس کُن آفتابٕچ پوجا کران۔\n17.\\tاَمہ پتہٕ ووٚن میہ زِ ژے چھُکھ وُچھمُت، اے انسان سٕندِس نیٚچوِس؟ کیا یہوداہ کِس گرس خٲطرٕ چھا یہِ ہلکہٕ چیز زِ تِم چھِ یِم مکروہ کٲم کران یِم تِم یتہِ کران چھِ؟ تکیازِ تِمو چُھ زمینہٕ تشدد سٍتۍ بٔرِتھ، تہٕ چھِ میہ شرارت دِنہٕ خٲطرٕ واپس آمٕتۍ: تہٕ لو، تِمو تھوو لنجہِ پننہِ نَسس پیٹھ۔ {یہِ چھا...: یا، کیا ارتکاب کرنہٕ کھوتہٕ چھَا کانٛہہ ہلکہٕ چیز}\n18.\\tتێلہِ کٔرٕ بہٕ تہِ غصہٕ سٍتـ̡ سٍتـ̡ میٲنۍ أچھ تہٕ نہ رحم، تہٕ یێلہِ تہٕ یێلہِ تہٕ یِم میانین کنن منز بَڑِ آوازٕ سٍتـ̡ چُھہ وَنُن، {توتہِ} بہٕ چُھس نہٕ تِمن بوزان۔","1.\\tتٔمۍ ووٚن میانین کنن منز تہِ بَڑِ آوازِ سٍتـ̡ وۆنُن، یِمن شہرس پیٹھ قبضہ چُھ، تِمن ہٕندِس نزدیک، حتیٰ کہ پرٮ۪تھ أکِس انسانس تہٕ تٔمۍ سٕندِس اتھس منز تباہ کرن وول ہتھیار تہِ۔\n2.\\tتہٕ وچھ شیہ نفر دراو تھزرِ دروازہ کِس وتہِ پیٹھ، یُس شمالس کُن چھُ، تہٕ پرٮ۪تھ أکِس شخصس اتھس منز ذبح کرنُک ہتھیار اوس۔ تہٕ تِمو منزٕ اوس اکھ شخٕص کُنہِ کُنہِ لٔگِتھ لٔگِتھ، تہٕ تِم گٔیہِ اَندٕر، تہٕ کھڑا برٛیسن قربان گاہس نِش۔ {یُس لیتھ: ہیب۔ یُس بدلاونہٕ آمُت چُھ} {اکھ ذبح...: ہیب۔ تٔمۍ سُند پھُٹُن ہُند اکھ ہتھیار} {بذریعہ تٔمۍ سٕند...: ہیب۔ تٔمۍ سٕندِس کمرس پیٹھ}\n3. تہٕ اسرٲیلِکِس خدایہِ سُند جلال آو کروبس پیٹھٕ ہیوٚت، ییمہِ پتہٕ سُہ گرٕ کِس دروازس تام ووت۔ تہٕ تٔمۍ بُلوو کُن لٲگِتھ نفرس یُس ادیبُک سیاہی سیتۍ اوس۔\n4. تہٕ خداوند ووٚن أمِس شہرس منز، یروشلمس منز، تہٕ تِمن نفرن ہٕندِس ڈیکس پیٹھ اکھ نشان تھاوُن یِم آہ چُھ کران تہٕ یِمن سارِنٕے مکروہ عملن ہٕندِ خٲطرٕ فریاد کران چھِ۔ {اکھ نشان سیٹ کٔرتھ: ہیب۔ نشان زد کٔرِو}\n5.\\tتہٕ باقین وون میانہِ بوزنس منز، تم گژھ أمس پتہٕ شہرس منز، تہٕ مارُن: پنٕنۍ أچھ گژھ نہٕ تراوٕن، تہٕ نہ گژھ تۅہہ رحم کٔرتھ: {میون بوزُن: ہیب۔ ماین کَن}\n6.\\tبُزرگ تہٕ بُزرگ تہٕ لۄکٹۍ شُرۍ تہٕ زنانہٕ مارُن، مگر کٲنٛسہِ تہِ شخصس نِش گژھِو نہٕ یٔمِس نشانہٕ آسہِ۔ تہٕ میانِس مقدس مقامس پیٹھ شروع کٔرِتھ۔ پتہٕ گٔیہٕ تِمو قدیم نفرن نِش شروع یِم مکانس برونہہ کُن ٲسۍ۔ {بلکل: ہیب۔ تباہی کُن}\n7.\\tتہٕ تٔمۍ ووٚن تِمَن گرٕ ناپاک کٔرِتھ، تہٕ مَردَن سٍتـ̡ بٔرِتھ بٔرِتھ: نیرِو نٮ۪بر۔ تہٕ تِم گٔیہِ درٛاو تہٕ شہرس منٛز مارٕ۔\n8.\\tتہٕ سپُد یێلہِ تِم تِم ماران ٲسۍ، تہٕ بہٕ گۆو بُتھِس پٲٹھۍ، تہٕ وۆنُن، اے خدا! کیا ژٕ کٔرِکھ یروشلمس پیٹھ پننہِ غصہٕ سٍتـ̡ پننہِ قہر سٍتـ̡ اسرٲیلُک سورُے باقیات تباہ کٔرِتھ؟\n9.\\tتێلہِ وۆنُن میہ زِ اسرٲیلِس تہٕ یہوداہ کِس گرس سٍتـ̡ چُھہ زیادٕ زیادٕ، تہٕ زمین چُھ خونہٕ سٍتـ̡ بٔرِتھ تہٕ شہر چُھہ بدکاری سٍتـ̡ بٔرِتھ، تِکیازِ تِمن ہُند وَنُن چُھ، خداوند چُھ زمینہٕ ترٲومُت، تہٕ خداوند چُھ نہٕ وُچھان۔ بٔرِتھ، وغیرہ} {بد اخلاقی: یا، فیصلہٕ کِس کشمکش}\n10.\\tتہِ میانہِ اچھ تہِ چھیہ نہ رحم کٔرتھ، نہ گژھہِ میہ رحم تہِ، {مگر} تہندِس کلس پیٹھ تہنزِ وتہِ بدلہٕ دِنہٕ۔\n11.\\tتہٕ وُچھِتھ یُس کُنہِ {رپورٹ...: ہیب۔ لفظ دیت واپس}","1.\\tامہ پتہ وچھ میہ تہ وچھ تتھ آسمانس منز یُس کروبن ہندس کلس پیٹھۍ اوس، تمن پیٹھ نمودار گوو یُس نیلم کنہِ اوس، تخت ہٕندِس شکلہِ ہٕندۍ پٲٹھۍ۔\n2.\\tتہٕ تٔمۍ کٔر کُنہِ کُنہِ شخژس سٍتـ̡ تہٕ وونُن، چکرَن درمِیان گٔژِھتھ تہٕ پَنُن اَتھٕ بٔرِتھ کٔرِو کرُبِمَن منزٕ نارٕ سٍتـ̡ بٔرِتھ، تہٕ پَنُن اَتھٕ بٔرِتھ کٔرِو شہرس مَنٛز پھٔہلِتھ۔ تہٕ سُہ گوٚو میانہِ نظرِ منٛز۔ {تُہند اتھ: ہیب۔ چانہِ اتھہ ہند کھوکھر}\n3.\\tوۅنۍ اوس کرُبِم مکانہٕ کِس دٔچھنِس طرفہٕ کھڑا، ییلہ یہِ نفر اژان اوس۔ تہٕ اوٚبرن بٔرِتھ اندرم صحن۔\n4. پتہٕ ووت خداوند سُند جلال کروبس پیٹھ، {تہٕ کھڑا} گرٕ کِس دروازس پیٹھ۔ تہٕ گرٕ اوس اوٚبرٕ سٍتـ̡ بٔرِتھ، تہٕ دربار اوس خداوند سٕندِ عظمتٕچ گاشہٕ سٍتـ̡ بٔرِتھ۔ {ہیوٚت: ہیب۔ تُلنہٕ آمُت}\n5.\\tتہٕ کرُبن ہٕندٮ۪ن پَکھن ہٕنز آواز ٲس نیبرِمِس صحنس تام بوزنہٕ آمٕژ، یِتھ کٔنۍ سُہ کتھ کران چھُ۔\n6.\\tتہٕ سپُد یہِ سپُد، {یہ} ییلہ تٔمۍ کُن پوشہٕ لٲگِتھ نفرس حکم دِیُت، وونُن زِ چکرَن منز، کرُبِمَن درمِیان نار نِش نِش امہ پتہ گوٚو سہ اندر تہ کھڑا چکرس نش کھڑا۔\n7.\\tتہٕ {اَکہ} کروبن ترووُن پَنُن اَتھٕ کُن یُس کرُبِمَن درمِیان اوس، تہٕ رٔٹِتھ {یہ} تہٕ تھووُن {یہ} سٕندِس اتھس مَنٛز، یُس کُنہِ {پھٔلِتھ: ہیب۔ سوزنہٕ آمُت}\n8.\\tتہٕ کرُبن منز گٔیہِ تِمن ہٕندِس پکھَن تَل انسان سٕندِ اَتھٕچ شکل ظٲہِر۔\n9.\\tتہٕ ییلہ میہ وُچھ، وُچھ ژۅن چکرَن ہٕندِس ژۅن چکرَن سٍتۍ، اَکھ چکرٕ أکِس کربس سٍتۍ، تہٕ بییِس چکرَس سٍتـ̡ تہٕ چکرَن ہُند ظہور اوس بیرل کٔنہِ ہُند رنگ۔\n10.\\tتہٕ یِمن ہٕندِس ظاہری شکلہٕ سٍتـ̡ اوس یِمن ژۅشونی ہٕندِس ہشرس منز، یِتھہٕ پٲٹھۍ چکرِ ہٕندِس درمِیان آسہِ۔\n11.\\tییلہ تم گٔیہ، تم گٔیہِ ژۅشونی طرفن پیٹھ۔ تِم پھیرۍ نہٕ یِتھ کُنہِ جایہِ کُن کُن یُس کلہٕ وُچھان اوس۔ تِم گٔیہِ نہٕ پھیُر یُتھ تِم گٔیہِ۔\n12.\\tتہٕ تِہُند سورُے جسم، تہٕ تِہُند کمر، تہٕ تِہٕندِس پکھہٕ تہٕ پکھہٕ تہٕ چکرٕ، {حتیٰ کہ} اچھن سٍتۍ بٔرِتھ، {حتیٰ کہ} تِمن ژۅن ہٕندِس چکرس منز۔ {جسم: ہیب۔ ماز}\n13.\\tچکرِ ہُند تعلق اوس، یہ اوس میانہِ بوزنس منز تمن ووننہٕ آمُت، اے چکر۔ {یہ اوس...: یا، تِم ٲسۍ میانہِ سماعتس منز وُننہٕ آمٕتۍ، وہیل، یا، گلگل}\n14.\\tتہٕ پریتھ أکِس بُتھ اوس ژور بُتھ: گۄڈنیُک بُتھ اوس اِنسان سُند بُتھ، تہٕ تریم بُتھ اوس شیر سُند بُتھ، تہٕ ژوٗرِم بُتھ اوس عقاب سُند بُتھ۔\n15. تہٕ کروبِم تُلِتھ تُلنہٕ۔ یہٕ {چُھ} سُہ زندٕ مخلوق یُس مے چیبار کِس دریاوس نکھٕ وُچھمُت۔\n16.\\tتہٕ ییلہ کروبِم گٔیہِ، چکرِ گٔیہِ تِمن نِش تہٕ ییلہ کرُبِمو پَنٕنۍ پَکھہٕ تُلِتھ زمینہٕ پیٹھٕ کھسنہٕ خٲطرٕ، یِمو چکرٕ تہِ گٔیہِ نہٕ یِمن سٍتـ̡ پھیرٕ۔\n17.\\tییلہ تم کھڑا ٲسۍ، {یِم} کھڑا گٔیہِ۔ تہٕ ییلہ تِم تُلِتھ تُلِتھ، {یِم} تُلِتھ تُلِتھ تہِ: تِمن منز اوس زندٕ مخلوق سُند روح {اوس}۔ {of...: یا، زندگی ہُند}\n18.\\tاَمہِ پَتہٕ دراو خداوند سُند جلال گرٕ کِس دروازٕ پیٹھٕ تہٕ کھڑا گٔیہِ کروبِمَن پیٹھ۔\n19. تہٕ کروبِمو تُلِتھ پَنٕنۍ پَکھہٕ تہٕ تھوٚد میانہِ نظرِ منز زمینہٕ پیٹھٕ کھسنہٕ: ییلہ تِم نیبر گٔیہِ، چکرٕ تہِ ٲسۍ تِمن سٍتـ̡ تہٕ {پرٮ۪تھ کُن} اوس خداوند سٕندِس گرٕ کِس مشرقی دروازٕ کِس دروازس پیٹھ کھڑا ۔ تہٕ تِمن پیٹھٕ اوس اسرٲیلِکِس خدایہِ سُند جلال {اوس}۔\n20. یہِ چُھ سُہ زندٕ مخلوق یُس مے اسرٲیلِس خداہس تل چبار کِس دریاوس نِش وُچھمُت۔ تہٕ میہ ٲس پتاہ زِ تم ٲسۍ کروبیم۔\n21.\\tپریتھ اکس ٲسۍ ژور بُتھ تہ پریتھ اکس ژور پکھ۔ تہٕ انسان سٕندِ اتھن ہٕنز شکلہٕ ٲس تہندِس پکھس تل۔\n22.\\tتہٕ تِمن ہٕندِس بُتھِس ہِش یِم میہ چیبر کِس دریاوس نِش وُچھمٕتۍ، تِمن ہٕنزِ شکلہٕ تہٕ پانہٕ: تِم ٲسۍ پرٮ۪تھ أکِس سیوٚد برونہہ کُن۔","1.\\tامہِ علاوہ تُل روح میہ تھوٚد، تہٕ ووت میہ خداوند سٕندِس گرٕ کِس مشرقی دروازس کُن، یُس مشرقس کُن نظر چُھ، تہٕ وُچھِن دروازٕ کِس دروازس پیٹھ پانژٕ تہٕ وُہ نفر۔ یِمن مَنٛز وُچھ میہ عذر سُند نیچو جازنیاہ تہٕ بنیاہ سُند نیچو پیلاتیا، لوکن ہٕندِس شہزادس منز۔\n2. اَمہِ پتہٕ ووٚن تٔمۍ مےٚ، اِنسانہٕ سٕندِس نیٚچو، یِم چھِ یِم یَتھ شہرس مَنٛز شرارت کران چھِ، تہٕ بدکار مشورٕ دِوان چھِ:\n3.\\tیُس ونان چھہِ {یہ} چھہ نہ نزدیک۔ اسہِ بناوو مکانہٕ: یہِ {شہر} چُھ کیلڈرون، تہٕ أسۍ {بٔنِو} ماز۔ {یہِ چھُ...: یا، نزدیکی مکانہٕ بناوُن چھُنہٕ سانہِ خٲطرٕ}\n4.\\tتێلہِ کٔر تِمن خلاف پیشن گوئی، اے انسان سٕندِس نیٚچو۔\n5. تہٕ خداوند سُند روح آو میہ پیٹھ، تہٕ وونُن میہ کتھ کرُن؛ یِتھٕ پٲٹھۍ چُھ خداوند فرماوان۔ یِتھٕ پٲٹھـ̡ چُھہ تۅہہ ووٚنمُت، اے اِسرٲیلِیُک گھر، تِکیازِ بہٕ چُھس تُہٕندِس ذہنس مَنٛز یِنہٕ وٲلِس چیزس پتاہ چُھس۔\n6.\\tیَتھ شہرس مَنٛز چُھہ پَنُن مارُن ہُند تعداد بٔرِمُت، تہٕ تُہۍ چھِو اَمہ کِس سڑکہٕ مَرنہٕ والیو سٍتـ̡ بٔرِتھ بٔرِمٕژ۔\n7. تێمہِ کِنۍ چُھ خداوند خدا یِتھٕ پٲٹھۍ وَنان۔ یُس تۅہہ اتھ منز مارۍ مٲرۍ، تم چھہِ ماز تہ یہ شہر چھہ کلڈرن، مگر بہٕ کڈٕ ژیہ منزہ نیبر۔\n8.\\tتلوارِ ہُند خوف چھُ۔ تہٕ بہٕ اَنہٕ ژےٚ پٮ۪ٹھ تلوار، خداوند خدا چُھ وَنان۔\n9. تہٕ بہٕ کٔرٕ ژےٚ اَمہِ منزٕ نٮ۪بر تہٕ ژےٚ غٲر لوٗکن ہٕندِس اتھس مَنٛز، تہٕ کرٕ تۅہہِ درمیان فٲصلہٕ عمل۔\n10.\\tتلوار سٍتـ̡ پۯاوٕنـ̡ بہٕ کٔرٕ تُہند فیصلہ اسرٲیلِس کِس سرحدس پیٹھ۔ تہٕ ژیہ گژھہِ پتاہ زِ بہٕ چُھس خداوند ۔\n11. یہِ {شہر} گژھِ نہٕ تُہُند ماز بٔنِتھ تہٕ نہ گژھِ تُہُند ماز بٔنِتھ۔ {مگر} بہٕ کٔرٕ تُہند فیصلہ اسرٲیلِس کِس سرحدس منز:\n12. تہٕ ژے گژھہِ پتاہ زِ بہٕ چُھس خداوند چُھس: کیازِ ژے چُھہ نہٕ میانین قونونن مُطٲبق پٔکِتھ، تہٕ نہ چُھکھ میٲنۍ فٲصلن پیٹھ عمل کورمُت، بلکہ چُھکھ پانس اندۍ پکھۍ کُنہِ کُلِس سٍتـ̡ آداب کٔرِتھ۔ {تۅہہِ خٲطرٕ...: یا، یُس نہٕ پکان چُھ}\n13.\\tتہٕ سپُد ییلہ میہ پیشن گویی کٔر زِ بنیاہ سُند نیچو پیلتیا سپُد مُرد۔ اَمہِ پَتہٕ پیوٚو بہٕ بُتھِس پٲٹھۍ، تہٕ وَنُن بَڑِ آوازٕ سٍتـ̡ تہٕ وونُن، اے خدایہ! کیا ژٕ کٔرِو اسرٲیلِچ باقیات پوٗرٕ پٲٹھۍ؟\n14. دُبارٕ آو خداوند سُند کلام میانہِ نِش، یُس وَنُن چُھ،\n15.\\tانسان سٕندِ نیٚچُو، تُہٕندِس بٲے تہٕ تُہٕندِس بٲے تہٕ تُہٕندِس رِشتہٕ سٍتـ̡ تہٕ سارِنٕے اِسرٲیلِس سٍتـ̡ یِمن یروشلِمٕکۍ بسکیٖنو وَنُن چُھ، یێلہِ ہُند دوٗر گژھُن، یێمہِ زمینہٕ چُھہ اسہِ دِنہٕ آمُت۔\n16. تێمہِ کِنۍ ونو خداوند خدا چُھ یِتھٕ پٲٹھۍ فرماوان۔ حالانٛکہِ مے چھِ تِم دوٗر کُلٮ۪ن مَنٛز ترٛٲومٕتۍ، تہٕ حالانٛکہِ مے چھِ یِم مُلکن مَنٛز پھٔٹِمٕتۍ، توتہٕ بہٕ روزٕ تِمن مُلکن مَنٛز اکھ لۄکٕٹ پناہ گاہٕ۔\n17. تێمہِ کِنۍ وَنُن زِ خداوند چُھ یِتھٕ پٲٹھـ̡ وَنان۔ بہٕ کَرٕ تۅہہ لُکن نِش تہِ جمع تہٕ تِمن ملکَن نِش جمع کٔرِتھ ییتہِ تہٕ ژےٚ چھِو بٔنِتھ تہٕ بہٕ دِیہٕ ژے اسرٲیلٕچ زمین۔\n18. تہٕ تِم یِن تتہِ یِن، تہٕ تِم نِن اَمہِ کِس سارِنٕے ناپسندیدٕ چیز تہٕ تِمن ہٕنزِ سارِنٕے ناپاک کُن نِنہٕ۔\n19. تہٕ بہٕ دِیہ تِمن اکھ دِل، تہٕ بہٕ تراوٕ ژے اندر اکھ نۆو روح۔ تہٕ بہٕ کٔرٕ تِہٕندِ مازٕ منزٕ کٔنہِ دِل تہٕ دِیہ تِمن مازُک دِل:\n20. یُتھ تِم میانین قونونن مُطٲبق پٔکِتھ، تہٕ میٲنۍ احکام برقرار تھاون، تہٕ تِم گژھن میٲنۍ لوک، تہٕ بہٕ بنہٕ تِہُند خدا۔\n21.\\tمگر یێمہِ سُند دِل چُھہ تِمن ہٕندِس ناپسندیدٕ چیزن تہٕ تِمن ہٕنزِ ناپسندیدگی ہٕندِس دِلس پَتہٕ پکان چُھ، بہٕ کٔرٕ تِمن ہٕنزِ وتہِ ہُند بدلہٕ، خداوند خدا چُھ فرماوان۔\n22.\\tاَمہِ پتہٕ تُلِتھ پَنٕنہِ پَکھہٕ تہٕ پَکہٕ تُلِتھ پَنٕنہِ پَکھہٕ۔ تہٕ تِمن پیٹھٕ اوس اسرٲیلِکِس خدایہِ سُند جلال {اوس}۔\n23.\\tتہٕ خداوند سُند جلال ووت شہرٕ کِس وسطہٕ پیٹھ، تہٕ ووت تتھ پہاڑس پیٹھ یُس شہر کِس مشرقس کُن چُھ۔\n24.\\tاَمہِ پَتہٕ نِیوو میہ روٝحہِ خدایہِ سٕندِ روٝحہِ سٍتـ̡ چالدیاہس مَنٛز، یِمن ہٕندِس قید کِس نِش۔ تہ یُس وژن میہ وچھمت اوس، سہ گوٚو میہ نش تھوٚد۔\n25. تێمہِ پَتہٕ کٔر میہ تِمن سٍتـ̡ قٲد کرنہٕ کِس بارس مُتعلِق کتھ یِم خداوند میہ ہٲومٕژ ٲس۔","1. خداوند سُند کلام تہِ آو میہ نِش،\n2.\\tانسان سٕندِس فرزندس منز روزُن چھُکھ أکِس باغی گرس مَنٛز روزان، یُس وُچھُن تہٕ وُچھُن چھُنہٕ یِوان۔ تِمن چِھ بوزنہٕ خٲطرٕ کَن، تہٕ بوزنہٕ خٲطرٕ چِھ نہٕ: کیازِ تِم چِھ اکھ باغی گرٕ۔\n3. تێمہِ کِنۍ، اے انسانہٕ سٕندِس نیٚچو، تُلنہٕ خٲطرٕ تیار کرُن، تہٕ دۅہہٕ کٔرِو تِمن ہٕندِس نظرس نِش ہٹاوُن۔ تہٕ تُہۍ گژھِو پننہِ جایہِ پٮ۪ٹھٕ تِمن ہٕنزِ نظرِ منز بییِس جایہ نِش نیرُن، یہ ہیکہِ تِم غور کٔرِتھ، حالانکہ تِم اکھ باغی گرٕ آسن۔ {چیز: یا، آلات}\n4.\\tتیلہِ کٔرِو تِمن ہٕندِس نظرس منز پنُن سامان تِمن ہٕندِس نظرِ برونہہ کُن نیرُن، تہٕ تِمن ہٕندِس نظرس منز تہِ نیرُن، یِتھٕ پٲٹھۍ یِمن قٲدس منز نیران چھُ۔ {یتھ کٔنۍ تِم...: ہیب۔ یِتھ کٔنۍ زَن قید کِس برونٛہہ کُن}\n5.\\tتِمن ہٕنزِ نظرِ منز کٔرِو دیوار کھٔنِتھ تہٕ اَمہ سٍتـ̡ کٔرِو نِنہٕ۔ {ڈگ...: ہیب۔ ژیہ کھٔنِتھ کٔرِو}\n6.\\tتِہٕندِس نظرس مَنٛز تھاوُن تہٕ تُہٕندِس پھیکس پیٹھ تُلُن، تہٕ تُہٕندِس بُتھِس پٲٹھۍ، یێلہِ نہٕ ژے زمین وُچھِو، تێکیازِ مے چُھہ ژے اِسرٲیلِس کِس گرس خٲطرٕ اکھ نشانی مقرر کٔرمٕژ۔\n7.\\tتہٕ مے کٔر یُتھ میہ حکم دِنہٕ آمُت اوس، بہٕ کٔر دۅہہٕ پنُن سامان قٲد کرنہٕ خٲطرٕ تہٕ یێلہِ تہِ کٔر میہ دیوارس منز پننہ اتھہٕ سٍتـ̡ کھٔنـ̡ ۔ میہ اوٚن شفقس منز {یہ} نیبر، {تہٕ} بہٕ چھُس {یہ} تِمن ہٕندِس نظرس منز {پننِ} پھیکس پیٹھ۔ {کھٔنِتھ: ہیب۔ میہ خٲطرٕ کھودنہٕ آمُت}\n8. تہٕ صُبحَس آو خداوند سُند کلام میانہِ نِش وَنُن،\n9. اِنسان سٕندِس اَسٍتـ̡ چُھہ نہٕ اِسرٲیلِیُک گرٕ یُس باغی گرٕ چُھہ ژے ووٚنمُت، تێہہ کیا چُھہ؟\n10.\\tتِمن وَنُن چُھہ یِتھٕ پٲٹھـ̡ خداوند خدا چُھ وَنان۔ یہِ بار چُھ یروشلمس مَنٛز شہزادٕ سٕندِس تہٕ تِمن مَنٛز سارِنٕے اِسرٲیلِس سٍتـ̡\n11.\\tونُن، بہٕ چُھس تُہند نشانہٕ: یِتھٕ پٲٹھۍ میہ کورمُت، تِتھے پٲٹھۍ گژھہِ تِمن سٍتـ̡ کرنہٕ: تِم گژھن قید کرنہٕ۔ {تِم...: ہیب۔ ہٹٲوِتھ گٔژھِو قیدَس مَنٛز}\n12.\\tتہٕ یُس شہزادہ یُس تِمن منزٕ چُھہ یُس شفقس منز پننِس پھیکس پیٹھ تھپھ کٔرِتھ، تہٕ نیرِ نیرُن: تِم کرِ دیوارس منز کھٔنِتھ تہٕ سُہ کرِ پنُن بُتھ تھپھ، یُتھ نہٕ سُہ زمین وُچھِتھ زِ سُہ چُھ نہٕ اچھو سٍتـ̡ زمینہٕ وُچھان۔\n13. بہٕ تہٕ بہٕ پھٔہلِتھ أمِس سٍتـ̡ تہٕ سُہ ییہِ میٲنِس جالس مَنٛز رٔٹنہٕ: تہٕ بہٕ اَننہٕ سُہ بابل کِس سرزمینس مَنٛز۔ توتہِ گژھہِ نہ سہ وچھان، حالانکہ سہ گژھہِ تتہِ مرُن۔\n14.\\tتہٕ بہٕ پھٔہلِتھ پرٮ۪تھ واو کُن یُس أمِس تہٕ تٔمۍ سٕندِس سارِنٕے بندن ہٕندِس مددٕ خٲطرٕ چھُ۔ تہٕ بہٕ کٔڑٕ تِمن پتہٕ تلوار۔\n15. تہٕ تِمن گژھہِ معلوم زِ بہٕ چُھس خداوند چُھس، یێلہِ بہٕ تِم قومن مَنٛز پھٔہلِتھ تہٕ تِمن مُلکن مَنٛز منتشر کرِ۔\n16. مگر بہٕ تراوٕ تِمو منزٕ کینہہ نفر تلوار، قحط نِش تہٕ وباہن نِش۔ یُتھ زن تِم کافرن مَنٛز پنٕنۍ تمام مکروہ آسنُک اعلان کٔرِتھ یُس تِم یِم یِوان چھِ۔ تہٕ تِمن گژھہِ پتاہ زِ بہٕ چُھس خداوند ۔ {کینہہ ...: ہیب۔ مرد آف نمبر}\n17.\\tامہِ علاوہ آو رب سُند کلام میہ نِش وونُن،\n18.\\tانسان سٕندِس پَنٕنـ̡ روٹی کھیوٚو تہٕ پَنُن آب چُھہ تھرتھر تہٕ احتیاط سٍتـ̡ پییُن۔\n19.\\tتہٕ وَنُن زِ یِتھٕ پٲٹھـ̡ یروشلم کین بسکینن ہُند خداوند خدا، {تہٕ} اسرائیل کِس سرزمینُک خدا۔ تِم گژھن پنٕنۍ روٹی احتیاط سان کھٮ۪ن، تہٕ پنُن آب چیٚنہٕ حیرانگی سٍتۍ، یُتھ زن تٔمۍ سٕنز زمین گژھہِ تِمن سارِنٕے سارِنٕے سٍتـ̡ یِمن ہٕندِس تشددٕ سٍتـ̡ یِمن سارِنٕے سٍتـ̡ تِمن ہٕندِس تشددٕ سٍتـ̡ تِمن سارِنٕے سٍتـ̡ یِمن ہٕندِس {یہ سورُے...: ہیب۔ امچ مکمل آسن}\n20. تہٕ یِم شہر آباد گژھن تہٕ زمین گژھن ویران کرنہٕ۔ تہٕ ژیہ گژھہِ پتاہ زِ بہٕ چُھس خداوند ۔\n21. تہٕ خداوند سُند کلام آو میہ نِش،\n22.\\tاِنسان سٕندِس پَتُر، سُہ محاورٕ کیا چُھہ یُس تۅہہِ اِسرٲیلِس مَنٛز چُھ، یُس وَننہٕ آمُت چُھ، دۅہہٕ چُھ زیٹھراوان تہٕ پرٮ۪تھ کانہہ وژن چُھ ناکام سپدان؟\n23.\\tتِمن وَنُن یِتھٕ پٲٹھۍ چُھ خداوند خدا فرماوان۔ بہٕ کرٕ یہ ضرب المثل بند تہٕ تم کرن نہٕ ونہٕ اسرٲیلِس منز یہ محاورہ پٲٹھۍ استعمال۔ مگر تِمن وَنُن زِ دۅہ چھُ اتھس منز، تہٕ پرٮ۪تھ وژنُک اثر۔\n24.\\tتکیازِ اسرٲیلِس گرس منز گژھہِ نہ کانہہ فضول وژن تہٕ نہ خوشامد کرنہٕ۔\n25. یێلہِ بہٕ چُھس خداوند چُھس: بہٕ کَرٕ کَتھ تہٕ یُس لفظ بہٕ بولہٕ سُہ گژھہِ سپدُن۔ یہِ گژھِ نہٕ زیادٕ زیٹھہٕ روزُن، تکیازِ اے باغی گرٕ، بہٕ وَنُن کلام تہٕ کَرٕ یہِ انجام دِنہٕ، خداوند خدا چُھ وَنان۔\n26.\\tبییہِ آو رب سُند کلام میہ نِش وونُن،\n27.\\tاِنسان سٕندِ فرزند، وُچھِو تِم یُس وُچھان چُھہ سُہ یُس وُچھان چُھہ سُہ چُھہ واریاہن دۅہن سٍتـ̡ وُچھان، تہٕ سُہ چُھ تِمن زمانن ہٕنز پیشن گویی کران یُس دور چُھ۔\n28. تێمہِ کِنۍ وَنُن تِمن وَنُن، یِتھٕ پٲٹھۍ چُھ خداوند خدا فرماوان۔ خداوند خدا چُھ ونان زِ میانہِ کلامَس مَنٛز گژھِ نہٕ کانٛہہ تہِ زیٹھر، مگر یُس لفظ مےٚ وونمُت چُھ، سُہ گژھِ کرنہٕ یُن۔","1. تہٕ خداوند سُند کلام آو میہ نِش،\n2. اِنسان سٕندِس نیٚچُو، یِم پیشن گویی کٔرِن تِمن ہٕندِس دِلہٕ سٍتـ̡ پیشن گویی کٔرِتھ تہٕ تِمن وَنُن یِم پَنٕنـ̡ دِلہٕ سٍتـ̡ پیشن گویی کران چِھ، تہٕ یِمن ہٕندِس دِلہٕ سٍتـ̡ پیشن گویی کرٕنـ̡ تہٕ یێلہِ سٍتـ̡ خداوند سُند کلام بوزو۔ {یہ پیشین گویی نیبر...: ہیب۔ یِم چھِ پننیو دِلہٕ منزٕ پیغمبر آسان}\n3. یِتھٕ پٲٹھـ̡ چُھ خداوند خدا فرماوان۔ افسوس، یِمن بیوقوف پیغمبرن ہٕندِ خٲطرٕ، یِم پننِس روحس پٲٹھۍ، تہٕ یِمو نہٕ کیٚنٛہہ وُچھمُت! {فالو: ہیب۔ پَکُن پَکُن} {تہٕ...: یا، تہٕ تِم چیٖز یِم نہٕ تِمو وُچھمٕتۍ چھِ}\n4. اے اسرائیل، تہندِ پیغمبرن ہٕندِ پٲٹھۍ۔\n5.\\tتہٕ چُھہ نہٕ خدایہ سٕندِس دۅہہٕ جنگس مَنٛز کھڑا گژھنہٕ خٲطرٕ اِسرٲیلِیُک گرٕ بَنوومُت۔ {گیپس: یا، خلاف ورزی} {بنیومُت...: ہیب۔ ہیج کٔرِتھ ہیج}\n6. تِمو چُھ باطل تہٕ اپُز وُچھمُت، یہِ ونان زِ خداوند چُھ ونان: تہٕ خداوند چُھ نہٕ تِم سوزمُت، تہٕ تِمو چُھ {باقی﴾ وۅمید کٔرمٕژ زِ تِم کرِ کلامٕچ تصدیق ۔\n7. کیا ژے چُھہ نہٕ اکھ بےکار وژن وُچھمُت، تہٕ کیا ژے چُھہ نہٕ اپُز خدایہ وُچھمُت، یێلہِ زن تُہۍ ونان چھِو، خداوند چُھ وَنان۔ حالانکہ میہ چھیہ نہ کتھ کٔرمٕژ؟\n8. تَمہِ کِنۍ چُھ خداوند خدا یِتھٕ پٲٹھۍ وَنان۔ کیازِ ژے چُھہ باطل کتھ کٔرمٕژ، تہٕ اپُز وُچھمُت، تێمہِ کِنۍ چُھس بہٕ چُھس ژے خلاف، خداوند خدایہ چُھ ونان۔\n9. تہٕ میٲنۍ اتھہٕ آسہِ تِمن پیغمبرن پیٹھ یُس باطل وُچھان چُھ، تہٕ یُس خدایہ چُھ اپُز وُچھان: تِم گژھن نہٕ میانین لوکن ہٕندِس مجلسس مَنٛز آسٕن، تہٕ نہ گژھن تِم اسرٲیلٕکِس سرزمینس مَنٛز دٲخل گژھن۔ تہٕ ژیہ گژھہِ پتاہ زِ بہٕ چُھس خداوند خدا۔ {اسمبلی: یا، راز، یا، مشورہ}\n10.\\tکیازِ، تِکیازِ تِمو چھُ میانین لُکن ہٕندِس لُکن ہٕندِس بہتَس سٍتـ̡ وَننہٕ آمُت۔ تہٕ {اتہِ} اوس نہٕ امن؛ تہٕ أکۍ بنوو اکھ دیوار، تہٕ لو، باقیو کٔر اتھ بے مزاجٕ {morter}: {اکھ دیوار: یا، اکھ ہلکہٕ دیوار}\n11.\\tتِمن وَنُن یُس رُکُن دِنہٕ آمُت چھُ، یُس وَسُن وُسُن، اَتہِ گژھہِ وُپھ وُسُن۔ تہٕ تۅہہ، اے بٔڈۍ ڈولہٕ، پیوٚو پیوٚو۔ تہٕ اکھ طوفانی واو پھٔٹِتھ ژٔٹِتھ {یہ}۔\n12.\\tییلہ دیوار پیوٚو، یہ گژھہِ نہ ژیہ وننہ یُن، سہ کتہِ چھہ یُس ژیہ لوٚگمُت چھُ؟\n13. تێمہِ کِنۍ چُھ خداوند خدا یِتھٕ پٲٹھۍ وَنان۔ بہٕ تہِ ژٔٹِتھ پننہِ غصس منز طوفانی واو سٍتۍ ژٔٹِتھ تہِ۔ تہٕ میانِس غصس منز گژھہِ وُپھ وُن روٗد، تہٕ {میانِ} غصس منز بٔڈ ڈولہٕ پتھرِ کھٮ۪نہٕ خٲطرٕ۔\n14.\\tیِتھٕ پٲٹھـ̡ بہٕ پھُٹرٲوِتھ دیوار یُس ژے بےٚ مزاجٕ سٍتـ̡ دِژمُت چُھ، تہٕ یێلہِ ہُند بُنیاد ییہِ دریافت کرنہٕ، تہٕ یێلہِ پۯاوُن، تہٕ تێہہ گژھہِ پتاہ زِ بہٕ چُھس خداوند چُھس۔\n15. یِتھٕ پٲٹھۍ کٔرٕ بہٕ دیوارس پیٹھ پنُن غصہٕ پورٕ، تہٕ تِمن پیٹھ یِمو اتھ بے مزاجہ {morter} سٍتـ̡ دِژمُت چُھ، تہٕ ژے وَنُن زِ دیوار {چُھ} چُھنہٕ {زیادٕ}، تہٕ نہ چُھہ تِمو یِمو اتھ لٔگِتھ چُھس۔\n16.\\tیُس یُس یروشلمس متلق پیشن گویی کران چُھ، تہٕ یُس أمِس خٲطرٕ امنُک خواب وُچھان چُھ، تہٕ {اَمُن} چُھہ نہٕ، خداوند خدا چُھ وَنان۔\n17. یِتھے پٲٹھۍ، اے انسان سٕندِس نیٚچو، پَنُن بُتھ تھٲوِو پَنٕنـ̡ لُکہٕ سٕنزِ کورِ سٍتـ̡ یِم پَنٕنـ̡ دِلہٕ سٍتـ̡ پیشن گویی کران چھِ۔ تہٕ تِمن خلاف پیشن گویی کٔرِو،\n18. تہٕ ونُن، یِتھٕ پٲٹھۍ چُھ خداوند خدا فرماوان۔ ہا ہا تِمن زنانن ہٕندِ خٲطرٕ یِم سارِنٕے نرِ ہٕندِس سوراخس تِلہٕ سِوان چھِ، تہٕ پرٮ۪تھ کُنہِ قدٕس کِلس پیٹھ رومال بناوان چھِ۔ کیا ژٕ کٔرِکھ میانین لوکن ہٕنزِ روحن ہُند شکار، تہٕ کیا ژٕ بچٲوکھ زندٕ روحن {یُس ژے نِش} یِن؟ {آرم ہولز: یا، اِلبو}\n19.\\tتہٕ کیا ژٕ کٔرِکھ میہ میانین لوکن منز مُٹھہٕ وارٕ وارٕ تہٕ روٹی ٹُکرٕ خٲطرٕ، تِمن روحن مارنہٕ خٲطرٕ یِم نہٕ مرٕن، تہٕ تِمن روحن بچاونہٕ خٲطرٕ یِم نہٕ زندٕ روزن یِن، میانین لوکن سٍتۍ یِم اپُز بوزان چھِ۔\n20. اَمہِ مۄکھٕ چُھ خداوند خدا یِتھٕ پٲٹھۍ وَنان۔ وچھ بہٕ چُھس چُھس تۅہہِ تِمن ہُند شکار کران تہٕ بہٕ ژٔٹِتھ ژٔٹِتھ تہٕ تِمن روحن یِمن ہُند شکار کٔرِتھ ژٔٹِتھ تہٕ یِمن روحن تہِ ژٔٹِتھ تہٕ یِمن روحن ہُند شکار تہِ کٔرِتھ یِمن ہُند شکار چھُکھ کٔرِتھ۔ {بناوُن...: یا، باغن منز}\n21.\\tچانۍ رومال تہِ ژٔٹِتھ تہٕ پنٕنۍ لُکھ ژٔٹِتھ تہٕ یِم گژھن نہٕ تۅہہِ ہٕندِس اتھس منز شکار۔ تہٕ ژیہ گژھہِ پتاہ زِ بہٕ چُھس خداوند ۔\n22. کیازِکہ اپزٕ سٍتـ̡ چُھہ ژے نیک سُند دِل غمگسار کورمُت، یُس نہٕ مے غمگین کورمُت چُھ۔ تہٕ کٔرٕن بدکارن ہٕندِ اتھہٕ مضبوٗط، زِ سُہ گژھِ نہٕ پننہِ بدکار وتہِ نِش واپس، أمِس زِندٕ ہُند وعدٕ کٔرِتھ: {by...: یا بہٕ کرٕ تٔمۍ سٕنز زُو بچاوُن: ہیب۔ تس تیز کٔرتھ}\n23. تێلہِ گژھہِ نہ بییہ کانہہ باطل تہٕ نہ خدایہ خدایہ وُچھن، تکیازِ بہٕ کرٕ پننین لوکن چانہِ اتھہ نِش نجات تہ ژیہ گژھہِ معلوم زِ بہٕ چُھس خداوند ۔","1. اَمہِ پَتہٕ آو اسرٲیلٕکۍ بزرگو میانہِ نِش تہٕ بیوٹھ میانہِ برونہہ کُن۔\n2. تہٕ خداوند سُند کلام آو میہ نِش،\n3.\\tاِنسان سٕندِس بُتھِس مَنٛز چھُ یِمو مردو پَنٕنـ̡ پَنٕنـ̡ بُتـ̡ بُتھِس سٍتـ̡ بُتھِس پٲٹھـ̡ تھوومُتـ̡ تہٕ یِمن ہٕندِس بُتھِس پٲٹھـ̡ پَنٕنـ̡ پٲٹھـ�\n4. تێمہِ کِنۍ کٔرِو تِمن سٍتـ̡ کتھ تہٕ تِمن ونُن، یِتھٕ پٲٹھـ̡ چُھ خداوند خدا فرماوان۔ اسرٲیلُک پرٮ۪تھ کانہہ انسان یُس پَنٕنـ̡ بُتـ̡ پننِس دِلس مَنٛز بُتـ̡ تھاوان چُھ، تہٕ پَنٕنـ̡ بُتھِس برونہہ کُن پَنٕنـ̡ بُتھِ ہُند رُکاوٹ تھوان چُھ، تہٕ پیغمبرس نِش چُھ یِوان۔ بہٕ چُھس خداوند أمِس جواب دِوان یُس تٔمۍ سٕندِس بُتَن ہٕندِس بٔڈِس مُطٲبِق یِوان چھُ۔\n5.\\tیُتھ بہٕ ہێکہٕ اسرٲیلُک گرٕ تِہندِس دِلس مَنٛز نِتھ، تِکیازِ تِم چھِ سٲری پنٕنـ̡ بُتـ̡ سٍتـ̡ میہ نِش دور۔\n6. تێمہِ کِنۍ وَنُن زِ اِسرٲیلِس کِس گرس سٍتـ̡ چُھہ یِتھٕ پٲٹھـ̡ خداوند خدا فرماوان۔ توبہ کٔرِو تہٕ پَنٕنـ̡ بُتـ̡ نِش پھیرِو۔ تہٕ پَنٕنۍ بُتھ پھٔرِو پنٕنۍ سارِنٕے مُشکِلَو نِش۔ {تم پانے: یا، باقی}\n7. اِسرٲیلِکِس گرس مَنٛز پرٮ۪تھ أکِس شخصہٕ، یُس اسرٲیلِس مَنٛز روزان چُھ، یُس میانہِ نِش الگ چُھ، تہٕ پَنٕنـ̡ بُتـ̡ پَنٕنـ̡ بُتـ̡ بُتھِس پٲٹھـ̡ تھاوان چُھ، تہٕ چُھہ أکِس پیغمبرس نِش یُس میانہِ مُتلق پرژھہٕ گٲر کران چُھ۔ بہٕ چُھس خداوند پانَے أمِس جواب دِوان:\n8. تہٕ بہٕ کرٕ أمِس شخصس خلاف پنُن بُتھ، تہٕ بناوٕ أمِس اکھ نشانی تہٕ محاورہٕ، تہٕ بہٕ کرٕ سُہ پننین لوکن منزٕ ژٹان۔ تہٕ ژیہ گژھہِ پتاہ زِ بہٕ چُھس خداوند ۔\n9.\\tتہٕ یێلہِ پیغمبرن کُنہِ کُنہِ کتھہِ ہٕندِس سٍتـ̡ دھوکہٕ دِنہٕ آمُت، تہٕ بہٕ کرٕ تٔمِس پَنُن اَتھٕ تہٕ بہٕ کَرٕ تٔمِس سٍتـ̡ پَنٕنـ̡ اِسرٲیلـ̡ سٍتـ̡ تباہ کرنہٕ۔\n10. تہٕ تِمن ہُند سزا گژھہِ تِمن ہٕندِس بدکٲری ہُند سزا۔\n11.\\tیُتھ زِ اسرٲیلُک گرٕ گژھِ نہٕ میانہِ نِش مزید گمراہ گژھُن، تہٕ نہ گژھِ تِہندِ سارِنٕے گناہ سٍتـ̡ آلودہ سپدُن۔ خداوند خدا چُھ ونان زِ تِم گژھن میٲنۍ لوٗکھ تہٕ بہٕ تہٕ بہٕ تِہُند خدا بٔنِتھ۔\n12. خداوند سُند کلام آو میہ نِش دُبارٕ وونُن،\n13. اِنسان سٕندِس نیٚچُو، یێلہِ زمینہٕ سٍتـ̡ سٍتـ̡ گُناہ کٔرِتھ، تێلہِ بہٕ کَرٕ اَتھ پیٹھ پنُن اتھہٕ، تہٕ اَمہِ سٍتـ̡ پھُٹراوٕ تہٕ اَتھ سٍتـ̡ ژٔٹِھہٕ تہٕ ژٔٹِتھ\n14.\\tیێلہِ یێلہِ یِم تریہ نفر نوح، دانیال تہٕ ایوب اتھ مَنٛز ٲس، تِم پزِ پَنٕنـ̡ نیکی سٍتـ̡ پَنٕنـ̡ پَنٕنـ̡ نجات دِنـ̡ ۔\n15.\\tاگر بہٕ بدکار جانور زمینہِ منزۍ نیرُن، تہٕ تِم کرِ یہِ خراب کرنہٕ، یُتھ زن کانہہ تہِ انسان یِمن درندن ہٕندِ وجہ سٍتۍ نیرِتھ: {غنیمت: یا، سوگ}\n16.\\t{اگرچہ} یِم تریہ نفر اتھ منز ٲسۍ، {یێلہِ} بہٕ زندٕ، خداوند خدا چُھ ونان زِ تِم کرِ نہ نیچوۍ تہٕ کورِ دِنہٕ۔ تم گژھن صرف بچاونہٕ، مگر زمین گژھہٕ ویران۔ {اتھ منز: ہیب۔ اتھ منٛز}\n17. یا {اگر} بہٕ تتھ زمینس پیٹھ تلوار اَنِتھ تہٕ ونان، تلوار، زمینہٕ منزٕ گژھ۔ تہ میہ ژٔٹۍ انسان تہٕ جانور اتھ نِش:\n18.\\tیێلہِ یێلہِ یِم تریہ نفر اتھ مَنٛز ٲسِتھ، {یێلہِ} بہٕ زندٕ چُھس، خداوند خدا چُھہ ونان زِ تِم دِن نہٕ نیچوۍ تہٕ کورِ دِنہٕ، مگر یِم گژھن پانہٕ دِنہٕ۔\n19.\\tیا {اگر} بہٕ اتھ زمینس منز اکھ وبا سوزان تہٕ اتھ پیٹھ پنُن غصہٕ ترووُن تہٕ اَتھ نِش انسان تہٕ جانور ژٹنہٕ خٲطرٕ:\n20.\\tیێلہِ نوح، دانیال تہٕ ایوب {ٲس} اتھ مَنٛز، {یێتھ} بہٕ زندٕ، خداوند خدا چُھ ونان زِ تِم کرِ نہ نیچو تہٕ کورِ دِنہٕ۔ تِم کرِ پَنٕنـ̡ پَنٕنـ̡ نیکی سٍتـ̡ پَنٕنـ̡ پَنٕنـ̡ رٔٹِتھ پَن\n21. یِتھٕ پٲٹھـ̡ چُھہ خداوند خدایہِ فرماوان۔ ییلہ بہٕ یروشلمس، تلوار، قحط، تہٕ بدمعاش درندہ تہٕ وباہن پیٹھ ژور دردناک فیصلہٕ سوزان چھُس، انسان تہٕ درندٕ ژٹنہٕ خٲطرٕ۔ {کتھہ پاٹھۍ...: یا، تہِ ییلہ تہِ}\n22. توتہِ گژھہِ اَتھ مَنٛز اکھ باقیات یُس نیرِتھ یُس نیچو تہٕ کورِ دۅشوے نیرِ، وُچھِو تِم تہٕ تِہٕنزِ وَتھ تہٕ تِہٕندِ اعمال وُچھِو، تہٕ یُس بُردی میہ یروشلمس پیٹھ واتنوومُت چُھ، تہٕ یُس میہ اَتھ سٍتـ̡ دِژمُت چُھ، تہٕ یێمہِ سٍتـ̡ یُس بہٕ اَتھ سٍتـ̡ دِژمُت چُھ، تێلہِ گژھہِ تسلی دِنہٕ۔\n23. تہٕ تِم کٔرِن تۅہہِ تسلی دِنہٕ، یێلہِ تہٕ تِہٕنزِ وتہٕ تہٕ تِہٕندِ اعمال وُچھِو، تہٕ ژے گژھہِ پتاہ زِ یُس میہ اتھ مَنٛز کورمُت چُھ، سُہ چُھہ نہٕ بغٲر وجہہ کٔرمٕتـ̡ ۔","1. تہٕ خداوند سُند کلام آو میہ نِش،\n2. اِنسان سٕندِس کُلِس کُلِس کھۅتہٕ کُنہِ تہِ کُلِس کھۅتہٕ زیادٕ کیا چُھ، {یا کُلِھ} کُلِس کھۅتہٕ زیادٕ چُھہ یُس جنگل کین کُلٮ۪ن مَنٛز آسہِ؟\n3.\\tکُنہِ تہِ کٲم کرنہٕ خٲطرٕ کیا لٔکر نِنہٕ یِنہٕ؟ کِنہ {مرد} نِیہ اتھ پیٹھ کانہہ تہِ بانہٕ لٹاونہٕ خٲطرٕ؟\n4.\\tوچھو یہ چھہ نارس منز تراونہ یوان۔ نار چھہ امکۍ دۅشوے اندس کھیوان، تہ اتھ منز چھہ دزان۔ کیا یہِ چھَا {کُنہِ} کامہِ خٲطرٕ مُلاقات کَرنہٕ آمُت؟ {کیا یہ...: ہیب۔ کیا یہ گژھہِ ترقی؟}\n5.\\tوُچھو، ییلہ یہ مکمل اوس، یہ اوس نہ کامہِ خٲطرٕ پورٕ سپدان: ییلہ نار یہ زالِتھ آسہِ، تہٕ یہ دزنہٕ ییہِ۔ {میٹ: ہیب۔ بَناوُن فِٹ}\n6. تَمہِ کِنۍ چُھ خداوند خدا یِتھٕ پٲٹھۍ وَنان۔ یتھے پاٹھۍ چھہ جنگل کین کُلٮن منز انگور کُل، یُس میہ نارس ایندھن خٲطرٕ دِژمُت چھُ، تِتھے پٲٹھۍ دِیہ بہٕ یروشلم کین بسکینن دِوان۔\n7. تہٕ بہٕ کٔرٕ تِمن خلاف پنُن بُتھ؛ تِم گژھن {اکہِ} نارٕ منزٕ نیران، تہٕ {بییِہ} نار کرِ تِمن کھٮ۪وان۔ تہٕ ژے گژھہِ پتاہ زِ بہٕ چُھس خداوند چُھس، ییلہ بہٕ تمن خلاف پنُن بُتھ تھوو۔\n8. تہٕ بہٕ کَرٕ زمینہٕ ویران تکیازِ تِمو چُھ زیادتی کٔرمٕژ، خداوند خدا چُھ فرماوان۔ {کمیٹڈ...: ہیب۔ ناجائز قبضہ کرُن}","1. بییہِ آو رب سُند کلام میہ نِش وونُن،\n2. انسانہٕ سُند فرزند، یروشلم کرو تٔمۍ سٕنز مکروہ زانن،\n3. تہٕ ونُن، یِتھٕ پٲٹھۍ چُھ خداوند خدا یروشلمس ونان ۔ تُہُند زٮ۪نہٕ تہٕ تُہُند پیدائشُک {چُھ} کنعان کِس سرزمینس سٍتـ̡ ۔ تہند مول اوس اکھ اموری، تہٕ تہنز موج ٲس ہٹی۔ {پیدائش: ہیب۔ ژٹُن، یا، رہائش}\n4. تہٕ یێلہِ تۅہہِ زینہٕ دۅہہ ژے زینہٕ سٍتـ̡ ٲس نہٕ تۅہہِ ناف ژٹنہٕ آمٕژ، تہٕ نہ ٲسکھ آبہٕ سٍتـ̡ واش کٔرمٕژ۔ ژے اوسُکھ نہٕ نوٗنہٕ تہٕ لٔٹِتھ تہٕ لٔٹِتھ کٔرِتھ۔ {نرم کرُن...: یا، ییلہ میہ ژے وچھ}\n5. تۅہہِ ہٕندِس سٍتـ̡ کٔرِتھ تہٕ یِمو منزٕ کانہہ تہِ کرُن، تہٕ تۅہہِ سٍتـ̡ رحم کرُن۔ مگر ژے کٔرِکھ کھُلہٕ مٲدانس منز، پننہِ شخصہٕ سٕندِس لۅتہٕ سٍتـ̡ کٔرِتھ دِنہٕ، ییمہِ دۅہہ ژے زامُت اوس۔\n6.\\tتہٕ ییلہ بہٕ ژے نِش پٔکِتھ تہٕ وُچھمُت تہٕ ژے چُھس پننِس خونس مَنٛز آلودہ گٔژھمُت، میہ ووٚن ژے {ییلہ ژے پننِس خونس مَنٛز رٔلِتھ}، زندٕ روزُن۔ آ، میہ ووٚن ژے {ییلہ ژیہ پننہِ خونس منز وُچھِو}، زندٕ۔ {آلودہ: یا، قدمن تل لٔگِتھ}\n7.\\tمیہ کٔر ژے کھہہِ ہٕندِس کُنہِ ہٕندِس پٲٹھۍ، تہٕ ژے چھُکھ بٔڈِتھ تہٕ بٔڈۍ وُچھمُت، تہٕ ژے چھُکھ عٔلِم زیور آمُت: تۅہہِ چھُکھ سین بٔنِتھ تہٕ تُہٕندِس مَس وُچھمُت، تہٕ ژے چھُکھ ننگہٕ تہٕ ننگہٕ۔ {وجہ...: ہیب۔ تۅہہ بنوو اکھ لچھ} {بہترین...: ہیب۔ زیورن ہند زیور}\n8.\\tییلہ بہٕ ژے نِش پٔکِتھ تہٕ ژے وُچھمُت، وُچھ، تُہند وق اوس محبتُک وق۔ تہٕ بہٕ چُھس ژے پیٹھ پنُن پوشہٕ پھٔہلِتھ، تہٕ تُہٕندِس ننگہٕ پٲٹھۍ، آ، بہٕ چُھس ژے سٍتـ̡ قسم، تہٕ ژے سٍتـ̡ عہد کورمُت، خداوند خدایہ چُھہ ونان، تہٕ ژے بنیوو میٲنۍ ۔\n9. اَمہِ پَتہٕ چھلُکھ ژے آبہٕ سٍتـ̡ آ، میہ ووت ژے نِش تُہند خون، تہٕ مے کٔر ژے تیٖل سٍتـ̡ مسح کرنہٕ۔ {خون: ہیب۔ بلڈز}\n10.\\tمیہ لوٚگ ژے تہِ کامہِ لاگُن، تہٕ ژے لٲگِتھ ژے رٔٹِتھ لٔگِتھ تہٕ ژے لٔگِتھ ریشم لٲگِتھ۔\n11.\\tمیہ لٲگِتھ ژے تہِ گہنہ سٍتـ̡ سجٲومٕژ، تہٕ بہٕ تھووُن چانہِ اتھن پیٹھ کٔرِتھ کٔرِتھ زنجیر۔\n12. تہٕ بہٕ تھوو چانہِ ڈٮ۪کہٕ پیٛٹھ اکھ جوہر، تہٕ کنن منٛز بالہٕ، تہٕ چانہِ کلَس پٮ۪ٹھ اکھ خوبصورت تاج۔ {ڈٮ۪کہٕ: ہیب۔ نَس}\n13. یِتھٕ پٲٹھۍ ٲسکھ ژے سۄنہٕ تہٕ رۄپہٕ سٍتۍ سجاونہٕ آمٕژ۔ تہٕ تُہند پوشاک اوس نفیس کُن، تہٕ ریشم تہٕ کامہِ ہُند ۔ ژے کھیوٚو اصل آٹ، ماچھ تہٕ تیل، تہٕ تہٕ ژے ٲسکھ واریاہ خوبصورت، تہٕ ژے کٔر أکِس سلطنتس منٛز ترقی۔\n14. تہٕ تُہٕنز شہرت گٔیہِ تُہٕنزِ خوبصورتی خٲطرٕ کافرن مَنٛز درٛاوٕن، یُس میہ ژے پیٹھ تھوومُت اوس، خداوند خدا چُھ ونان زِ یہِ ٲس میانہِ خوبصورتی سٍتـ̡ کامل سپدمٕژ۔\n15.\\tمگر ژے کٔر پننہِ خوبصورتی پیٹھ بھروسہ، تہٕ پننہِ شہرت کِنۍ کٔرٕن بدکار گِندُن، تہٕ کٔرٕن پرٮ۪تھ أکِس یِنہٕ وٲلِس سٍتـ̡ پَنٕنۍ زناکاری ۔ أمۍ سُنٛد یہِ اوس۔\n16.\\tتہٕ پنہٕ نِس پلوَس سٍتـ̡ تُلِتھ تہٕ پَنٕنـ̡ تھدِ جایہِ مُختلِف رَنٛگو سٍتـ̡ سجٲوِتھ تہٕ کٔرٕکھ اَتھ سٍتـ̡ طٔریٖقہٕ: {یِتھٕے چیز} یِنہٕ یِنہٕ تہٕ نہٕ یِنہٕ یِنہٕ۔\n17.\\tژے نِش میانہِ سۄنہٕ تہٕ رۄپہٕ ہٕندِ خوبصورت جوٲہِر تہِ، یُس میہ ژے دِژمُت اوس، تہٕ کٔرٕکھ پانس سٍتـ̡ انسانن ہٕنزِ شکلہٕ تہٕ تِمن سٍتـ̡ کٔرٕکھ طریٖقہٕ، {انسانو سٍتـ̡ عبران۔ اکھ مرد سُند}\n18.\\tتہٕ تُل پنٕنۍ پوشہٕ تہٕ ؤلِتھ تہٕ تِمن برونہہ کُن میٲنۍ تیٖل تہٕ میٲنۍ بخور تھووُن۔\n19.\\tمیون ماز تہِ یُس میہ ژے دِژمُت اوس، اصل آٹ، تیٖل تہٕ ماچھ، یُس میہ ژیہ کھیوٚومُت، ژے تھووُن تِمن برونہہ کنہِ مٔٹھۍ مٔٹھۍ۔ {اکھ مٔٹھۍ...: ہیب۔ آرام کرنُک ذائقہٕ}\n20. امہِ علاوٕ چھُے ژے پنٕنۍ نیچوۍ تہٕ کورِ نِمٕژ، یِم ژے میانہِ خٲطرٕ زامٕتۍ چھِ، تہٕ یِم ژے تِمن کھٮ۪نہٕ خٲطرٕ قربان کٔرۍمٕتۍ۔ {یہِ} چھَا تُہنزِ بدکٲری ہُند اکھ لۄکُٹ معاملہٕ، {بَنُن...: حَب۔ کھٮ۪نہٕ خٲطرٕ}\n21.\\tیُتھ ژے میٲنۍ شُرۍ مٲرِتھ تہٕ تِمن دِژٕکھ تِمن ہٕندِ خٲطرٕ نارس منزٕ نیرُن؟\n22. تہٕ چُھہ نہٕ پنٕنـ̡ جوانی ہٕندِس دۅہہٕ یاد، یێلہِ تہٕ ژے ننگہٕ تہٕ ننگہٕ ٲس، {تہٕ} ٲس پننہِ خونس سٍتـ̡ آلودہ گٔمٕژ۔\n23. تہٕ یہِ سپُد تُہٕندِس سارِنٕے بدکاریو پَتہٕ سپدُن، (ہا ہا، ہا ہا! خداوند خدا چُھ فرماوان؛)\n24. {یہ} ژے چھُکھ پانس خٲطرٕ اکھ اعلیٰ مقام تہٕ پرٮ۪تھ سڑکہِ مَنٛز اکھ تھوٚد جاے بنٲومٕژ۔ {نمایاں...: یا، کوٹھہٕ ہاؤس}\n25. ژے کٔر وتہِ ہٕندِس پرٮ۪تھ کُنہِ کُنہِ کُنہِ پٲٹھـ̡ پَنُن تھوٚد جاے بنوومُت، تہٕ کٔرٕکھ پَنٕنہِ خوٗبصوٗرتی ہٕندِس سٍتـ̡ بێزاری ہٕندِس سٍتـ̡ تہٕ کٔرٕن پَنٕنـ̡\n26.\\tژے کٔر پننین ہمساین سٍتـ̡ زنا تہِ کٔرمٕژ، یُس ماز سٍتـ̡ بٔڈ چُھ۔ تہٕ کٔرٕن پنٕنۍ بدکاری ہُریر، میہ شرارت دِنہٕ خٲطرٕ۔\n27. وُچھ، تێمہِ کِنۍ چُھس میہ ژے پیٹھ پنُن اَتھٕ پھٔہلٲومُت، تہٕ چُھکھ تُہٕندِس عام کھیٛنس کم کٔرِتھ، تہٕ چُھکھ ژے تِمن ہٕنزِ مرضی تام واتناوُن یِم ژےٚ نفرت کران چھِ، فلسطینن ہٕنزِ کورِ، یِم تُہٕندِس فحش طریقہٕ سٍتـ̡ شرمندہ چھِ۔ {کورۍ: یا، شہر}\n28.\\tژے کٔر اشورین سٍتـ̡ تہِ طریٖقہٕ سٍتـ̡ گِندُن، تکیازِ ژے ٲس نہٕ تسٕندِس سٍتـ̡ آ، ژیہ چھکھ تمن سیتۍ بدکار گِندمُت، توتہِ ٲسکھ نہ تسلی بخشان۔\n29. توے کٔر کنعان کِس سرزمینس مَنٛز پَنُن زناکاری کلدیہ تام بڑٲومُت۔ تہٕ توتہِ گٔیہِ نہٕ تۅہہ اَتھ سٍتۍ مطمئن۔\n30. خداوند خدا چُھ ونان زِ تُہند دِل کوتاہ کمزور چُھ، یێلہِ چُھہ یِم سارِنٕے {کامہِ} کٔرِتھ، یُس أکِس بدکار زنانہِ ہٕنز کٲم کران چُھ۔\n31. یتھ مَنٛز چُھہ توے پرٮ۪تھ وتہِ ہٕندِس سرس مَنٛز پَنُن نُمایا مقام بناوُن، تہٕ پرٮ۪تھ سڑکہِ مَنٛز پَنُن تھوٚد مقام بناوُن۔ تہٕ چُھس نہٕ کُنہِ بدکار سٕندِس پٲٹھۍ، یَتھ مَنٛز تہٕ ژے کرایہِ ہٕنز حقارت کٔرِتھ۔ {یتھ منز ژیہ تعمیر کرُن...: یا، پننہِ کورِ منز چھہ تۅہہ، بیترِ}\n32.\\t{مگر یۅسہٕ زنانہِ زنا کران آسہِ، {یُس} پننِس خاوندس بدلہٕ اجنبی نِوان چھُ!\n33.\\tتِم چھِ سارِنٕے طوائفَن تحفہٕ دِوان، مگر تُہۍ چھِو پَنٕنٮ۪ن سارِنٕے عاشقن دِوان تہٕ تِمن کرایہ دِوان تاکہ تِم گژھن تۅہہِ نِش پرٮ۪تھ طرفہٕ یِنہٕ۔ {کرایہٕ: ہیب۔ Bribest}\n34. تہٕ اَتھ برعکس چُھہ تۅہہِ سٍتـ̡ بێیہِ زنانہٕ سٍتـ̡ یێلہِ چُھہ نہٕ تۅہہِ سٍتـ̡ بدکاری کرنہٕ خٲطرٕ تہٕ تێلہِ چُھہ نہٕ کانہہ ثواب دِنہٕ یِوان، تێلہِ چُھہ تۅہہِ خلاف ورزی کران۔\n35. اَمہِ مۄکھہٕ، اے بدکار، خداوند سُند کلام بوزو:\n36. یِتھٕ پٲٹھۍ چُھ خداوند خدا فرماوان۔ تکیازِ تۅہہِ ہنز گندگی ٲس ژٔٹِتھ تہٕ تۅہہِ ہٕندِس عشقس سٍتـ̡ تہٕ پننین بُتن ہٕندِس خونہٕ سٍتـ̡ تہٕ تُہٕندِس شُرین ہٕندِس خونہٕ سٍتـ̡ یُس ژے تِمن دِژمُت اوس۔\n37.\\tتێلہِ کٔرٕ بہٕ پنٕنـ̡ سٲری عاشق، یِمن سٍتـ̡ ژے خۅش گومُت چُھ، تہٕ تِمن سارِنٕے سٍتـ̡ یِمن سٍتـ̡ ژے نفرتـ̡ چُھہ کٔرمٕژ۔ بہٕ کٔرٕ تِم ژےٚ خٕلاف جمع تہٕ تِمن نِش کٔرٕ تُہند ننگہٕ ظٲہِر، یُتھ تِم تُہٕنٛز تمام ننگہٕ وُچھن۔\n38. تہٕ بہٕ کٔرٕ تۅہہِ سُند فیصلہ یِتھ زن زنانہٕ یِم خاندر پھُٹراوان تہٕ خون تراوان چھِ۔ تہٕ بہٕ دِیہ ژے غصہٕ تہٕ حسدٕ سٍتۍ خون۔ {as: Heb. فیصلن سۭتۍ}\n39.\\tتہٕ بہٕ دِیہٕ ژےٚ تِہنٛدِس اتھس منٛز، تہٕ تِم ترٛاوَن تُہٕنٛز اعلیٰ جاے تہٕ تُہٕنٛزِ تھدِ جایہِ پھُٹراوٕن، تِم تہِ ژےٚ پلو تہٕ تُہٕنٛدِ خوبصورت جوٲہِر نِن، تہٕ ژےٚ ننگہٕ تہٕ ننگہٕ تراون۔ {تُہُند فیئر...: ہیب۔ تُہند زیورٕکۍ آلات}\n40. تِم تہِ کٔرِن تۅہہِ خٕلاف اکھ جمٲژ تہٕ تِم لگٲوِن تۅہہِ کٔنہِ سٍتـ̡ کٔنہِ تہٕ تلوارو سٍتـ̡ ژٔٹِتھ دِنہٕ۔\n41. تہٕ تِم زٲلن تُہٕندِس گَرٕ نارٕ سٍتـ̡ تہٕ واریہن زنانن ہٕندِس نظرِ سٍتـ̡ تۅہہِ پیٹھ فیصلہٕ دِنہٕ۔\n42. یِتھے پٲٹھۍ کٔرٕ بہٕ ژے کُن پنُن غصہٕ آرام کرنہٕ خٲطرٕ، تہٕ میون حسد ژےٚ نِش ژلہٕ تہٕ بہٕ روزٕ ژھۄپہٕ، تہٕ بہٕ روزٕ نہٕ مزید شرارت۔\n43.\\tکیازِ ژے چُھہ نہٕ پننہ جوانی ہٕندِ دۅہ یاد، مگر یِمن سارِنٕے چیزن سٍتـ̡ چُھس میہ پریشان کورمُت۔ خداوند خدا چُھ ونان زِ بہٕ تہٕ کٔرٕ تۅہہِ ہٕندِس کلس پیٹھ تہٕ یێلہِ تہٕ ژے کٔرِو نہٕ یہِ فحاشی پنٕنـ̡ سارِنٕے کُنہِ کُنـ̡ ۔\n44.\\tوچھو پریتھ کانہہ شخص یُس محاورہ استعمال کرِ، سہ گژھہِ تۅہہِ خلاف یہ محاورہ استعمال کرُن، یتھہ پاٹھۍ موج تہِ چھیہ، تۅہہ چھیہ پننہِ کورِ تہِ۔\n45.\\tژے چھے پننہِ ماجہ ہٕنز کور، یۅسہٕ پننِس خاوندس تہٕ شُرٮ۪ن سٍتـ̡ نفرت کران چھےٚ۔ تہٕ تہٕ ژٕ ٲس پننہٕ بینہٕ ہٕنٛز بینہٕ، یۄس پننین خاندارن تہٕ تہندین شُرین سۭتۍ نفرت ٲس کران: تہنز موج ٲس ہٹی، تہٕ تہند مول اوس اموریت۔\n46.\\tتہٕ تہنز بٔڈ بینہِ سامریہ، سۅ تہٕ تٔمۍ سٕنزِ کورِ یُس تُہٕندِس کھوورِ اتھس منز روزان چھِ، تہٕ تُہٕنزِ لۄکٕٹ بینہِ، یۄسہٕ تُہٕندِس دچھنہِ اتھس منز روزان چھِ، سدوم تہٕ تٔمۍ سٕنزِ کورِ۔ {تُہند لۅکٹ: ہیب۔ ژے کھوتہٕ کم}\n47.\\tتوتہِ چُھکھ نہٕ تِہٕنزِ وتہِ پٔکِتھ، تہٕ تِہٕندِس مکروہ پَتہٕ پٔکِتھ تہٕ کٔرِکھ نہٕ تِمن ہٕندِس بد کارس پٲٹھۍ، مگر یێلہِ یہِ سٮ۪ٹھاہ کم {چیز} آسہِ، تہٕ توے گٔے تِمن سارِنٕے وَتن مَنٛز زیادٕ بدکار گٔمٕژ۔ {یتھہ پاٹھۍ...: یا، یہ اوس اکھ لۅکٹ چیز ماننہ آمت}\n48. خداوند خدا چُھ ونان زِ سدوم چُھہ نہٕ تٔمۍ سٕنزِ بینہِ تہٕ تٔمۍ سٕنزِ کورِ ہٕندِس سٍتـ̡ تہٕ تُہٕنزِ کورِ ہٕندِس سٍتـ̡ تہٕ تُہٕنزِ کورِ چھے نہٕ کٔرمٕژ۔\n49.\\tوچھو یۅہے ٲس چانہِ بینہِ سدوم سُند بدکاری، غرور، روٹی ہُند بھرپور تہٕ کاہلی ٲس أمِس تہٕ کورِ منز، نۂ کٔر تٔمۍ غریبن تہٕ محتاجن ہُند اتھہٕ مضبوط۔\n50.\\tتہٕ تِم ٲسۍ مغرور تہٕ میانہِ برونہہ کُن کٔرٕکھ مُکرٲہِی کٔرِتھ، اَمہِ مۄکھٕ کٔرِم مے تِم یِتھٕ پٲٹھۍ وُچھمٕژ {اصل}۔\n51. سامریاہن چُھ نہٕ تُہند نصف گۅناہ کورمُت۔ مگر ژے کٔرِکھ پنٕنۍ گناہ تِمو کھوتہٕ زیادٕ بڑاومٕژ، تہٕ پنٕنۍ بیٚنہِ کٔرٕکھ پنٕنۍ تمام مکروہ عملن منٛز جواز ثٲبت یِم ژے کٔرمٕژ۔\n52. یێمہِ تہِ چُھہ پننین بینہِ ہُند فیصلہ کورمُت، تێہہ تہِ کرُن پننین گۅناہوں ہٕندِ خٲطرٕ شرم یُس تِمو سٍتـ̡ زیادٕ مکروہ کورمُت چُھ، تِم چھِ ژے کھوتہٕ زیادٕ نیک آسان: آ، ژے تہِ گژھ پریشان تہٕ پنٕنۍ شرم برداشت کرٕن، یێلہِ تہٕ ژے چُھہ پنٕنـ̡ بیٚنہِ ہُند انصاف دِژمُت۔\n53.\\tییلہ بہٕ تِہُند قید تہٕ سدوم تہٕ تٔمۍ سٕنزِ کورِ ہُند قید تہٕ سامریہ تہٕ تٔمۍ سٕنزِ کورِ ہُند قید دُبارٕ اَننہٕ، تیلہِ اَنہٕ بہٕ تِمن مَنٛز تُہٕندِس قٲدَس مَنٛز دُبارٕ اَننہٕ:\n54.\\tیُتھ زِ ژے گژھہِ پنُن شرم برداشت کٔرِتھ، تہٕ یُس تہِ تہِ کرُن تہٕ تِمن ہٕندِ خٲطرٕ تسلی دِنہٕ خٲطرٕ گژھہِ پریشان گژھُن۔\n55. ییلہ تہنز بینہِ سدوم تہٕ تٔمۍ سٕنزِ کورِ پننِس پرانہِ جایدادس منز واپس گژھن تہٕ سامریہ تہٕ تٔمۍ سٕنزِ کورِ گژھن پننِس پرانہِ جایدادس منز واپس، تیلہِ گژھن تۅہہ تہٕ تہنز کورِ پننِس پرانہِ جایدادس منز واپس۔\n56.\\tتکیازِ پننہِ بینہِ سدوم سُند ذکر اوس نہٕ تۅہہِ ہٕندِس فخرٕ کِس دۅہہٕ سٍتـ̡ کرنہٕ آمُت، {ذِکر: حب۔ اکھ رپورٹ، یا، بوزن} {فخر: ہیب۔ فخر، یا، ایکسیلنسیز}\n57.\\tتُہٕندِس بدکٲری ہُند ظٲہِر سپدنہٕ برٛونٛہہ، یِتھ کٔنۍ زَن شامٕچ کورِ تہٕ تٔمِس اندۍ پٔکھۍ سارِنٕے سٍتـ̡ فلسطینن ہٕنزِ کورِ، یِم تۅہہِ اندۍ پٔکھۍ حقارت کران چھِ۔ {شام: ہیب۔ آرام} {حقارت کٔرِتھ: یا، خراب}\n58. خداوند چُھ ونان زِ ژے چُھہ پَنٕنۍ فحاشی تہٕ پَنٕنہِ کُنہِ سٍتـ̡ دِژمُت۔ {بورن: ہیب۔ تِم برداشت کٔرِتھ}\n59. یِتھٕ پٲٹھۍ چُھ خداوند خدا فرماوان۔ بہٕ کَرٕ ژےٚ سٍتۍ تہِ سلوٗک یِتھٕ پٲٹھۍ ژے کٔرۍمٕتۍ، یٔمۍ عہد پھُٹراونس منز حلف ناپسند کٔرۍ۔\n60. بہٕ کَرٕ چانہِ جوانی ہٕندِس دۅہَس مَنٛز ژے سٍتـ̡ پنُن عہد یاد، تہٕ بہٕ کَرٕ ژے سٍتـ̡ اکھ ابدی عہد قٲیم۔\n61. تیلہِ گژھہِ ژے پنٕنۍ وتہٕ یاد تہٕ شرم گژھِ، ییلہ ژے پنٕنۍ بیٚنہِ، پنٕنۍ بٔڈۍ تہٕ لۄکٕٹ رٔٹِتھ رٔٹِو، تہٕ بہٕ دِیہ تِم کورِ خٲطرٕ، مگر چانہِ عہد سٍتـ̡ نہٕ۔\n62. تہٕ بہٕ کَرٕ ژے سٍتـ̡ پنُن عہد قایم۔ تہٕ ژے گژھہِ پتاہ زِ بہٕ چُھس خداوند چُھس:\n63.\\tیُتھ ژے گژھہِ یاد تھاوُن، تہٕ پریشان گژھُن، تہٕ پننہِ شرم کِنۍ گژھہِ نہٕ زانہہ تہِ پننہِ شرم کِنۍ زانہہ تہِ چُھہ پَنُن بوش کھولُن، یێلہِ بہٕ ژے سارِنٕے کٔرِتھ تہٕ یێلہِ تہٕ ژے کٔرِتھ تہٕ یێلہِ تہٕ ژے کٔرِتھ تہٕ یێلہِ تہٕ ژے کٔرِتھ تہٕ یێلہِ تہِ ژے سٍتـ̡ تسٕندِس سٍتـ̡ تسٕندِس سٍتـ̡","1. تہٕ خداوند سُند کلام آو میہ نِش،\n2. اِنسان سٕندِس فرزندس کٔرِو اکھ معمہ تہٕ کٔرِو اِسرٲیلِس مَنٛز تمثیل۔\n3.\\tتہٕ ونُن، یِتھٕ پٲٹھۍ چُھ خداوند خدایہ فرماوان۔ اکھ بٔڈ عقاب یتھ بٔڈۍ پکھہ ٲسۍ، زیٹھۍ پکھہ، پکھہ بٔرِتھ، یمِس مختلف رنگ ٲسۍ، آو لبنان کُن تہ تُل دیودارچ تھوٚد لنجہِ: {غوطہٕ خور...: ہیب۔ ایمبرائیڈرینگ}\n4.\\tتٔمۍ ژٔٹِتھ ژٔٹِتھ لٔگِتھ ۔ تٔمۍ کوٚر یہٕ سوداگرن ہنٛدس شہرس منٛز قٲیم۔\n5.\\tتٔمۍ نِش زمینہِ ہُند بیول تہِ تہٕ ووت پھلہٕ دار کھہَس مَنٛز۔ تٔمۍ تھوو {یہ} عظیم آبس نِش، {تہٕ} تھووُن اکھ ولو کُل۔ {پلانٹ کٔرِتھ...: ہیب۔ یہ ترٛٲوِو بیٲلۍ کِس کھاہس منٛز}\n6. تہٕ یہِ بنیوو بٔڈِتھ تہٕ بنیوو کم قد ہٕنز اکھ پھٔہلِتھ بیل، یٔمۍ سٕنزِ لنجہِ أمِس کُن پھیرِ، تہٕ تِمن ہٕندِ موٗل ٲس أمِس تَل کُن، تہٕ یِتھٕ پٲٹھۍ بنیوو یہِ بیل تہٕ لٔج لٔگۍ۔\n7.\\tاتہِ اوس بیاکھ اکھ بوٚڈ عقاب تہِ ییمِس بٔڈۍ پکھہ تہ واریاہ پکھہ ٲسۍ، تہ وُچھتھ لوٚگ أمس کُن پنٕنۍ لنجہ تہ لٔج أمس کُن، تاکہ سُہ کرِ أمِس باغہٕ کِس کھورِ سٍتۍ آب دِنہٕ۔\n8.\\tیہِ آو أکِس اصل میٚژِ مَنٛز بٔڈۍ آبہٕ سٍتـ̡ لاگنہٕ، یُتھ زِ یہِ گژھہِ لنجہِ نیرِتھ، تہٕ مٮ۪وٕ دِیہِ، یُتھ یہِ جان بیل بنہِ۔ {میژ: ہیب۔ فیلڈ}\n9. یِتھٕ پٲٹھـ̡ چُھہ خداوند خدا فرماوان۔ کیا یہ گژھہِ ترقی؟ کیا سُہ کٔرِن نہٕ امکۍ موٗل تُلِتھ تہٕ امکۍ پھل ژٹِتھ زِ یہ مرزاونہٕ؟ یہ گژھہِ پننہِ چشمہ کین سارنٕے پنہٕ ؤتھرن منز مرزاونہٕ، بٔڈۍ طاقتہٕ ورٲے تہِ یا واریہن لوٗکن ورٲے تہِ زِ یہ موٗل تُلِتھ تُلِتھ۔\n10.\\tآ، وچھو، {ووتھ} کٔرِتھ، کیا یہ گژھہِ ترقی؟ ییلہ مشرقی واو اتھ سیتۍ واتہِ تیلہِ گژھہِ نہ یہ مکمل طور مرزاونہ یُن؟ یہ گژھہِ تمن کھالن منز مرزاونہ ییتہِ یہ بڑیومُت۔\n11. امہِ علاوٕ آو خداوند سُند کلام میانہِ نِش وونُن،\n12.\\tوۅنۍ ونُن باغی گرس منز، ژیہ چھے نہٕ پتاہ زِ یِمن {چیزن ہُند کیا مطلب چھُ}؟ وَنُن زِ بابلُک بادشاہ چُھ یروشلمس مَنٛز آمُت، تہٕ تٔمِس بادشاہ تہٕ اَمہِ کِس شہزادس نِتھ پانس سٍتـ̡ بابل کُن نِنـ̡ ۔\n13.\\tتہٕ کٔرٕن بادشاہ سٕندِ نِش نِش تہٕ أمِس سٍتـ̡ عہد کورُن، تہٕ أمِس سٍتـ̡ حلف کورمُت، تہٕ أمِس سٍتـ̡ چُھہ زمینُک طاقتور تہِ رٔٹمُت: سُہ اوٚن حلف}\n14.\\tیُتھ زِ بادشٲہی گژھہِ بُنیاد تہ یہ گژھہِ نہ پانس تھوٚد کٔرِتھ، {مگر} یُس تمۍ سُند عہد برقرار تھاونہ سٍتـ̡ گژھہِ یہ کھڑا روزِ۔ {مگر...: ہیب۔ پنُن عہد برقرار تھاونہٕ خٲطرٕ، اتھ پیٹھ کھڑا گژھنہٕ خٲطرٕ}\n15. مگر تٔمۍ کٔر تٔمِس خٕلاف بغاوت پنٕنۍ سفیر مصرس منٛز سوزنہٕ، تاکہ تِم دِن أمِس گُرِ تہٕ واریاہ لُکھ دِنہٕ۔ کیا سُہ گژھہٕ ترقی؟ کیا سُہ بچِتھ یُس یِتھۍ {چیز} کران چُھ؟ یا سُہ گژھہِ عہد پھُٹراوُن، تہٕ یِیہِ نجات دِنہٕ؟\n16.\\tیێلہِ چُھس بہٕ روزان، خداوند خدا چُھ ونان یێلہِ تتھ جایہِ {یێتہِ} بادشاہ {روزان چُھ} یێمہِ سُہ بادشاہ بنوو، یٔمۍ سُہ سُہ بادشاہ بنوو، تہٕ یٔمۍ سُند عہد پھُٹراوُن، {حتیٰ کہ} بابل کِس وسطس مَنٛز چُھ سُہ مرُن۔\n17. نہ کٔرِن فرعون پننِس طاقتور لشکر تہٕ بٔڈۍ صحبتس سٍتـ̡ جنگس مَنٛز تٔمِس خٲطرٕ پہاڑ تراوِتھ تہٕ قعلہٕ بنٲوِتھ واریاہن نفرن ژٹنہٕ خٲطرٕ۔\n18.\\tیہ وُچھِتھ زِ تٔمۍ کٔر عہد پھُٹرٲوِتھ حلفس حقارت کٔرِتھ، ییلہ زن تٔمۍ پنُن اتھہٕ دِتمُت تہٕ یِم سارِنٕے {کامہ} کٔرِتھ، سُہ گژھہِ نہٕ ژلِتھ۔\n19. تێمہِ کِنۍ چُھ خداوند خدا یِتھٕ پٲٹھۍ ونان ؛ {As} بہٕ چُھس زندٕ، یقینا میون عہد یُس تٔمۍ حقارت کٔرمٕژ چُھ، تہٕ میون عہد یُس تٔمۍ پھُٹرٲومُت چُھ، سُہ تہِ کرٕ بہٕ تٔمۍ سٕندِس کلس پیٹھ بدلہٕ۔\n20. تہٕ بہٕ پھٔہلِتھ پنُن جال أمِس سٍتـ̡ تہٕ سُہ ییہِ میٲنِس جالس مَنٛز رٔٹنہٕ، تہٕ بہٕ اَننہٕ سُہ بابل تہٕ تتہِ کرٕ أمِس سٍتـ̡ تٔمِس گُلاونہٕ خٲطرٕ یُس تٔمۍ میانہِ خلاف زیادٕ زیادٕ کورمُت چھُ۔\n21. تہٕ تٔمۍ سٕندِ سارِنٕے ژٔلِتھ گٔژھن تلوار سٍتـ̡ تہٕ یِم باقٕے روزن تِم گژھن سارِنٕے ہواہن کُن پھٔہلِتھ تہٕ ژیہ گژھہِ پتاہ زِ میہ چُھہ خداوند کُن کتھ کٔرمٕژ۔\n22. یِتھٕ پٲٹھۍ چُھ خداوند خدا وَنان۔ بہٕ رٔٹِتھ تھدِ دیودارٕچ سارِوٕے کھۄتہٕ تھٔدِ لٔنٛجہِ تہِ، تہٕ تھاوٕ {یہ}؛ بہٕ کٔرٕ أمۍ سٕنزِ جوان لٔرِ پیٹھٕ اکھ نرم تہٕ أکِس تھدِس بالس پیٹھ تہٕ نٲمِس کُنہِ\n23. بہٕ کٔرٕ یہِ اِسرٲیلِس تھزرس مَنٛز تہٕ سُہ کٔرِتھ کُنہِ کۅ اَمہ کِس لنجہِ ہٕندِس ژھایہ منز روزن تِم روزان۔\n24. تہٕ میدانٕکۍ سارِنٕے کُلۍ گژھن پتاہ زِ میہ چُھس خداوند تھدِ کُلِس وونمُت، بۄن کُلِس تھود کورمُت، سبز کُلِس ہۄکھمُت، تہٕ خشک کُلِس پھۄلاونہٕ آمُت: مے چُھس خداوند کُل کٔرمُت تہٕ کورمُت۔","1. خداوند سُند کلام آو میہ نِش دُبارٕ وونُن،\n2. تۅہہ کیا مطلب چُھہ زِ تۅہہ چُھہ اسرٲیلِچ سرزمینس مُتلق یہ محاورہ استعمال کران زِ بابو چُھہ کھٹۍ انگور کھیوٚمُت، تہٕ شُرین ہٕندِ دند چِھہ دِنہٕ آمٕتۍ۔\n3. یێلہِ چُھس بہٕ زندٕ، خداوند خدا چُھ ونان زِ تێہہ گژھہِ نہٕ اسرٲیلِس مَنٛز یہِ محاورہ استعمال کرنہٕ خٲطرٕ مزید کانہہ موقعہٕ۔\n4. وُچھو، سارِنٕے روح چھِ میٲنۍ ۔ یِتھٕ پٲٹھۍ چھُ مٲلہِ سُند روح تہِ میون تہِ: یُس روح گۅنہگار کران چھُ، سُہ گژھہِ مرُن۔\n5. مگر اگر انسان عادل آسہِ، تہٕ سُہ کرِ یُس حلال تہٕ صحیح آسہِ، {یہ...: حب۔ فیصلہٕ تہٕ انصاف}\n6. {تہ} چُھنہٕ پہاڑن پیٹھ کھیوٚمُت، نہ چُھس نہٕ اِسرٲیلِس گرٕ کِس بُتن کُن أچھ تُلِمُت، نہ چُھہ ہمساین ہٕنزِ زنانہِ ناپاک کورمُت، تہٕ نہ چُھہ کُنہِ ماہواری ہٕنزِ زنانہِ نزدیک،\n7.\\tتہٕ چُھنہٕ کٲنسہِ سٍتـ̡ ظلم کورمُت، {بلکہ} چُھنہٕ قرضدارس پنُن وعدٕ واپس کورمُت، کُنہِ تہِ چُھنہٕ تشدد سٍتـ̡ خراب کورمُت، پنُن روٹی دِژمُت تہٕ ننگہٕ پوشہٕ لٲگِتھ کورمُت۔\n8.\\tتٔمۍ چُھ نہٕ سود خوری دِژمُت، نہ چُھہ کانہہ ہُریر کورمُت، {یُس} چُھ پنُن اتھہٕ بدکاری نِش ہٹٲومُت، انسانس تہٕ انسانس درمیان چُھ صحیح فیصلہٕ انجام دِژمُت،\n9. چُھس میانین قونونن منز پکان تہٕ پننین فیصلن پیٹھ عمل کورمُت، پٔزۍ پٲٹھۍ ورتاونہٕ خٲطرٕ۔ خداوند خدا چُھ ونان سُہ {چُھ} منصفانہٕ، سُہ روزِ یقینا زندٕ۔\n10.\\tیێلہِ أمِس نیچو {یعنی} ڈاکو، خوُن تراوُن وول تہٕ {یُس} یِمو منزٕ کُنہِ {چیز} ہُند یِتھٕ پٲٹھۍ کرِ، {ڈاکو: یا، کُنہِ مکانہٕ پھُٹراوُن} {یُس کرِ...: یا، یُس پننِس بٲیِس سٍتـ̡ یِمو منزٕ کُنہِ تہِ کرِ}\n11.\\tتہٕ یِمو منزٕ چُھنہٕ کانہہ تہِ کٲم کٔرمٕژ، بلکہ چُھہ پہاڑن کھٮ۪وان تہٕ ہمساین سٕنزِ زنانہِ ناپاک کٔرِتھ،\n12. غریبن تہٕ محتاجن سٍتـ̡ چُھہ ظلم کورمُت، عہدٕ چُھنہٕ بحال کورمُت، تہٕ بُتن کُن أچھ تُلِمُت، کُن کٔرِمُت،\n13.\\tسود دِژمُت تہٕ ہُریر کورمُت: تیلہِ کیا سُہ زندٕ روزُن؟ سُہ روزِ نہٕ زندٕ: تٔمۍ چھِ یِم سٲری مکروہ کٔرمٕتۍ۔ سُہ گژھہِ یقینا مرُن۔ تٔمۍ سُند خون آسہِ تس پیٹھ۔ {خون: ہیب۔ بلڈز}\n14.\\tوُن، یێلہِ سُہ اکھ نیچو زیٚو، یُس پننِس مٲلہِ سٕندِس سٲری گۅناہ وُچھِتھ یُس تٔمِس کٔرِمُت چھُ، تہٕ سُہ کرِ نہٕ یِتھٕ پٲٹھۍ کرُن،\n15. {یُس} چُھنہٕ پہاڑن پیٹھ کھٮ۪ومُت، تہٕ نہ چُھنہٕ اِسرٲیلِس گرٕ کِس بُتن کُن أچھ تُلِمُت، تہٕ چُھنہٕ پننِس ہمساین سٕنزِ زنانہِ ناپاک کٔرمٕژ،\n16.\\tنہ چُھہ کٲنسہِ سٍتـ̡ ظلم کورمُت، نہ چُھہ وعدٕ رُکٲومُت، نہ چُھہ عٔلمہٕ سٍتـ̡ برباد کورمُت، {مگر} چُھہ پنُن روٹی فاقہٕ مَنٛز دِژمُت، تہٕ ننگہٕ پوشہٕ لٲگِتھ کورمُت، {ہَے نہٕ...: ہیب۔ کیا چُھ نہٕ وعدٕ کورمُت، یا چُھنہٕ وعدٕ کورمُت}\n17. {یُس} چُھ غریبن نِش پنُن اتھہٕ ژٹمُت، {یُس} چُھنہٕ سود حٲصل کورمُت تہٕ نہ ہُرراوُن، میٲنۍ فیصلہٕ چُھ عمل کورمُت، میانین قونونن منز چُھ پکان ؛ سُہ گژھِ نہٕ پننِس مٲلہِ سٕندِ بدکاری خٲطرٕ مَرُن، سُہ روزِ یقینا زندٕ۔\n18.\\tتٔمۍ سٕندِس مٲلِس سٍتـ̡ کیازِ تٔمۍ کٔر ظُلم کٔرِتھ، تٔمۍ کٔرُن پننِس بٲے سٍتـ̡ بدکار تہٕ سُہ تہِ کٔرُن یُس نہٕ تٔمۍ سٕندِس لُکہٕ سٍتـ̡ رٔٹِتھ تہٕ یُس نہٕ تٔمۍ سٕندِس لُکہٕ سٍتـ̡ مَرُن۔\n19.\\tتوتہِ ونو تیلہِ، کیازِ؟ کیا نیچو چُھ نہٕ مٲلۍ سٕنز بدکاری برداشت کران؟ یێلہِ نیچوۍ سُہ یُس حلال تہٕ صحیح چُھ، {تہٕ} میانہِ سارِنٕے قونوٗن رٔٹِتھ تہٕ یِم کرِ، سُہ روزِ یقینا زندٕ۔\n20. یُس روح گۅنہگار کرِ، سُہ گژھہِ مرُن۔ نیچو گژھِ نہٕ مٲلہِ سٕنز بدکاری برداشت کٔرِتھ، تہٕ مٲلِس گژھِ نیچوۍ سٕنز بدکاری تہٕ بدکارن ہٕنز بدکاری گژھہِ أمِس پیٹھ۔\n21. مگر اگر بدکار پنہٕ نِس سارِنٕے گۅنہہ نِش پتھ پھیرِ، تہٕ میانہِ سارِنٕے قونوُن رٔٹِتھ کرِ تہٕ یُس حلال تہٕ صحیح آسہِ، سُہ گژھہِ نہٕ زندٕ۔\n22. تٔمۍ سٕنزِ سارِنٕے غلطی یِم تٔمۍ کٔرمٕژ چھِ، تِمن ہُند ذکر گژھِ نہٕ أمِس سٍتـ̡ کرنہٕ یُن: یُس تٔمۍ سٕندِس نیکی سٍتـ̡ کٔرِمُت چُھ، سُہ روزِ زندٕ۔\n23.\\tمیہ چھا کانہہ خوشی زِ بدکار گژھہِ مرُن؟ خداوند خدا چُھ فرماوان: {تہٕ} چُھ نہٕ یہِ زِ سُہ گژھِ پنہٕ نِس وتہٕ نِش واپس یِن، تہٕ زِندٕ روزُن؟\n24. مگر ییلہِ نیک پنہٕ نِس نیکی نِش پتھ پھیرِ، تہٕ بدکار سُند انجام دِنہٕ آمٕژ سارِنٕے مُطٲبِق کرِ سُہ زِندٕ؟ تٔمۍ سٕندِس سارِنٕے نیکی ہُند ذِکر گژھِ نہٕ کرنہٕ: یُس تٔمۍ سٕندِس گناہ سٍتـ̡ تہٕ یُس گۅناہ کورمُت چُھ، تِمن مَنٛز گژھہِ سُہ مرُن۔\n25.\\tتوتہِ چُھہ تُہۍ ونان زِ خداوند سُند وتھ چُھنہٕ برابر۔ اے اسرٲیلُک گرٕ بوزو، کیا میٲنۍ وتھ چھا نہٕ برابر؟ کیا چُھنہٕ تُہٕندِ وَتہٕ غٲر مساوی؟\n26. یێلہِ اَکھ نیک انسان پَنٕنہِ نیکی نِش پتھ پھِرِتھ تہٕ بدکاری کٔرِتھ تہٕ تِمن مَنٛز مرُن۔ تٔمۍ سٕندِ بدکار سٍتـ̡ یُس تٔمۍ کٔرمُت چُھ، سُہ گژھہِ مرُن۔\n27.\\tبییہِ ییلہ بدکار انسان پننہِ بدکاری نِش پتھ پھیرِ، تہٕ یُس حلال تہٕ صحیح کٲم کرِ، سُہ کرِ پنُن روح زندٕ۔\n28.\\tکیازِ سُہ چُھ غور کران تہٕ پنہٕ نِس سارِنٕے خطامن نِش پتھ کُن روزِ، سُہ روزِ نہٕ زندٕ۔\n29. توتہِ چُھ اسرٲیلِک گرٕ ونان زِ خداوند سُند وتھ چُھنہٕ برابر۔ اے اِسرٲیلٕکۍ گرٕ، کیا میٲنۍ وتہٕ چھا نہٕ برابر؟ کیا چُھنہٕ تُہٕندِ وَتہٕ غٲر مساوی؟\n30. تێمہِ کِنۍ کٔرٕ بہٕ تُہُند فیصلہٕ، اے اِسرٲیلِیُک گر، پرٮ۪تھ کانٛہہ چُھ پننہِ طٔریٖقہٕ مُطٲبِق، خداوند خدا چُھ فرماوان۔ توبہ کٔرِو، تہٕ پَنٕنـ̡ سارِنٕے گناہ نِش پھیُرِو۔ لہذا گژھہِ نہ بدکاری تۅہہِ برباد۔ {تم پانے: یا، باقی}\n31. پَنٕنہِ سارِنٕے گناہ کٔرِو پانس نِش، یِمو سٍتـ̡ تۅہہِ سٍتـ̡ کٔرِو پَنٕنـ̡ سٍتـ̡ دِنہٕ آمُ تہٕ بنوو ژے اکھ نوٚو دِل تہٕ اکھ نوٚو روح: کیازِ ژے مرُن، اے اسرٲیلُک گرٕ؟\n32. یێلہِ چُھہ نہٕ میہ تٔمِس سٕندِس مرنس سٍتـ̡ کانہہ خۅش سپدان یُس خداوند خدا چُھ ونان چُھ: تێلہِ پھیرِو تہٕ زندٕ روزُن۔ {تم پانے: یا، باقی}","1. امہِ علاوہ کرو اسرٲیلکۍ شہزادن ہٕندِ خٲطرٕ اکھ ماتم\n2.\\tتہِ ونو تہنز موج کیا چھیہ؟ اکھ شیرہ: سۄ لٔگۍ شیرن منٛز، تٔمۍ کٔر پننین بچن جوان شیرن منٛز۔\n3.\\tتہٕ تٔمۍ پرورش پنُن اکھ بچہٕ: یہِ بنیوو اکھ جوان شیر، تہٕ أمِس ہیٚچھُن شِکارس رَٹُن۔ یہ اوس انسان کھیوان۔\n4. قومن تہِ بوز تٔمِس سٍتـ̡ ۔ سُہ آو تِہندِس کھۅنہِ منز نِنہٕ، تہٕ تِمو أنِکھ سُہ زنجیر ہیتھ مصرٕکِس سرزمینس منز۔\n5.\\tوۅنۍ ییلہ أمس وُچھ زِ أمس ٲس انتظار کٔرمٕژ، {تہٕ}أمس ٲس وۅمید ختم گٔمٕژ، تمہ پتہٕ نیو تٔمۍ پنُن بیاکھ بچہٕ، {تہٕ} بنوو أمس اکھ جوان شیر۔\n6.\\tتہٕ سُہ گوٚو شیرن منز ہیوٚر بوٚن، سُہ بنیوو اکھ جوان شیر، تہٕ ہیوچھُن شِکار رَٹُن، {تہٕ} کھٮ۪وان انسان۔\n7.\\tتہٕ سُہ اوس تِہٕندِس ویران محلس زانان، تہٕ تِمن ہٕندِس شہر تباہ کٔرِتھ۔ تہٕ زمین ٲس ویران تہٕ اَمہ سٕنزِ گُرجہِ ہٕندِس شورس سٍتۍ۔ {تہنز ویران ...: یا، تہنز بیواہ } {مکمل آسن...: یا، اتھ منز چھہ سورے موجود}\n8. تمہ پتہ لوٚگ قومن صوبو پیٹھہ پریتھ طرفہ أمس خلاف تہ پھہلٲوکھ أمس پیٹھ پنُن جال۔\n9. تہٕ تِمو تھووُکھ سُہ زنجیرن منز تہٕ أنِن بابل کِس بادشاہس نِش۔ تِمو أنِن سُہ رٔٹِتھ یُتھ زِ تٔمۍ سٕنز آواز گژھہِ نہٕ اسرٲیلِہ کِس پہاڑن پیٹھ بوزنہٕ۔ {زنجیرن منز: یا، ہکس منز}\n10.\\tچانۍ موج چھیہ تۅہہِ ہندس خونس منز بیل ہیو یُس آبس سٍتۍ ووتمُت اوس، سۅ ٲس پھل دار تہٕ واریاہ آبہٕ آسنہ کِنۍ بٔرِتھ۔ {منز...: یا، پننہِ خاموشی منز، یا، پننہِ شکلہِ منز}\n11.\\tتہٕ أمِس آسہٕ تِمن ہٕندِس لٔرِس خٲطرٕ مضبوٗط لورِ یِم حُکوٗمت ٲسۍ، تہٕ تٔمۍ سُند قد اوس گٔنِس لنجہِ منز تھزرس منز، تہٕ سۅ ٲس پننِس تھزرس منز پنٕنۍ لنجہِ ہٕندِس بٔڈِس سٍتۍ ظٲہر سپدان۔\n12.\\tمگر سۅ گٔیہِ شرارتس منز تُلنہٕ، سۅ آیہ زمینس پیٹھ تراونہٕ، تہٕ مشرِقی واو کٔر تٔمۍ سٕندِ مٮ۪وٕ ہۄکھ: تٔمۍ سٕنزِ مضبوٗط لٔر پھُٹمٕژ تہٕ مرزاونہٕ آمٕژ۔ نارن کھیوٚو تِم کھٮ۪وان۔\n13.\\tتہٕ وۅنۍ چھے سۅ بیابانن منز، خشک تہٕ ترشیہ زمینس منز ووتمٕژ۔\n14.\\tتہٕ چُھہ تٔمۍ سٕنزِ لنجہِ ہٕنزِ لٔرِ منزٕ نار نیران، یُس أمِس مٮ۪وٕ کھٮ۪وان چُھ، یُتھ أمِس چُھنہٕ کانہہ مضبوٗط لٔر بٔنِتھ حکمرٲنی کرنہٕ خٲطرٕ۔ یہ {چھُ} اکھ ماتم تہٕ ماتم خٲطرٕ آسہِ۔","1. تہٕ سپُد سٔتِم ؤریس مَنٛز، پوٗنٛژمِس ریتس مَنٛز، دٔہمہِ دۅہہٕ، یُس اسرٲیلٕکۍ کینہہ بزرگ آیہِ خداوند سٕندِس پرژھہٕ گٲر کرنہٕ خٲطرٕ، تہٕ بیوٹھ میانہِ برونہہ کُن۔\n2. اَمہِ پَتہٕ آو خداوند سُند کلام یُس میہ وَنُن چُھ،\n3. اِنسان سٕندِس بُزرگ سٍتـ̡ کتھ کرٕن، تہٕ تِمن وَنُن چُھہ یِتھٕ پٲٹھـ̡ خداوند خدا چُھہ فرماوان۔ ژیہ چھکھ میہ پرژھہ گار کرنہِ آمت؟ {As} بہٕ چُھس زندٕ، خداوند خدا چُھ ونان، بہٕ چُھس نہٕ ژےٚ پرژھہٕ گٲر کٔرِتھ۔\n4. کیا ژٕ کٔرِکھ تِمن ہُند فٲصلہٕ، کیا ژٕ کٔرِکھ تِمن ہُند فٲصلہٕ؟ تِمن کٔرِو پننین مٲلن ہٕنزِ مکروہ ہٕنز زان: {وِلٹ...: یا، تِمن ہٕندِ خٲطرٕ کٔرِو تِمن ہٕندِ خٲطرٕ التجا کرنہٕ}\n5. تہٕ تِمن وَنُن یِتھٕ پٲٹھۍ چُھ خداوند خدا فرماوان۔ ییمہِ دۅہہ میہ اسرٲیلُک انتخاب کوٚر، تہٕ یعقوب سٕندِس گرٕ کِس بیولس کُن پنُن اتھہٕ تُل، تہٕ مصر کِس سرزمینس مَنٛز تِمن سٍتـ̡ پنُن پان تُلُن، ییلہ میہ تِمن کُن پنُن اتھہٕ تُلِتھ وونُن، بہٕ چُھس خداوند تُہند خدا۔ {تُلتھ...: یا، قسم}\n6.\\tییمہِ دۅہہ تُل میہ تِمن کُن اتھہ تُل، تِمن مصر چہ سرزمینہٕ منزٕ تِمن ہٕندِ خٲطرٕ جاسوسی کٔرِتھ، یُس دۄد تہٕ ماچھ سٍتـ̡ وسان اوس، یُس سارِنٕے زمینن ہُند جلال چھُ:\n7. تێمہِ وۆن میہ تِمن زِ پرٮ۪تھ أکِس انسانس کٔرِو تٔمۍ سٕنزِ أچھن ہٕنزِ ناپاک تہٕ پان کٔرِو نہٕ مصرٕکۍ بُتَو سٍتـ̡ ناپاک کرنہٕ: بہٕ چُھس خداوند تُہند خدا۔\n8.\\tمگر تِمو کٔر میہ خلاف بغاوت، تہٕ کٔرٕکھ نہٕ میانہِ کتھہِ بوزُن: تِمو کٔر نہٕ پرٮ۪تھ کٲنسہ انسانس پنہٕ نِس أچھن ہٕنزِ مُشکِل، تہٕ نہ کٔر تِمو مصرٕکۍ بُت ترٲومٕتۍ، تێلہِ ووٚن بہٕ تِمن پیٹھ پنُن غصہٕ تراوُن، یُس مصر کِس سرزمینس مَنٛز تِمن خلاف پنُن غصہٕ دوٗر کٔرِتھ۔\n9.\\tمگر میہ کٔر پننہِ ناوٕ خٲطرٕ زِ یہ گژھِ نہٕ کافرن برونہہ کُن آلودہ سپدُن، یِمن منز تِم ٲسۍ، یِمن ہٕندِس نظرِ مَنٛز مے تِمن سٍتـ̡ پانس سٍتـ̡ ظٲہر کورمُت، یێمہِ سٍتـ̡ یِمن سٍتـ̡ مصر کِس سرزمینہٕ سٍتـ̡ نٮ۪بر کڈنہٕ مۅکھہٕ۔\n10. اَمہِ مۄکھٕ دِژ مے تِم مصرٕکہِ سرزمینہٕ منزٕ نٮ۪بر تہٕ أنِتھ بیابانن مَنٛز۔\n11.\\tتہٕ مے دِژ تِمن پنٕنۍ قونوٗن، تہٕ ہٲومُت پنٕنۍ فیصلہٕ، یُس {یێلہ} انسان کرِ، سُہ گژھہِ تِمن مَنٛز تہِ روزُن۔ {ہٲوۍ...: ہیب۔ تمن زاننہٕ خٲطرٕ بنوو}\n12. امہِ علاوٕ دِژ میہ تِمن پنُن سبت تہِ، یُس میانہِ تہٕ تِمن درمِیان اکھ نشانہٕ بٔنِتھ، یُس تِمن ہٕندِس پاکیزگی سٍتـ̡ چُھس یُس تِمن پاک کران چُھس۔\n13.\\tمگر اِسرٲیلٕکۍ گرن کٔر بیابانن مَنٛز میانہِ خلاف بغاوت: تِمو کٔر نہٕ میانین حکمن مَنٛز پکان تہٕ تِمو کٔر میانین فٲصلن سٍتـ̡ حقارت کرنہٕ، یُس {یێلہ} انسان کرِ، سُہ گژھہِ تمن مَنٛز تہِ روزُن۔ تہٕ میانہِ سبت کٔر تِمو سٮ۪ٹھاہ آلودٕ: پتہٕ ووٚنمُت، بہٕ تراوٕ تِمن پیٹھ بیابانن مَنٛز پنُن غصہٕ، یِمن کھٮ۪نہٕ خٲطرٕ۔\n14.\\tمگر میہ کٔر پننہِ ناوٕ خٲطرٕ زِ یہِ گژھِ نہٕ کافرن برونہہ کُن آلودہ کرنہٕ، یٔمۍ سٕندِس نظرس منز مے تِم نیبر کٔرۍ۔\n15. توتہِ تُل میہ بیابانس منز تِمن کُن اتھہ، زِ بہٕ اَننہٕ تِمن تتھ زمینس مَنٛز یُس میہ دِژمُت اوس، یُس دۄد تہٕ ماچھ سٍتۍ وسان اوس، یُس سارِنٕے زمینن ہُند جلال چھُ۔\n16.\\tتکیازِ تِمو کٔر میانین فٲصلن سٍتـ̡ حقارت تہٕ میانین قونونن منز پکان نہٕ، بلکہ کٔرٕکھ میانہِ سبت ناپاک: تکیازِ تِہند دِل اوس پننین بتن ہٕندِس پَتہٕ پَتہٕ۔\n17. بہر حال میانہِ أچھ بچٲو تِم تباہ کرنہٕ نِش، تہٕ نہ کٔر مے تِمن بیابانن منز ختم۔\n18.\\tمگر میہ ووٚن بیابانس منز تِہندین شُرین زِ تم گژھ نہ پننین مٲلن ہٕندِس حکمس مَنٛز پٔکِتھ، نہ تہندِس فٲصلس پیٹھ عمل کرُن، تہٕ نہ کرو پنن پان تِہندیو بُتن سٍتـ̡ ناپاک کرنہٕ۔\n19. بہٕ چُھس خداوند تُہند خدا۔ میانین قونونن منز پکُن، تہٕ میٲنۍ فیصلہٕ تھاوُن، تہٕ تم کرٕن؛\n20. تہٕ میٲنۍ سبت مقدس کرُن۔ تہٕ یِم گژھن میانہِ تہٕ تۅہہِ درمِیان اکھ نشانہٕ، یُتھ ژے زانہِ زِ بہٕ چُھس خداوند تُہند خدا۔\n21. باوجوٗد تہِ کٔر شُرۍ میانہِ خلاف بغاوت: تِم ٲسۍ نہٕ میانین قونونن مَنٛز پکان تہٕ نہ کٔرٕکھ میٲنۍ فٲصلہٕ تہٕ یِمن ہٕندِس فٲصلس مَنٛز روزُن، یُس {یێلہِ} انسان کرِ، سُہ روزِ تِمن مَنٛز تہِ۔ تِمو کٔر میٲنۍ سبت آلودہ تہٕ پتہٕ ووٚنمُت، بہٕ تراوٕ تمن پیٹھ پنُن غصہٕ، تاکہ بیابانن منٛز تمن خلاف پنُن غصہٕ پورٕ کرنہٕ۔\n22.\\tبہر حال کٔر میہ پنُن اتھہ واپس، تہٕ پننہ ناوٕ خٲطرٕ کورُن یہ کتھ زِ یہ گژھہِ نہ کافرن ہٕندِس نظرس منز آلودہ کرنہٕ، یمۍ سٕندِس نظرس منز میہ تم برونہہ کُن انۍ۔\n23.\\tمیہ تُل بیابانن منز تہِ تِمن کُن اتھہٕ تُل، زِ بہٕ کرٕ تِم کافرن مَنٛز پھٔٹِتھ تہٕ یِم مُلکن مَنٛز منتشر کٔرِتھ۔\n24.\\tکیازِ تِمو اوس نہٕ میانہِ فٲصلن پیٹھ عمل کٔرمٕتۍ، بلکہ ٲسۍ میانین قونونن حقارت کٔرمٕژ، تہٕ میٲنۍ سبت ٲس آلودہ کٔرمٕژ، تہٕ تِہنز نظر ٲس پننین مٲلن ہٕندِس بُتن پَتہٕ۔\n25. اَمہِ مۄکھٕ دِژ مے تِمن قونوٗن تہٕ یِم نہٕ اصل ٲسۍ، تہٕ یِم فٲصلہٕ تہٕ یِم نہٕ زِندٕ روزٕنۍ۔\n26. تہٕ مے کٔر تِمن پننین تحفن مَنٛز آلودہ کرنہٕ، یتھ مَنٛز تِمو دِژ سارِنٕے نارس مٔنزۍ یُس رحم کھولان چُھ، یُتھ بہٕ کرٕ تِمن ویران کرنہٕ، یُس تِمن پتاہ گژھہِ زِ بہٕ چُھس خداوند چُھس۔\n27. تێمہِ کِنۍ، اِنسانہٕ سٕندِس بُتھِس سٍتـ̡ کتھ کرٕن، تہٕ تِمن وَنُن یِتھٕ پٲٹھـ̡ خداوند خدا چُھ فرماوان۔ توتہِ چُھہ اتھ منز چُھہ چُھہ چُھہ میہ سٍتـ̡ بے عزتی کٔرمٕژ، یێلہِ چُھہ تِمو میانہِ خلاف زیادتی کٔرمٕژ۔ {کمیٹڈ...: ہیب۔ ناجائز قبضہ کرُن}\n28.\\t{تکیازِ}ییلہ میہ تِم زمینس مَنٛز أنِمُت، {تکیازِ} یُس میہ تِمن دِنہٕ خٲطرٕ پنُن اتھہٕ تُلِتھ، تِمو وُچھ پرٮ۪تھ تھدِ بالہٕ تہٕ سٲری گٔنۍ کُلۍ، تہٕ تِمو کٔر تتہِ پنٕنۍ قربانی پیش تہٕ تتہِ کٔر تِمو پنٕنۍ مٔٹھۍ مَزٕ،  تہٕ ترووُن تتہِ پنٕنۍ شرابٕچ پیشکش۔\n29.\\tاَمہ پتہٕ وون میہ تِمن زِ سُہ کُس تھدِ مقام چھُ؟ تہٕ اَمیُک ناو چُھ از تام بامہ ونان۔ {میہ ووٚن...: یا، میہ ووٚن تمن تھدِ جایہ کیا چھہ، یا، باماہ}\n30. تێلہِ چُھہ یێلہِ اِسرٲیلِس کُن وَنُن، یِتھٕ پٲٹھـ̡ چُھ خداوند خدا فرماوان۔ کیا تُہۍ چھوا پننین مٲلن ہٕندِس طریقس پیٹھ آلودہ گٔمٕتۍ؟ تہٕ تِمن ہٕندِس مکروہ پتہٕ کٔرِو طریٖقہٕ؟\n31. یێلہِ تہٕ یێلہِ تہٕ پَنٕنـ̡ بُتـ̡ دِوان چھِو، تێلہِ چُھہ از تام پَنٕنـ̡ سارِنٕے بُتـ̡ سٍتـ̡ پَنُن پان آلودہ کَران۔ {As} بہٕ چُھس زندٕ، خداوند خدا چُھ ونان، بہٕ چُھس نہٕ ژےٚ پرژھہٕ گٲر کٔرِتھ۔\n32. تہٕ یُس تہٕ تُہٕندِس ذہنس مَنٛز یِیہِ سُہ گژھِ نہٕ آسُن، یُس تہٕ تۅہہِ وَنُن چھُ، أسۍ بٔنِو مُلکن ہٕندِس خاندانن ہٕندِس پٲٹھۍ، لٔکرِ تہٕ کٔنـ̡ خدمت کرنہٕ خٲطرٕ۔\n33. خداوند خدا چُھس ونان زِ بہٕ چُھس زِندٕ روزان، یٔقیٖنی طور أکِس طاقتور اتھہٕ سٍتـ̡ تہٕ نٔر پھٔہلٲوِتھ تہٕ غصہٕ سٍتـ̡ بہٕ چُھس ژے پیٹھ حکمرٲنی کٔرِتھ:\n34. تہٕ بہٕ کٔرٕ ژےٚ لُکہٕ نِش نٮ۪بر تہٕ ژےٚ تِمن ملکَن نِش جمع کٔرِتھ یِمن مَنٛز ژٔٹِتھ تہٕ نٔر پھٔہلِتھ تہٕ غصہٕ سٍتـ̡ ژٔلِتھ ۔\n35.\\tتہٕ بہٕ اَننہٕ ژےٚ لُکن ہٕندِس بیابانس مَنٛز، تہٕ اَتہِ کَرٕ بہٕ ژےٚ برٛۄنٛہہ کُن التجا کرنہٕ۔\n36. یِتھ کٔنۍ میہ مصر کِس بیابانس مَنٛز تہندٮ۪ن آباؤ اجدادن سٍتـ̡ التجا کٔر، تِتھے کٔنۍ کٔرٕ بہٕ ژے سٍتـ̡ التجا کرنہٕ، خداوند خدا چُھ فرماوان۔\n37. تہٕ بہٕ کرٕ ژے لوڑِ تَل نیرُن، تہٕ بہٕ اَننہٕ ژے عہد کِس بندس مَنٛز: {بند: یا، نجات دِنہٕ}\n38.\\tتہٕ بہٕ کٔرٕ تم یِمن مَنٛز باغی تہٕ یِم میانہِ خلاف زیادتی کران چھِ، بہٕ کٔرٕ تِم تِمن ملکہٕ منزٕ نٮ۪بر نیرِتھ یتہِ تِم روزان چھِ، تہٕ تِم گژھن نہٕ اسرٲیلِس مَنٛز اژنہٕ۔\n39.\\tیێلہِ چُھہ تۅہہِ اے اسرٲیلُک گھر، یێلہِ چُھہ خداوند خدایہ فرماوان۔ یێلہِ گژھِو تٔمۍ سٕندِس بُتـ̡ سٍتـ̡ پٲٹھـ̡ تہٕ یێلہِ تہِ کٔرِو نہٕ میانہِ کتھہِ سٍتـ̡ تہٕ یێلہِ تہِ کٔرِو میٲنۍ مقدس ناو پنہٕ نِس تحفہٕ سٍتـ̡ تہٕ پنہٕ نـ̡ بُتـ̡ سٍتـ̡ ناپاک ناو۔\n40.\\tکیازِ میٲنِس مقدس پہاڑس منز، اسرٲیلِک تھزرس مَنٛز، خداوند خدایہ چُھ ونان زِ اَتھ مَنٛز گژھن سارِنٕے اِسرٲیلِیُک گر، یِم سارِوٕے زمینس مَنٛز، میانہِ خدمت کَرٕن: اَتہِ کَرٕ بہٕ تِم قبوٗل، تہٕ تتہِ کرٕ بہٕ چانہِ نذرانہٕ تہٕ تُہٕنزِ نذرانہٕ ہٕندِس گۄڈنِکِس پھلٕچ ضرورت، چانہِ سارِنٕے مُقدس چیزن سٍتـ̡ ۔ {فرسٹ فروٹس: یا، چیف}\n41.\\tبہٕ کٔرٕ ژے چانہِ مٔدٕر مَزٕ سٍتـ̡ قبول، یێلہِ بہٕ ژے لُکہٕ نِش نٮ۪بر کٔرِتھ تہٕ تِمن ملکَن نِش نِش نِش یِمن مَنٛز ژےٚ بٔرِتھ چھِو۔ تہٕ بہٕ گژھہٕ ژے منز کافرن برونہہ کُن پاک۔ {مٔٹھۍ...: ہیب۔ آرامُک مزہ چُھ}\n42.\\tتہٕ ژیہ گژھہِ پتاہ زِ بہٕ چُھس خداوند چُھس، یێلہِ بہٕ ژے اسرٲیلِس مَنٛز، تتھ ملکس مَنٛز یُس میہ تُلِتھ تُلِتھ تہٕ تُہٕندِس مٲلِس دِنہٕ مۅکھہٕ۔\n43. تہٕ تَتہِ گژھِو پَنٕنـ̡ وَتہٕ تہٕ پَنٕنـ̡ سارِنٕے کامہِ یاد پٲٹھـ̡ یِمن مَنٛز تۅہہِ ناپاک گٔمٕژ چھِ۔ تہٕ تُہۍ کٔرِو پننین سارِنٕے بُرائین ہٕندِس سٍتـ̡ پننِس نظرس سٍتـ̡ لوکھ۔\n44. تہٕ یێلہِ چُھہ تێلہِ پتاہ زِ بہٕ چُھس خداوند چُھہ، یێلہِ بہٕ چُھس پننہِ ناوٕ خٲطرٕ تہٕ تێہٕنزِ بدکار عملہٕ مطٲبق تہٕ تێہٕنزِ بدکار عملہٕ مطٲبق، اے اسرٲیلِکِس گھرس مُطٲبق، خداوند خدا چُھ فرماوان۔\n45.\\tامہِ علاوہ آو رب سُند کلام میانہِ نِش وونُن،\n46.\\tانسان سٕندِس پَنُن بُتھ جنوبس کُن تھووُن، تہٕ پَنُن کلام تراوُن جنوبس کُن، تہٕ کٔرِو جنوُب کِس جنگلس خلاف پیشن گوئی۔\n47.\\tتہٕ وَنُن جنوُب کِس جنگلَس مَنٛز، خداوند سُند کلام بوزو۔ یِتھٕ پٲٹھـ̡ چُھ خداوند خدا فرماوان۔ وچھ بہٕ ژے منز نار زال، تہٕ سُہ کھیٚیہِ ژے منز موجود پرٮ۪تھ سبز کُلِس تہٕ پرٮ۪تھ خۄشٕک کُلِس کھٮ۪یہِ: نار گژھِ نہٕ ژھیتہٕ تہٕ جنوبٕ پیٹھٕ شمالس تام سارِنٕے بُتھ یِن اَتھ منز زالنہٕ۔\n48.\\tتہٕ سارِنٕے ماز وُچھِن زِ میہ چُھس خداوند سٍتـ̡ یہ دِژمُت: یہِ گژھہِ نہٕ ژٔٹِتھ ۔\n49. اَمہ پتہٕ ووٚن مے، اے خدا! تِم چھِ میانہِ مُتلق ونان زِ سُہ چھُنہٕ تمثیلہٕ بولان؟","1. تہٕ خداوند سُند کلام آو میہ نِش،\n2. اِنسان سٕندِس فرزندس کُن پھِرُن پَنُن بُتھ یروشلمس کُن، تہٕ پَنُن کلام تراوُن مُقدس مقامن کُن، تہٕ اسرٲیلِچ سرزمینس سٍتـ̡ پیشن گویی کرُن،\n3. تہٕ وَنُن زِ اِسرٲیلِس مَنٛز وَنُن، یِتھٕ پٲٹھؠ چُھ خداوند فرماوان۔ وچھ بہٕ چُھس ژے خلاف، تہٕ پنٕنۍ تلوار تٔمۍ سٕنزِ چادرٕ منزٕ کٔڈِتھ تہٕ ژے نِش کرٕ نیک تہٕ بدکار ژٹان۔\n4. تیلہِ وُچھِتھ زِ بہٕ ژے نِش نیک تہٕ بدکار ژٹِتھ، تێمہِ مۅکھہ گژھہِ میٲنۍ تلوار تٔمۍ سٕنزِ کھالہٕ منزٕ جنوبٕ پیٹھٕ شمالس تام سارنٕے مازس خٕلاف نیرِ۔\n5. یُتھ سارِنٕے ماز گژھہِ پتاہ زِ میہ چھُ خداوند پنٕنۍ تلوار پننہِ چادرٕ منزٕ کٔڈمٕژ: سُہ گژھِ نہٕ وُنہٕ واپس۔\n6. تَمہِ کِنۍ کرو اے انسان سٕندِس نیچو، پۯاوٕنـ̡ پۯاوٕنـ̡ ہٕندِس کمرس سٍتـ̡ تہ تلخی سان چھہ یمن ہنزن اچھن برونہہ کنہِ آہ کران۔\n7.\\tتہِ گژھہِ ییلہ تۅہہِ ونان چھہِ، ژیہ کیازِ چُھہ شہہ دوان۔ تہٕ ژے دِیُن جواب، خبرن خٲطرٕ؛ کیازِ یہِ چُھ یِوان: تہٕ پرٮ۪تھ دِل گٔیہِ پَلہٕ، تہٕ سارِنٕے اتھہٕ گژھن کمزور، تہٕ پرٮ۪تھ کُنہِ روح گژھہِ کمزور، تہٕ سارِنٕے کۅٹھہٕ گژھن کمزور گٔژھِتھ آبہٕ: وُچھ، یہِ چُھ یِوان، تہٕ یِیہِ سپدِ، خداوند خدا چُھ فرماوان۔ {گژھِ کمزور...: ہیب۔ آبس منز گژھُن}\n8. بییہِ آو رب سُند کلام میہ نِش وونُن،\n9. اِنسان سُند فرزند، نبوت کٔرِو تہٕ وَنُن، یِتھٕ پٲٹھـ̡ چُھ خداوند فرماوان۔ ونو تلوار، تلوار چھیہ تیز، تہ تلوار تہِ چھیہ تیز۔\n10.\\tیہ چھہ ذبح کرنہ خاطرہ تیز۔ یہ چھہ فربش کرنہ آمت زِ یہ گژھہِ چمک: تیلہ کیا اسہِ پزیا مسکراہ؟ یہ چھہ میٲنس نیچوۍ سٕنزِ لٔرِس سٍتـ̡ تہٕ پرٮ۪تھ کُلِس سٍتـ̡ سٍتـ̡ دِنہٕ آمُت۔ {یہ چھہ کُلِس حقارت کران...: یا، یہ چھہ میانہِ نیچوۍ سنز لاٹھ، یہ چھہ پریتھ کُلِس حقارت کران}\n11.\\tتہٕ أمِس دِژ یہِ سٍتـ̡ دِنہٕ یِنہٕ خٲطرٕ، یێلہِ یہِ تلوار چُھہ تیز کرنہٕ آمُت، تہٕ یہِ چُھہ مَضموٗن ہٕندِس اتھس مَنٛز دِنہٕ آمُت۔\n12.\\tکٔرِو تہٕ کرٛٮ۪کہٕ دِن، یُس میانہِ لُکہٕ سٍتـ̡ آسہِ، یێلہِ گژھہِ میانہِ لُکہٕ سٍتـ̡ دِنہٕ آمُت، تێلہِ گژھہِ تێلہِ ژٔٹِھس پیٹھ۔ {دہشت ...: یا، تم چھہِ میانین لوکن سیتۍ تلوارس پیٹھ تراونہ آمت}\n13.\\tکیازِ {یہِ} چھُ اکھ آزمائش، تہٕ اگر {تلوار} لٔرِس تہِ دِیہِ؟ خداوند خدا چُھ ونان زِ یہِ گژھِ نہٕ {زیادٕ} آسُن۔ {کیازِ...: یا، ییلہ مقدمہ سپدِ، تیلہِ کیا چُھ؟ کیا تِم تہِ آسن حقارت کرن وٲلِس لٔرِس سٍتۍ؟}\n14. تێمہِ کِنۍ، انسان سٕندِس فرزند، پیشن گویی کٔرِو تہٕ پنہٕ نِس اتھہٕ رلٲوِتھ تہٕ تریمہِ لٹہِ گژھہِ تلوار دۄگنہٕ کرنہٕ، مقتول سٕنز تلوار: یہِ چُھہ بٔڈِس {انسان} سٕنز تلوار یُس تِہندِس خانس مَنٛز اژان چُھ۔ {اتھہٕ...: ہیب۔ اتھہٕ سۭتۍ اتھہٕ}\n15. مے چُھ تلوارُک نوک تِہندِ سارِنٕے دروازس پیٹھ تھوومُت، یُتھ {تِہُند} دِل گژھہِ بیہوش، تہٕ {تِہُند} کھنڈرات گژھن ضرب کرنہٕ: آہ! {یہِ} چُھ چمکاونہٕ آمُت، {یہٕ چُھ} ذبح کرنہٕ خٲطرٕ ؤلِتھ۔ {پوائنٹ: یا، چمک، یا، خوف} {لٔپِتھ: یا، تیز}\n16.\\tژیہ گژھ اَکہِ طرفہٕ {یا تہ} دچھنہِ طرفہٕ، {یا}کھوورِ طرفہٕ، ییتہِ تہِ تُہند بُتھ {آسہِ}۔ {یا پیٹھ...: ہیب۔ پان سیٹ کٔرِو، کھوورِ اتھہٕ رٔٹِو}\n17.\\tبہٕ کٔرٕ پننین اتھن تہِ رٔلِتھ تہٕ بہٕ کٔرٕ پنُن غصہٕ رُکاونہٕ: میہ چُھہ خداوند ووٚنمُت۔\n18.\\tخداوند سُند کلام آو میہ نِش دُبارٕ وونُن،\n19. اے انسان سٕندِ نیچو، ژے کٔرِو زٕ وتہٕ مُقرر یُتھ بابل کِس بادشاہ سٕنز تلوار ییہِ یِنہٕ: دۅشوے یِن أکِس زمینہٕ منزٕ نیرٕن: تہٕ ژٲرِکھ اکھ جاے تہٕ ژٲرِو شہرٕچ وتہِ ہٕندِس سرس پیٹھ۔\n20.\\tاکھ وتھ مقرر کرُن، یُتھ تلوار عمونین ہٕندِس ربتس تہٕ یروشلمس مَنٛز یہوداہ کِس دفاع کِس بارس تام واتہِ۔\n21.\\tبابل ہُند بادشاہ اوس وتہِ ہٕندِس الگ گژھنس پیٹھ کھڑا، دۅن وتن ہٕندِس سرس پیٹھ، خدایہ ورتاونہٕ خٲطرٕ: تٔمۍ کٔر تیر چمک، تٔمۍ کٔر تصویرن سٍتـ̡ مشورٕ، تٔمۍ کٔر جگرس مَنٛز نظر۔ {پار کٔرِتھ: ہیب۔ موج} {تیر: یا، چاقو} {تصویر: ہیب۔ ٹیرافیم}\n22. تٔمۍ سٕندِس دچھنہِ اتھس پیٹھ اوس یروشلمُک خدا، کپتان مقرر کرنہٕ خٲطرٕ، ذبح کرنہٕ خٲطرٕ ٲس ٲس کھولنہٕ، کرٛٮ۪کہٕ دِتھ آواز تُلنہٕ، دروازن پیٹھ مینڈٕ مقرر کرنہٕ، پہاڑ تراوُن، {تہٕ} قلعہ بناونہٕ خٲطرٕ۔ {کپتان: یا، بیٹرنگ ریمس: ہیب۔ ریمس}\n23.\\tتہٕ یِمن ہٕندِ نظرِ ہٕندِس نظرس منز گژھہِ یہ اپُز خدا، یِمن ہٕندِ خٲطرٕ حلف کھٲلِتھ آسہِ، مگر سُہ کرِ بدکاری یاد پاونہٕ خٲطرٕ، یُتھ زن تِم یِن نِنہٕ۔ {تمن خٲطرٕ...: یا، تمن سۭتۍ کرنہٕ آمٕتۍ قسمہٕ خٲطرٕ}\n24. تێمہِ کِنۍ چُھ خداوند خدایہ یِتھٕ پٲٹھۍ وَنان۔ تِکیازِ تۅہہ چُھہ پَنٕنـ̡ گناہ یاد تھاونہٕ خٲطرٕ بنوومُت، تێلہِ چُھہ تُہٕندِس سارِنٕے کامہِ سٍتـ̡ تُہٕندِس گناہ سٍتـ̡ ظٲہر سپدان۔ کیازِ، {بہٕ چُھس ونان}، زِ تہۍ چھِو یاد کرنہٕ خٲطرٕ آمٕتۍ، تہٕ یِن اتھہٕ سٍتۍ نِنہٕ۔\n25.\\tتہٕ تُہ، اسرٲیلُک بدکار شہزادہ، یٔمۍ سُند دۅہ آو یێمہِ سٍتـ̡ بدکاری سپدِ،\n26. یِتھٕ پٲٹھۍ چُھ خداوند خدا فرماوان۔ تاج ہٹٲوِتھ تُلِو تاج: یہ {sham} کرِ نہ {یُس} ہُے آسُن: تھزرٲوِتھ {سُہ یُس} یُس بوٚن چُھ، تہٕ اَبد کٔرِتھ {سُہ یُس} تھوٚد چھُ۔\n27.\\tبہٕ کرٕ یہ الٹُن، الٹٲوِتھ، الٹٲوِتھ، تہٕ یہ گژھہِ نہٕ توٚت تام زِ سُہ ییہ یُس حق آسہِ۔ تہٕ بہٕ دِیہ یہ {أمس}۔ {بہٕ کرٕ الٹ...: ہیب۔ بگاڑ، بگاڑ، بگاڑ، کیا بہٕ بناوٕ یہ}\n28. تہٕ تو، انسان سٕندِس نیٚچو، پیشن گویی کٔرِو تہٕ وَنُن، یِتھٕ پٲٹھۍ چُھ خداوند خدایہِ عمونیتس مُتعلِق تہٕ تِہٕنزِ ملامت مُتعلِق وَنان۔ توے تہِ ونو تلوار، تلوار {چُھ} کڈنہٕ آمُت: ذبح کرنہٕ خٲطرٕ {یہ} چُھہ چمک دِنہٕ خٲطرٕ:\n29.\\tییلہ تِم تۅہہِ نِش باطل وُچھان چھِ، یێلہِ تِم تۅہہِ سٍتـ̡ اپُز دِوان چھِ، یێلہِ تِمن ہٕندِس گُنِس پیٹھ مارنہٕ آمُت چھُ، یێمہِ سُند دۅہ آو یێلہِ تِہُند گُناہ ختم سپدِ۔\n30.\\tبہٕ کرٕ یہ تہندس چالس منز واپس؟ بہٕ کَرٕ تۅہہِ سُند فیصلہ تتھ جایہِ یتہِ ژے تخلیق کرنہٕ آمُت چھُ، پننہِ پٲدٲیشی سرزمینس منز۔ {شُل...: یا، کٔرِو یہِ واپس}\n31. تہٕ بہٕ تراوٕ ژے پیٹھ پنُن غصہٕ، بہٕ دِیہٕ ژے خلاف پننہِ قہر کِس نارس منٛز، تہٕ ژے دِیہٕ وحشی نفرن ہٕندِس اتھس منٛز، {تہٕ} تباہ کرنہٕ خٲطرٕ ہنرمند۔ {بروٹش: یا، دزان}\n32. تہٕ ژے گژھ نارس خٲطرٕ تیٖل دِنہٕ۔ چانۍ خون آسہِ زمینس منز۔ ژے گژھِ نہٕ یاد تھاونہٕ یُن: کیازِ میہ چُھہ خداوند کتھ کٔرمٕژ۔","1. اَمہِ علاوٕ آو خداوند سُند کلام میانہِ نِش وَنُن،\n2. وۅنۍ اے انسان سٕندِس نیچو، کیا ژٕ کٔرِکھ فیصلہ کٔرِتھ، کیا ژٕ کٔرِکھ خونریز شہرُک فیصلہٕ؟ آ، ژے ہٲوِکھ أمِس سٲرۍسٕے مُکرٲہِس سٍتـ̡ ۔ {جج: یا، درخواست کٔرِو} {خونی...: ہیب۔ خونُک شہر؟} {ہٲوِو یہِ: ہیب۔ أمِس کٔرِو زاننہٕ}\n3. پَتہٕ وَنُن چُھہ یِتھٕ پٲٹھـ̡ خداوند خدا چُھہ ونان زِ شہر چُھ اَتھ مَنٛز خوُن تراوان، یُتھ زن تٔمۍ سُند وق یِنہٕ ییہِ، تہٕ پانس خٕلاف بُت بناوُن پانس ناپاک کرنہٕ خٲطرٕ۔\n4. ژے چُھہ پننِس خونس مَنٛز قصوروار بنیومُت یُس ژے تروومُت چھُ۔ تہٕ کٔرٕکھ پنُن پان پننٮ۪ن بُتن مَنٛز ناپاک یِم ژے بنٲومٕتۍ چھِ۔ تہٕ ژے چُھکھ پنُن دۅہ نزدیک واتنوومُت، تہٕ چُھس پننین ؤرین تام آمُت، تێلہِ چُھس مے ژے کافرن ہٕندِ خٲطرٕ ملامت تہٕ سارنٕے ملکن ہُند طنز بنوومُت۔\n5.\\t{یُس نزدیکی آسہِ} تہٕ {یُس تۅہہِ نِش دور آسہِ} تۅہہِ ٹھٹھہٕ کرُن، {یُس فن چھُ} بدنام {تہٕ} واریاہ پریشان۔ {بدنام...: ہیب۔ ناوُک آلودہ، واریاہ پریشٲنی منٛز}\n6.\\tوُچھو اسرٲیلٕکۍ شہزادو، پرٮ۪تھ کانہہ اوس توے سٍتـ̡ خوُن بہاونہٕ خٲطرٕ۔ {پاور: ہیب۔ آرم}\n7.\\tژے مَنٛز چھُ تِمو مٲلِس تہٕ ماجہِ ہٕندِ دٔسۍ گاش دِژمُت: ژے مَنٛز چھُ تِمو اجنبی سٍتـ̡ ظُلم کٔرِتھ، تہٕ ژے مَنٛز چھُ یِمو یِمو باپ تہٕ بیواہ ہٕندِس سٍتـ̡ پریشان کٔرِمٕتۍ۔ {ظلم: یا، دھوکہ}\n8. ژے کٔر میانین مقدس چیزن حقارت تہٕ میانین سبت ہٕنز بے عزتی کٔرمٕژ۔\n9.\\tتۅہہِ مَنٛز چھِ انسان یِم خونس بہاونہٕ خٲطرٕ قصہٕ نِوان چھِ: تہٕ تۅہہِ مَنٛز چھِ تِم پہاڑن کھٮ۪وان: تۅہہِ مَنٛز چھِ تِم فحاشی کران۔ {یہ...: ہیب۔ بد کلامی ہُند}\n10.\\tژے مَنٛز چھُ تِمو پننین مٲلن ہٕنز ننگہٕ دریافت کٔرمٕژ: ژے مَنٛز چھُ تِمو سُہ عاجز کورمُت یُس آلودگی خٲطرٕ الگ کرنہٕ آمُت اوس۔\n11.\\tتہٕ أکِس چھُ ہمساے سٕنزِ زنانہِ سٍتـ̡ مُشکِل کٔرمٕژ۔ تہٕ بییِس کٔر پننہ کورِ بے حیائی سان ناپاک کرنہٕ۔ تہٕ بییِس منز چھے تٔمۍ سٕنزِ مٲلہِ سٕنزِ کورِ عاجزی کٔرمٕژ۔ {اکھ: یا، پرٮ۪تھ کُنہِ} {بیاکھ: یا، پرٮ۪تھ کُنہِ} {فحش: یا، فحش ذریعہ}\n12.\\tژے مَنٛز چُھ تِمو خوُن بہاونہٕ خٲطرٕ تحفہٕ نِمٕتۍ۔ خداوند خدا چُھ ونان زِ ژے چُھکھ سود تہٕ ہُریر، تہٕ ژے چُھکھ پننین ہمساین نِش لالچ سٍتۍ حٲصل کٔرمٕژ، تہٕ مے چُھکھ مٔشِد گومُت، خداوند خدا چُھ ونان ۔\n13. تێمہِ کِنۍ چُھس میہ چُھس تۅہہِ ہٕندِس بے ایمانی فٲیدٕ سٍتـ̡ تہٕ تۅہہِ سٕندِس خونس سٍتـ̡ یُس ژے درمِیان اوسمُت چُھ، تہٕ چُھہ تُہٕندِس خونس سٍتـ̡ پَنُن اَتھٕ مُتٲثِر کٔرِمُت۔\n14.\\tتُہند دِل ہیکہٕ تِمن دۅہن منز روزِتھ، کِنہ تُہند اتھہٕ ہیکہٕ مضبوٗط ٲسِتھ، یِمن دۅہن بہٕ ژےٚ سٍتـ̡ میہ چُھہ خداوند کتھ کٔرمٕژ، تہٕ کرٕ {یہ}۔\n15. تہٕ بہٕ کٔرٕ ژے کافرن مَنٛز پھٔہلِتھ تہٕ ژے مُلکن مَنٛز منتشر کٔرِتھ، تہٕ ژے نِش کٔرٕ تُہٕنز گندگی ختم۔\n16.\\tتہٕ تہٕ ژے رٔٹِتھ پَنُن وَرث پانس مَنٛز رٔٹِتھ تہٕ ژے گژھہِ پتاہ زِ بہٕ چُھس خداوند ۔ {نِش نِنہٕ...: یا، یِہ گژھِ ناپاک کرنہٕ}\n17. تہٕ خداوند سُند کلام آو میہ نِش،\n18.\\tاِنسان سٕندِس فرزندس سٍتـ̡ چُھہ اِسرٲیلُک گرٕ میانہِ خٲطرٕ بٔنِتھ بَنُن: تِم سارِنٕے چِھہ پتل، تہٕ ٹِن، ششتٕر تہٕ سیسہٕ، بُٹھہٕ کِس درمِس مَنٛز۔ تِم چھِ رۄپہٕ ہُند گُرٕ تہِ۔ {رۄپہٕ ہُند ڈراس: ہیب۔ ڈروس، وغیرہ}\n19. تێمہِ کِنۍ چُھ خداوند خدا یِتھٕ پٲٹھۍ ونان ؛ تکیازِ تم سٲری چھہِ گۅپھ بٔنِتھ، وچھو، لہذا کرٕ بہٕ ژیہ یروشلمس منز جمع کرنہٕ۔\n20.\\tیِتھٕ پٲٹھۍ چھِ تِم رۄپہٕ تہٕ پیتل، ششتٕر، تہٕ سیسہٕ تہٕ ٹین جمع کٔرِتھ، اَتھ پیٹھ نار دِنہٕ خٲطرٕ، یُس پگلاونہٕ خٲطرٕ۔ یِتھے پٲٹھۍ کٔرٕ بہٕ ژے پننِس غصس تہٕ غصس منز جمع تہٕ بہٕ تراوٕ ژے تتہِ، تہٕ ژے گِلہٕ تہٕ۔ {as...: Heb. اجتماعہٕ مطٲبق}\n21.\\tآ، بہٕ کرٕ ژے جمع کٔرِتھ، تہٕ پننہِ قہر کِس نارس منز پھوُن تہٕ ژے گژھہِ اتھ منز پگلاونہٕ۔\n22. یِتھٕ پٲٹھۍ چُھہ بٹھس منز رۄپہٕ پگلاونہٕ یِوان، تِتھے پٲٹھـ̡ گژھہِ تُہۍ اتھ منز پگلاونہٕ یِنـ̡ ۔ تہٕ ژیہ گژھہِ پتاہ زِ میہ چھہ خدایہ ژے پیٹھ پنُن قہر تراومت۔\n23.\\tتہٕ خداوند سُند کلام آو میہ نِش وونُن،\n24.\\tانسان سٕندِ فرزند، تٔمِس وَنُن زِ تُہۍ چھُکھ سُہ سرزمین، یُس نہٕ پاکیزگی ہٕندِس دۅہہَس مَنٛز چھُ، تہٕ یُس نہٕ پاکیزگی ہٕندِس دۅہہٕ پۯاونہٕ آمُت چھُ۔\n25.\\tاَتھ مَنٛز چھُ تٔمۍ سٕندٮ۪ن پیغمبرن ہٕنز سازش سپدان، یِتھٕ پٲٹھۍ چھُ شِکارس کُن گٔژھان۔ تِمو چِھ روحہٕ کھٮ۪مٕتۍ؛ تِمو چھِ خزانہٕ تہٕ قیمتی چیز نِمٕتۍ۔ تِمو بنٲوۍ أمِس واریاہ بیواہ ۔\n26.\\tتٔمۍ سٕندٮ۪و پادٕریو کٔر میانہِ قانونٕچ خلاف ورزی تہٕ میٲنۍ مقدس چیزن ہٕنز بے حرمتی کٔرمٕژ: تِمو چُھہ نہٕ پاک تہٕ ناپاک چیزن درمیان کانہہ فرق ہٲومُت، تہٕ چُھکھ نہٕ یِمو ناپاک تہٕ پاکیزس درمیان فرق ہٲومُت، تہٕ چُھکھ میانین سبت دۅہن نِش پنٕنۍ أچھ ژوٗرِ تھومٕژ، تہٕ بہٕ چُھس یِمن مَنٛز ناپاک کرنہٕ آمُت۔ {خلاف ورزی: ہیب۔ تشددٕچ پیشکش کٔرٕن}\n27.\\tتٔمۍ سٕندِس شہزادس منز چھِ یِمن ہٕندِس شکارس رٔٹِتھ رٔٹِتھ، خوُن تراوُن، تہٕ روحن تباہ کرنہٕ خٲطرٕ، بے ایمان فٲیدٕ حٲصل کرنہٕ خٲطرٕ۔\n28.\\tتہٕ تٔمۍ سٕندٮ۪و پیغمبرو چُھہ تِمن بےٚ غٲلب وُچھِتھ تہٕ تِمن سٍتـ̡ اپُز وُچھِتھ ونان زِ خداوند خدا چُھ یێلہِ نہٕ کتھ کٔرمٕژ۔\n29.\\tزمینہٕ کٮ۪و لوکو چھُ ظُلمُک استعمال کوٚرمُت، تہٕ ڈاکہ زنی کٔرمٕژ تہٕ غریبَن تہٕ ضرورتمندَن چھِ پریشان کٔرمٕژ: آ، تِمو چھُ اجنبِس پٮ۪ٹھ غلط ظُلم کوٚرمُت۔ {ظلم: یا، دھوکہ} {غلط پٲٹھۍ: ہیب۔ حقہٕ ورٲے }\n30. تہٕ میہ ژھانڈ تمن منز اکھ نفر یُس باڑ بناوِ، تہٕ زمینہٕ خٲطرٕ میانہِ برونہہ کنہِ کھٲڑِتھ کھڑا گژھہِ، مگر میہ لوٚب نہٕ کانہہ تہِ۔\n31. تَمہِ کِنۍ چھُ مے تِمن پیٹھ پنُن غصہٕ تراومُت۔ خداوند خدا چُھ ونان زِ مے چُھ تِمن پننہِ قہر کہِ نارٕ سٍتـ̡ دِژمُت: تِہٕندِس طٔریٖقہٕ سٍتـ̡ چُھس یِمن ہٕندِس کلس سٍتـ̡ بدلہٕ دِژمُت۔","1. خداوند سُند کلام آو میہ نِش دُبارٕ وونُن،\n2.\\tانسان سُند نیچو، زٕ زنانہٕ، أکِس ماجہ ہٕنز کورِ:\n3. تہٕ تِمو کٔر مصرس مَنٛز بدکاری ۔ تِمو کٔر جوانی منز بدکاری کرنہٕ: تتہِ ٲسۍ تِہندِ سین دباونہٕ آمٕتۍ، تہٕ تتہِ ٲسۍ تِمو پننہ کنوارپن ہٕندِس دٲرس زخم دِوان۔\n4.\\tتہٕ تِمن ہُند ناو اوس احولہ بٔڈِتھ تہٕ احلیبہ تسٕنز بینہِ۔ تہٕ تِم ٲسۍ میٲنۍ تہٕ تِمن زاے نیچوۍ تہٕ کورِ۔ یتھہ پاٹھۍ ٲسۍ تہند ناو۔ سامریہ {is} احولہ تہٕ یروشلم اہولیبہ۔ {احولہ: یعنی تہند خیمہ یا خیمہ } {اہولیبہ: یعنی، میون خیمہ اتھ منز}\n5.\\tتہٕ احولاہن کٔر میٲنۍ آسنہٕ وِزِ بدکار گِندان۔ تہٕ سُہ اوس پننین عاشقن سٍتـ̡ پٲٹھ\n6.\\t{یِمَن} نیوٗل پوشہٕ لٲگِتھ، کپتان تہٕ حکمران، یِم سٲری ٲسۍ پسندیدٕ نوجوان، گُرِ سوار گُرِ سوار۔\n7. یِتھٕ پٲٹھۍ کٔر تٔمۍ تِمن سٍتـ̡ پنٕنۍ طوائفہٕ کٔرِتھ، یِمن سارِنٕے سٍتـ̡ یِمن سٍتـ̡ یِمن سارِنٕے سٍتـ̡ یِمن سٍتـ̡ أمِس پٲٹھـ̡ {کمیٹڈ...: ہیب۔ تِمن دِژ تٔمۍ سٕنز بدکاری دِژمٕژ﴾ {منتخب کٔرِتھ...: ہیب۔ آشور سٕندٮ۪ن شُرین ہُند انتخاب}\n8.\\tتٔمۍ ترٲو نہٕ مصرہٕ پیٹھٕ پننہ بدکاری تہٕ تکیازِ جوانی منز ٲسۍ تِمو أمِس سٍتـ̡ لٔگِتھ، تہٕ تِمو کٔرٕکھ أمِس سٍتـ̡ کُنوارِ ہٕندِس سینس زخم تہٕ تٔمِس پۯاوٕنـ̡ پَنٕنـ̡ بدکٲری ہٕندِس سٍتـ̡ ۔\n9. اَمہِ مۄکھٕ چُھس مے سُہ پنہٕ نِس عاشقن ہٕندِس اتھس منز، اشورین ہٕندِس اتھس منز، یِمن سٍتـ̡ أمِس پٲٹھـ̡ دِنہٕ آمُت۔\n10.\\tیِمو لٔج تٔمۍ سٕندِس نیچوِس تہٕ کورِ نِتھ تلوار سٍتـ̡ مٲرِتھ تہٕ سۅ گٔیہِ زنانن مَنٛز مشہوٗر۔ تکیازِ تمو اوس أمس پیٹھ فیصلہٕ دِتمُت۔ {مشہور: ہیب۔ اکھ ناو}\n11.\\tتہٕ ییلہ تسٕنزِ بینہِ احلیبہ وُچھ سۅ ٲس پننہِ بے حد محبتس منز زیادٕ بدکار تہٕ پننہِ بینہِ کھوتہ زیادٕ بدکار گٔیہِ۔ {سۅ ٲس...: ہیب۔ تٔمۍ کٔر پنُن حد کھوتہٕ زیادٕ محبت، وغیرہ} {زیادٕ کھوتہٕ زیادٕ...: ہیب۔ پننہ بینہِ ہنزِ بدکاری کھوتہ زیادہ}\n12.\\tسُہ اوس اسیرین ہمساین، کپتانن تہٕ حکمرانن سٍتۍ سٮ۪ٹھاہ خوبصورتی سان پلو لٲگِتھ، گُرِ سوارِ سوار، یِم سٲری ٲسۍ پسندیدٕ نوجوان۔\n13.\\tمیہ وُچھ سۅ ٲس ناپاک گٔمٕژ، {یہ} تِمو کٔر دۅشوے اکی طرفہٕ،\n14. تہٕ {یہ} ہُریوو تٔمۍ پنٕنۍ بدکاری ہُریر: تکیازِ ییلہ تٔمۍ دیوارس پیٹھ نفر ترٲوتھ وُچھ، کلدینن ہٕنزِ شکلہٕ ٲس سِندرٕ سٍتـ̡ وُچھمٕژ،\n15.\\tپننین کمرن پیٹھ لٔگِتھ لٲگِتھ، کلس پیٹھ رنٛگ کٔرِتھ لٲگِتھ، یِم سارِنٕے شہزادٕ چھِ، یِمن ہٕنزِ پٲدٲیشی سرزمینہٕ پٲٹھۍ، چالڈیا کِس بابلی ہٕندِس طرزس پٲٹھۍ:\n16.\\tتہٕ یێلہِ تٔمۍ تِم پننیو أچھو سٍتـ̡ وُچھ، تٔمۍ کٔرٕن تِمن نِش پٲٹھۍ، تہٕ سوٗزِن تِمن نِش قاصد۔ {یُس جلدی...: ہیب۔ امۍ سنزن اچھن وچھتھ\n17.\\tتہٕ بابل آو أمِس نِش محبتہٕ کِس بسترس منز، تہٕ تِمو کٔر أمِس پننہِ بدکاری سٍتـ̡ ناپاک تہٕ سُہ گٔیہِ تِمو سٍتـ̡ ناپاک تہٕ تٔمۍ سُند دٮ۪ماغ گۆو تِمن نِش بیگان۔ {بابلونی: ہیب۔ بابل سٕندۍ بچہٕ} {بیگان: ہیب۔ لولہٕ، یا، بے جوڑ}\n18.\\tتہ تس ٲس پننہ بدکاری دریافت کٔرمٕژ، تہٕ تٔمۍ سُند ننگہٕ پنُن دریافت: پتہٕ گوو میون ذہن أمس نِش بیگانگی، یتھہ پاٹھۍ میون ذہن تسنزِ بینہِ نِش الگ گومُت۔\n19.\\tتوتہِ ہُریر تٔمۍ پننہ جوانی ہٕندِس دۅہہٕ یاد پاونہٕ خٲطرٕ بُلاونہٕ خٲطرٕ، یَتھ مَنٛز تٔمۍ مصرٕکِس سرزمینس مَنٛز بدکٲری ہُند کردار ادا کٔرمٕژ۔\n20.\\tتکیازِ سۅ ٲس تِمن ہٕندِس ماز سٍتـ̡ گُرِ ہُند ماز ہیوٗ تہٕ یٔمۍ سُند مسلہٕ گُرِ ہُند مسلہٕ چُھ۔\n21. یِتھٕ پٲٹھۍ کٔر ژے پننہِ جوانی ہٕنزِ بے حیائی یاد پاونہٕ خٲطرٕ، مصریو ہٕندِ دٔسۍ پننہ جوانی ہٕندِس پٔرِس مۅکھہٕ پنہٕ نِس جوٲنی ہٕندِس دٔسۍ دِنہٕ آمٕژ۔\n22. تێمہِ کِنۍ، اے اہولیبہ، خداوند خدا چُھ یِتھٕ پٲٹھۍ فرماوان۔ وچھ، بہٕ کٔرٕ چانۍ عاشق ژے خٕلاف، یِمن نِش تُہند ذہن الگ چُھ، تہٕ بہٕ اننہٕ تِم پریتھ طرفہٕ ژے خٕلاف ۔\n23.\\tبابل تہٕ سارِنٕے چالدین، پیکوڈ تہٕ شوا تہٕ کوا، تہٕ سارِنٕے اشورِی: یِم سٲری ٲسۍ پسندیدٕ نوجوان، کپتان تہٕ حُکُمران، بٔڈۍ سردار تہٕ مشہور، یِم سٲری ٲسۍ گُرٮ۪ن پیٹھ سوارِ۔\n24. تہٕ تِم یِن تۅہہِ خلاف رتھ، گاڑِ تہٕ چکرٕ ہیتھ تہٕ لُکن ہٕنزِ مجلسہٕ سٍتۍ، یُس تۅہہِ خلاف بکلر، ڈھال تہٕ ٹوپہٕ لٲگِتھ تہٕ بہٕ کرٕ تِمن برونہہ کُن فیصلہٕ، تہٕ تِم کرِ تۅہہِ ہٕندِس فٲصلس مطٲبق فیصلہ کرنہٕ۔\n25. تہٕ بہٕ کٔرٕ ژےٚ سٍتـ̡ پنُن حسد، تہٕ تِم کٔرِن تُہٕنزِ نَس تہٕ تُہٕندِس کَن نِنـ̡ ۔ تہٕ تُہٕندِ باقٕے گٔیہِ تلوار سٍتـ̡ تہٕ تُہٕندِس نیچوِس تہٕ کورِ نِنـ̡ ۔ تہٕ تُہند باقیات گژھہِ نارس سٍتۍ کھٮ۪نہٕ۔\n26. تِم تہِ کٔڑِن تُہٕندِس پلو تہٕ نِن تُہٕندِ خوبصورت جوٲہر۔ {منصفانہ...: ہیب۔ چانہِ سجاوٹٕکۍ آلات}\n27. یِتھٕ پٲٹھۍ کَرٕ بہٕ تُہٕنز فحاشی تہٕ تُہٕنز فحاشی تہٕ مصر کِس سرزمینہٕ پیٹھٕ اَننہٕ آمٕژ، یُتھ نہٕ ژٕ تِمن کُن أچھ تُلِتھ تہٕ نہٕ مزید مصر یاد تھاوُن۔\n28. یِتھٕ پٲٹھۍ چُھ خداوند خدا فرماوان۔ وچھ بہٕ ژے تِمن اتھس مَنٛز یِمن نِش تُہُند دٮ۪ماغ چُھ، یِمن نِش تُہُند دٮ۪ماغ چُھہ دِنہٕ آمُت:\n29.\\tتہٕ تِم کرَن تۅہہِ سٍتـ̡ نفرتُک سلوک تہٕ تُہٕنز سٲرٕے محنتہٕ نِش نِن، تہٕ تُہٕنزِ فحاشی تہٕ تُہٕنزِ بدکٲری ہٕنز ننگٲنی ظٲہِر۔\n30. بہٕ کٔرٕ ژے سٍتـ̡ یِم {چیز}، کیازِ ژے چھے کافرن ہٕندِس پَتہٕ کُنہِ سٍتـ̡ کُنہِ سٍتـ̡ گٔژھمٕژ۔\n31.\\tژے پٔکِتھ لہذا دِیہ بہٕ تٔمۍ سُند پیالہ چانہِ اتھس منز۔\n32. یِتھٕ پٲٹھۍ چُھ خداوند خدا وَنان۔ ژے گژھ پننہ بینہِ ہٕندِس پیالہ سٍتۍ سرٛوٚن تہٕ بٔڈۍ پیالہ چُھس: ژے گژھہِ طنز کرنہٕ خٲطرٕ اَسُن تہٕ طنز کرنہٕ آمُت۔ اتھ منز چھہ واریاہ کینہہ موجود۔\n33.\\tژے گژھہِ شرابہٕ تہٕ غمس سٍتـ̡ بٔرِتھ، حیرٲنی تہٕ ویرٲنی ہٕندِس پیالہٕ سٍتـ̡ پننہِ بینہِ سامریہ سٕندِ پیالہٕ سٍتـ̡ بٔرِتھ۔\n34.\\tژے چُھہ یہِ چیٚنہٕ تہٕ چوسُن، تہٕ ژے کٔرِو اَمہِ سٕندِ ٹُکرٕ پھُٹراوُن، تہٕ پَنٕنـ̡ پَنٕنـ̡ ژٔٹِھتھ ژٔٹِھھ، تِکیازِ میہ چُھہ کتھ کٔرمٕژ، خداوند خدا چُھ فرماوان۔\n35. تێمہِ کِنۍ چُھ خداوند خدایہ یِتھٕ پٲٹھـ̡ وَنان۔ تکیازِ ژے چھکھ میہ مٔشِد گومُت، تہٕ ژے چھُکھ پَنٕنۍ بے حیٲیی تہٕ پَنٕنۍ بدکاری تہِ برداشت کٔرِتھ۔\n36. خداوند چُھ میہ مزید وونمت۔ اے انسان سٕندِس فرزند، کیا ژٕ کٔرِکھ احولہ تہٕ احولیبہ ہُند فیصلہ کٔرِتھ؟ آ، تِمن کٔرِو تِمن ہٕنزِ مکروہ ہُند اعلان ۔ {جج: یا، درخواست کٔرِو}\n37. زِ تِمو چُھ زنا کٔرمُت، تہٕ تِمو چُھ پننین بتن سٍتـ̡ زنا کٔرمٕژ، تہٕ پننین نیچوین تہِ، یِم تِمو میانہِ نِش دِژمٕتۍ، تہٕ چُھکھ تِمن ہٕندِ خٲطرٕ نارٕ سٍتـ̡ نِنہٕ خٲطرٕ واتناوُن۔\n38.\\tیِمو کٔر میہ سٍتـ̡ یێلہِ سٍتـ̡ یێلہِ سٍتـ̡ میانہِ مقدس گاہچ ناپاک تہٕ میانہِ سبت ناپاک کٔرٕنـ̡ ۔\n39.\\tییلہ تِمو پنٕنـ̡ شُرِ پننین بتن ہٕندِس مُتمن سٍتـ̡ مارنہٕ آمٕتـ̡ تہٕ تِم آیہ امی دۅہہ میانہِ مُقدس مَنٛز اَتھ ناپاک کرنہٕ خٲطرٕ۔ تہٕ لو، یِتھٕ پٲٹھۍ کوٚر تِمو میانہِ مکانس منٛز۔\n40. تہٕ امہِ علاوٕ، تہٕ یِمو چھُ دوٗرِ پیٹھٕ یِنہٕ وٲلِس نفرس خٲطرٕ سوزمُت، یِمن نِش اکھ رسول اوس سوزنہٕ آمُت۔ تہٕ یِمن ہٕندِ خٲطرٕ ژے پنُن پان واش کٔرِتھ، پنٕنۍ أچھ رنٛگ کٔرِتھ تہٕ پنُن پان سجٲوِتھ زیور سٍتـ̡ سجٲوِتھ، {یِنہٕ خٲطرٕ: ہیب۔ یِوان}\n41.\\tتہٕ أکِس شاندار بسترس پیٹھ، تہٕ اَتھ برونہہ کُن تیار کٔرِتھ میزس پیٹھ، ییمہ سٍتـ̡ ژے میٲنۍ بخور تہٕ میٲنۍ تیٖل تھوو۔ {سٹیٹلی: ہیب۔ عزت}\n42.\\tتہٕ اَکھ ہجوم ہٕنز آواز ٲس أمِس سٍتۍ آرام سان تہٕ عام قٕسمٕکۍ نفرن سٍتۍ أنۍ بیابان منزٕ صابان، یِمو تِمن ہٕندِس اتھن پیٹھ کٔرِتھ کٔرِتھ تہٕ کلَن پیٹھ خوبصورت تاج لٲگِتھ۔ {منز...: ہیب۔ انسانن ہٕنز} {صابین: یا، شراب}\n43.\\tاَمہ پتہٕ ووٚن میہ زنا کِس بُزرگ سٍتـ̡ کیا تِم وۅنۍ أمِس سٍتـ̡ بدکاری کٔرِتھ، تہٕ سُہ {تِمن سٍت}؟ {طوائف...: ہیب۔ تٔمۍ سٕنز طوائف}\n44.\\tتوتہِ گٔیہِ تِم أمِس نِش، یِتھٕ پٲٹھۍ گٔیہِ تِم أکِس زنانہِ نِش اژان یُس بدکار زنانہٕ آسہِ۔\n45.\\tتہٕ نیک مرد، تِم کرِ تِمن زناکارن ہٕندِس طریقس سٍتـ̡ تہٕ خونریز زنانن ہٕندِس طریقس سٍتـ̡ انصاف کرنہٕ۔ تکیازِ تم چھہِ زناکار، تہ خون چھہ تہندس اتھس منز۔\n46. یِتھٕ پٲٹھۍ چُھ خداوند خدا وَنان۔ بہٕ اَننہٕ تِمن پیٹھ اکھ صحبت، تہٕ دِیہ تِمن ہٹاونہٕ تہٕ خراب کرنہٕ خٲطرٕ۔ {to be...: Heb. ہٹاونہٕ خٲطرٕ تہٕ خراب کرنہٕ خٲطرٕ}\n47.\\tتہٕ کمپنی کرِ تِمن کنیو سٍتـ̡ کٔنہِ تہٕ تلوارو سٍتـ̡ سوزنہٕ۔ تِم مارن پنٕنۍ نیچوۍ تہٕ کورِ تہٕ تِمن ہٕندِس گَرٕ نارس سٍتـ̡ زٲلِتھ۔ {ڈسپیچ...: یا، تِم الگ کٔرِو}\n48.\\tیِتھٕ پٲٹھۍ کٔرٕ بہٕ زمینہٕ منزٕ بے حیائی ختم کرنہٕ، یُتھ سارنٕے زنانن گژھہِ تُہنزِ فحش حرکتہٕ پتہٕ نہٕ کرُن ہیچھناونہٕ۔\n49. تہٕ تِم دِیہِ تُہٕنزِ بے حیٲیی ہُند بدلہٕ، تہٕ تۅہہِ پَنٕنـ̡ بُتـ̡ ہٕندِس بُتـ̡ ہُند گۅناہ تہٕ تێہہِ گژھہِ پتاہ زِ بہٕ چُھس خداوند خدا۔","1. دُبارٕ نٔوِمہِ ؤریس منز، دٔہمہِ ریتس منز، دٔہمہِ دۅہہٕ آو میہ نِش خداوند سُند کلام وونُن،\n2. اَمہ دۅہہُک ناو لیکھِو بابل کِس بادشاہن امی دۅہہٕ یروشلمس خلاف۔\n3.\\tتہٕ باغی گرس سٍتـ̡ اکھ تمثیل ونِو تہٕ تِمن ونُن، یِتھٕ پٲٹھـ̡ خداوند خدا چُھ فرماوان۔ أکِس بانس پیٹھ تھٲوِو، {یہ} تھٲوِو، تہٕ اَتھ منٛز ترٛٲوِو آب تہِ:\n4.\\tامکۍ ٹُکرۍ جمع کٔرِو اتھ منز، {حتیٰ کہ} پریتھ جان ٹُکر، ران تہ پھیپھ۔ {یہ} بٔرِو ژٲر ہڈجہِ سٍتۍ۔\n5.\\tریوُن ژٲر تہ اتھ تلہ کنہِ أڈجہ تہِ زالُن، {تہٕ} کرُن اتھ منز رژھ تہ اَمہ چہ أڈجہ وُچھن۔ {برن: یا، ڈھیر}\n6. اَمہِ مۄکھٕ چُھ خداوند خدایہِ یِتھٕ پٲٹھۍ فرماوُن؛ خونریز شہرس افسوس، تتھ برتن یمۍ سُند گند {چُھ} اَتھ منز، تہٕ یٔمۍ سُند گندٕ چُھ نہٕ اَتھ منزٕ نیبر گومُت! یہ کٔرِو ٹُکرٕ ٹُکرٕ نیبر؛ اتھ پیٹھ گژھہِ نہ کانہہ زیادہ۔\n7. تکیازِ تٔمۍ سُند خون چُھ تس منز۔ تمۍ تھوو یہ اکس کنہِ پتھرس پیٹھ۔ تٔمۍ ترٛٲو نہٕ یہ زمینس پیٹھ، گردِ سۭتۍ ؤلنہٕ خٲطرٕ۔\n8.\\tیُتھ زِ امہِ سٍتۍ گژھہِ انتقام نِنہٕ خٲطرٕ غصہٕ پٲدٕ سپدِ۔ میہ چھہ امۍ سند خون اکس کنہِ پتھرس پیٹھ تھوومُت، تاکہ یہ گژھہِ نہ تھپھ کرنہ۔\n9. تَمہِ کِنۍ چُھ خداوند خدا یِتھٕ پٲٹھۍ وَنان۔ خونریز شہرس افسوس! بہٕ بناوٕ نارٕ خٲطرٕ ڈھیر تہِ عظیم۔\n10.\\tلٔکرِ پیٹھ تھپھ کٔرِتھ، نار زالُن، ماز کھیوٚن تہٕ رژھ رژھ مسالہٕ تراوُن، تہٕ أڈجہِ زالنہٕ۔\n11.\\tتیلہ تھووُن اَمہ کِس کولس پیٹھ خٲلی، یُتھ امُک پیتل گژھہِ گرم تہٕ دزِتھ تہٕ اَمہ سٍتۍ گژھہِ اَمہ کِس گندٕ سٍتۍ گٔژھِتھ تہٕ اَمہ ہُند گندٕ گژھہِ کھٮ۪نہٕ۔\n12.\\tسۅ چھیہ اپزس سٍتـ̡ تھکان تہٕ تٔمۍ سُند بۆڈ گندٕ دراو نہٕ أمِس منز: تٔمۍ سُند گندٕ آسہِ نارس مَنٛز۔\n13.\\tچانہِ گندگی منز چھیہ بے حیائی: کیازِ میہ چھیہ ژیہ پاک کٔرمٕژ، تہٕ ژے چھکھ نہٕ پاک کٔرمٕژ، توٚت تام گژھ نہٕ ژے پننہِ گندگی نِش پاک کرنہٕ، یوتام نہٕ بہٕ ژے پنُن غصہٕ ژے پیٹھ تھپھ کرِ۔\n14. میہ چُھہ خداوند کتھ کٔرمٕژ: یہ گژھہِ سپدُن، تہٕ بہٕ کرٕ یہِ۔ بہٕ گژھٕ نہٕ واپس، نہ بہٕ تراوٕ تہٕ نہ بہٕ توبہٕ۔ خداوند خدا چُھ ونان زِ تُہٕندِس طریقس مُطٲبِق تہٕ تُہٕندِس اعمال مُطٲبِق کٔرِن تُہُند فیصلہٕ۔\n15.\\tخداوند سُند کلام تہِ آو میہ نِش،\n16.\\tانسان سٕندِ فرزند، وچھ بہٕ ژے نِش چانہِ أچھن ہٕنز خواہش ژٔٹِتھ تہٕ توتہِ گژھ نہ ماتم تہٕ نہ روُن، تہٕ نہ گژھ چانہِ اوٚش وسان۔ {رن ڈاون: ہیب۔ گو}\n17.\\tروُن نِش بٔرِتھ، مُردن ہٕندِ خٲطرٕ گژھ نہٕ ماتم کرنہٕ، پَنٕنہِ کلہٕ ہُند تھوٚر لٲگِتھ تہٕ پَنٕنہِ کھورِ لٲگِتھ تہٕ پَنٕنـ̡ وٕٹھہٕ تھپھ کٔرِتھ تہٕ نہ کھٮ۪و انسانن ہٕنزِ روٹی۔ {فاربر: ہیب۔ خاموش روزُن} {چپ: ہیب۔ پیٹھم وٕٹھ}\n18.\\tیێلہِ کٔر میہ صبحس لُکن سٍتـ̡ کتھ کرنہٕ: تہٕ میانہِ زنانہٕ تہِ گٔیہِ مٔرۍ۔ تہٕ مے کٔر صبحٲے یُتھ مےٚ حُکُم اوس دِنہٕ آمُت۔\n19.\\tتہٕ لوکو ووٚن میہ زِ ژیہ کیا چھکھ اسہِ خٲطرٕ یِم {چیز} یِمن ہٕندِ خٲطرٕ کیا چھِ، یُس تہٕ ژٕ چُھہ کران {یِتھ}؟\n20. اَمہِ پَتہٕ دِیُت میہ تِمن جواب، خداوند سُند کلام آو میہ نِش،\n21. یِتھٕ پٲٹھـ̡ خداوند خدا چُھ ونان زِ اسرٲیلِس سٍتـ̡ کتھ کرٕنـ̡ ۔ وچھ بہٕ کٔرٕ پنٕنۍ مقدس مقام، چانہِ طاقتٕچ فضیلت، چانہِ أچھن ہٕنز خواہش، تہٕ تۅہہِ ہٕندِس روح سٍتۍ ترس کھسان۔ تہٕ تُہند نیچو تہٕ کورِ یِم ژےٚ ترٲومٕژ چھِ، تِم گژھن تلوار سٍتۍ پَسنہٕ۔ {یہ...: ہیب۔ چانہِ روحُک رحم چھُ}\n22. تہٕ یِتھٕ پٲٹھۍ کٔرِو یُتھ میہ کورمُت چُھ، تہٕ نہ گژھ پَنٕنـ̡ وٕٹھـ̡ تھپھ کٔرِتھ، تہٕ نہ کٔرِو انسانن ہٕنزِ روٹی کھٮ۪وان۔\n23. تہٕ تُہٕندِس کَلَس پیٹھ، تہٕ تُہٕندِس کھورَس پٲٹھۍ، تہٕ تُہٕندِس کھورَس پٲٹھۍ، تہٕ تُہٕندِس کھورَس پٲٹھۍ۔ مگر تُہۍ گژھِو پننین گناہوں ہُند افسوس تہٕ اکھ أکِس سٍتۍ ماتم کٔرِو۔\n24. یێلہِ چُھہ حزقی ایل تۅہہِ خٲطرٕ اکھ نشانہٕ: یُس تٔمۍ سُند یُس تہِ کورمُت چُھ، تہٕ یێلہِ یێلہِ یہِ سپدِ، تێلہِ گژھہِ پتاہ زِ بہٕ چُھس خداوند خدا۔\n25.\\tتہٕ اے انسان سٕندِس نیٚچوُن، {یێلہِ} گژھِ نہٕ تِمن نِش تِہٕنز طاقت، تِہٕنزِ عظمتٕچ خوشی، تِہٕنزِ أچھن ہٕنز خواہش، تہٕ یێمہِ سٍتـ̡ تِمن ہُند ذہن، پنٕنـ̡ نیچوۍ تہٕ کورِ نِنـ̡ نِنـ̡ {یہ...: Heb. تِہُند روح تُلُن}\n26. {یہ} یُس تمہِ دۅہہ ژلان آسہِ سُہ گژھہِ تۅہہِ نِش یُس {تۅہہ} کَن سٍتـ̡ بوزناوُن؟\n27.\\tاَمہِ دۅہہٕ گژھہِ تُہٕندِ خٲطرٕ یُس ژلنہٕ آمُت آسہِ، تہٕ ژے گژھہِ کتھ کٔرِتھ، تہٕ تُہۍ گژھِہ تِمن ہٕندِ خٲطرٕ اکھ نشانہٕ۔ تہٕ تِمن گژھہِ پتاہ زِ بہٕ چُھس خداوند ۔","1. خداوند سُند کلام آو میہ نِش دُبارٕ وونُن،\n2. اِنسان سٕندِس بُتھِس سٍتـ̡ کٔرِو پَنُن بُتھ عمونیَن خٕلاف، تہٕ تِمن خلاف کٔرِو پیشن گوئی۔\n3. تہٕ امونیتَن وَنُن زِ خداوند خدا سُند کلام بوزو۔ یِتھٕ پٲٹھـ̡ چُھ خداوند خدا فرماوان۔ تکیازِ ژے ووٚن، آہا، میانہِ مقدس مقامس خلاف، ییلہ یہ بے حرمتی کرنہٕ آو۔ تہٕ اسرائیلٕچ سرزمینس خلاف، ییٚلہ سُہ ویران اوس۔ تہٕ یہوداہ کِس گرس خلاف، ییلہ تم قٲد گٔیہ؛\n4. تێمہِ مۅکھہٕ بہٕ ژے مشرق کین لوکن نِش واتناوُن، تہٕ تِم بناوَن توے مَنٛز پنٕنۍ محل تہٕ تۅہہِ مَنٛز پنٕنۍ مکانہٕ بَناوٕن، تِم کھیون تُہند پھل تہٕ تُہند دۄد چیٚن۔ {مرد: ہیب۔ بچہٕ}\n5. تہٕ بہٕ بناوٕ ربہ اونٹَن ہٕندِ خٲطرٕ اصطبل تہٕ عمونیَن ہٕندِ خٲطرٕ بَناوٕنٕچ جاے، تہٕ ژے گژھہِ معلوم زِ بہٕ چُھس خداوند ۔\n6. یِتھٕ پٲٹھۍ چُھ خداوند خدا فرماوان۔ تکیازِ ژے چُھکھ ژرِ پوٚپ کٔرِتھ، تہٕ کھۅرن سٍتـ̡ تھپھ کٔرِتھ، تہٕ دِلس سٍتـ̡ خۅش کورمُت تہٕ اسرٲیلِس سٍتـ̡ چُھہ پنہٕ نِس سارِنٕے سٍتـ̡ خۅش سپدان۔ {اتھہٕ: ہیب۔ اتھہٕ} {کھۄر: ہیب۔ کھۄر} {دل: ہیب۔ روح}\n7.\\tوُچھ، تێمہِ کِنۍ کٔرٕ بہٕ ژے پیٹھ پنُن اتھہٕ، تہٕ کٔرٕ ژے کافرن ہٕندِس غنیمتس خٲطرٕ حوالہٕ۔ تہٕ بہٕ ژٕ ژے لوکن نِش ژٹتھ تہٕ بہٕ کرٕ ژے ملکن نِش ختم کرنہٕ: بہٕ کرٕ ژے تباہ کرنہٕ۔ تہٕ ژے گژھہِ پتاہ زِ بہٕ چُھس خداوند چُھس۔ {اکھ غنیمت: یا، ماز}\n8. یِتھٕ پٲٹھـ̡ چُھ خداوند خدایہ فرماوان۔ تکیازِ موآب تہٕ سیر چھہِ ونان زِ وچھو، یہوداہ سُند گرٕ چُھ سارنٕے کافرن ہٕندۍ پٲٹھۍ۔\n9.\\tتێلہِ، وُچھِو بہٕ موآب سٕندِس طرفس شہرو منز، تٔمۍ سٕندِس سرحدس پیٹھ، ملکٕچ عظمت، بیت جیشیموت، بعلمیون تہٕ کریاتھیم، {طرف...: ہیب۔ موآب سُند کندھ}\n10.\\tمشرقس ہٕندِس نفرس سٍتـ̡ تہٕ دِیُن تِمن قبضس منز، یُتھ زن نہ قومن مَنٛز یاد تھاونہٕ یِن۔ {سۭتۍ...: یا، عمون کین بچن خلاف}\n11. تہٕ بہٕ کرٕ موآبس پیٹھ فیصلہٕ۔ تہٕ تِمن گژھہِ پتاہ زِ بہٕ چُھس خداوند ۔\n12. یِتھٕ پٲٹھۍ چُھ خداوند خدا فرماوان۔ تکیازِ یێمہِ ایڈومَن چُھ یہوداہ کِس گرس سٍتـ̡ انتقام نِتھ سٍتـ̡ {by...: ہیب۔ انتقام کٔرِتھ}\n13. تێمہِ کِنۍ چُھ خداوند خدا یِتھٕ پٲٹھۍ وَنان۔ بہٕ تہِ کٔرٕ اَدومس پیٹھ پنُن اَتھٕ تہٕ ژٔٹِتھ ژٔٹِتھ انسان تہٕ جانور ژٹِتھ ۔ تہٕ بہٕ بناوٕ یہ تیمان نِش ویران۔ تہٕ تِم گٔژھن تلوار سٍتۍ۔ {تِم...: نتہٕ گژھن تِم تلوار سٍتۍ دیدانس کُن پیوٚن}\n14. تہٕ بہٕ کَرٕ پننِس قوم اسرٲیلِس سٍتـ̡ پنُن انتقام، تہٕ تِم کٔرِن میٲنۍ شرارت تہٕ میانہِ قہر مُطٲبق ایڈومَس مَنٛز۔ تہٕ تِمن گژھن میٲنۍ انتقامُک پتہٕ، خداوند خدا چُھ وَنان۔\n15. خداوند خدا چُھ یِتھٕ پٲٹھۍ فرماوان۔ تکیازِ فلسطینیو چُھ انتقام سٍتـ̡ نمٹمُت، تہٕ کورُکھ پرٲنِس نفرتس تباہ کرنہٕ خٲطرٕ انتقام۔ {باپت...: یا، دائمی نفرتس سٍتۍ}\n16. تێمہِ کِنۍ چُھ خداوند خدا یِتھٕ پٲٹھۍ فرماوان۔ وچھ بہٕ پھٔلِتھ فلسطینن پیٹھ پنُن اتھہٕ، تہٕ بہٕ ژٔٹِتھ کرٕ سمندرٕ کِس بٹھس پیٹھ باقیات تباہ کرنہٕ۔ {سمندری ساحل: یا، سمندرُک پناہ گاہ}\n17. تہٕ بہٕ کَرٕ تِمن سٍتـ̡ زبردست انتقام۔ تہٕ تِمن گژھہِ پتاہ زِ بہٕ چُھس خداوند چُھس، یێلہِ بہٕ تِمن سٍتـ̡ پنُن انتقام۔ {عظیم انتقام: ہیب۔ عظیم انتقام}","1. تہٕ یہِ سپُد کاہمہِ ؤریس مَنٛز، ریتہٕ کِس گۄڈنِکِس دۅہس مَنٛز، {یُس} خداوند سُند کلام آو میہ نِش،\n2.\\tانسان سُند فرزند، کیازِ یُس ٹائرسن یروشلمس خلاف وونمُت، آہا، سُہ چُھ پھُٹمُت {یُس اوس} لوکن ہٕندِس دروازس پیٹھ: سُہ چُھس میہ کُن پھیُراونہٕ آمُت: بہٕ چُھس بھرنہٕ آمُت، {وُن} سُہ چُھ ضایع کرنہٕ آمُت:\n3. یێمہِ کِنۍ چُھ خداوند خدا یِتھٕ پٲٹھۍ وَنان۔ وچھ بہٕ چُھس ژے خلاف، اے ٹائرس، تہٕ کرٕ واریاہ قومن پانس خلاف یِنہٕ، یتھ کٔنۍ سمندرٕ چُھ تٔمۍ سٕنزِ لہرٕ ہُران۔\n4. تہٕ تِم کرِ ٹائرس سٕندِ دیوارٕ تباہ تہٕ تٔمۍ سٕندِس مینار پھُٹراوُن: بہٕ تہٕ کٔرٕ أمِس نِش تٔمۍ سٕنز گرد تہٕ بناوٕ أمِس کنہِ پتھرِ ہٕندِس پٲٹھۍ۔\n5. سمندرس مَنٛز جال پھٔہلاونہٕ خٲطرٕ گژھہِ یہِ جاۓ آسٕنۍ، کیازِ میہ چُھ کتھ کٔرمٕژ، خداوند خدا چُھ فرماوان: تہٕ یہِ گژھہِ قومن ہٕندِ خٲطرٕ غنیمت بنہٕ۔\n6.\\tتہٕ تٔمۍ سٕنزِ کورِ یِم میدانس مَنٛز آسہِ، یِم تلوار سٍتـ̡ مارنہٕ یِن۔ تہٕ تِمن گژھہِ پتاہ زِ بہٕ چُھس خداوند ۔\n7. یِتھٕ پٲٹھـ̡ چُھ خداوند خدا فرماوان۔ وچھ بہٕ اَننہٕ بابل کِس بادشاہ ٹائرس نیبوکدرزارس پیٹھ، یُس بادشاہن ہُند بادشاہ اوس، شمالہٕ پیٹھ، گُرۍ، رتھ، تہٕ گُرۍ سوار، تہٕ کمپنی تہٕ واریہن لوٗکن سۭتۍ۔\n8.\\tسُہ مارِ تُہنزِ کورِ تلوار سٍتـ̡ میدانس مَنٛز۔ تہٕ سُہ بناوِ تۅہہِ خٕلاف اکھ قعلہٕ، تہٕ تۅہہِ خٕلاف اکھ پہاڑ تراوُن، تہٕ تُہٕندِس خٕلاف تُلِتھ تُلِہِ۔ {کاسٹ ...: یا، شاٹُک انجن تراوُن}\n9. تہٕ سُہ کرِ تُہنزن دیوارن خلاف جنگُک انجن تہٕ پننہِ کلہٕ سٍتـ̡ پھُٹراوِ تُہند مینار۔\n10. تٔمۍ سٕندٮ۪ن گُرٮ۪ن ہٕنزِ کثرت کِنۍ گژھہِ تِہٕنز گرد ژٔلِتھ: گُرۍ سوارَن تہٕ چکرَن تہٕ رتھَن ہٕندِس شورس سٍتـ̡ ژٔلِتھ ژٔلِتھ یێلہِ سُہ تُہٕندِس دروازس مَنٛز اژِ، یِتھٕ پٲٹھۍ انسان أکِس شہرس مَنٛز اژان چھُ۔ {بطور مرد...: ہیب۔ پھُٹمُت شہرٕکۍ دٲخل گژھنہٕ مطٲبق}\n11.\\tسُہ گُرِ ہٕندِس کھورٕ سٍتـ̡ چُھہ تُہٕندِس سارِنٕے سڑکہٕ سٍتـ̡ پَکُن: سُہ مارِ تُہٕندِس لُکھ تلوار سٍتـ̡ تہٕ تُہٕنزِ مضبوٗط چھاونی گٔژھِن زمینس پیٹھ۔\n12. تہٕ تِم بناوَن تُہٕندِس دٲیرٕ سٍتـ̡ لوُٹ، تہٕ تُہٕندِس سامانس سٍتـ̡ شِکار۔ تہٕ تُہٕندِس دیوارس پھُٹراوٕن، تہٕ تُہٕندِس خۅش گَرٕ تباہ کٔرِن تہٕ تُہٕندِس کٔنہِ تہٕ لٔکٕر تہٕ تُہٕنز گرد آبس مَنٛز تراوٕنـ̡ ۔ {تُہند خوشگوار...: ہیب۔ چانہِ خواہشکۍ مکانہٕ}\n13. تہٕ بہٕ کٔرٕ چانہِ بٲتن ہُند شور بند۔ تہٕ چانہِ ہارپٕچ آواز گژھہِ نہٕ وۅنۍ بوزنہٕ۔\n14.\\tتہٕ بہٕ بناوٕ ژے کنہِ پتھرِ ہٕندِس پٲٹھۍ: ژٕ بَناوٕ جال پھٔہلاونہٕ خٲطرٕ {اکھ جاے}۔ تہٕ یێلہِ یێلہِ تہٕ یێلہِ چُھہ خداوند سٕندِ کُنہِ سٍتـ̡ بٔنِتھ تہ\n15. یِتھٕ پٲٹھـ̡ چُھ خداوند خدایہ ٹائرس ونان ۔ ژیہ پنہِ چہ آوازِ پیٹھ ژلہِ نہ ژیہ ژکہِ پنہِ ہنزِ آوازِ پیٹھ ژلہِ ژلہِ۔\n16. تیلہٕ گژھن سمندرٕکۍ سٲری شہزادٕ پننیو تختو پیٹھٕ بۄن، تہٕ پلو ترٲوِن تہٕ لٔگِتھ پَنٕنۍ پلو لاگن: تِم لٔگِن تھرتھر پٲٹھۍ۔ تِم گژھن زمینس پیٹھ بِہتھ، تہٕ پرٮ۪تھ ساعتہ تھرتھرن تہٕ ژےٚ وُچھِتھ حیران۔ {تھرتھر: ہیب۔ تھرمبلنگس}\n17.\\tتہٕ تِم تُہٕندِ خٲطرٕ اکھ ماتم تُلِتھ تہٕ وَنُن، ژے کِتھہ کٔنۍ گٔیہٕ تباہ گٔمٕژ، سُہ شہر، یُس سمندرس مَنٛز مضبوط اوس، سُہ تہٕ تٔمۍ سٕندِس بسکین، یُس تِمن سارِنٕے سارِنٕے سٍتـ̡ دہشت ہُند سبب بنان چُھ! {of...: ہیب۔ سمندرن ہُند}\n18.\\tوۅنۍ گژھہِ جزیرہ ژٔٹِتھ ژٔل آ، سمندرس منز یم جزیرہ {چھہ} تۅہہِ نیرنس پیٹھ پریشان گژھن۔\n19. یِتھٕ پٲٹھۍ چُھ خداوند خدا وَنان۔ ییلہ بہٕ ژے اکھ ویران شہر بناوِ، یِتھٕ پٲٹھۍ شہرن ہٕندۍ پٲٹھۍ، یِمن منز نہٕ آباد آسہِ۔ ییلہ بہٕ ژے پیٹھ سرٛوٚن انان، تہٕ بٔڈ آب کرِ ژے ؤلِتھ۔\n20. ییلہ بہٕ ژے تِمن سٍتـ̡ یِمن سٍتـ̡ پرانہِ زمانہٕ کین لُکن سٍتـ̡ وسان چُھہ، تہٕ ژے تھاوٕ تِمن سٍتـ̡ زمینہِ ہٕندِس بٔنِمِس حصس مَنٛز، یِمن سٍتـ̡ یِم کھۅنہٕ وسان چِھہ، یُس نہٕ تُہٕندِس بٔسِتھِس سٍتـ̡ بٔنِتھ روزُن۔ تہٕ بہٕ کٔرٕ زندٕ سٕندِس سرزمینس مَنٛز عظمت حٲصِل۔\n21. بہٕ بناوٕ ژے اکھ دہشت تہٕ تہٕ ژٕ گژھ نہٕ بییہٕ تہٕ یێلہِ {اکھ دہشت گردی: ہیب۔ دہشت ہُند دہشت}","1. خداوند سُند کلام آو میہ نِش دُبارٕ وونُن،\n2. وۅنۍ اے انسان سٕندِ نیچو، تُل ٹائرس سٕندِ خٲطرٕ اکھ ماتم ۔\n3. تہٕ وَنُن طایرس، اے یُس سمندرٕ کِس دروازس پیٹھ بٔسِتھ چُھ، یُس واریاہن جزیرن ہٕندِس لُکن ہُند سوداگر، یِتھٕ پٲٹھۍ چُھ خداوند خدایہ فرماوان۔ اے ٹائرس، ژے چُھس ووٚنمُت، بہٕ چُھس کامل خوبصورتی۔ {کامل...: ہیب۔ خوبصورتی ہند کامل}\n4.\\tچانۍ سرحد چھیہ سمندرن منز، چانۍ معمارو چھیہ چانۍ خوبصورتی کامل کرمژ۔ {درمیان: ہیب۔ دِل}\n5.\\tتِمو چھِ تُہٕندِس سارِنٕے سٲرِسٕے سِنیرٕکِس فر کُلِس سٍتـ̡ بَنوومُت: تِمو چھِ تۅہہِ ہٕندِ خٲطرٕ مستول بناونہٕ خٲطرٕ لبنان پیٹھٕ دیودار نِمٕتۍ۔ {بنیومُت: ہیب۔ بَناونہٕ آمُت}\n6.\\t﴿﴾ بشنٕکۍ اوکَن چھُ تُہٕندِس کھورِ ہٕندِس کھورِ ہٕندِس سٍتۍ بَنٲومٕتۍ۔ اشورین ہٕنزِ صحبتہٕ چھِ تۅہہِ ہٕنزِ بینچ دٕندِ دٕندِ دندٕ بنٲومٕژ، {اَنِن} چِٹِم کِس جزیرٕ منزٕ نِنہٕ۔ {صحبت...: یا، تِمو چھِ تۅہہِ ہٕندِ دندِ ہٕندِس ہیچس رٔٹِتھ لٔگۍمٕتۍ} {کمپنی: ہیب۔ کور}\n7. مصرٕچ کامہِ سٍتـ̡ نٔوۍ کُن سُہ اوس سُہ یُس ژے پنُن جہازٕ بٔنِتھ پھٔہلِتھ دِوان چھُ۔ ایلشہ کِس جزیرس پیٹھ نیول تہٕ واگن رنگ اوس سُہ یُس ژے ؤلِتھ اوس۔ {نیوٗل...: یا، جامنی تہٕ سرخ رنگ}\n8.\\tزیدون تہٕ اَروادٕکۍ بسکیٖن ٲسۍ تُہٕندِس جہازس سٍتـ̡ تُہٕندِس جہازس سٍتـ̡ تُہٕندِس دٲنِس {مرد}، اے ٹائرس، {یُس} اوس تُہند پائلٹ۔\n9.\\tجبل ہٕندِس قدیم تہٕ تِمن ہٕندِس دٲنِس سٍتـ̡ ٲس تۅہہِ سٍتـ̡ سمندرٕکۍ سارِنٕے جہازٕ تہٕ تُہٕندِس سَمنٛدازس سٍتـ̡ تۅہہِ سٍتـ̡ تُہٕندِس مالس پیٹھ قبضہ کرنہٕ خٲطرٕ۔ {calkers: یا، سٹاپرز آف چِنکس: Heb. مضبوط، وغیرہ}\n10.\\tتِم ٲسۍ فارس تہٕ لُد تہٕ پھُٹ سٕندِس فوجس منز، تۅہہِ ہٕندِس جنگی نفر: تِمو لوٚگ تۅہہِ منز ڈھال تہٕ ہیلمیٹ۔ تِمو کٔر تۅہہِ ہٕنز خوبصورتی پیش کرنہٕ۔\n11.\\tاَروادٕکۍ نفر ٲسۍ تُہٕندِس لشکرس سٍتـ̡ تُہنزن دیوارن پیٹھ، تہٕ گامادِم ٲسۍ تُہٕندِس مینارس منز: تِمو لٔگۍ پنٕنۍ ڈھال تُہنزن دیوارن پیٹھ۔ تِمو چھُ تُہٕنٛز خوبصورتی کٲمل کٔرمٕژ۔\n12.\\tترشِش اوس تُہند سوداگر۔ رۄپہٕ، ششتٕر، ٹیٖنہٕ تہٕ سیسہٕ سٍتۍ ٲسۍ تِمو تہندٮ۪ن میلن منز سودا کران۔\n13.\\tجاوان، توبل تہٕ میشچ، تِم ٲسۍ تُہندِ سوداگر: تِمو ٲسۍ تُہندِ بازرَس مَنٛز نفرن ہٕندِس نفرن تہٕ پیتلٕکۍ بانن ہُند سودا کران۔ {مارکیٹ: یا، تجارت}\n14.\\tتوگرمہ ہٕندِس گرس منز ٲسۍ تِمو گُرٮ۪ن تہٕ گُرِ سوارَن تہٕ خچرن سٍتـ̡ تُہٕندِس مٲلس مَنٛز تجارت کٔرِتھ۔\n15. دیدانٕکۍ مرد ٲسۍ تُہند سوداگر۔ واریاہ جزیرٕ {ٲس} تۅہہِ ہٕندِ اَتھٕ ہُند سامان: تِمو أنۍ ژے {تکیازِ} دندِ دندِ تہٕ آبنوس ہُند اکھ موجودٕ سینگ۔\n16.\\tشام اوس تُہند سوداگر، تۅہہِ ہٕندِس بٔڑِس سامانس سٍتـ̡ تہٕ تُہٕندِس مٲلس مَنٛز زمرد ، واگن تہٕ بٔرِتھ کامہِ سٍتـ̡ تہٕ نٔوۍ کُن تہٕ مرجان تہٕ عقیق۔ {سامانہٕ...: ہیب۔ تہند کامہٕ} {Agate: یا، chrysoprase}\n17.\\tیہوداہ، تہٕ اسرائیلٕچ سرزمین، تِم ٲسۍ تُہند سوداگر: تِمو ٲسۍ تُہندِ بازرِ مِنِتھ، تہٕ پناگ، ماچھ، تیٖل تہٕ بام ہُند تجارت۔ {بام: یا، روزن}\n18.\\tدمشقس اوس تُہند سوداگر، تہٕ سارِنٕے دولتن ہٕندِس بٔڈِس سٍتـ̡ ہیلبون کس شرابس منٛز، تہٕ سفید ییر۔\n19.\\tدان تہٕ جاوان تہِ یِمن ہٕندِس میلن منز یِوان گٔژھِتھ: چمکدار ششتٕر، کیسیا تہٕ کالامس ٲسۍ تُہندِس بازرس منز۔ {گَژھُن...: یا، میوزَل}\n20. دیدان اوس تُہند سوداگر، رتھَن ہٕندِ خٲطرٕ قیمتی پلوَن منٛز۔ {قیمتی...: ہیب۔ آزٲدی ہٕندۍ لباس}\n21.\\tعرب، تہٕ کیدارٕکۍ سٲری شہزادہ، تِمو کٔر توے سٍتـ̡ کۅکرِ تہٕ کۅکرِ تہٕ ژھاوٕرۍ، یِمن مَنٛز ٲسۍ تُہند سوداگر۔ {تِمو اوس قبضہ کٔرِتھ...: ہیب۔ تِم ٲسۍ تۅہہِ ہٕندِ اَتھٕکۍ سوداگر}\n22.\\tشیبا تہٕ راماہ ہٕندِ سوداگر، تِم ٲسۍ تُہٕندِس سوداگرَس مَنٛز سارِنٕے مسالہٕ تہٕ سارِنٕے قیمتی پتھرن تہٕ سۄنہٕ سٍتـ̡ سٍتـ̡ رٔٹِتھ ۔\n23.\\tہاران، تہٕ کنہ تہٕ عدن، شیبا ہٕکۍ سوداگر، آشور، {تہٕ} چلماد، {ٲس} تُہند سوداگر۔\n24.\\tیِم ٲسۍ تُہٕندِس سوداگرس پرٮ۪تھ قٕسمس منز، نیوٗل پلو تہٕ کامہِ منز، تہٕ مالدار پلون منز، رزِ سٍتۍ بٔنِتھ تہٕ دیودار سٕندِس سٍتـ̡ بٔنِتھ۔ {سٲری ...: یا، بہترین چیز} {پلو: ہیب۔ فولڈنگس}\n25.\\tترشِش سٕندِ جہازٕ گیوٚو تۅہہِ ہٕندِس بازرَس مَنٛز تہٕ ژے گٔیہٕ بٔرِتھ سمندرَس مَنٛز سٮ۪ٹھاہ شاندار۔\n26. چُھہ ژے بٔڈِس آبس مَنٛز أنِمُت: مشرِقی واو چُھ ژے سمندرَس مَنٛز پھُٹرٲومُت۔ {درمیان: ہیب۔ دِل}\n27.\\tتُہند دولت، تہٕ تُہند مالہٕ، تُہند مالہٕ، تُہٕندِس سَمٲرۍ، تہٕ تُہٕندِس جہازس سٍتـ̡ تہٕ تُہٕندِس سارِنٕے جنگی نفر، یُس تۅہہِ مَنٛز چُھ، تہٕ تُہٕندِس سارِنٕے صحبتس مَنٛز یُس تُہٕندِس تباہی ہٕندِس دۅہہٕ سمندرَس مَنٛز پَسُن۔ {تہٕ منز...: یا، سارِنٕے سٍتۍ تہِ} {سمندرن منز: ہیب۔ دِل وغیرہ}\n28.\\tمضافاتی علاقہ گژھہِ پننین پائلٹن ہٕنزِ فریاد ہٕنزِ آوازِ سٍتـ̡ لرزان۔ {مضافاتی علاقے: یا، لہریں}\n29.\\tتہٕ سٲری یُس کھورِ رَٹان چُھ، سمندرٕکۍ سٲری پائلٹ، گژھن پننیو جہازو پیٹھٕ بۄن، تِم گژھن زمینس پیٹھ کھڑا ۔\n30.\\tتہٕ یِمن ہٕنز آواز بوزناوٕن، تہٕ کٔرِن تِمن ہٕندِس کلَس پٲٹھـ̡ گردِ تراوُن، تِم گٔژھن پانس سٍتـ̡ رٔلِتھ\n31.\\tتہٕ تِم کرَن تۅہہِ خٲطرٕ پوٗرٕ پٲٹھۍ، تہٕ تِم کرَن تۅہہِ خٲطرٕ دِلہٕ سٍتـ̡ تلخی تہٕ تلخی سٍتـ̡ روُن۔\n32.\\tتہٕ تِمن ہٕندِس وَتہٕ سٍتـ̡ تُہٕندِس خٲطرٕ ماتم تہٕ تۅہہِ پیٹھ ماتم کٔرِتھ، {ونن} زِ سمندرس منز تباہ سپدن وٲلِس پٲٹھـ̡ کُس شہر چُھہ ٹائرس ہیوٗ شہر؟\n33.\\tییلہ تُہند سامان سمندرٕ منزہ نیرِ، ژے کٔر واریاہ لُکھ بٔرِتھ۔ ژے کٔر زمینہٕ کِس بادشاہن پنٕنۍ دولت تہٕ پنٕنۍ تجارتہٕ سٍتۍ مالا مال۔\n34.\\tییلہ تہِ ژیہ سمندرٕ سٍتۍ پھٹِتھ آبس منز، تۅہہِ ہُند مال تہٕ تُہٕنز سٲری صحبت گژھہِ پانس منز۔\n35.\\tجزیرن ہٕندِس سارِنٕے بسکیٖن دَر گژھن تۅہہِ وُچھِتھ حٲران تہٕ تِہٕندِس بادشاہس گژھن خوفزدہ تہٕ تِمن ہٕندِس بُتھِس سٍتـ̡ پریشان گٔژھن۔\n36.\\tلُکن ہٕندِس سوداگر سٍتـ̡ چُھہ ژے کُن پھِرُن۔ ژیہ گژھہِ دہشت گردی تہ بییہ زانہہ تہِ آسہِ۔ {اکھ دہشت گردی: ہیب۔ دہشت } {زانہہ نہ...: ہیب۔ ہمیشہٕ روزِ نہٕ ہمیشہٕ}","1. خداوند سُند کلام آو میہ نِش دُبارٕ وونُن،\n2.\\tانسان سٕندِس فرزندس وَنُن طایرس کِس شہزادس تہٕ یِتھٕ پٲٹھۍ چُھ خداوند خدایہ فرماوان۔ تکیازِ تُہند دِل چُھس تھوٚد تہٕ ژے چُھس ووٚنمُت، بہٕ چُھس خدایہ سٕنزِ نشستس پیٹھ بِہتھ، سمندرن منز۔ توتہِ چُھہ تُہۍ اَکھ انسان تہٕ خدایہ نہٕ، یێلہِ تہٕ توے چُھہ پَنُن دِل خدایہ سُند دِل تھاوُن: {درمیان: عبرانی۔ دِل}\n3.\\tوُچھو، ژے چھُکھ دانیال کھۅتہٕ زیادٕ عقلمند۔ کانہہ راز چھُنہٕ یُس تِم ژےٚ نِش ژوٗرِ تھٲوِتھ:\n4. پننہِ دانشمٲری تہٕ پننہِ عقلہٕ سٍتۍ کٔر ژے دولت حٲصل تہٕ سۄن تہٕ رۄپھ پننِس خزانس مَنٛز حٲصل کٔرۍمٕتۍ۔\n5.\\tپننہِ بٔڈ دانشمٲری سٍتۍ ہُرراوُن تہٕ چُھہ پنُن دِل تُلُن: {تُہُند عظیم...: ہیب۔ چانہِ حکمتٕچ عظمت}\n6. تَمہِ کِنۍ چُھ خداوند خدا یِتھٕ پٲٹھۍ وَنان۔ تکیازِ ژے چُھہ پنُن دِل خدایہ سُند دِل مقرر کورمُت۔\n7.\\tوُچھ، تێمہِ مۅکھہٕ بہٕ اَننہٕ تہٕ تِم کٔرِن تُہٕنزِ حکمتٕچ خوبصوٗرتی خلاف تلوار تہٕ تِم کٔرِن تُہٕنزِ گاش ناپاک کرنہٕ۔\n8.\\tتِم أنِن تۅہہِ کھۅڈس مَنٛز، تہٕ سمندرَس مَنٛز مارنہٕ آمٕتۍ تِمن ہُند مرُن مرُن۔\n9.\\tکیا ژیہ ونہِ تہِ ونُن یُس ژیہ ماران چُھ، بہٕ چُھس خدا؟ مگر تۅہہِ آسہِ انسان تہٕ کانہہ خدا، یُس ژے مارِ۔ {یُس ماران چُھ: یا یُس زخمی چُھ}\n10.\\tژے مرُن غیر ختنہ سپدن والین ہُند مرُن، کیازِ میہ چُھہ کتھ کٔرمٕژ، خداوند خدا چُھ فرماوان۔\n11. امہِ علاوٕ آو خداوند سُند کلام میانہِ نِش وونُن،\n12.\\tانسان سٕندِس بادشاہس سٍتـ̡ رٔٹِتھ تہٕ ونُن زِ خداوند خدایہ چُھ یِتھٕ پٲٹھۍ فرماوان۔ ژے چھکھ حکمت، تہٕ خوبصورتی سٍتۍ بٔرِتھ تہٕ خوبصورتی سٍتـ̡ مُہر کٔرِتھ۔\n13. تہٕ تہٕ چُھہ خدایہ سٕندِس باغس منز عدنس مَنٛز۔ پرٮ۪تھ کانہہ قیمتی پتھر اوس تُہند پردٕ، سارڈیس، ٹوپاز تہٕ ہیرہ، بیرل، اونکس، تہٕ جیسپر، نیلم، زمرد تہٕ کاربنکل تہٕ سۄن: تۅہہِ ہٕندِس ٹیبریٹس تہٕ پایپن ہٕنز کاریگری ٲس تۅہہِ منز تمہ دۅہہ تیار کرنہٕ آمٕژ ییمہ دۅہہ ژے تخلیق کرنہٕ آو۔ {سارڈیئس: یا، روبی} {بیریل: یا، کرسولائٹ} {زمرد: یا، کرسوپراس}\n14.\\tژے چھُکھ مسح کٔرِتھ کرُن یُس پردہ کٔرِتھ چھُ۔ تہٕ مے چُھس ژے مقرر کٔرمٕژ: تہٕ ژٕ ٲسکھ خدایہ سٕندِس مقدس پہاڑس پیٹھ۔ ژے چُھکھ نارٕ کِس کنن منز ہیوٚر بوٚن پکان ۔\n15.\\tژے روُز تمہِ دۅہہ پیٹھٕ یُس تہٕ ژے تخلیق کرنہٕ آمُت اوس، تۅہہِ سٍتـ̡ بد کاری لبنہٕ یِنہٕ وٲلِس دۅہہٕ پیٹھٕ پنہٕ نِس طریقس مَنٛز کامل۔\n16.\\tچانہِ تجارتہٕ سٍتـ̡ چُھہ تِمو ژے منزٕ تشددٕ سٍتـ̡ بٔرِتھ تہٕ ژے کٔرِکھ گۅنہہ، تێلہِ کٔرٕ بہٕ ژے خدایہ سٕندِ پہاڑہٕ پیٹھٕ ناپاک سٍتـ̡ کٔڈِتھ تہٕ بہٕ کٔرٕ ژے تباہ کٔرِتھ ، اے پردٕ کرُن، نارٕ کِس پتھرس منز۔\n17.\\tچانہِ خوبصورتی سٍتـ̡ چُھہ تُہُند دِل تُلُمُت، ژے کٔر پننہِ چمکہٕ سٍتـ̡ پنٕنۍ حکمت خراب: بہٕ تراوٕ ژے ژے زمینس پیٹھ، بہٕ تراوٕ ژے بادشاہن برونہہ کُن، یُتھ تِم ژے وُچھن۔\n18.\\tژے کٔر پنہٕ نِس گناہ سٍتـ̡ پنٕنـ̡ گناہ سٍتـ̡ ناپاک کرنہٕ۔ تَمہِ مۄکھٕ کَرٕ بہٕ ژےٚ منزٕ اکھ نار، سُہ ژےٚ ژٔلِتھ تہٕ بہٕ اَننہٕ ژےٚ سارِنٕے سارِنٕے وٕچھن وٲلِس نظرِ سوٗر کٔرِتھ۔\n19.\\tیُس تۅہہِ لُکن منز زانان چھُ، تۅہہِ گژھہِ حیران گژھُن: ژیہ گژھہِ دہشت تہٕ زانہہ تہِ روزُن۔ {اکھ دہشت گردی: ہیب۔ دہشت ہُند دہشت}\n20. دُبارٕ آو خداوند سُند کلام میانہِ نِش وونُن،\n21. اِنسان سٕندِس فرزندس کٔرِو پَنُن بُتھ زِدونس خٕلاف، تہٕ اَتھ خٕلاف کٔرِو پیشن گوئی،\n22. تہٕ ونُن، خداوند خدا چُھ یِتھٕ پٲٹھۍ فرماوان۔ وُچھ، بہٕ چُھس ژے خلاف، اے زیدون۔ تہٕ بہٕ گژھہِ توے سٍتـ̡ جلال حٲصل کرنہٕ: تہٕ تِمن گژھہِ معلوم زِ بہٕ چُھس خداوند چُھس، یێلہِ بہٕ أمِس مَنٛز فیصلہٕ انجام دِیہ، تہٕ یێلہِ بہٕ یێلہِ أمِس مَنٛز پاک سپدٕنـ̡ ۔\n23. تکیازِ بہٕ سوزٕ تٔمۍ سٕنزِ وبا تہٕ تٔمۍ سٕنزِ سڑکن منز خون۔ تہٕ زخمیَن ہُند فیصلہ یِیہِ أمِس درمِیان پرٮ۪تھ طرفہٕ تلوار سٍتۍ کرنہٕ۔ تہٕ تِمن گژھہِ پتاہ زِ بہٕ چُھس خداوند ۔\n24.\\tتہٕ یِمن اندۍ پٔکھۍ یِمن سٍتـ̡ حقارت کرن وٲلِس سارِنٕے سارِنٕے سٍتـ̡ گژھہِ نہٕ کانہہ دُکھ دِنہٕ یُن، تہٕ یِمن سٍتـ̡ حقارت کٔرِتھ آسہِ۔ تہٕ تِمن گژھہِ پتاہ زِ بہٕ چُھس خداوند خدا۔\n25.\\tیِتھے پٲٹھۍ چُھ خداوند خدایہ فرماوان۔ یێلہِ بہٕ یِمن لُکن نِش اسرٲیلُک گرٕ جمع کٔرِتھ یِمن مَنٛز تِم پھٔہلِتھ چھِ، تہٕ یِمن مَنٛز یِم کافرن ہٕندِس نظرس مَنٛز پاک کرنہٕ یِن، تێلہِ گژھن تِم پننِس سرزمینس مَنٛز روزان یُس مے پننِس خادم یعقوبس دِژمُت چھُ۔\n26. تہٕ تِم روزن اَتھ مَنٛز محفوٗظ روزان، تہٕ مکانہٕ بناوٕن، تہٕ انگور کٔرِن باغ۔ آ، تِم روزن اعتبارٕ سٍتۍ، ییلہ میہ تِمن سارِنٕے نفرتَن پیٹھ فیصلہٕ دِنہٕ آسہِ یِم تِمن اندۍ پکھۍ حقارت کران چھِ۔ تہٕ تِمن گژھہِ معلوم زِ بہٕ چُھس خداوند تِہُند خدا۔ {محفوٗظ پٲٹھۍ: یا، اعتمادٕ سان} {حقارت کرُن: یا، خراب}","1. دٔہمہِ ؤریس منز، دٔہمہِ ریتس منز، بٔہمہِ دۅہہ، رب سُند کلام آو میہ نِش،\n2. اِنسانہٕ سٕندِس بُتھِس سٍتـ̡ کٔرِو پَنُن بُتھ مصرُک بادشاہ فرعونس سٍتـ̡ تہٕ أمِس سٍتـ̡ تہٕ سارِنٕے مصرس سٍتـ̡ پیشن گویی کٔرِو:\n3. کتھ کرو تہٕ ونُن، یِتھٕ پٲٹھۍ چُھ خداوند خدایہ فرماوان۔ وُچھ، بہٕ چُھس ژے خلاف، مصرُک بادشاہ فرعون، سُہ بٔڈ ڈریگن یُس پننین دریاوَن منز بٔرِتھ چُھ، یُس وَنُن چُھ، میون دٔریاو چُھ میون پنُن، تہٕ مے چُھس پانس خٲطرٕ بنوومُت۔\n4.\\tمگر بہٕ تراوٕ چانہِ دٔریاوَن ہٕنزِ گاڈٕ تہٕ بہٕ کٔرٕ چانہِ دریاوَن ہٕندِس گاڈٕ سٍتـ̡ ژٔٹِتھ تہٕ بہٕ کٔرٕ ژے تُہٕندِس دریاوَن منزٕ نیبر تہٕ تُہٕندِس سٍتـ̡ گاڈٕ ژٔٹِتھ ژٔٹِتھ تہٕ تُہٕندِس دٔریاوَن ہٕندِس سارِنٕے گاڈٕ ژٔٹِتھ ژٔٹِتھ ۔\n5. تہٕ بہٕ تراوٕ ژے بیابانس مَنٛز، ژے تہٕ پنٕنۍ دریاوَن ہٕندِس سارِنٕے گاڈَن ہٕندِس سٍتـ̡ پۯاوٕنـ̡ ژے یِیہِ نہٕ اَکہٕ وٹہٕ اننہٕ، تہٕ نہ یِیہِ جمع کرنہٕ: مے چُھس ژے کھہہٕ کین درندَن تہٕ اسمانٕکۍ جاناوارن ماز خٲطرٕ دِژمُت۔ {کھولو...: ہیب۔ میدانُک بُتھ}\n6. تہٕ مصر کین سارنٕے بسکینن گژھہِ معلوم زِ بہٕ چُھس خداوند چُھس، کیازِ تِم چُھہ اسرٲیلِس کِس گرس سٍتـ̡ نِشہ سٍتـ̡ سٍتـ�\n7. ییلہ تِمو تۅہہِ ہٕندِس اتھس تھپھ کٔرِتھ ژٔٹِتھ ژٔٹِتھ تہٕ تِہٕندِس سارِنٕے لٔگِس لٔگِتھ ژٔٹِتھ تہٕ ژٔٹِتھ ژٔٹِتھ تہٕ ژٔٹِتھ تہٕ تِہٕندِس سارِنٕے لٔگِس رٔٹِتھ رٔٹِتھ ۔\n8. تَمہِ کِنۍ چُھ خداوند خدا یِتھٕ پٲٹھۍ وَنان۔ وچھ، بہٕ اَنہٕ ژےٚ پٮ۪ٹھ تلوار، تہٕ ژےٚ نِش ژٔٹِتھ انسان تہٕ جانور ژٔٹِتھ۔\n9. تہٕ مصرٕچ سرزمین گژھہِ ویران تہٕ ویران۔ تہٕ تِمن گژھہِ پتاہ زِ بہٕ چُھس خداوند چُھس: کیازِ تٔمۍ چُھ ووٚنمُت، دٔریاو {چُھ} میون تہٕ مے چُھس {یہ} بنوومُت۔\n10.\\tوُچھ، تێمہِ کِنۍ چُھس بہٕ ژے تہٕ تۅہہِ دریاوَن خلاف، تہٕ بہٕ کرٕ مصرٕچ سرزمینہٕ سراسر ویران تہٕ سینے کِس مینار پیٹھٕ حتیٰ کہ ایتھوپیا کِس سرحدس تام۔ {بلکل ...: ہیب۔ فضلہٕ فضلہٕ} {منز...: یا، مِگڈول پیٹھہٕ سینی تام} {Syene: Heb. Seveneh}\n11. اَتھ مَنٛز گژھِ نہٕ انسان سُند کھوٚر نیرُن، تہٕ نہ گژھِ اَتھ مَنٛز ژتٲجی ؤری روزُن۔\n12. تہٕ بہٕ بناوٕ مصرٕچ سرزمین تِمن ملکن مَنٛز ویران تہٕ یِمن شہرن مَنٛز یِم تباہ گٔیہِ، تہٕ بہٕ کٔرٕ مصری قومن مَنٛز پھٔٹِتھ تہٕ تِم کٔرِن ملکن مَنٛز منتشر کرنہٕ۔\n13. توتہِ چُھ خداوند خدا یِتھٕ پٲٹھۍ وَنان۔ ژتٲجی ؤری سپدِتھ کٔرٕ بہٕ مصری لوکن نِش جمع ییتہِ تم منتشر ٲسۍ۔\n14.\\tتہٕ بہٕ اَنِہ دُبارٕ مصرُک قید تہٕ تِم کرٕ پتھرو سٕندِس سرزمینس منز، تِمن ہٕندِس بستی ہٕندِس سرزمینس مَنٛز واپس۔ تہٕ تِم آسن اَکھ بُنیٲدی بادشٲہی ۔ {رہائش: یا، پیدائش} {بیس: ہیب۔ کم}\n15. یہِ گژھِ سلطنتَن مَنٛز سارِوٕے کھۄتہٕ بُنیٲدی آسُن۔ تہٕ نہ کرٕ یہٕ قومن کھوتہٕ زیادٕ پانس تھزر: کیازٕکہ بہٕ کرٕ تم کم کرنہٕ، تاکہ تم کرن نہٕ مزید قومن پیٹھ حکمرٲنی کرنہٕ۔\n16. تہٕ یہِ گژھہِ نہٕ اسرٲیلِکِس گرس سٍتـ̡ یقین یُس تِمن ہٕندِس گُناہ سٍتـ̡ یاد تھاوان چُھ، یێلہِ تِمن ہُند خیال تھاون بێیہِ تێلہِ بێیہِ تِمن ہُند خیال تھاوُن، مگر تِمن گژھہِ پتاہ زِ بہٕ چُھس خداوند خدا۔\n17.\\tتہٕ سپُد سَتِمہِ وُہمہِ ؤریس مَنٛز، گۄڈنِکِس {رٮ۪تھ} مَنٛز، ریتھ کِس گۄڈنِکِس {دۄہ} مَنٛز، خداوند سُند کلام آو مےٚ نِش،\n18.\\tانسان سُند نیچو، بابل کِس بادشاہ نیبوکدرِزارن دِژ پنُن لشکر ٹائرس خٕلاف اکھ بٔڈ خدمت انجام دِنہٕ: پرٮ۪تھ کلہٕ اوس ٹَکلہٕ بناونہٕ آمُت، تہٕ پرٮ۪تھ کُنہِ پھیُر اوسُکھ ژُلنہٕ آمُت، توتہِ اوس نہٕ تس کانہہ مزدوری، تہٕ نہ اوس تٔمۍ سُند لشکر ٹائرس سٕندِ خٲطرٕ، تمہِ خدمتہٕ خٲطرٕ یُس تٔمۍ اتھ خلاف کٲم کٔرمٕژ ٲس۔\n19. تێمہِ کِنۍ چُھ خداوند خدا یِتھٕ پٲٹھۍ ونان ؛ وچھ بہٕ دِیہ مصرٕچ سرزمین بابل کِس بادشاہ نبوکدرزارس ۔ تہٕ سُہ نِیہِ أمِس بٔڑِس سٍتـ̡ تہٕ تٔمۍ سُند شِکار۔ تہٕ یہ آسہِ تٔمۍ سٕندِ فوجُک معاوضہٕ۔ {تٔمۍ سُند غنیمت نِیو...: ہیب۔ تٔمۍ سُند غنیمت خراب کرُن، تہٕ أمۍ سُند شکار}\n20. میہ چُھ تس مصرٕچ زمین دِژمٕژ یێمہِ سٍتـ̡ تٔمۍ سٕنزِ محنتہٕ سٍتـ̡ أمِس خٕلاف خدمت کٔرمٕژ، کیازِ تِمو کٔر میانہِ خٲطرٕ، خداوند خدا چُھ ونان ۔ {تٔمۍ سٕنٛدِ خٲطرٕ...: یا، تٔمۍ سٕنٛدِ کرایہٕ خٲطرٕ}\n21. اَمہِ دۅہہٕ کَرٕ بہٕ اِسرٲیلِس ہٕندِس گرس ہُند سینگ پھُلُن، تہٕ بہٕ دِیہٕ ژے تِمن مَنٛز ٲسُک کھُلہٕ۔ تہٕ تِمن گژھہِ پتاہ زِ بہٕ چُھس خداوند ۔","1. خداوند سُند کلام آو میہ نِش دُبارٕ وونُن،\n2. اِنسان سُند فرزند، پیشن گویی کٔرِو تہٕ ونُن، یِتھٕ پٲٹھـ̡ چُھ خداوند خدایہِ سُند وَنان۔ ہاؤل یے، واہ دۅہہ!\n3. یُس دۅہ {چُھ} نزدیک، یوتام زِ خداوند سُند دۅہ {چُھ} نزدیک، اَکھ اوٚبرُک دۄہ۔ یہِ آسہِ کافرن ہُند وق۔\n4. تہٕ تلوار گژھہِ مصرس پیٹھ، تہٕ ایتھوپیاہَس مَنٛز گژھہِ سٮ۪ٹھاہ دَگ، یێلہِ مارنہٕ ییہِ مصرس مَنٛز، تہٕ تِم نِن تٔمۍ سٕنز بُنیاد پھُٹراونہٕ۔ {دَگ: یا، خوف}\n5. ایتھوپیا، تہٕ لیبیا، تہٕ لِدِیا، تہٕ سارِنٕے رَلہٕ مِلہٕ لُکھ تہٕ چُب تہٕ یُس زمینہِ ہٕندِس لُکن سٍتـ̡ رٔلِتھ چُھ، یِمن سٍتـ̡ تلوار سٍتـ̡ پۯاوُن۔ {لیبیا: ہیب۔ Phut} {مرد: Heb. بچہٕ}\n6. خداوند چُھ یِتھٕ پٲٹھۍ فرماوان۔ تِم تہِ یِم مصرس برقرار تھاوان چھِ، تِم گژھن پٮ۪وان۔ تہٕ تٔمۍ سٕندِ طاقتُک غرور گژھہِ وسُن: ساین کِس مینار پیٹھٕ گژھن تِم تلوار سٍتـ̡ اَتھ مَنٛز پیوٚن، خداوند خدا چُھ فرماوان۔ {پیٹھ...: یا، مگڈول پیٹھہٕ سینی تام}\n7. تہٕ تِم گژھن ویران مُلکن مَنٛز ویران تہٕ تٔمۍ سٕندِس شہر گژھن تِمن شہرن مَنٛز یِم تباہ گٔمٕتۍ۔\n8. تہٕ تِمن گژھہِ پتاہ زِ بہٕ چُھس خداوند چُھس، یێلہِ بہٕ مصرس مَنٛز نار دِیُت، تہٕ {یێلہِ} تٔمۍ سٕندِ سٲری مددگار گژھن تباہ کرنہٕ۔ {تباہ: ہیب۔ پھُٹمُت}\n9.\\tاَمہِ دۅہہٕ گژھن میہ نِش جہازن منز قاصد نیران تاکہ لاپرواہ ایتھوپِین خوفزدہ کرنہٕ مۅکھہٕ، تہٕ یِمن سٍتـ̡ سٮ۪ٹھاہ دَگ واتہِ، یِتھٕ پٲٹھـ̡ مصر کہِ دۅہہٕ سٍتـ̡ سپدِ۔\n10.\\tخداوند خدا چُھ یِتھٕ پٲٹھۍ فرماوان۔ بہٕ کٔرٕ مصرٕچ ہجوم تہِ بابل کِس بادشاہ نبوکدرِزر سٕندِ اتھہٕ سٍتـ̡ بند کرنہٕ۔\n11.\\tسُہ تہٕ تٔمۍ سٕندِس لُکھ یِن أمِس سٍتـ̡ قومن ہٕندِس خوفناک سٍتـ̡ زمینہٕ تباہ کرنہٕ خٲطرٕ اننہٕ۔ تہٕ تِم کٔرِن مصرس خلاف تلوار تُلنہٕ، تہٕ مارن والیو سٍتـ̡ زمینس بٔرِتھ۔\n12. تہٕ بہٕ کٔرٕ دریاو خشک تہٕ زمینہٕ کٕنِتھ بدکارن ہٕندِس اتھس منز، تہٕ بہٕ کٔرٕ زمینہٕ تہٕ یُس تہٕ یُس تہٕ اَتھ مَنٛز موجود چھُ، اَتھ منز موجود سارِنٕے چیز، اَمہ سٍتـ̡ چُھس کٔرِتھ کٔرِمُت: بہٕ چُھس خداوند کٔرِتھ کتھ کٔرمٕژ۔ {خشک : ہیب۔ خشک سالی} {all...: Heb. امچ مکمل آسن}\n13. خداوند خدا چُھ یِتھٕ پٲٹھۍ وَنان۔ بہٕ کٔرٕ بُت تہِ تباہ تہٕ بہٕ کرٕ نوفس نِش {تِہٕن} شکلہٕ بند کرنہٕ۔ تہٕ بییہِ آسہِ نہٕ مصر کِس سرزمینُک شہزادٕ تہٕ بہٕ کرٕ مصرٕچ سرزمینس منز خوف۔\n14.\\tتہٕ بہٕ کرٕ پتھروس ویران تہٕ زونس منز نار دِیہِ، تہٕ کرٕ نمبرس منز فیصلن پیٹھ عمل۔ {زون: یا، ٹینس}\n15. تہٕ بہٕ تراوٕ پنُن غصہٕ گۅنہہ، مصرٕچ طاقت۔ تہٕ بہٕ ژٔٹِتھ کٔرِس نمبر۔ {گناہ: یا، پیلوسیم}\n16.\\tتہٕ بہٕ دِیہٕ مصرس مَنٛز نار: گۅناہ گژھہِ سٮ۪ٹھاہ دَگ تہٕ پھٔٹِتھ تہٕ نوفس روزِ دۅہہٕ مصیبت۔\n17.\\tایوین تہٕ پِبسیتھٕکۍ جوان گژھن تلوار سٍتـ̡ پٔرِتھ تہٕ یِم {شہر} گژھن قٲد کرنہٕ۔ {ایوین: یا، ہیلیوپولس} {Pibeseth: یا، Pubastum}\n18.\\tتہٕ تہِ گژھہِ سُہ دۅہ انہِ گوٚٹ، یێلہِ بہٕ تتہِ مصرٕچ کۅکرِ پھُٹراوِ، تہٕ تٔمِس سٕندِس طاقتُک شوکت گژھہِ أمِس مَنٛز ختم۔ {اندھیر: یا، روکُن}\n19. یِتھٕ پٲٹھـ̡ بہٕ کَرٕ مصرس مَنٛز فیصلہٕ: تہٕ تِمن گژھہِ معلوم زِ بہٕ چُھس خداوند چُھس۔\n20.\\tتہٕ یہ سپُد کاہمہِ ؤریس منز، گۅڈنکس {ریت} منز، ریتہٕ کِس سٔتِمس دۅہس منز، {یُس} خداوند سُند کلام آو میہ نِش وونُن،\n21. اِنسان سٕندِس نیٚچُو، مے پھُٹروو مصرُک بادشاہ فرعون سٕنز نٔر تہٕ لو، یہ گژھِ نہٕ ٹھیک گژھنہٕ خٲطرٕ پابند کرنہٕ، اتھ رٔٹنہٕ خٲطرٕ اکھ رولر تراونہٕ خٲطرٕ، تلوار رٹنہٕ خٲطرٕ مضبوٗط بناونہٕ خٲطرٕ۔\n22. تَمہِ کِنۍ چُھ خداوند خدا یِتھٕ پٲٹھۍ وَنان۔ وچھ بہٕ چُھس مصر کِس بادشاہ فرعونس خلاف، تہٕ پھُٹراوٕ تٔمۍ سٕندِ نٔرۍ، مضبوٗط تہٕ یُس پھُٹمُت اوس۔ تہٕ بہٕ کرٕ تلوار أمۍ سٕنٛدِ اتھہٕ منٛزٕ نیبر۔\n23.\\tتہٕ بہٕ کٔرٕ مصری قومن مَنٛز پھٔٹِتھ تہٕ کٔرٕ تِم مُلکن مَنٛز منتشر کرنہٕ۔\n24.\\tتہٕ بہٕ کٔرٕ بابل کِس بادشاہ سٕنزِ نرِ مضبوٗط، تہٕ پنٕنۍ تلوار تٔمۍ سٕندِس اتھس منز، مگر بہٕ پھُٹراوٕ فرعون سٕنز نرِ تہٕ سُہ کرِ أمِس برونہہ کنہِ أکِس مہلک زخم سٕنزِ کرٛٮ۪کہٕ سٍتـ̡ گرٛٮ۪کھہٕ۔\n25. مگر بہٕ کٔرٕ بابل کِس بادشاہ سٕندِ نرِ مضبوط، تہٕ فرعون سٕندِ نٔر پیوٚو پیوٚو۔ تہٕ تِمن گژھہِ پتاہ زِ بہٕ چُھس خداوند چُھس، ییلہ بہٕ پنٕنۍ تلوار بابل کِس بادشاہ سٕندِس اتھس مَنٛز تھوو، تہٕ سُہ کرِ یہ مصرٕکِس سرزمینس پیٹھ پھٔہلاونہٕ۔\n26. تہٕ بہٕ کٔرٕ مصری قومن مَنٛز منتشر تہٕ تِم کٔرِن ملکن مَنٛز پھٔٹِتھ۔ تہٕ تِمن گژھہِ پتاہ زِ بہٕ چُھس خداوند ۔","1. تہٕ یہ سپُد کاہمہِ ؤریس منز، تریمس {ریت} منز، ریتہٕ کِس گۄڈنِکِس {دۅہ} منز، {یُس} خداوند سُند کلام آو میہ نِش وونُن،\n2. اِنسان سٕندِس نیٚچُو، کٔرِو مصرٕکِس بادشاہ فرعونس سٍتـ̡ تہٕ تٔمِس لٔگِس سٍتـ̡ کتھ کرنہٕ۔ ژیہ کُس چھکھ پننہِ عظمتس منز ہیو ؟\n3.\\tوُچھِو اَشورِیَن اوس لبنانس مَنٛز اَکھ دیودار، یٔمِس سٍتـ̡ گورٕ لنجہِ تہٕ ژھایہِ دار کفن تہٕ تھدِ تھدِ ہُند اوس۔ تہٕ تٔمۍ سُنٛد ٹاپ اوس گٔنٮ۪ن لنجہِ منٛز۔ {منصفانہ شاخن سۭتۍ: ہیب۔ شاخن ہُند میلہٕ}\n4.\\tآبن بنوو سُہ عظیم، سرٛنٮ۪ن کٔر سُہ تھزرس پیٹھ تھزرس پیٹھ تہٕ سوٗزِن پنٕنۍ لۅکٹۍ دریاو کھیت کین سارنٕے کُلٮ۪ن تام۔ {بنوو...: یا، پرورش کٔرِتھ} {سیٹ...: یا، أمِس اننہٕ} {لٹل ریورز: یا، نالہٕ}\n5.\\tامہِ مۅکھہ اوس تٔمۍ سُند تھزر کھیت کین سارِنٕے کُلٮ۪ن پیٹھ، تہٕ تٔمۍ سٕندِ لنجہِ ہٕندِ کُلِس ہٕندِس کُلِس ہٕندِس تھزرس پیٹھ، تہٕ تٔمۍ سٕنزِ لنجہِ گٔیہِ واریاہ آبہٕ کِنۍ زیٖٹھۍ۔ {ییلہ...: یا، ییلہ تم سوزۍ}\n6.\\tاسمانٕکۍ سارِوٕے جاناوارو بَنوو تٔمۍ سٕندِس لٔنڈِس مَنٛز پنٕنۍ گُرٕ تہٕ تٔمۍ سٕنزِ لنجہِ تَل کٔر میدانٕکۍ سارِوٕے جانور پنٕنۍ بچہٕ پٲدٕ تہٕ تٔمۍ سٕندِس ژھایہ تل ٲسۍ سارِنٕے بٔڈ قومن روزان۔\n7. یِتھے پٲٹھۍ اوس سُہ پننہِ عظمتس منز، پننین لنجہِ ہٕندِس زیچھرس منز، تکیازِ تٔمۍ سُند مول اوس بٔڈۍ آبہٕ سٍتـ̡ ۔\n8.\\tخدایہ سٕندِس باغس مَنٛز ہیوٚک نہٕ سُہ ژوٗرِ تھٲوِتھ: فر کُلۍ ٲسۍ نہٕ تٔمۍ سٕنزِ لنجہِ ہٕندۍ پٲٹھۍ، تہٕ شطرنج کُلۍ ٲسۍ نہٕ تٔمۍ سٕنزِ لنجہِ ہٕندۍ پٲٹھۍ۔ تہٕ نہ اوس خدایہ سٕندِس باغس منز کانہہ تہِ کُل پننہِ خوبصورتی منز أمِس ہیوٗ آسان۔\n9.\\tمیہ بنوو تس پننہِ لنجہِ ہندِ بٔڈۍ سٍتـ̡ خوبصورت: یُتھ عدنٕکۍ سٲری کُلۍ یِم خدایہ سٕندِس باغس مَنٛز ٲسۍ، تٔمِس سٍتـ̡ حسد کٔرِتھ۔\n10. تَمہِ کِنۍ چُھ خداوند خدا یِتھٕ پٲٹھۍ وَنان۔ تکیازِ ژے چُھکھ پنُن تھزر تھوٚد کٔرمُت، تہٕ تٔمۍ چُھس گٔنِس لنجہِ منز پنُن تھوٚد تھوٚد تہٕ تٔمۍ سُند دِل چُھ تھزرس پیٹھ تھوٚد۔\n11. تێمہِ کِنۍ چُھس مے سُہ کافرن ہٕندِس طاقتور سٕندِس اتھس مَنٛز دِژمُت۔ سُہ کرِ یٔقیٖنی طور أمِس سٍتـ̡ سٍتـ� {وہ...: ہیب۔ اتھ منز کرِ سُہ أمِس سٍتۍ}\n12.\\tتہٕ قومن ہٕندِس خوفناکَس چھُ أمِس ژٹِتھ ژٔٹِتھ دِژمُت: بالن تہٕ سارنٕے وادین مَنٛز چھِ تٔمۍ سٕنزِ لنجہِ پٔسۍمٕژ، تہٕ تٔمۍ سٕنزِ لٔنٛجہِ چھِ زمینہٕ کِس سارِنٕے دریاوَن سٍتـ̡ پھُٹمٕژ۔ تہٕ زمینٕکۍ سٲری لُکھ گٔیہِ أمۍ سٕنٛدِ ژھایہِ نِش بۄن، تہٕ گٔیہِ أمِس ترٲومٕتۍ۔\n13.\\tتٔمۍ سٕندِس برباد گژھنس پیٹھ گژھن اسمانٕکۍ سٲری جاناوار باقٕے تہٕ میدانٕکۍ سٲری جانور آسن تٔمۍ سٕنزِ لنجہِ پیٹھ۔\n14.\\tیُتھ زِ آبہٕ سٍتـ̡ سارِنٕے کُلـ̡ چُھہ نہٕ پننِس تھزرس سٍتـ̡ تُلِتھ، نۂ تہٕ تِہٕندِس کُلـ̡ ہٕندِس تھزرس سٍتـ̡ چُھہ تِمن ہٕندِس تھزرس سٍتـ̡ کھٔسِتھ، یێلہِ تِم سارِنٕے کُلـ̡ چُھہ مرنہٕ آمُت، یێلہِ چُھہ سارِنٕے کُلـ̡ ہٕندِس تھزرس مَنٛز دِنہٕ آمُت، یێلہِ چُھہ سارِنٕے کُلـ̡  تِمن سٍتۍ یِم کھۄدٕ گَژھان چھِ۔ {تہند کُل...: یا، پننس تھزرس پیٹھ کھڑا چُھ}\n15. خداوند خدا چُھ یِتھٕ پٲٹھۍ فرماوان۔ ییمہِ دۅہہ سُہ قبرِ پیٹھ ووت میہ گۆو ماتم تہ میہ کور تس سٍتۍ سرٛوٚن تہٕ میہ رُکٲوۍ امہِ سٍتۍ سٔہلاب تہٕ بٔڈ آب رُکاونہٕ آمُت: تہٕ مے کٔر لبنان تٔمۍ سٕندِ خٲطرٕ ماتم تہٕ میدانٕکۍ سٲری کُلۍ گٔیہِ أمِس خٲطرٕ بے ہوش۔ {ماتم کرنہٕ خٲطرٕ: ہیب۔ کرٛیٚہنہٕ آسُن}\n16.\\tمیہ بنوو قومہٕ تٔمۍ سٕندِس زوال کِس آوازِ سٍتـ̡ لرزاونہٕ، یێلہِ بہٕ سُہ تِمن سٍتـ̡ جہنمس مَنٛز ترٛاوُن یُس کھۅنہٕ وسان چُھ، تہٕ عدنٕکۍ سارِنٕے کُلۍ، یُس لبنان ہُند انتخاب تہٕ بہترین، آب چیوان چُھ، یِم سٲری آب چیوان چھِ، گژھن زمینہِ ہٕندِس بٔنِس حصس مَنٛز تسلی دِنہٕ۔\n17. تِم تہِ گٔیہِ أمِس سٍتـ̡ جہنمَس مَنٛز یِم تلوار سٍتـ̡ مارنہٕ آمٕتۍ۔ تہٕ {تِم یِم أمۍ سٕنزِ نٔر ٲسۍ، {یُس} ٲسۍ کافرن ہٕندِس ساے تل روزان۔\n18.\\tژہ کُس چھُکھ عدن کین کُلٮ۪ن منز عظمت تہٕ عظمتس منز ہیو آسان؟ توتہِ گژھ ژیہ عدن کین کُلٮن سٍتـ̡ زمینہِ ہٕندِس بٔنِس حصس مَنٛز والنہٕ: توے گژھِو تلوار سٍتـ̡ مارنہٕ آمٕتـ̡ ختنہ کرنہٕ آمٕتـ̡ رٔٹِتھ ۔ یہِ چُھ فرعون تہٕ تٔمۍ سٕندِس سارِنٕے بٔڈِس سٍتـ̡ خداوند خدایہ سُند ونان۔","1. تہٕ یہِ سپُد بٔہمہِ ؤریس مَنٛز، بٔہمہِ رٮ۪تہٕ کِس گۄڈنِکِس دۅہس منز، {یُس} خداوند سُند کلام آو میہ نِش،\n2. اِنسان سٕندِس نیٚچُو، تُل مصرٕکِس بادشاہ فرعونس سٕندِ خٲطرٕ ماتم تہٕ ونُن زِ تہٕ تُہۍ چھُکھ قومن ہٕندِس جوان شیرٕکۍ پٲٹھۍ، تہٕ ژے ووت پنٕنِس دریاوَس سٍتـ̡ تہٕ تِمن ہٕندِس دریاوَن سٍتـ̡ گٔژھِتھ تہٕ تِمن ہٕندِس دریاوَن سٍتـ̡ گٔژھِتھ تہٕ تِمن ہٕندِس دریاوَن سٍتـ̡ گِندٕنـ̡ ۔ {وہیل: یا، ڈریگن}\n3. یِتھٕ پٲٹھـ̡ چُھ خداوند خدا فرماوان۔ تَمہِ کِنۍ پھٔہلِتھ بہٕ ژےٚ پَنُن جال واریاہن لوٗکن ہٕنزِ صحبتہٕ سٍتۍ۔ تہٕ تِم أنِن ژےٚ میانہِ جالس منٛز۔\n4. تیلہِ تراوٕ بہٕ ژے زمینس پیٹھ، بہٕ تراوٕ ژے کھُلہٕ مٲدانس پیٹھ، تہٕ بہٕ کرٕ ژے سٍتـ̡ سارِنٕے زمینہٕ کِس درندٕ سٍتـ̡ بٔرِتھ۔\n5. تہٕ بہٕ تراوٕ چانۍ ماز پہاڑن پیٹھ، تہٕ وادی بٔرِتھ چانہِ تھزرٕ سٍتـ̡ بٔرِتھ۔\n6. بہٕ تہِ کرٕ چانہِ خونہٕ سٍتـ̡ سُہ زمینہٕ آبپاشی یتھ مَنٛز ژے تیران چُھ، {حتیٰ کہ} پہاڑن تام۔ تہٕ دریاو گژھن ژے سٍتۍ بٔرِتھ۔ {سُہ زمین یتھ منز...: یا، تیری تیرنٕچ سرزمین}\n7. تہٕ ییلہ بہٕ ژے نیبر کٔرِتھ، بہٕ کرٕ اسمانس ؤلِتھ تہٕ اَمہ کِس تارکس سیاہ بناوُن۔ بہٕ کٔرٕ آفتابس اوٚبرٕ سٍتۍ، تہٕ زوٗن دِیہ نہٕ تس گاش۔ {پٔٹِو...: یا، ژے ژھیپھ کٔرِو}\n8. اسمانٕچ سارِنٕے چمکدار گاش کرٕ بہٕ ژے سٍتـ̡ تاریک تہٕ تێنزِ زمینہِ پى۪ٹھ، خداوند خدا چُھ فرماوان۔ {روشن...: ہیب۔ آسمانس منز روشنی ہند گاش} {تاریک: ہیب۔ تِم سیاہ گٔیہِ}\n9. بہٕ کَرٕ واریہن لوٗکن ہٕندِس دِل تہِ پریشان، ییلہ بہٕ تُہند تباہی قومن مَنٛز، تِمن ملکن مَنٛز اَننہٕ یِمن نہٕ ژے زانان آسہِ۔ {ویکس: ہیب۔ شرارتس یا غمس اکساو}\n10.\\tآ، بہٕ کرٕ واریاہ لُکھ ژے وُچھِتھ حٲران تہٕ تِہٕندِ بادشاہ گژھن تۅہہِ خٲطرٕ سٮ۪ٹھاہ خوفزد، یێلہِ بہٕ تِمن برونہہ کنہِ تلوار لہراو۔ تہٕ تِم گژھن پرٮ۪تھ کُنہِ ساعتہ تھرتھر تھرِتھ، پرٮ۪تھ کانہہ انسان پننہِ زُو خٲطرٕ، تۅہہِ ہٕندِس زوال کِس دۅہس منز۔\n11. یِتھٕ پٲٹھۍ چُھ خداوند خدا وَنان۔ بابل کِس بادشاہ سٕنز تلوار ییہِ توے پیٹھ۔\n12. طاقتور سٕنزِ تلوارو سٍتـ̡ بہٕ کرٕ چانہِ ہٕندِس بٔڈِس سٍتـ̡ یِمن سارِنٕے قومن ہٕندِس خوفناک سٍتـ̡ تہٕ تِم کٔرِن مصرٕچ شان و شوکت برباد تہٕ تِمن ہٕندِس سارِنٕے بٔڈِس سٍتـ̡ تباہ کرنہٕ۔\n13. بہٕ کٔرٕ امہِ سٕندِس سارِنٕے درندٕ سٍتـ̡ بٔڈِس آبس سٍتـ̡ تباہ ۔ نہ گژھہِ انسان سٕندِ کھۅر تِمن مزید تنگ کٔرِتھ تہٕ نہ درندن ہٕندِ کھورِ تِمن تنگ کٔرِتھ۔\n14. تیلہِ کٔرٕ بہٕ تِہُند آب سرٛوٚن تہٕ تِہُند دٔریاو تیٖلٕکۍ پٲٹھۍ، خداوند چُھ فرماوان۔\n15.\\tییلہ بہٕ مصرٕچ سرزمین ویران کرِ، تہٕ مُلُک گژھہِ تتھ سٍتـ̡ بێزار یُس بٔرِتھ اوس، یێلہِ بہٕ سارِنٕے سٍتـ̡ یێلہِ یێلہِ بہٕ سارِنٕے سٍتـ̡ یێلہِ یێلہِ بہٕ یێلہِ یێلہِ بہٕ سارِنٕے سٍتـ̡ یێلہِ یێلہِ بہٕ یێلہِ سٍتـ̡ بٔرِتھ روزان چُھس، تێلہِ گژھہِ تِمن معلوم زِ بہٕ چُھس خداوند چُھس۔ {بے چارہ...: ہیب۔ امہ کس مکمل آسنس نش ویران گژھُن}\n16.\\tیہِ چُھ سُہ ماتم ییمہِ سٍتـ̡ تِم أمِس ماتم کرن: قومن ہٕنزِ کورِ کرِ أمِس ماتم کرنہٕ، تِم کرِ أمِس خٲطرٕ ماتم کرنہٕ، مصر تہٕ تٔمِس سارِنٕے بٔڈِس خٲطرٕ، خداوند خدا چُھ فرماوان۔\n17.\\tیہِ سپُد بٔہمہِ ؤریس مَنٛز، ریتہٕ کِس پنٛدٲہمہِ دۅہہٕ مَنٛز، {یُس} خداوند سُند کلام آو میہ نِش،\n18.\\tاِنسان سٕندِس بٔڈِس سٍتـ̡ وُپھ کٔرِتھ تہٕ تِمن سٍتـ̡ دِیُن تہٕ مشہور قومن ہٕنزِ کورِ تہٕ یِمن سٍتـ̡ دِنہٕ آمُت چُھہ یِمن سٍتـ̡ دٔرِتھ دِنہٕ آمُت۔\n19.\\tخوبصورتی منز کُس کُس چھُکھ گذران؟ بۄن گژھِو، تہٕ ژٕ گژھ بے ختنہٕ والٮ۪ن سٍتـ̡ دِنہٕ۔\n20.\\tتِم گژھن تلوار سٍتـ̡ مارنہٕ آمٕتـ̡ سٍتـ̡ دِنہٕ آم {سۅ...: یا، تلوار چھیہ تراونہ آمژ}\n21.\\tطاقتورن منز طاقتور گژھن جہنم منزہ نیبر تمن سٍتـ̡ کتھ کرنہٕ یُس أمس مدد کران چُھ: تِم گٔیہِ بٔنِتھ تہٕ تلوار سٍتـ̡ مارنہٕ آمٕتۍ۔\n22.\\tاَشُر چھُ تَتہِ تہٕ تٔمِس سارِنٕے سٍتـ̡ تٔمِس سٍتـ̡ قبرٕ گٔیہِ: تِم سارِنٕے گٔیہِ تلوار سٍتـ̡ مارنہٕ:\n23.\\tیمۍ سٕنزِ قبرِ ہٕندِس اندۍ پکھۍ چھِ، تہٕ تٔمۍ سٕنزِ قبرِ اندۍ پٔکھۍ چھِ، تِم سٲری گٔیہِ تلوار سٍتۍ مارنہٕ، ییمہ سٍتۍ زندٕ سٕندِس سرزمینس منز دہشت پٲدٕ گٔیہِ۔ {دہشت : یا، مایوس}\n24.\\tاتہِ چھہ ایلام تہٕ تٔمۍ سٕنزِ قبرِ اندۍ سٲری لٔگۍمٕتۍ، یِم سٲری چھِ تلوار سٍتۍ مارنہٕ آمٕتۍ، یِم زٔمیٖنہٕ کِس زیرِ حصس مَنٛز ختنہ کٔرِتھ گٔیہِ، ییمہ سٍتۍ تِمن ہٕندِس سرزمینس منز دہشت گٔیہِ۔ توتہِ چُھ تِمو پنٕنۍ شرم تِمن سٍتۍ ژٔلِتھ یِم کھۅنہٕ کھۅنہٕ وسان چھِ۔\n25.\\tتِمو چھُ أمِس سارِنٕے بٔڈِس سٍتـ̡ مقتولن ہٕندِس درمِس مَنٛز اکھ بسترٕ بٔنِتھ: تٔمۍ سٕنزِ قبرٕ چھِ أمِس اندۍ پٔکھۍ: یِم سارِنٕے چھِ ختنہٕ کٔرِتھ، تلوار سٍتـ̡ مارنہٕ آمٕتۍ: یێلہِ تِہُند خوف اوس زندٕ سٕندِس ملکس مَنٛز پٲدٕ سپدان، توتہِ چُھ تِمو تِمن سٍتـ̡ شرم تُلِتھ یِم کھۄدٕ گٔژھان چھِ:  سُہ چُھ مارنہٕ آمتس منز تھاونہٕ آمُت۔\n26.\\tاَتھ مَنٛز چھُ مِشِخ، طُبَل تہٕ تٔمِس سارِنٕے قبرَن ہٕندِس اندۍ پٔکھۍ: یِم سارِنٕے چھِ ختنہٕ کٔرِتھ، تلوار سٍتـ̡ مارنہٕ آمٕتۍ، حالانکہِ یِمو کٔر زندٕ سٕندِس سرزمینس مَنٛز دہشت پٲدٕ۔\n27. تہٕ تِم گژھن نہٕ تِمن طاقتورن سٍتـ̡ روزُن، یِم جنگی ہتھیار ہیتھ جہنمس مَنٛز گٔژھمٕتۍ، تہٕ تِمو چھِ پنٕنۍ تلوار کلَس تَل تھومٕژ، مگر تِہٕندِ بدکار آسہِ تِمن ہٕندِس اڈجن پیٹھ، حالانکہِ تِم آسہِ زندٕ سٕندِس ملکس مَنٛز طاقتورن ہُند وحشت۔ {تہندِس سٍتۍ...: ہیب۔ پننہٕ جنگک ہتھیارو سۭتۍ}\n28.\\tآ، تہٕ یِم تلوار سٍتـ̡ مارنہٕ آمٕتـ̡ تہٕ یِمن سٍتـ̡ مارنہٕ آمٕتـ̡ تِمن سٍتـ̡ گژھہِ ژٔٹِتھ روزُن۔\n29. اَتہِ چُھہ اَدوم، تٔمہِ سٕندِس بادشاہ تہٕ تٔمۍ سٕندِس سارِنٕے شہزادہٕ، یِم تلوار سٍتـ̡ مارنہٕ آمٕتۍ چھِ، تِم گژھن ختنہٕ نہٕ والٮ۪ن سٍتـ̡ تہٕ یِمن سٍتـ̡ گٔژھِتھ گٔژھِ۔ {لیڈ: ہیب۔ دِنہٕ آمُت، یا، پُٹ}\n30.\\tشُمالٕکۍ شہزادٕ تہٕ سارِنٕے زِدونِی، یِم مارنہٕ آمٕتۍ گٔیہِ۔ پننہِ دہشت سٍتۍ چھِ تِم پننہِ طاقتس پیٹھ شرمندہ گژھان۔ تہٕ تِم چھِ تلوار سٍتۍ مارنہٕ آمٕتۍ تہٕ تِمن سٍتۍ چھِ پنٕنۍ شرم برداشت کٔرِتھ یِم کھۅنہٕ وُن چھِ۔\n31. فرعون گژھہِ تِم وُچھِتھ تہٕ یِیہِ پننِس سارِنٕے لشکرس سٍتـ̡ تسلی دِنہٕ، یێلہِ تہِ یێلہِ سٍتـ̡ فرعون تہٕ تٔمۍ سُند سارِوٕے لشکر تلوار سٍتـ̡ مارنہٕ آمُت، خداوند خدا چُھ فرماوان۔\n32. یێلہِ چُھہ میہ زندٕ سٕندِس ملکس مَنٛز پنُن خوف پٲدٕ کورمُت: تہٕ سُہ یِہ تلوار سٍتـ̡ مارنہٕ آمٕتـ̡ {تِمن سٍتـ̡ یِم ختنہ کرنہٕ آمٕتـ̡ {تِمن سٍتـ̡ یِم تلوار سٍتـ̡ مارنہٕ آمٕتۍ، {حتیٰ کہ} فرعون تہٕ تٔمۍ سٕندِس سارِنٕے بٔڈِس سٍتـ̡ چُھہ خداوند خدایہ ونان ۔","1. بییہِ آو رب سُند کلام میہ نِش وونُن،\n2.\\tانسان سٕندِس بچس سٍتـ̡ کتھ کرٕن، تہٕ تِمن ونُن، ییلہ بہٕ کُنہِ زمینس پیٹھ تلوار انان، یێلہِ زمینہِ ہٕندِس لوکھ پننِس ساحلس پیٹھ اکھ نفر نِتھ تہٕ سُہ پنہٕ نِس چوکیدارس خٲطرٕ مقرر کرُن: {ییلہ...: ہیب۔ اکھ زمین ییلہ بہٕ تس پیٹھ تلوار انان}\n3. یێلہِ سُہ تلوار زمینس پیٹھ یِوان وُچھِ، سُہ چُھہ بُرِ وُنـ̡ تہٕ لُکن خبردار کٔرِتھ۔\n4. یُس تہِ بُنُک آواز بوزان چُھ، تہٕ یُس نہٕ خبردار کرِ۔ اگر تلوار ییہ تہٕ أمس نِنہٕ تہٕ تٔمۍ سُند خون آسہِ پننِس کلس پیٹھ۔ {کُنہِ تہِ...: ہیب۔ یُس بوزان چُھ}\n5.\\tتٔمۍ بوز بُزرٕچ آواز، تہٕ کٔرٕن نہٕ وارننگ۔ تٔمۍ سُند خون آسہِ تس پیٹھ۔ مگر یُس خبردار کرِ سُہ کرِ پنُن روح بچاو۔\n6.\\tمگر اگر چوکیدار تلوار وُچھِ، تہٕ وُپھ دِیہِ نہٕ بُرٕ، تہٕ لُکن گژھِ نہٕ خبردار کرنہٕ۔ اگر تلوار ییہِ تہٕ تِمو منزٕ کانہہ تہِ شخص نِنہٕ یِیہ، سُہ چُھ پننہِ بدکاری سٍتۍ نِنہٕ یِوان۔ مگر تٔمۍ سُند خون، میہ آسہ چوکیدار سٕندِس اتھس منز۔\n7. تہٕ اے انسان سٕندِس نیچو، مے چُھہ ژے اسرٲیلِس کِس گرس مَنٛز اکھ چوکیدار مقرر کورمُت۔ تێمہِ کِنۍ گژھ ژے میانہِ ٲسس پیٹھ یہ لفظ بوزناوُن، تہٕ تِمن کٔرٕن میانہِ نِش خبردار کرنہٕ۔\n8.\\tییلہ بہٕ بدکارس ونان چھُس، اے بدکار {انسان}، ژے گژھہِ یقینا مرُن۔ یێلہِ نہٕ تۅہہ بدکارن تٔمۍ سٕنزِ وتہِ نِش خبردار کرنہٕ خٲطرٕ کتھ کرِ، سُہ بدکار {انسان} گژھہِ پننہِ بدکاری سٍتـ̡ مرُن۔ مگر تٔمۍ سُند خون، میہ آسہٕ تۅہہِ ہٕندِس اتھس منز۔\n9.\\tتوتہِ اگر ژیہ بدکارس پننہِ وتہِ نشہِ خبردار کرِ۔ اگر نہٕ سُہ پننہِ وتہِ نِش پھیرِ، سُہ گژھہِ پننہِ بدکاری سٍتۍ مرُن۔ مگر ژے کٔر پنُن روح بچٲومُت۔\n10. تێمہِ کِنۍ، اے انسان سٕندِس نیچو، اسرٲیلِس کِس گرس سٍتـ̡ کتھ کرٕنـ̡ ۔ یێلہِ چُھہ تُہۍ کتھ کران زِ یێلہِ سانہِ گناہ تہٕ سانہِ گۅناہ اسہِ پیٹھ آسن، تہٕ أسۍ کِتھہ پٲٹھـ̡ روزِو؟\n11. خداوند خدا چُھ ونان زِ بہٕ چُھس زندٕ روزان، بہٕ چُھس نہٕ بدکار سٕندِس مرنس سٍتـ̡ کانہہ خوشی۔ مگر بدکار چھُ پننہِ وتہِ نِش پھیران تہٕ زندٕ روزُن: یُس بدکار پنہٕ نِس وتہِ نِش پھیُرِو، پنہٕ نِس بد وتہِ نِش پھیُرِو۔ اے اسرٲیلُک گرٕ کیازِ چُھہ ژے مرُن؟\n12. تێمہِ کِنۍ، اے انسان سٕندِس نیٚچو، پنہٕ نِس لُکہٕ کِس اولادس وَنُن زِ نیکوکارن ہٕنزِ پاکیزگی ہٕندِس دۅہہٕ سٍتـ̡ ہێکہِ نہٕ تٔمِس بد کاری ہٕندِس دۅہہٕ سٍتـ̡ نجات دِنہٕ۔ یێلہِ سُہ گناہ کٔرِتھ تہٕ یێلہِ سُہ گناہ کٔرِتھ تہٕ یێلہِ ہێکہِ نیکی ہٕندِس دۅہہٕ سٍتـ̡ زندٕ روزِتھ۔\n13. ییلہ بہٕ نیکوکارن ونان زِ سُہ گژھہِ یقینا زندٕ۔ اگر سُہ پننِس نیکی پیٹھ بھروسہٕ کرِ، تہٕ بدکاری کرِ، تٔمۍ سٕنزِ تمام نیکی گژھِ نہٕ یاد تھاونہٕ۔ مگر تٔمۍ سٕنزِ بدکٲری خٲطرٕ یُس تٔمۍ کٔرمُت چُھ، سُہ مرُن امہِ خٲطرٕ۔\n14. یێلہِ بہٕ یێلہِ بدکارن وَنُن چُھس یێلہِ تہٕ یێلہِ چُھہ یێلہِ مَرُن، اگر سُہ پنہٕ نِس گۅنہٕ نِش پتھ کُن، تہٕ سُہ کٔرِتھ یُس حلال تہٕ صحیح آسہِ۔ {یہ...: ہیب۔ فیصلہٕ تہٕ انصاف}\n15.\\tاگر بدکار عہد واپس کرِ، دُبارٕ دِیُن یُس أمِس لوُٹمُت اوس، زندگی ہٕندِس قونونس مُطٲبِق، بدکاری کرنہٕ ورٲے۔ سُہ روزِ یقینا زندٕ، سُہ گژھِ نہٕ مرُن۔\n16.\\tتٔمۍ سٕندِس گۅناہ سٍتـ̡ یُس تٔمِس سٍتـ̡ کرنہٕ آمُت چُھ، سُہ گژھہِ نہٕ تٔمِس سٍتـ̡ بیان کرنہٕ یُن: تٔمۍ کٔر حلال تہٕ صحیح۔ سُہ روزِ یقینا زندٕ۔\n17.\\tتوتہِ چُھہ تُہندِ لوکن ہٕندِ اولادٕ ونان زِ خداوند سُند وتھ چُھنہٕ برابر، مگر تِمن ہٕندِ وتھ چُھنہٕ برابر۔\n18. یێلہِ نیکی پنہٕ نِس نیکی نِش پتھ پھیرِ، تہٕ بدکاری کرِ، سُہ گژھہِ اَمہ سٍتـ̡ مرُن۔\n19. مگر اگر بدکار پننہِ بدکاری نشہِ پتھ پھیرِ، تہٕ یُس حلال تہٕ صحیح آسہِ، سُہ گژھہِ اَمہ سٍتـ̡ زندٕ۔\n20.\\tتوتہِ چُھہ تُہۍ ونان زِ خداوند سُند وتھ چُھنہٕ برابر۔ اے اسرٲیلٕکۍ گرٕ، بہٕ کَرٕ ژےٚ پرٮ۪تھ أکِس تٔمۍ سٕندِ وتہِ پٲٹھۍ۔\n21.\\tتہٕ یہ سپُد سانہِ قید کِس بٔہمہِ ؤریس منز، دٔہمہِ ریتس منز، ریتہٕ کِس پٲنژمِس دۅہس منز، یُس یروشلم منزہ ژلمت اوس، سُہ آو میہ نِش یُس یُس یروشلم منزہ ژلمت اوس، وونُن زِ شہر چُھ مارنہٕ آمُت۔\n22. وُنہِ اوس شامَس خداوند سُند اَتھٕ میٲنِس پیٹھ، یُس ژلنہٕ آمُت اوس سُہ یُس ژلنہٕ آو۔ تہٕ اوسُس میون بوش کھولمُت، یوٚت تام سُہ صبحٲے مےٚ نِش آو۔ تہٕ میون بوش اوس کھولمُت، تہٕ بہٕ اوسس نہٕ مزید گونگ۔\n23. پتہٕ آو خداوند سُند کلام میہ نِش، یُس وَنُن چُھ،\n24.\\tاِنسان سٕندِس بُتھِس سٍتـ̡ یێلہِ یێلہِ سٍتـ̡ یێلہِ ہُند وَنُن چُھہ زِ ابراہیم اوس اَکھ تہٕ سُہ اوس زمینہِ ہُند وٲرث۔ زمین چھیہ اسہِ وراثتس منز دِنہٕ آمژ۔\n25. تێلہِ چُھہ تِمن وَنُن، یِتھٕ پٲٹھـ̡ چُھ خداوند خدایہ فرماوان۔ تُہۍ چھِو خونس سٍتـ̡ کھٮ۪وان، تہٕ پَنٕنـ̡ بُتن کُن أچھ تُلِتھ، تہٕ خوُن تراوُن: تہٕ کیا تُہہِ کٔرِو زمینس سٍتـ̡ قبضہٕ؟\n26.\\tتُہۍ چھِو پننہِ تلوارِ پیٹھ کھڑا روزان، تہٕ تُہۍ چھِو پرٮ۪تھ أکِس ہمساین سٕنزِ زنانہِ ناپاک کٔرِتھ، تہٕ کیا تُہۍ چھِو زمینہٕ حٲصِل کٔرِتھ؟\n27.\\tیِتھٕ پٲٹھـ̡ چُھہ تِمن سٍتـ̡ وَنُن، یێلہِ چُھہ خداوند خدا فرماوان۔ {As} بہٕ چُھس زندٕ، یُس {چُھ} یُس کھٲلِس منز چُھ، سُہ یُس کھُلہٕ مٲدانس منز چُھس بہٕ دِنہٕ یِن درندن کھٮ۪نہٕ خٲطرٕ، تہٕ یِم قعلن تہٕ غارن منز آسن تِم گژھن وباہٕ سٍتۍ مرن۔ {to be...: Heb. تس کھٮ۪نہٕ خٲطرٕ}\n28.\\tکیازِ بہٕ کرٕ زمینہٕ ویران تہٕ تٔمۍ سٕندِس طاقتُک شوکت گژھہِ ختم۔ تہٕ اسرٲیلٕکۍ پہاڑ گژھن ویران گژھن، یُتھ نہٕ کانہہ تہِ نیرِ۔ {زیادٕ...: ہیب۔ ویران تہٕ ویرانی}\n29.\\tتێلہِ گژھہِ تِمن پتاہ زِ بہٕ چُھس خداوند چُھس، یێلہِ بہٕ چُھس تِہندِ سارِنٕے بد عملہٕ کِنہِ زمینہٕ ویران کٔرمٕژ یِم تِمو کٔرمٕژ چھِ۔\n30. تہٕ اے انسان سٕندِ نیٚچُو، تہٕ چُھہ تُہٕندِس لُکن ہٕندِس بچہٕ وُنہِ تہِ دیوارن تہٕ گرن ہٕندِس دروازس مَنٛز تہٕ اَکھ أکِس سٍتـ̡ کتھ کران تہٕ پرٮ۪تھ أکِس سٍتـ̡ کتھ کران چُھہ، پرٮ۪تھ أکِس سٍتـ̡ چُھہ پننِس بٲیِس سٍتـ̡ کتھ کران، یێلہِ چُھہ تێلہِ دُعا کران تہٕ بوزُن یُس کلام خداوند سٕندِ طرفہٕ نیران چُھ۔ {ژے خلاف: of، of thee}\n31. تہٕ تِم چھِ تۅہہِ نِش یِوان یِتھٕ پٲٹھۍ، تہٕ تِم چِھ تُہٕندِس کَتھٕ بوزان تہٕ تِم چِھ نہٕ تِمن ہٕندِس لالچس سٍتـ̡ سٍتـ̡ دِل دِوان۔ {یتھ کٔنۍ...: ہیب۔ لُکن ہٕندِس یِنہٕ مُطٲبِق} {تِم چِھ بِہِتھ...: یا، میانہِ لُکھ چُھہ توے برونہہ کُن بِہِتھ} {تِم چھِ ہاوان...: ہیب۔ تِم چھِ محبت کران، یا مذاق}\n32.\\tتہِ چھکھ تِمن ہٕندِس سٍتـ̡ سٍتـ� محبتن ہُند اکھ بٲتھ\n33.\\tتہٕ ییلہ یہ سپدِ، تہٕ یێلہِ سپدِ، تێلہِ گژھہِ تِمن مَنٛز اکھ پیغمبر تہِ موجود۔","1. تہٕ خداوند سُند کلام آو میہ نِش،\n2. اِنسان سٕندِس فرزندس سٍتـ̡ کٔرِو اسرٲیلـ̡ چُھہ پۯاوٕنـ̡ نِش پیشن گویی کٔرِتھ، تہٕ تِمن وَنُن چُھہ یِتھٕ پٲٹھـ̡ خداوند چُھہ چُھہ پۯاوٕنـ̡ پى۪ٹھہٕ پى ہا ہا اسرٲیلِین ہٕندِس پٔرِس پٲٹھـ̡ یُس پانس کھٮ۪وان چُھہ! کیا پَزِ نہٕ پَلہٕ رٔچھن کھیٚنہٕ دِنہٕ یِنۍ؟\n3. تم چِھ چربی کھیوان، تہٕ تم چِھ ییرٕ لاگان تہٕ تم چِھ کھیوان یم کھیوان چِھ، {مگر} تم چِھ نہٕ کھیٚوان کھیوان۔\n4. بیمارن چُھہ نہٕ مضبوط، نہ چُھہ بیمار سُہ شفا دِژمُت، تہٕ نہ چُھہ ژے پھُٹمُت سُہ دُبارٕ أنِمُت، نۂ چُھہ یُس رٲوِمُت چُھ، تہٕ چُھہ یُس رٲوِمُت چُھ، تہٕ چُھہ یُس رٲوِمُت چُھہ تُہٕندِس سٍتـ̡ ژھانڈمُت۔ مگر تۅہہ کٔر زبردستی تہٕ ظلمہٕ سٍتۍ تمن پیٹھ حکمرٲنی کرنہٕ۔\n5.\\tتہٕ تِم گٔیہِ پھٔٹِتھ، تکیازِ {چُھنہ} چُھہ نہٕ کانہہ چرواہ تہٕ تِم بنییہِ کھہہٕ کین سارنٕے درندَن ہُند ماز، ییلہ تِم منتشر گٔیہِ۔ {کیازِ...: یا، چرواہ ورٲے}\n6.\\tمیانہِ کۅکرِ ٲس سارنٕے بالن تہٕ پرٮ۪تھ تھدِ بالس پیٹھ پھیران: آ، میون ریوڑ اوس سارِنٕے زمینہِ پیٹھ پھٔہلِتھ تہٕ کٲنسہ تہِ ژھانڈنہٕ تہٕ ژھانڈنہٕ آمُت۔\n7. تێمہِ کِنۍ، اے چرواہ، بوٗزِو خداوند سُند کلام۔\n8. خداوند خدا چُھ ونان زِ بہٕ چُھس زندٕ روزان، یێلہِ میون ریچھ بنیوو شِکار، تہٕ میون ریوڑ بنیوو کھہہٕ کِس پرٮ۪تھ درندَس خٲطرٕ ماز، کیازِکہِ {اتہِ} اوس نہٕ کانہہ چرواہ تہٕ نہ میٲنۍ پٔرِتھ ژھانڈنہٕ آمُت، مگر میٲنۍ پٔرِو کھیٚوان تہٕ میٲنۍ پٔرِس کھٮ۪وان نہٕ۔ {کیازِ...: یا، چرواہ ورٲے}\n9. تێمہِ کِنۍ، اے چرواہ، بوزو خداوند سُند کلام۔\n10.\\tخداوند خدا چُھ یِتھٕ پٲٹھۍ فرماوان۔ وُچھِو، بہٕ چُھس چرواہَن خلاف تہٕ بہٕ کرٕ پنُن ریوڑ تِمن ہٕندِس اتھس منز، تہٕ کرٕ تِمن کھیٚنہٕ نِش بند۔ نہ چرواہ گژھن وۅنۍ پانس کھٮ۪نہٕ۔ تِکیازِ بہٕ کَرٕ پنُن پَنُن کھۄلہٕ تِہٕندِ مَژٕ نِش، یُتھ نہٕ تِمن ہُند ماز بٔنِتھ۔\n11. یِتھٕ پٲٹھۍ چُھ خداوند خدا وَنان۔ وچھ بہ، {حتیٰ کہ} بہ، دۅشوے پننین دانٛدن ژھانڈان تہٕ تمن ژھانڈان۔\n12.\\tیِتھٕ پٲٹھۍ چُھہ پَنٕنـ̡ پۯاونہٕ آمُتـ̡ یێلہِ چُھہ پَنٕنـ̡ پى۪ٹھـ� یِتھے پٲٹھۍ کٔرٕ بہٕ پنٕنۍ دانٛد ژھانڈان، تہٕ تِم کٔرٕ تِمن سارِنٕے جاین نِش نِش ییتہِ تِم اوٚبرٕ تہٕ تاریک دۄہس منٛز بکھرِتھ آسہِ۔ {as...: Heb. تلاشہٕ مطٲبق}\n13. تہٕ بہٕ کٔرٕ تِم لُکہٕ نِش نِش تہٕ تِمن ملکَو نِش جمع کٔرِتھ تہٕ تِمن ہٕندِس سرزمینس مَنٛز اَننہٕ تہٕ دِیہٕ تِمن سٍتـ̡ دریاوَن نِش تہٕ مُلکہٕ کِس سارِنٕے آباد مقامن پى۪ٹھ۔\n14. بہٕ چُھس تِمن اَصٕل مرگہٕ مَنٛز کھٮ۪وان تہٕ اِسرٲیلِس کِس تھدٮ۪ن پہاڑن پیٛٹھ روزن تِمن ہٕندِس گٔنڈِس مَنٛز تہٕ تِم گژھن اِسرٲیلِس کِس پہاڑن پى۪ٹھ۔\n15. بہٕ کَرٕ پَنٕنـ̡ کھیٚراونہٕ، تہٕ بہٕ کَرٕ تِمن بٔرِتھ بٔنِتھ، خداوند چُھ فرماوان۔\n16.\\tبہٕ کرٕ سُہ ژھانڈان یُس راوُن اوس، تہٕ یُس پھُٹمُت اوس، تہٕ یُس بیمار اوس، سُہ کرٕ مضبوط، مگر بہٕ کرٕ چربی تہٕ مضبوط۔ بہٕ کٔرٕ تمن فیصلہٕ سٍتـ̡ کھیوان۔\n17. تہٕ یێلہِ چُھہ تۅہہِ میانہِ ریوُن، یِتھٕ پٲٹھـ̡ خداوند خدا چُھ وَنان۔ وچھ، بہٕ چُھس چارواین تہٕ چارواین درمِیان فٲصلہٕ کَران۔ {مویشی: ہیب۔ کۅکرِ تہٕ بچن ہٕندۍ لۄکٕٹ چارو} {سُہ ژھاوُل: ہیب۔ گریٹ سُہ گوٹس}\n18.\\t{باسان چھُو} چُھہ تۅہہِ خٲطرٕ اکھ لۄکُٹ چیز یُس اصل مرگہٕ کھیوٚمُت، مگر ژیہ پزِ پننین کھۅرن سٍتـ̡ پنہٕ نِس مرگہٕ ہٕندِس باقیاتس سٍتـ̡ پَنٕنـ̡ چُھہ پَنٕنـ̡ پَنٕنـ̡ چُھ تہٕ سرٛنِس آبس چیٚنہٕ خٲطرٕ، مگر ژیہ پزِ پننیو کھورو سٍتۍ باقیات گند کرُن؟\n19.\\tتہٕ میانہِ کھورِ سٍتـ̡ چُھہ سُہ کھیوان یُس ژے پنہٕ نِس کھورِ سٍتـ̡ دِژمُت چُھ۔ تہٕ تِم چِھ سُہ چیوان یُس ژے پننیو کھورو سٍتۍ گڑبڑ چُھ کٔرمُت۔\n20. تێمہِ کِنۍ چُھ خداوند خدایہ تِمن وَنان۔ وچھ بہ، {حتیٰ کہ} بہ، موٹۍ چارواین تہٕ دبلی چارواین درمیان فیصلہ کٔرتھ۔\n21.\\tکیازِ ژے چھُکھ اندۍ پکھۍ تہٕ پھیپھ دِتھ سارِنٕے بیمارِ پنہٕ نِس سینٛگو سٍتـ̡ دِژمٕتۍ، یوتام تِم ژٔٹِتھ پھٔٹِتھ چھِو۔\n22. تَمہِ کِنۍ بہٕ بچٲوِتھ پنُن پَنُن کھورِ تہٕ تِم گژھن نہٕ وۄنۍ شِکار۔ تہٕ بہٕ کٔرٕ چارواین تہٕ چارواین درمیان فٲصلہٕ۔\n23. تہٕ بہٕ تھاوٕ تِمن پیٹھ اکھ چرواہ تہٕ سُہ دِیہِ تِمن کھٮ۪وان، حتیٰ کہ میون خادم ڈیوڈ۔ سُہ دِیہِ تِمن کھٮ۪وان، تہٕ سُہ بنہِ تِہُند چرواہ۔\n24. تہٕ بہٕ خداوند تِہُند خدا بنہٕ تہٕ میون خادم داؤد یِمن مَنٛز شہزادٕ آسہِ۔ میہ چُھہ خداوند کتھ کٔرمٕژ۔\n25. تہٕ بہٕ کَرٕ تِمن سٍتـ̡ امنُک عہد تہٕ بد کار درندٕ کٔرِن زمینہٕ منزٕ نِش نِش تہٕ تِم روزن بیابانن مَنٛز تہٕ جنگلن مَنٛز شۄنگنہٕ۔\n26. تہٕ بہٕ بناوٕ تِمن تہٕ پننِس بالس اندۍ پٔکھۍ جایَن اکھ نعمت۔ تہٕ بہٕ کرٕ أمۍ سٕندِس موسمس منز شاور وسان۔ اتہِ گژھہِ برکتُک بار۔\n27.\\tتہٕ کھہُک کُلِس دِیہِ پنُن پھل تہٕ زمینہٕ دِیہِ پنُن پھل تہٕ تِم روزن پننہِ زمینہِ مَنٛز محفوٗظ، تہٕ گژھہِ یہ زانُن زِ بہٕ چُھس خداوند چُھس، یێلہِ بہٕ تِہٕندِس جوُرٕچ بند پھُٹرٲوِتھ تہٕ تِمن ہٕندِس اتھہٕ نِش نِش نجات دِوان یِم تِمن ہٕنزِ خدمت کران چھِ۔\n28. تہٕ تِم گژھن نہٕ وۄنۍ کافرن ہُند شکار، تہٕ نہ گژھن زمینُک درندٕ یِمن کھٮ۪ن۔ مگر تِم روزن محفوٗظ پٲٹھۍ، تہٕ کانٛہہ تہِ گژھِ نہٕ تِمن خوفزدہ کرنہٕ۔\n29. تہٕ بہٕ تِہندِ خٲطرٕ اکھ مشہور کُل تُلِتھ تہٕ تِم گژھن نہٕ زمینس مَنٛز فاقہٕ سٍتـ̡ کھسنہٕ، تہٕ نہ گژھن وۅنۍ کافرن ہٕنز شرمندگی برداشت کرنہٕ۔ {شہرت کِنۍ: یا، شہرت خٲطرٕ} {کھٮ۪نہٕ آمُت: ہیب۔ نِنہٕ آمُت}\n30. یِتھٕ پٲٹھـ̡ گژھن تِمن پتاہ زِ بہٕ چُھس خداوند تِہُند خدا {چُھ} تِمن سٍتـ̡ تہٕ {یہ} تِمن سٍتـ̡ چُھہ یێمہِ سٍتـ̡ أسرٲیلـ̡ سٍتـ̡ میٲنۍ قوم چُھہ، خداوند خدا چُھ ونان ۔\n31. تہٕ اے میٲنۍ ریوٕ، میانہِ مرگہٕ ہُند ریو، {تہٕ} بہٕ چُھس تُہند خدا، خداوند چُھ وَنان۔","1. اَمہِ علاوٕ آو خداوند سُند کلام میانہِ نِش وَنُن،\n2. انسان سٕندِ فرزند، پَنُن بُتھ کٔرِو سیٖر کِس کُنہِ ک\n3.\\tتہٕ ونُن زِ خداوند خدا چُھ یِتھٕ پٲٹھۍ فرماوان۔ وچھ اے پہاڑ سیر، بہٕ چُھس ژے خلاف تہٕ بہٕ پھٔہلٲوٕ ژے خلاف پنُن اتھہٕ، تہٕ بہٕ کرٕ ژے ویران۔ {زیادٕ...: ہیب۔ ویران تہٕ ویرانی}\n4. بہٕ کرٕ تُہند شہر برباد تہٕ ژٕ گژھہٕ ویران تہٕ ژے گژھہٕ معلوم زِ بہٕ چُھس خداوند چُھس۔\n5.\\tکیازِ تۅہہِ ٲس دٲیمی نفرت، تہٕ تِمن ہٕندِس مصیبت وِزِ تلوار ہٕندِ زور سٍتـ̡ چُھہ تِمن ہٕندِس ظلمس سٍتـ̡ {تِہٕندِس ظلمس سٍتـ̡ خاتمہٕ سپدُن: {دٲیمی...: یا، پرانہِ نفرت} {شیڈ...: حب۔ بچہٕ کٔرِتھ کٔرِتھ} {فورس: ہیب۔ اتھہٕ}\n6. تێمہِ کِنۍ، یێلہِ بہٕ چُھس زندٕ روزان، خداوند خدا چُھہ ونان زِ بہٕ کرٕ ژے خونس خٲطرٕ تیار، تہٕ خون تہِ کرِ ژے پتہٕ۔\n7. یِتھٕ پٲٹھۍ بناوٕ بہٕ سیٖر پہاڑ ویران تہٕ یُس نیران چُھ تہٕ یُس واپس یِوان چُھس اَتھ نِش ژٹِتھ ۔ {زیادٕ...: ہیب۔ ویران تہٕ ویرانی}\n8. تہٕ بہٕ بٔرِتھ تٔمۍ سٕندِس پہاڑس سٍتـ̡ تٔمۍ سٕندِس مارنہٕ آمٕتـ̡ {انسان} سٍتـ̡ بٔرِتھ تہٕ تُہٕندِس سارِنٕے دریاوَن مَنٛز، یِم تلوار سٍتـ̡ مارنہٕ آمٕتۍ چھِ۔\n9. بہٕ بناوٕ ژے ہمیشہٕ ویران تہٕ چانہِ شہر گژھن نہٕ واپس، تہٕ ژے گژھہِ معلوم زِ بہٕ چُھس خداوند ۔\n10.\\tکیازِ ژے چُھہ ووٚنمُت، یِم دۅشوے مُلُک تہٕ یِم دۅشوے مُلُک آسن میٲنۍ تہٕ أسۍ آسن یہِ حٲصِل کٔرِتھ۔ ییلہ زن خداوند اوس تتہِ: {یێلہِ...: یا، یودوَے خداوند اوس تتہِ}\n11. تێمہِ کِنۍ، یێلہِ بہٕ زِندٕ چُھس، خداوند خدا چُھہ ونان زِ بہٕ کٔرٕ چانہِ غصہٕ مُطٲبق تہٕ چانہِ حسد مُطٲبق یُس ژے تِمن خلاف پننہِ نفرتُک استعمال کورمُت چُھ۔ تہٕ بہٕ کٔرٕ تِمن مَنٛز پنُن پان زاننہٕ، ییٚلہِ بہٕ تُہند فیصلہ کرِ۔\n12. تہٕ ژے گژھہِ پتاہ زِ بہٕ چُھس خداوند چُھس، {تہٕ یہ} چُھس تُہند سٲری کفر بوزمُت یُس ژے اسرٲیلِس پہاڑن خلاف کتھ کرمژ چُھ، یہِ ونُن چُھ، تِم چِھہ ویران کرنہٕ آمٕتۍ، تِم چِھ اسہِ کھٮ۪نہٕ خٲطرٕ دِنہٕ آمٕتۍ۔ {استعمال کرنہٕ خٲطرٕ: ہیب۔ کھٮ۪نہٕ خٲطرٕ}\n13. یِتھٕ پٲٹھۍ چُھہ ژے پننہِ زبانہٕ سٍتـ̡ میانہِ خلاف فخر کٔرِتھ، تہٕ کٔرٕکھ میانہِ خلاف پنٕنۍ کتھ بڑٲومٕژ: مے چُھس بوزمُت۔ {فخر کٔرتھ: ہیب۔ میگنیفایِڈ}\n14.\\tخداوند خدا چُھ یِتھٕ پٲٹھۍ فرماوان۔ ییلہ سورے زمین خۅش گژھہِ، بہٕ کرٕ ژے ویران۔\n15. یِتھٕ پٲٹھـ̡ ژے اسرٲیلِکِس گرس ہٕندِس وَرستس پیٹھ خۅش گٔیہ، کیازِ یہِ اوس ویران گومُت، تِتھے کٔرِتھ کٔرٕ بہٕ ژے تہِ کٔرِتھ: اے کوہ سیر تہٕ سارِنٕے اِدومیاہس سٍتـ̡ تہٕ تِمن گژھہِ پتاہ زِ بہٕ چُھس خداوند ۔","1. اے انسان سٕندِس فرزندس سٍتـ̡ کٔرِو اسرٲیلـ̡ ہٕندِس پہاڑس سٍتـ̡ پیشن گویی تہٕ وَنُن، اے اِسرٲیلٕکۍ پہاڑ، بوزو خداوند سُند کلام:\n2. یِتھٕ پٲٹھۍ چُھ خداوند خدا فرماوان۔ تکیازِ دشمنن چُھ ژےٚ خلاف ووٚنمُت، آہا، قدیم تھدِ جایہِ تہِ چھِ سانہِ قبضس منز:\n3. تێمہِ کِنۍ کٔرِو پیشن گویی تہٕ ونُن، یِتھٕ پٲٹھۍ چُھ خداوند خدا فرماوان۔ تکیازِ تِمو چُھ {توہ} ویران کورمُت، تہٕ چُھکھ ژیہ پریتھ طرفہٕ نِنہٕ، یُتھ تہٕ تُہۍ ہێکہِ کُلِس ہٕندِس باقیاتس سٍتـ̡ بٔنِتھ، تہٕ تُہۍ چھِو کتھ کرن والٮ۪ن ہٕندِس چپَس مَنٛز رٔٹِتھ، تہٕ لُکن ہٕنز بدنامی چھِ: {کیازِ: حب۔ تکیازِ کیازِ} {are...: یا، تم چھہِ زبنہِ ہندس وٹھس پیٹھ وۅتھنہٕ آمت}\n4. تێمہِ کِنۍ، اے اسرٲیلٕکۍ پہاڑ، بوٗزِو خداوند خدا سُند کلام۔ یِتھٕ پٲٹھـ̡ چُھ خداوند خدایہ پہاڑن تہٕ بالن تہٕ دریاوَن تہٕ وادین مُتعلِق تہٕ یِمن شہرن ہُند شِکار تہٕ طنز بنیومُت یِم اندۍ پٔکھۍ چھِ۔ {دریاو: یا، بوٹم، یا، ڈیلز}\n5. تێمہِ کِنۍ چُھ خداوند خدا یِتھٕ پٲٹھۍ وَنان۔ یقینا چھُ میہ پننہِ حسد کِس نارس منز کافرن ہٕندِس باقیاتس خلاف کتھ کٔرمٕژ، تہٕ سارِنٕے اِڈومیاہس خٕلاف، یِمو میانہِ زمینہٕ سارِنٕے دِلٕچ خوشی سٍتۍ، حقارت آمیز ذہنو سٍتۍ، یہ شکارٕ خٲطرٕ کڈنہٕ خٲطرٕ کٔرِتھ کٔرِتھ۔\n6. اَمہِ مۄکھٕ کٔرِو اسرٲیلِچ سرزمینس مُتعلِق پیشن گویی تہٕ پہاڑن تہٕ بالن تہٕ دریاوَن تہٕ وادین مُتلق ونُن، یِتھٕ پٲٹھۍ چُھ خداوند خدا فرماوان۔ وچھ میہ کٔر پننِس حسدس تہٕ غصس منز کتھ کرنہٕ، کیازِ ژے چھے کافرن ہٕنز شرم برداشت کٔرمٕژ:\n7. تێمہِ کِنۍ چُھ خداوند خدا یِتھٕ پٲٹھۍ وَنان۔ میہ تُلمت پنُن اتھ، یُس کافر چُھہ تۅہہِ اندۍ پکھۍ یُس تۅہہِ اندۍ پکھۍ چھُ، تِم گژھن پنٕنۍ شرم برداشت کٔرِتھ۔\n8. مگر اے اسرٲیلٕکۍ پہاڑ، تم کٔرِو پَنٕنۍ لنجہِ ژٔٹِتھ تہٕ میانین اسرٲیلِکِس قومس پَنُن پھل دِیُن۔ تکیازِ تم چھہِ یِنہٕ وٲلۍ۔\n9. کیازِ، وُچھ، بہٕ چُھس تہٕ بہٕ چُھس ژے کُن پھیرُن، تہٕ ژے یِیہٕ کاشتہٕ تہٕ وونہٕ۔\n10. تہٕ بہٕ کٔرٕ توے سٲرۍسٕے اِسرٲیلِس سٍتـ̡ انسانس سٍتـ̡ بٔرِتھ تہٕ شہر یِن آباد کرنہٕ، تہٕ یِن بٔنِتھ بٔنِتھ ۔\n11.\\tتہٕ بہٕ کرٕ ژے انسان تہٕ درندٕ سٍتـ̡ ضرب تہٕ تِم گژھن ہُریر تہٕ پھل دِنہٕ: تہٕ بہٕ کَرٕ ژےٚ پرانہِ جایدادٕ پتہٕ بَساونہٕ، تہٕ بہٕ کَرٕ تۅہہِ ہٕندِس آغازس کھۅتہٕ بہٕ بہٕ تہٕ بہٕ کرٕ تۅہہِ سٍتـ̡ بہتر تہٕ ژے گژھہِ پتاہ زِ بہٕ چُھس خداوند ۔\n12. آ، بہٕ کرٕ انسان توے پیٹھ پکناوُن، حتیٰ کہ میانین لوکن اسرائیل۔ تہٕ تِم گژھن تُہٕندِس قبضس منز، تہٕ تُہٕندِس وٲرِثس منز روزِو نہٕ تِمن ہٕندِس وٲرثس سٍتـ̡ ۔\n13. خداوند خدا چُھ یِتھٕ پٲٹھۍ وَنان۔ تکیازِ تِم چِھ تۅہہِ ونان زِ ژے چُھکھ انسانس مُتعلِق تہٕ چُھکھ پَنٕنـ̡ قومن ہُند غم زِ\n14. تێمہِ کِنۍ گژھ نہٕ تۅہہ مزید انسانس کھٮ۪وان تہٕ نہ کرٕ پنٕنـ̡ قومن ہٕندِس غم سٍتـ̡ ۔ {غم: یا، گرُن وجہ}\n15. خداوند خدا چُھ ونان زِ بہٕ کٔرٕ نہٕ ژے مَنٛز کافرن ہٕنز شرم بوزنہٕ، تہٕ نہ کرٕ تہٕ ژٕ کرٕ مزید لوکن ہٕنز ملامت تہٕ نہ کرٕ تہٕ پنٕنـ̡ قومن ہٕندِس زوال سٍتـ̡ دِنہٕ۔\n16. امہِ علاوٕ آو خداوند سُند کلام میانہِ نِش وَنُن،\n17.\\tاِنسان سٕندِس نیٚچُو، یێلہِ اِسرٲیلُک گرٕ پنہٕ نِس زمینس مَنٛز روزان اوس، تِمو کٔر یہِ پننہِ طریقہٕ سٍتـ̡ تہٕ پننہِ عملہٕ سٍتـ̡ ناپاک کرنہٕ۔\n18.\\tاَمہِ مۄکھٕ ووت میہ تِمن پیٹھ پنُن غصہٕ یُس تِمو زمینس پیٹھ تروومُت اوس، تہٕ تِمن ہٕندٮ۪ن بُتن ہٕندِ خٲطرٕ یُس تِمو یہ آلودہ کورمُت اوس۔\n19.\\tتہٕ مے کٔر تِم کافرن مَنٛز پھٔٹِتھ تہٕ تِم گٔیہِ مُلکن مَنٛز منتشر کرنہٕ: تِہٕندِ وتہٕ مُطٲبِق تہٕ تِہٕندِ عملہٕ مُطٲبِق کٔر مے تِمن ہُند فیصلہٕ۔\n20. تہٕ ییلہ تِم کافرن مَنٛز دٲخل گٔیہِ، یێلہِ تِم گٔیہِ تِمو میانہِ مقدس ناوٕچ بے عزتی کٔرِتھ، یێلہِ تِمو تِمن ووٚن، یِم چھِ خداوند سٕندِ لُکھ تہٕ گٔیہِ تٔمۍ سٕنزِ زمینہٕ منزٕ نیبر۔\n21.\\tمگر میہ اوس پننِس مقدس ناوس پیٹھ رحم کھسان، یُس اسرٲیلِکۍ گرن کافرن منز ناپاک کورمُت اوس، یُس تِم گٔیہِ۔\n22.\\tتێلہِ وۆن اسرٲیلِس گرس سٍتـ̡ یِتھٕ پٲٹھـ̡ خداوند خدا چُھہ فرماوان۔ بہٕ چُھس نہٕ چانہِ خٲطرٕ، اے اِسرٲیلِک گرٕ، بٔلکہِ میانہِ مقدس ناوٕ خٲطرٕ، یُس ژے کافرن مَنٛز ناپاک کورمُت چھُ، یُس تہٕ تُہۍ گٔیہِ۔\n23. تہٕ بہٕ کَرٕ پنُن عظیم ناو پاک، یُس کافرن مَنٛز ناپاک اوس کرنہٕ آمُت، یُس تِمن منز بے عزتی کٔرِتھ چُھہ ۔ تہٕ کافرن گژھہِ پتاہ زِ بہٕ چُھس خداوند چُھس، یێلہِ بہٕ تہندِس نظرن برونہہ کُن پاکیزہ سپدِ۔ {تِہُند: یا، تُہُند}\n24. تکیازِ بہٕ نِہ ژے کافرن منزٕ نِتھ تہٕ ژے سارِوٕے ملکَو منزٕ جمع کٔرِتھ تہٕ اَننہٕ ژے پنٕنِس سرزمینس مَنٛز۔\n25. تیلہٕ چُھس بہٕ ژے پیٛٹھ صاف آب چُھک، تہٕ ژٕ گژھہٕ پاک تہٕ چانہٕ تمام بُتن نِش پاک۔\n26. بہٕ دِیہ ژے اکھ نۆو دِل تہِ، تہٕ اکھ نۆو روح تہِ تراوٕ ژے منز، تہٕ بہٕ کٔرٕ ژے ماز سُند دِل تہٕ بہٕ دِیہ ژے مازُک دِل۔\n27. تہٕ بہٕ تراوٕ پنُن روح پانس اندر، تہٕ ژے کرٕ پننین قونونن مطٲبق، تہٕ تہٕ کرٕ میٲنۍ فیصلہٕ تہٕ کرٕنۍ۔\n28.\\tتہٕ تُہۍ روزِو تتھ زمینس مَنٛز یُس میہ پننین مٲلن دِژمُت چھُ۔ تہٕ تُہۍ بٔنِو میٲنۍ لوک، تہٕ بہٕ بنہٕ تُہند خدا۔\n29. بہٕ بچاوٕ ژے تہٕ چانہِ سارِنٕے ناپاکی نِش تہٕ بہٕ بَناوٕ تہٕ بہٕ بَناوٕ تہٕ کَرٕ نہٕ ژےٚ قحط۔\n30. تہٕ بہٕ کرٕ کُلِس ہُند پھل تہٕ کھہَس ہُند ہُریر، یُتھ زِ توے گژھہِ نہٕ کُلِس منز قحطُک کانہہ ملامت میلہِ۔\n31. تیلہٕ گژھِو تُہۍ پنٕنۍ بد وتہٕ تہٕ پنٕنۍ اعمال یاد تھاوٕنۍ یِم نہٕ نیک ٲسۍ، تہٕ پَنٕنٮ۪ن بدکارن تہٕ ناپاکیزَن ہٕندِ خٲطرٕ کٔرِو پنٕنـ̡ پانس نِش۔\n32.\\tبہٕ چُھس نہٕ تۅہہِ خٲطرٕ [یہِ}، خداوند خدایہِ چُھہ ونان، یێلہِ چُھہ تُہٕندِس سٍتـ̡ پنہٕ نِس طریقس سٍتـ̡ شرم تہٕ پریشان گژھُن، اے اِسرٲیلـ̡ ہٕندِس گھرس سٍتـ̡ ۔\n33. یِتھٕ پٲٹھـ̡ چُھ خداوند خدا فرماوان۔ ییمہِ دۅہہٕ بہٕ ژے تۅہہ سارِنٕے بدکاریو نِش پاک کرِ، بہٕ کرٕ ژے شہرن مَنٛز روزُن، تہٕ فضلہٕ یِن تعمیر کرنہٕ۔\n34.\\tتہٕ ویران زمینہٕ گژھہِ کاشت کرنہٕ، ییلہ زن یہِ سارِنٕے کُن گزرن وٲلِس نظرس منز ویران آسہِ۔\n35. تہٕ تِم ونن زِ یہِ زمین یُس ویران اوس، سُہ چُھ عدن کِس باغس ہیوٗ بنیومُت۔ تہٕ بنجر تہٕ ویران تہٕ تباہ شَہَر چھِ بَننہٕ آمٕتۍ، {تہٕ} چھِ آباد گَژھان۔\n36. تێلہِ یُس کافر چُھہ تۅہہِ اندۍ پکھۍ باقٕے روزان چُھہ، تێلہِ گژھہِ معلوم زِ بہٕ خداوند چُھس تباہ گٔمٕژ {جایے} تہٕ کُلـ̡ کُلـ̡ یُس ویران اوس، بہٕ چُھس کُلـ̡ یُس ویران اوسُس: بہٕ چُھس خداوند کٔرِتھ {یہ} کٔرمُت، تہٕ بہٕ کرٕ {یہ}۔\n37. یِتھٕ پٲٹھۍ چُھ خداوند خدا فرماوان۔ بہٕ کٔرٕ توتہِ یہِ پرژھہٕ یِنہٕ خٲطرٕ اِسرٲیلِس ہٕندِس گرس سٍتـ̡ کرنہٕ خٲطرٕ۔ بہٕ ہُرراوٕ تِمن ہٕندِ پٲٹھۍ۔\n38.\\tیُس مقدس ریوڑ ہٕندِس پٲٹھۍ، یِتھٕ پٲٹھـ̡ یروشلمُک ریوڑ پٲٹھـ̡ پنہٕ نِس سنجیدہ دعوتس مَنٛز۔ یِتھٕ پٲٹھۍ گژھن ویران شہر انسانن ہٕندِس ریوڑس سٍتـ̡ بٔرِتھ: تہٕ تِمن گژھہِ معلوم زِ بہٕ چُھس خداوند ۔ {مقدس...: ہیب۔ مقدس چیزن ہند ریوڑ}","1.\\tخداوند سُند اَتھٕ اوس میہ پیٹھ، تہٕ کٔرٕن میہ خداوند سٕندِس روحس سٍتـ̡ تہٕ تھووُن میہ وادی مَنٛز یُس اڈیو سٍتـ̡ بٔرِتھ اوس،\n2.\\tتہٕ دِژُن میہ اندۍ پکھۍ: تہٕ وُچھِتھ ٲس یِمن ہٕندِس اندۍ پکھۍ واریاہ ٲسۍ۔ تہٕ لو، {تِم} ٲسۍ واریاہ خۄشٕک۔ {وادی: یا، شیمپین}\n3.\\tتہٕ تٔمۍ ووٚن میہ زِ یِم أڈجہِ ہیکوا زندٕ ٲسِتھ؟ تہٕ میہ دیت جواب، اے خدایہ، ژے چُھہ پتاہ۔\n4.\\tبییہِ ووٚن میہ زِ یمن اڈجن پیٹھ کرو پیشن گویی تہٕ تمن وونُن، اے خشک أڈجہِ، بوزو خداوند سُند کلام۔\n5. یِتھٕ پٲٹھۍ چُھ خداوند خدا یِمن أڑجن سٍتـ̡ وَنان۔ وچھ بہٕ ژے اندر شاہ اژان تہٕ ژیہ زندٕ:\n6. تہٕ بہٕ تراوٕ ژے پیٹھ، تہٕ ژے ماز اَننہٕ تہٕ ژے مٕلہٕ سٍتـ̡ ؤلِتھ تہٕ ژے دِیہٕ تہٕ ژے زندٕ۔ تہٕ ژیہ گژھہِ پتاہ زِ بہٕ چُھس خداوند ۔\n7.\\tیێلہِ کٔر میہ پیشن گویی یُس میہ حکم دِنہٕ آمُت اوس، تہٕ یێلہِ میہ پیشن گویی کٔر، اَتھ منز گۆو شور، تہٕ وُچھ ہلکان تہٕ أڈجہِ گٔیہِ أڈجہِ ہٕنزِ أڈجہِ سٍتـ̡ أڈجہِ سٍتـ̡ رٔلِتھ ۔\n8.\\tتہٕ ییلہ میہ وُچھ تِمن پیٹھ رژھ تہٕ ماز آو تِمن پیٹھ، تہٕ کھال لوٚگ تِمن پیٹھ، مگر {تِمن منز} اوس نہٕ شاہ۔\n9. اَمہِ پتہٕ ووٚن تٔمۍ مےٚ وَنُن، ہوہس نِش پیشن گویی کرٕن، نَبوت کٔرٕن، اِنسان سٕندِس نیٚچو، تہٕ وَہس وَنُن، یِتھٕ پٲٹھـ̡ چُھ خداوند خدا وَنان۔ ژۅشونی ہواو منزٕ یِن، اے شاہ، تہٕ یِمن مارن پیٹھ شاہ دِیُو، یُتھ زن تِم زندٕ روزن۔ {واو: یا، شاہ}\n10. یێلہِ کٔر میہ پیشن گویی یێلہِ تٔمۍ سُند حُکُم دِیُت، تہٕ تِمن دِژ شاہ تہٕ تِم گٔیہِ زندٕ، تہٕ کھٔدۍ پننین قدمن پیٹھ، اکھ واریاہ بٔڈ لشکر۔\n11. اَمہِ پتہٕ ووٚن تٔمۍ میانہِ پٲٹھۍ، اے انسان سٕندِس نیٚچو، یِم أڈجہِ چھِ اسرٲیلُک سورُے گرٕ: وُچھِو تِم چھِ ونان زِ سانہِ أڈجہِ گٔیہِ ہۄکھمٕژ، تہٕ سون وۅمید چھِ ختم گٔمٕژ، أسۍ چھِ پننین حصن ہٕندِ خٲطرٕ ژٹنہٕ آمٕتۍ۔\n12. تێمہِ کِنۍ کٔرِو پیشن گویی تہٕ تِمن ونُن، یِتھٕ پٲٹھۍ چُھ خداوند خدا فرماوان۔ اے میٲنۍ لوکو، بہٕ کھولہٕ تہٕ ژےٚ قبرو منزٕ نیرِتھ تہٕ اَننہٕ اسرٲیلِس مَنٛز۔\n13. تہٕ ژے گژھہِ پتاہ زِ بہٕ چُھس خداوند چُھس، یێلہِ بہٕ چُھس تُہٕنزِ قبرٕ کھولِتھ تہٕ تێہہ قبرو منزٕ نیبر کٔرِتھ،\n14. تہٕ کرٕ میٲنۍ روح پانس مَنٛز، تہٕ ژٕ روزٕ زندٕ، تہٕ بہٕ تھاوٕ ژے پننہِ زمینس مَنٛز، تیلہٕ گژھہٕ ژے معلوم زِ میہ چُھہ خداوند کتھ کٔرمٕژ، تہٕ کٔرٕمُت، خداوند چُھ فرماوان۔\n15. خداوند سُند کلام آو میہ نِش دُبارٕ وونُن،\n16.\\tاَمہ علاوٕ، اے انسان سٕندِس نیٚچو، تُل اَکھ لوٗر تہٕ اَتھ پیٹھ لیکھِھکھ یہوداہ سٕندِ خٲطرٕ، تہٕ بنی اِسرٲیلِیَن ہٕندِ سٲتھین خٲطرٕ، تہٕ تٔمِس پٲٹھـ̡ لیٚکھِو، یێمہِ سٍتـ̡ یوسف سٕندِ خٲطرٕ، افرائیم سٕندِ لورِ تہٕ سارِنٕے اِسرٲیلِس سٍتـ̡ تٔمِس سٲتھین خٲطرٕ:\n17.\\tتہٕ یِم أکِس سٍتـ̡ أکِس سٍتـ̡ رٔلِتھ رٔلِتھ ۔ تہٕ تِم گژھن تۅہہِ ہٕندِس اتھس منز اکھ بنن۔\n18.\\tتہٕ ییلہ تُہٕندِس لُکہٕ سٍتـ̡ تۅہہِ سٍتـ̡ کتھ کرِ، کیا ژٕ ہٲوِکھ نہٕ اسہِ ہٲوِتھ یِمن سٍتـ̡ کیا چُھہ تُہٕندِس مطلبس سٍتـ̡ ۔\n19.\\tتِمن وَنُن چُھہ یِتھٕ پٲٹھـ̡ خداوند خدایہِ سُند وَنان۔ وچھ بہٕ رٔٹِتھ یوسف سٕنز لور، یُس افرائیم سٕندِس اتھس منز چُھ، تہٕ اسرٲیلٕکۍ قبیلہٕ تٔمۍ سٕندِس سٲتھین ہٕندِس اتھس منز، تہٕ تِم تھاوٕ پانس سٍتۍ، یہوداہ سٕنزِ لورِ سٍتـ̡ تہٕ بناوٕ تِمن اکھ لور، تہٕ تِم گژھن میٲنس اتھس منز۔\n20.\\tتہٕ یِمن پیٹھ ژے لیکھان چھِ، تِمن ہٕندِس اَتھَس مَنٛز آسہِ تِمن ہٕندِس اَچھن برونہہ کُن۔\n21. تہٕ تِمن وَنُن یِتھٕ پٲٹھۍ چُھ خداوند خدایہِ وَنان۔ وُچھ، بہٕ نِہ بنی اسرائیل کافرن منز، ییتہِ تم گٔیہِ، تہٕ کرٕ تِم پریتھ طرفہٕ جمع تہٕ تِمن ہٕندِس ملکس مَنٛز اننہٕ۔\n22. تہٕ بہٕ بناوٕ تِم اِسرٲیلِس کِس پہاڑن ہٕندِس زمینس مَنٛز اَکھ قوم۔ تہٕ اکھ بادشاہ آسہِ تِمن سارِنٕے خٲطرٕ بادشاہ: تہٕ تِم گژھن نہٕ مزید زٕ قوُم، تہٕ نہ گژھن تِم دۄن سلطنتن مَنٛز تقسیٖم کرنہٕ۔\n23.\\tتِم کٔرِن نہٕ پنٕنـ̡ بُتـ̡ سٍتـ̡ پنُن پان ناپاک کٔرِتھ، تہٕ نہ پَنٕنـ̡ پَنٕنـ̡ بُتـ̡ سٍتـ̡ تہٕ کُنہِ تہِ گناہ سٍتـ̡ بێیہِ بہٕ تِمن سارِنٕے مکانہٕ نِش بچاوٕ یِمن مَنٛز یِمو گۅناہ کٔرِمٕژ آسہِ، تہٕ بہٕ کَرٕ تِمن ہُند خدا۔\n24. تہٕ داؤد، میون خادم آسہِ تِمن پیٹھ بادشاہ۔ تہٕ تِمن سارِنٕے آسہِ اَکھ چرواہ: تِم تہِ گژھن میانین فٲصلن مَنٛز پٔکِتھ، تہٕ میانین قونونن ہُند عمل کرُن، تہٕ تِم کرٕنۍ۔\n25.\\tتہٕ تِم روزن تتھ زمینس مَنٛز یُس میہ پننِس خادم یعقوبس دِژمُت چھُ، یَتھ مَنٛز تُہند مٲلۍ باپ روزان چھِ۔ تہٕ تِم روزن اَتھ مَنٛز روزُن، تہٕ تِہٕندِس شُرۍ، تہٕ تِہٕندِس شُرِ ہٕندِس شُرِ ہمیشہٕ خٲطرٕ: تہٕ میون خادم داؤد روزِ ہمیشہٕ خٲطرٕ تِہُند شہزادٕ۔\n26. امہِ علاوٕ کٔرٕ بہٕ تِمن سٍتـ̡ صلح کرنُک معاہدٕ۔ یہِ آسہِ تِمن سٍتـ̡ ابدی عہد تہٕ بہٕ تھاوٕ تِمن سٍتـ̡ تہٕ تِمن ہٕندِس درمِیان پَنُن مقدس مقام۔\n27. میون خیمہ تہِ آسہِ تِمن سٍتـ̡ تہٕ یێلہِ بہٕ تِہُند خدا تہٕ تِم آسہِ میٲنۍ لوک۔\n28. تہٕ کافرن گژھہِ معلوم زِ بہٕ خداوند چُھس اسرٲیلِس پاک کران، یێلہِ میون مقدس روزِ ہمیشہٕ خٲطرٕ تِمن منز۔","1. تہٕ خداوند سُند کلام آو میہ نِش،\n2. اِنسان سٕندِس نیٚچُو، پَنُن بُتھ کٔرِو مَشِخ تہٕ طُبَل کِس بٔڈِس شہزادٕ مَجوگ سٕندِس سرزمینس سٍتـ̡ تہٕ أمِس خٕلاف کٔرٕن پیشن گوئی، {سردار...: یا، سردار سُند شہزادٕ}\n3.\\tتہٕ ونُن، یِتھٕ پٲٹھۍ چُھ خداوند خدایہ فرماوان۔ وچھ بہٕ چُھس ژے خلاف، اے گوگ، میشیک تہٕ طُبلُک بٔڈ شہزادہٕ:\n4. تہٕ بہٕ کٔرٕ ژےٚ واپس تہٕ ژےٚ نِش تہٕ ژےٚ سارِنٕے لشکر، گُرِ تہٕ گُرۍ سوار، یِم سارِنٕے قٕسمٕکۍ بٔڈۍ لٔگِتھ تہٕ یِم سارِنٕے تلوار رَٹان ٲسۍ۔\n5. فارس، ایتھوپیا تہٕ لیبیا تمن سۭتۍ۔ یم سٲری چھہِ ڈھال تہ ہیلمٹ لٲگتھ:{لیبیا: یا، پھوت}\n6. گومر، تہٕ تٔمۍ سٕندۍ سٲری بینڈ۔ شمٲلی کوارٹرُک ٹوگرمہ ہُند گرٕ تہٕ تٔمۍ سٕندِ سارِنٕے لُکھ تہٕ تٔمۍ سٕندِس سارِنٕے لُکھ تہٕ تۅہہِ سٍتـ̡ واریاہ لُکھ ۔\n7.\\tتیار روزو تہٕ پانس خٲطرٕ تیار روزُن، تہٕ پانس خٲطرٕ تیار کرُن، تہٕ تِمن ہٕندِ رٲچھ کٔرِتھ روزُن۔\n8.\\tواریاہن دۅہن پَتہٕ یِیہِ تُہٕندِس ملکس مَنٛز یُس تلوار سٍتـ̡ واپس اننہٕ آمُت چُھ، {تہٕ یێلہِ} چُھہ واریاہو لُکو منزٕ جمع کرنہٕ آمُت، یُس ہمیشہٕ ضایع رودمُت چُھ، مگر یہِ چُھ قومن منزٕ نیبر کڈنہٕ آمُت، تہٕ تِم روزن سارِنٕے سٍتـ̡ بٔرِتھ۔\n9.\\tژٕ کھسُن تہٕ یُس طوٗفان ہٕندۍ پٲٹھۍ، تہٕ ژے آسُکھ اوٚبرُک پٲٹھۍ، تہٕ پَنٕنـ̡ سارِنٕے لُکھ تہٕ پانس سٍتـ̡ واریاہ لُکھ ژٔلِتھ ۔\n10.\\tخداوند خدا چُھ یِتھٕ پٲٹھۍ فرماوان۔ یہ تہِ گژھہِ سپدِ، {یہ} اتھۍ ساعتہ گژھہِ تۅہہِ ذہنس منز چیز یِن، تہٕ تۅہہ گژھہِ اکھ بد خیال سونچُن: {سونچ...: یا، اکھ شرارتی مقصد تصور کرُن}\n11. تہٕ ژٕ وَنُن، بہٕ گژھٕ بے دیوار گامن ہٕندِس سرزمینس تام۔ بہٕ گژھٕ تِمن نِش یِم آرام سان روزان چھِ، یِم سارِنٕے چھِ دیوارٕ ورٲے روزان، تہٕ نہ چھِنہٕ سلاخہٕ تہٕ نہ دروازٕ، {محفوظ: یا، اعتماد سان}\n12.\\tغنیمت رٹُن، تہٕ شِکار کرُن؛ پَنُن اَتھٕ پھیُرُن یِمن ویران جاین {یِم وۄنۍ آباد چھِ}، تہٕ تِمن لُکن کُن یِم قومن منزٕ جمع کرنہٕ آمٕتۍ چھِ، یِمن مویشی تہٕ مال حٲصل چھِ، یِم زمینس منز روزان چھِ۔ {نِنہٕ خٲطرٕ...: ہیب۔ غنیمت خراب کرنہٕ خٲطرٕ، تہٕ شکارس شکار کرنہٕ خٲطرٕ} {درمیان: ہیب۔ ناف}\n13.\\tشیبا تہٕ دیدان تہٕ ترشیشٕکۍ سوداگر، تِمن ہٕندِس سارِنٕے جوان شیرن سٍتـ̡ وَنُن ژے وَنُن، کیا تُہۍ چھِو غُنیمت نِنہٕ آمٕتۍ؟ ژیہ چھکھ شکارہ رٹنہٕ خٲطرٕ پنٕنۍ صحبت جمع کٔرمٕژ؟ رۄپہٕ تہٕ سۄنہٕ نِنہٕ خٲطرٕ، چاروٲے تہٕ سامان نِنہٕ خٲطرٕ، واریاہ لوُٹ نِنہٕ خٲطرٕ؟\n14. تێمہِ کِنۍ، اِنسانہٕ سٕندِس نیٚچو، پیشن گویی کٔرِو تہٕ گوگس وَنُن، یِتھٕ پٲٹھـ̡ چُھ خداوند خدا فرماوان۔ اَتھ دۅہہٕ ییلہ میانہِ قوم اسرٲیلِچ بٔرِتھ روزِ، کیا ژیہ پتاہ آسہِ؟\n15.\\tتہٕ ژے گژھہِ پننہِ جایہِ پیٹھٕ شُمالہٕ کِس حِصس منز، تہٕ پانس سٍتـ̡ واریاہ لُکھ یِم سارِنٕے گُرٮ۪ن پیٹھ سوار ٲسِتھ، اکھ بٔڈ کمپنی تہٕ اکھ زبردست لشکر۔\n16.\\tتہٕ تہٕ ژے گژھ میانین اسرٲیلِین ہٕندِس قومس خٕلاف، زمینس ؤلِتھ اوٚبرٕکۍ پٲٹھۍ۔ یہ گژھہِ پتمین دۅہن منز، تہٕ بہٕ اَننہٕ ژے پننہِ سرزمینس خلاف، یُتھ زِ بہٕ گژھہِ ژے منز، اے گوگ، تِہنزن نظرن برونہہ کُن۔\n17. خداوند خدا چُھ یِتھٕ پٲٹھۍ فرماوان۔ {کیا چُھ} سُہ یٔمِس مُتلق میہ پرانہِ زمانس منز پننین خدمتگارن ہٕندِ دٔسۍ کتھ کٔرمٕژ، یِمو تِمن دۅہن {واریہ} ؤرین منز پیشن گویی کٔرمٕژ ٲس زِ بہٕ کرٕ ژے تِمن خلاف اننہٕ؟ {by: Heb. اتھہٕ سٍتۍ }\n18. تہٕ یێلہِ گژھہِ اَمی وِزِ یێلہِ گوگ اسرٲیلِچ سرزمینس پیٹھ واتہِ، خداوند خدایہ چُھ ونان زِ میٲنۍ قہر گژھہِ میٲنس بُتھِس پیٹھ۔\n19.\\tکیازِ میہ چھہ پننہِ حسدس منز کتھ کٔرمٕژ، یقینا تمہِ دۅہہ گژھہِ اسرٲیلِچ زمینس مَنٛز اکھ زبردست ہلچل ۔\n20.\\tیُتھ سمندرٕچ گاڈٕ تہٕ اسمانٕکۍ جاناوار، تہٕ کھہٕکۍ جانور تہٕ زمینہِ پیٹھ کھسنہٕ وٲلۍ سارِنٕے جانور تہٕ زمینہٕ کِس بُتھِس پیٹھ روزن وٲلۍ سارِنٕے انسان یِن میانہِ موجودگی سٍتـ̡ تھرتھراونہٕ، تہٕ پہاڑ یِن ؤسِتھ تہٕ کھڑایہِ جاے پیٚیہِ،  تہٕ پرتھ دیوار گژھہِ زمینس پیٹھ۔ {کھڑا...: یا، ٹاور، یا، ہیڑۍ}\n21. تہٕ بہٕ کرٕ پننین سارنٕے پہاڑن منز أمِس خلاف تلوار منگناونہٕ، خداوند خدا چُھ ونان زِ پرٮ۪تھ أکِس انسان سٕنز تلوار گژھہِ پننِس بٲیس خٕلاف۔\n22. تہٕ بہٕ کَرٕ أمِس خٕلاف وَباہٕ تہٕ خونہٕ سٍتـ̡ عرض۔ تہٕ بہٕ واو أمِس پیٹھ، تہٕ تٔمۍ سٕندِس بینڈس پیٹھ، تہٕ واریاہن لوٗکن پیٹھ یِم أمِس سٍتۍ چھِ، اکھ ووٚتھُن روٗد، تہٕ بٔڈۍ ڈولہٕ، نار تہٕ گندھ۔\n23. یِتھٕ پٲٹھۍ کٔرٕ بہٕ پنُن پان بڑاوُن، تہٕ پنُن پان پاکیز۔ تہٕ بہٕ گژھہٕ واریاہن قومن ہٕندِس نظرس منز زاننہٕ یِن، تہٕ تِمن گژھہِ معلوم زِ بہٕ چُھس خداوند ۔","1. تێمہِ کِنۍ، اے انسان سٕندِس نیٚچو، گوگس خلاف پیشن گویی کرٕن، تہٕ ونُن، یِتھٕ پٲٹھۍ چُھ خداوند خدا فرماوان۔ وچھ بہٕ چُھس ژے خلاف، اے گوگ، میشیک تہٕ طُبلُک بٔڈ شہزادہٕ:\n2. تہٕ بہٕ کرٕ ژے واپس پھیُر، تہٕ ژے ترٲوِتھ شُمٲلی حصہٕ پیٹھٕ تہٕ ژے اَننہٕ اسرٲیلٕکِس پہاڑن پیٹھ: {تراو...: یا ژے ژے شیہ وبا دِتھ واپس} {شمال...: ہیب۔ شمالک طرف}\n3. تہٕ بہٕ ژےٚ کھوورِ اتھہٕ سٍتۍ ژٔٹِتھ تہٕ تُہند تیر تراوٕ دٔچھنِس اتھہٕ منز۔\n4. تہٕ تہٕ پَنٕنـ̡ سارِنٕے لُکن ہٕندِس پہاڑن پى۪ٹھ، تہٕ یێلہِ سٍتـ̡ چُھہ تُہٕندِس سٍتـ̡ پۯاونہٕ آمُت، بہٕ دِیہٕ ژے پرٮ۪تھ قٕسمٕکِس بٔرِس جاناوارَن تہٕ کھٮ۪نہٕ یِنہٕ خٲطرٕ۔ {ترتیب دِنہٕ: ہیب۔ ونگ} {to be...: Heb. کھٮ۪نہٕ خٲطرٕ}\n5.\\tژے گژھہِ کھُلہٕ میدانس مَنٛز پیوٚو، کیازِ میہ چُھہ کتھ کٔرمٕژ، خداوند خدا چُھ فرماوان۔ {کھلہِ...: ہیب۔ میدانُک بُتھ}\n6. تہٕ بہٕ سوزٕ ماگوگس تہٕ یِمن منزٕ یِم جزیرن منز لاپرواہ روزان چھِ، تہٕ تِمن گژھہِ معلوم زِ بہٕ چُھس خداوند ۔ {لاپرواہی: یا، اعتماد سان}\n7. یِتھٕ پٲٹھـ̡ بہٕ کَرٕ پنُن مقدس ناو پننین لوکن اسرٲیلس مَنٛز زاننہٕ۔ تہٕ بہٕ دِیہٕ نہٕ تِمن پنُن مقدس ناو مزید آلودہ کرنہٕ: تہٕ کافرن گژھہِ معلوم زِ بہٕ چُھس خداوند ، اسرٲیلِس مَنٛز پاک ۔\n8. وُچھِو یہِ آو تہٕ یہِ چُھ سپدمُت، خداوند خدا چُھ فرماوان۔ یہ چھہ سہ دۅہ یتھ متعلق میہ کتھ کرمژ۔\n9.\\tیِم اسرٲیلٕکین شہرن مَنٛز روزان چھِ، تِم گژھن نار دِتھ زالنہٕ، دۅشوے ڈھال تہٕ بکلر، کمان تہٕ تیر، تہٕ نیزٕ تہٕ تِم زٲلِن ستن ؤرین نارٕ سٍتـ̡ زالنہٕ۔\n10.\\tیُتھ زِ تِم کٔرِن نہٕ کھہہٕ منزٕ کانہہ لٔکر نِن، تہٕ نہ ژٹِن جنگلَو منزٕ کانہہ تہِ۔ خداوند خدا چُھ ونان زِ تِم زٲلن نارٕ سٍتـ̡ ہتھیار تہٕ یِمو تِمن خراب کٔرِتھ تہٕ یِمن لُٹِتھ لُٹِتھ تہٕ لُٹنہٕ یِنہٕ وٲلِس لُٹنہٕ یِنہٕ۔\n11.\\tتہٕ اَمہ دۅہہ سپدِ، تہٕ بہٕ دِیہ گوگس اَتھ قبرن ہٕنز جاے، سمندرٕ کِس مشرقس کُن مسافرن ہٕنزِ وادی، تہٕ سُہ کرِ مسافرن ہٕنز نَس، تہٕ اَتہِ کرِ تِم گوگ تہٕ تٔمۍ سٕندِس سارِنٕے لٔگِس دفن تہٕ تِم وَنَن وادی ہمونگوگ۔ {نَس: یا، ٲس} {ہمونگوگ: یعنی گوگُک بٔڑ}\n12. تہٕ سَتھ رٮ۪تہٕ گژھِ اسرٲیلُک گرٕ تِمن دفن کرنہٕ، یُتھ تِم زمینہِ پاک کٔرِتھ۔\n13.\\tآ، زمینہٕ کین سارِنٕے لُکھ دفن کٔرِن {تِم}۔ خداوند خدا چُھ ونان زِ یێلہِ بہٕ ییہِ تِمن ہٕندِ خٲطرٕ شہرت حٲصِل کرنہٕ۔\n14.\\tتہٕ تِم کٔرِن مُسلسل روزگارن ہٕندِس نفرس ژٔٹِتھ، زمینہٕ کِس بُتھِس پیٹھ روزن وٲلِس سٍتـ̡ دفن کرنہٕ خٲطرٕ، سَتھ ریتھ ختم گژھنہٕ پتہٕ گژھن تِم ژھانڈنہٕ۔ {مرد...: ہیب۔ تسلسلٕکۍ مرد}\n15.\\tتہ یم مسافر زمینہِ منزۍ نیران چھہِ، ییلہ کانسہِ انسان سنز اڈجہ وچھان چھہِ، تیلہ کرِ سہ اتھ سیتۍ اکھ نشانہ، یوٚت تام دفن کرن والیو یہ ہمونگوگ وادی منز دفن کرِ۔ {سیٹ اپ: ہیب۔ بَناوُن}\n16. تہٕ شہرُک ناو تہِ آسہِ ہمونہ۔ یِتھٕ پٲٹھۍ کٔرِن تِم زمینہِ صاف کرنہٕ۔ {ہمونہ: یعنی، کثیر}\n17. تہٕ اے انسان سُند فرزند، یِتھٕ پٲٹھۍ چُھ خداوند خدا فرماوان۔ پرٮ۪تھ پکھہٕ دار جاناوارس سٍتـ̡ کتھ کرٕنـ̡ تہٕ میدانہٕ کِس پرٮ۪تھ درندَس سٍتـ̡ کٔرِو پان جمع تہٕ یِنہٕ سٍتـ̡ میانہِ قربانی خٲطرٕ کٔرِو پریتھ طرفہٕ جمع یُس بہٕ چانہِ خٲطرٕ قربان کرُن، {حتیٰ کہ} اسرٲیلِک پہاڑن پیٹھ اکھ بٔڈ قربانی تہٕ یُتھ تُہۍ ماز کھٮ۪وان تہٕ خون چیٚو۔ {اُن...: ہیب۔ پرٮ۪تھ پکھہٕ کِس جاناوارس تام} {میون قربانی: یا، میون ذبح}\n18.\\tتم کھیوٚو طاقتور سُند ماز تہٕ زمینہٕ کین شہزادن ہُند خون، کۅکرِ ہُند تہٕ ژھاوٕن، بیلن ہُند خون، یِم سارِنٕے بشان سٕندِ موٚٹۍ ماز چِھہِ۔ {ژھاوٕل: ہیب۔ گریٹ گوٹس}\n19.\\tتہٕ ژے کھیوٚو چربی یوٚت تام ژیہ پورٕ گژھِ، تہٕ میٲنۍ قربانی ہُند یُس میہ ژے خٲطرٕ قربان کورمُت چُھ، توٚت تام چُھکھ خون پیون۔\n20. یِتھٕ پٲٹھـ̡ یێلہِ یێلہِ میانہِ دسترِ پیٹھ گُرِ تہٕ رتھ، طاقتور نفرو سٍتـ̡ تہٕ سارِنٕے جنگی نفرو سٍتـ̡ بٔرِتھ یِنـ̡ خداوند خدا چُھ ونان۔\n21. تہٕ بہٕ کٔرٕ پنُن جلال کافرن مَنٛز قٲیم، تہٕ سارِنٕے کافر وُچھن میون فٲصلہٕ یُس مے انجام دِژمُت چُھ، تہٕ پنُن اتھہٕ یُس مے تِمن پیٹھ تھوومُت چُھ۔\n22.\\tیێلہِ گژھہِ اسرٲیلِکِس گرس پتاہ زِ بہٕ چُھس اَمہِ دۅہہٕ پیٹھٕ تہٕ برونہہ کُن خداوند تِہُند خدا۔\n23. تہٕ کافرن گژھہِ پتاہ زِ اسرٲیلُک گرٕ گۆو تہندِس ظلمس مۅکھہٕ قٲد کرنہٕ، کیازِ تِمو کٔر میانہِ خلاف زیادٕ، تێمہِ مۄکھٕ تھووُن میہ تِمن نِش پنُن بُتھ تہٕ دِژُن تِمن ہٕندِس دُشمن ہٕندِس اتھس مَنٛز۔\n24.\\tتِہٕنزِ ناپاکی مُطٲبِق تہٕ تِمن ہٕنزِ غلطی مُطٲبِق کٔر میہ تِمن سٍتـ̡ تہٕ تِمن نِش پنُن بُتھ ژوٗر۔\n25. تێمہِ کِنۍ چُھ خداوند خدا یِتھٕ پٲٹھۍ فرماوان۔ وۅنۍ اَنہٕ بہٕ یعقوب سٕندِس قٲد سٍتـ̡ دُبارٕ اَننہٕ، تہٕ کرٕ سارِنٕے اِسرٲیلِس سٍتـ̡ رحمت، تہٕ بہٕ کرٕ پننہِ مقدس ناوٕ سٍتـ̡ حسد۔\n26. اَمہِ پتہٕ گٔیہِ تِمو پنٕنۍ شرم تہٕ پنٕنۍ سٲری گُناہ یِمو میانہِ خلاف گُناہ کٔرِتھ، ییٚلہِ تِم پنہٕ نِس سرزمینس مَنٛز محفوٗظ روزان ٲسۍ، تہٕ کٲنسہ تہِ کھوژمُت۔\n27. یێلہِ بہٕ تِم لُکہٕ نِش دُبارٕ أنِتھ تہٕ تِمن ہٕندِس دُشمن ہٕندِس زمینہٕ نِش جمع کٔرِتھ تہٕ واریاہن قومن ہٕندِس نظرس منز یِمن مَنٛز پاکیز۔\n28.\\tتێلہِ گژھہِ تِمن پتاہ زِ بہٕ چُھس خداوند تِہُند خدا، یێمہِ سٍتـ̡ تِم کافرن مَنٛز قٲد کرنہٕ آمٕتۍ چھِ، مگر مے چُھس تِمن ہٕندِس سرزمینس مَنٛز جمع کٔرِمُت، تہٕ یِمو منزٕ چُھس نہٕ کانہہ تہِ تِمن ہٕندِس سرزمینس مَنٛز جمع کٔرِمٕتۍ۔ {کُس...: ہیب۔ میانہِ وجہ سٍتۍ وغیرہ}\n29. بہٕ چُھس نہٕ یِمن نِش پنُن بُتھ ژوٗرِ تھاوُن، کیازِ بہٕ چُھس پنُن روح اسرٲیلِس کِس گرس پیٹھ تراومُت، خداوند خدا چُھ فرماوان۔","1. سانہِ قید کِس پانژمِس تہٕ وُہِمِس ؤریس منز، ؤری کِس آغازس منز، ریتہٕ کِس دٔہمہِ دۅہس منز، ژۄدٲہمہِ ؤریس مَنٛز آو شہر مارنہٕ، امی دۅہہٕ اوس خداوند سُند اتھہٕ میٲنس پیٹھ، تہٕ أنِن میہ تتہِ۔\n2.\\tخدایہ سٕندِس وژنس مَنٛز اوٚن سُہ میہ اسرٲیلِس مَنٛز تہٕ تھووُن أکِس تھدِس بالس پیٹھ، یُس جنوبس کُن أکِس شہرُک فریم اوس۔ {کمہِ ذریعہ: یا، یتھ پیٹھ}\n3.\\tتہٕ سُہ اوٚن میہ تتہِ، تہٕ وُچھ، اَکھ شخٕص اوس، یٔمۍ سُند ظہور پیتل ہیوٗ اوس، اتھس منز ٲس فلکسٕچ اکھ لٲنہٕ، تہٕ اکھ پیمائش کٔرِتھ۔ تہٕ سُہ کھڑا دروازس پیٹھ۔\n4. تہٕ مردَن ووٚن مے، انسان سٕندِس نیٚچو، پنٕنِس أچھو سٍتـ̡ وُچھِو، تہٕ بوز پنٕنـ̡ کَنَو سٍتـ̡ تہٕ پَنُن دِل تھاوُن یُس بہٕ ژے ہاونہٕ یُن۔ تکیازِ بہٕ ہٲوِتھ تہٕ ژے ہٲوِتھ تہٕ یُس تہٕ ژے وُچھان چھُ، سُہ کٔرِو اسرٲیلِس کِس گرس سٍتـ̡ ظٲہر۔\n5.\\tتہٕ وُچھ مکانس اندۍ پکھۍ اکھ دیوار، تہٕ انسان سٕندِس اتھس منز اوس شیہ ہُرِ ہُند اکھ نٔر تہٕ اکھ اتھہٕ کھجر۔ تہٕ تھزر، اکھ سر۔\n6.\\tامہ پتہ آو سہ اتھ دروازس پیٹھ یُس مشرقس کُن نظر اوس تھاوان، تہ امہِ چہ ہیرن پیٹھ کھستھ ووت دروازہ کس دروازس پیٹھ پیمائش، یُس اکھ سرہ کھوٚل اوس۔ تہٕ بیاکھ دروازٕ، یُس اکھ سرٕ کھوٚل اوس۔ {یُس وچھان چُھ...: ہیب۔ یمۍ سُند بُتھ مشرقس کُن وتھ اوس}\n7.\\tتہِ {پرٮ۪تھ} لۅکٹۍ کمرہ {اوس} اکھ نٔر زیوٹھ تہ اکھ نال کھوٚل؛ تہٕ لۄکٹٮ۪ن کمرن درمیان ٲسۍ پانژھ کیوبٹ۔ تہ دروازہ کس پورچس پیٹھ دروازہ کس دروازس پیٹھ اوس اکھ سرۍ۔\n8.\\tتمۍ پیمُت اندرۍ گیٹ کس پورچ تہِ، اکھ سرۍ۔\n9.\\tاَمہ پتہٕ پیمُت تٔمِس دروازٕکِس دٲرس ٲٹھ کیوبِٹ۔ تہٕ امکۍ پوسٹ، زٕ کیوبٹ؛ تہ دروازک پورچ اوس اندرمس کُن۔\n10. تہٕ مشرقس کُن دروازٕکۍ لۄکٕٹۍ کمرٕ ٲسۍ اتھ طرفہٕ ترےٚ، تہٕ اَتھ طرفہٕ ترےٚ۔ تِم ٲسۍ اَکہِ پیمانٕکۍ ترےٚ: تہٕ پوسٹن ٲس اَتھ طرفہٕ تہٕ اَتھ طرفہٕ اکھ پیمانہٕ۔\n11. تہٕ تٔمۍ ووٚن دروازٕ کہِ اژنُک کھجر، داہ کیوبٹ۔ {تہٕ} دروازُک زیچھر، ترہ کیوبِٹ۔\n12.\\tلۅکٹٮن خانن برونہہ کنہِ تہِ ٲس اکھ کیوبِٹ {یتھ طرفہ} تہ اتھ طرفہ ٲس اکھ کیوبِٹ تہ لۅکٹۍ کمرہ {ٲس} اتھ طرفہ شیہ کیوبٹ تہ اتھ طرفہ شیہ کیوبِٹ۔ {جاے: ہیب۔ حد، یا، باؤنڈ}\n13.\\tاَمہ پتہٕ ووت اَکہِ لۅکٹِس کمرہٕ کِس چھتہٕ پیٹھٕ بییِس کمرس تام دروازٕ: کھجر اوس پانژھ وُہ کیوبِٹ، دروازس خلاف دروازٕ۔\n14.\\tتٔمۍ کٔر دروازس اندۍ دربار کس چوکس تام تریہ ہور کیوبٹن ہٕنزِ پوسٹہ تہِ۔\n15. تہٕ دروازٕ کہِ بُتھ پیٹھہٕ اندرمِس دروازٕ کِس بُتھِس تام ٲس پنژاہ کیوبِٹ۔\n16. تہٕ {اتہِ} آسہٕ لۄکٹٮ۪ن کمرن تہٕ اندۍ اندۍ اندۍ دروازس اندر تِمن ہٕندٮ۪ن چوکن تہٕ یِتھے پٲٹھۍ آسہٕ محرابَن ہٕندِس اندۍ دٲر تہٕ دٲرٕ {آسہٕ} اندۍ: تہٕ {پرٮ۪تھ کُنہِ} پوسٹس پیٹھ ٲس کھجور کُلۍ۔ {تنگ: ہیب۔ بند} {محراب: یا، گیلری، یا، پورچ} {اندرم: یا، اندر}\n17.\\tاَمہ پتہٕ اوٚن سُہ میہ نیبرِم دربارس منز، تہٕ اتہِ ٲسۍ کمرہٕ، تہٕ اندۍ پکھۍ ٲسۍ دربارٕ خٲطرٕ اکھ فٹ پاتھ بناونہٕ آمٕژ: فٹ پاتھس پیٹھ ترہ کمرہٕ۔\n18. تہٕ دروازن ہٕندِس زیچھرس خلاف فٹ پاتھ اوس بٔنِم فٹ پاتھ۔\n19.\\tامہ پتہ پیوو تمۍ بۅنہ کنہِ دروازہ پیٹھہ اندرمس صحنس برونہہ کُن اکھ ہتھ کیوبٹ مشرقس تہ شمالس کُن کھجر۔ {بغیر: یا، نیبر پیٹھ}\n20.\\tتہٕ نیبرِم صحنُک دروازٕ یُس شمالس کُن وُچھان اوس، تمٔۍ اوس امُک زیچھر تہٕ کھجر۔ {یُس وُچھمُت: ہیب۔ کمۍ سُند بُتھ اوس}\n21.\\tتہٕ اَمہ کِس لۅکٹۍ کمرہٕ ٲسۍ اَتھ طرفہٕ تریہ تہٕ اَتھ طرفہٕ ترےٚ۔ تہٕ امکۍ پوسٹ تہٕ امکۍ محراب ٲسۍ گوڑنکس دروازٕ کس پیمائش پتہٕ: امچ زیچھر ٲس پنژاہ کیوبٹ، تہٕ کھجر پانژھ تہٕ وُہ کیوبٹ۔ {محراب: یا، گیلری، یا، پورچ}\n22. تہٕ تِہٕنزِ دٲرِ، تہٕ تِہٕنزِ محراب، تہٕ تِہٕندِ کھجور کُلۍ، یُس مشرقس کُن وُچھان چُھ، تِمن ہٕندِس دروازس پٲٹھۍ۔ تہٕ تِم ووت سَتھ قدمو پٮ۪ٹھٕ اتھ تام۔ تہٕ امکۍ محرابیں ٲسۍ تمن برونٹھ کُن۔\n23.\\tتہ اندرم صحنک دروازہ اوس شمالس کُن تہ مشرقس کُن دروازس پیٹھ۔ تہٕ تٔمۍ پیمُت دروازٕ پٮ۪ٹھٕ دروازس تام ہتھ کیوبِٹ۔\n24.\\tامہ پتہ اوٚن میہ جنوبس کُن تہ وُچھن جنوبس کُن اکھ دروازہ: تہٕ تٔمۍ وُچھن یمو پیمانو مطٲبق امہِ چہ چوکن تہٕ محرابن ہٕنز پیمائش۔\n25.\\tتہِ آسہ اتھ منز تہ اندۍ محرابن منز، یمن دارین ہندۍ پاٹھۍ آسہِ: زیچھر اوس پنژاہ کیوبٹ، تہ کھجر پانژھ تہ وُہ کیوبٹ۔\n26. تہٕ اتھ تام کھسنہٕ خٲطرٕ ٲس ستھ ہیرٕ، تہٕ امکۍ محراب ٲسۍ تمن برونٹھ کُن: تہٕ اتھ ٲس کھجور کُلۍ، اکھ اتھ طرفہٕ تہٕ بیاکھ اَتھ طرفہٕ، اَمہ کِس پوسٹن پیٹھ۔\n27.\\tتہٕ اندرمس صحنس منز اوس جنوبس کُن اکھ دروازہ: تہٕ تٔمۍ اوس جنوبس کُن دروازٕ پیٹھہٕ دروازس تام اکھ ہتھ کیوبٹ مینان۔\n28.\\tتہٕ سُہ اوٚن میہ جنوبی دروازٕ کِنۍ اندرمِس آنگنس منز: تہٕ تٔمۍ کٔر یِمو پیمانو مطٲبق جنوبی دروازٕچ پیمائش۔\n29.\\tتہٕ اَمہ کِس لۅکٹۍ کمرہٕ، تہٕ اَمہ ہٕندِس کھورِ تہٕ اَمہ کِس محرابَن منز، یِمو پیمانو مطٲبق: {یہِ} ٲس پنژاہ کیوبِٹ زیٖٹھ، تہٕ پانژھ وُہ کیوبِٹ کھُلہٕ۔\n30.\\tتہٕ اندۍ اندۍ محراب ٲسۍ تقریباً پانژھ وُہ کیوبِٹ زیوٹھ تہٕ پانژھ کیوبِٹ کھُلہٕ۔ {وسیع : ہیب۔ وسعت}\n31. تہٕ امکۍ محراب {ٲس} مکمل دربارس کُن۔ تہٕ کھجور کُلۍ ٲسۍ یمن ہٕندِس پوسٹن پیٹھ: تہٕ اتھ تام کھسنہٕ خٲطرٕ ٲسۍ ٲٹھ قدم۔\n32. تہٕ سُہ اوٚن میہ مشرقس کُن اندرمِس آنگنس منز، تہٕ تٔمۍ کٔر یِمو پیمانہٕ مطٲبق دروازٕچ پیمائش۔\n33.\\tتہ امکۍ لۅکٹۍ کمرہ، تہ یمن ہندۍ پوسٹ تہ امہ چہ محراب، یمن پیمائش مطابق ٲسۍ {اتہِ} دارِ تہ اندۍ دارۍ: {یہ} ٲس پنژاہ کیوبٹ زیوٹھ تہ پانژھ وُہ کیوبٹ کھجر۔\n34. تہٕ امکۍ محراب ٲسۍ ظاہری صحنس کُن۔ تہٕ کھجور کُلۍ ٲسۍ امہِ کِس پوسٹن پیٹھ، اَتھ طرفہٕ تہٕ اَتھ طرفہٕ: تہٕ اتھ تام کھسنہٕ خٲطرٕ ٲسۍ ٲٹھ قدم۔\n35.\\tتہٕ سُہ اوٚن میہ شمٲلی دروازس پیٹھ، تہٕ مینُن یِمو پیمانہٕ مطٲبق۔\n36.\\tامکۍ لۅکٹۍ کمرہ، امکۍ پوسٹ تہ امکۍ محراب تہ اتھ اندۍ دارۍ: زیچھر اوس پنژاہ کیوبٹ، تہ کھجر پانژھ تہ وُہ کیوبٹ۔\n37.\\tتہٕ تِمن ہٕندِس عہدس {ٲس} اَمہ کُن دربارس کُن۔ تہٕ کھجور کُلۍ ٲسۍ امہِ کِس پوسٹن پیٹھ، اَتھ طرفہٕ تہٕ اَتھ طرفہٕ: تہٕ اتھ تام کھسنہٕ خٲطرٕ ٲسۍ ٲٹھ قدم۔\n38.\\tتہٕ خانہٕ تہٕ اَمہِ ہٕندِس اندراجَس مَنٛز ٲسۍ دروازن ہٕندِس کھورِ سٍتـ̡ یِمن سٍتـ̡ دزنہٕ آمٕژ نذرانہ چھلان۔\n39.\\tتہٕ دروازٕ کِس دٲرس مَنٛز آسہٕ اَتھ طرفہٕ زٕ میز، تہٕ اَتھ طرفہٕ زٕ ٹیبل، یَتھ پیٹھ زٲلِتھ نذرانہ تہٕ گۅناہ ہٕنز نذرانہ تہٕ ناجائز نذرانہٕ مارنہٕ خٲطرٕ۔\n40.\\tتہ اندۍ پکھۍ، ییلہ شمٲلی دروازہ کس دروازس تام واتان چھہِ، {ٲسۍ} زہ ٹیبل۔ تہٕ دوٚیمہِ طرفہٕ، یُس {اوس} دروازٕ کس دٲرس پیٹھ، {ٲس} زٕ ٹیبل۔ {بطور...: یا، قدمس پیٹھ}\n41.\\tاتھ طرفہ ژور ٹیبل {ٲس} تہ اتھ طرفہ ژور ٹیبل، دروازس اندۍ پکھۍ۔ ٲٹھ ٹیبل، یتھ پیٹھ تمو مارۍ {پنٕنۍ قربانی}۔\n42.\\tتہٕ ژۅن میزن ٲس زالنہٕ خٲطرٕ ژٔٹِتھ کٔنِس سٍتۍ، اکھ ڈۅڈ زیوٹھ تہٕ اکھ کیوبیٹ کھوٚر تہٕ اکھ کیوبیٹ تھوٚد۔\n43.\\tتہٕ ہُکس اندر، اکھ اتھہ کھوٚل، اندۍ بند، تہٕ میزن پیٹھ اوس نذرانہ ہُند ماز۔ {ہکس: یا، اینڈرونز، یا، زٕ ہارتھون}\n44.\\tتہ اندرمس دروازس ورٲے ٲسۍ اندرمس صحنس منز گیون والین ہندۍ کمرہ، یُس شمٲلی دروازس اندۍ پکھۍ اوس۔ تہٕ تہند امکان اوس جنوبس کُن: اکھ مشرقی دروازٕ کہِ طرفہٕ {تھا} شمالس کُن امکان۔\n45.\\tتہٕ تٔمۍ ووٚن میہ زِ یہِ کمرہٕ، یێمِچ امکانہٕ {چُھ} جنوبس کُن، {چُھ} پادٕرٮ۪ن ہٕندِ خٲطرٕ، یِمن ہٕندِس ایوانٕکۍ رٲچھ کرن وٲلۍ۔ {چارج: یا، وارڈ، یا، آرڈیننس}\n46.\\tتہٕ سُہ خانہٕ یُس شمالس کُن {چُھ} پادٕرین ہٕندِ خٲطرٕ، قربان گاہٕچ رٲچھ کرن وٲلۍ: یِم چِھہ لاوی سٕندِس نیچوین مَنٛز زادوک سٕندِ نیچوۍ، یِم خداوند سٕندِس خدمت کرنہٕ خٲطرٕ یِوان چھِ۔\n47.\\tتہ پیمُت تٔمۍ کٔر ہتھ ہتھ ہاتھ زیوٹھ تہٕ اکھ ہتھ کیوبِٹ کھُلہٕ، ژور مربع۔ تہٕ قربان گاہ {یُس} مکانس برونٹھ کُن۔\n48.\\tتہٕ سُہ أنۍ میہ مکانہٕ کِس برآمدس پیٹھ، تہٕ پیمُت دٲرِ ہُند پرٮ۪تھ کُنہِ، اَتھ طرفہٕ پانژھ کیوبِٹ تہٕ اَتھ طرفہٕ پانژھ کیوبِٹ: تہٕ دروازُک کھجر اوس اَتھ طرفہٕ تریہ کیوبِٹ تہٕ اَتھ طرفہٕ ترےٚ کیوب۔\n49.\\tدٲرِ ہُند زیچھر اوس وُہ کیوبِٹ، تہٕ کھجر اوس کاہ کیوبِٹ۔ تہٕ {سُہ اوٚن مے} ہیرن پیٹھ یتھ کٔنۍ تم اتھ تام وٲتۍ: تہٕ {اتہِ} ٲسۍ ستون، اکھ اتھ طرفہٕ تہٕ بیاکھ اَتھ طرفہٕ۔","1.\\tامہ پتہ نیو میہ مندرس منز، تہ پیمُت کھورۍ، اکہ طرفہ شیہ کیوبٹ کھجر، تہٕ دوٚیمہِ طرفہ شیہ ہاتھ کھجر، {یُس}خیمہ خانہِ ہند کھجر اوس۔\n2. تہٕ دروازُک کھجر اوس داہ کیوبٹ۔ تہٕ دروازٕکۍ اندۍ ٲسۍ اکہ طرفہٕ پانژھ کیوبِٹ تہٕ دوٚیمہِ طرفہٕ پانژھ کیوبِٹ: تہٕ تٔمۍ اوس امِچ زیچھر ژتٲجی کیوبِٹ: تہٕ کھجر، وُہ کیوبِٹ۔ {دروازٕ: یا، داخلہٕ}\n3.\\tامہ پتہ گۆو سہ اندرم تہ دروازہ کس کھورِ پیٹھ پیمائش کٔرِتھ زٕ کیوبٹ۔ تہٕ دروازٕ، شےٚ کیوبٹ؛ تہٕ دروازُک کھجر، ستھ کیوبٹ۔\n4.\\tتہ تٔمۍ پیمُت امیک زیچھر وُہ کیوبِٹ۔ تہٕ کھجر، وُہ کیوبِٹ، مندرس برونہہ کُن: تہٕ تٔمۍ ووٚن مے زِ یہِ {چُھ} سارِوٕے کھۄتہٕ مقدس {جاے}۔\n5.\\tمکانچ دیوار پیمائش کرنہ پتہ چھہ شیہ کیوبٹ۔ تہٕ پریتھ طرفہٕ خانہٕ ہُند کھجر، ژور کیوبٹ، پریتھ طرفہٕ مکانس اندۍ اندۍ اند۔\n6.\\tتہ اندۍ پکھۍ کمرہ ٲسۍ ترے، اکھ اکس پیٹھ تہ ترہ ترتیب۔ تہٕ تم ژاو دیوارس منٛز یُس اندۍ اندۍ کمرن خٲطرٕ مکانک {اوس}، تاکہ تم آسہٕ رٔٹتھ، مگر تم ٲسۍ نہٕ مکانہٕ کس دیوارس منٛز رٔٹتھ۔ {اکھ...: ہیب۔ سائیڈ چیمبر اوور سائیڈ چیمبر} {ترٕہ...: یا، تریہ تہٕ ترہ لٹہِ، یا، پوٚت} {ہیو ہولڈ: ہیب۔ رٔلِتھ رٔلِو}\n7. تہٕ {اتہِ} اوس اکھ بڑاوُن، تہٕ وُنہِ تہِ ہیوٚر کُن اندۍ پکھۍ کُن وُنہِ تہِ ہیوٚر کُن: تکیازِ مکانُک کھجر اوس وُنہِ تہِ ہیوٚر کُن، تہٕ یِتھٕ پٲٹھۍ ہُریوو {بٔنِم} {چیمبر} پیٹھٕ تھزرس تام۔ {تتہِ...: ہیب۔ یہٕ آو وسیع کرنہٕ، تہٕ گول گومُت}\n8.\\tمیہ وُچھ اندۍ پکھۍ مکانُک تھزر تہِ: اندۍ پکھۍ کمرن ہٕنز بنیٲذ ٲس شیہ بٔڈۍ کیوبٹن ہُند اکھ پورٕ سر۔\n9.\\tدیوارُک موٚٹ یُس {اوس} نیبر کُنہِ کمرس منز، {اوس} پانژھ کیوبِٹ: تہٕ {یہ} یُس {اوس} ترٲومُت {اوس} تِمن طرفن ہٕنزِ جاے یُس {اوس} اندر۔\n10.\\tتہٕ خانن درمیان اوس پریتھ طرفہٕ مکانس اندۍ وُہن ہُند کھوٚر۔\n11.\\tتہ اندۍ پکھۍ کمرن ہندۍ دروازہ ٲسۍ تتھ جایہ کُن یُس کھوورِ اوس، اکھ دروازہ شمالس کُن تہ بیاکھ دروازہ جنوبس کُن اوس، تہ یُس جایہ کھجر اوس، سہ اوس اندۍ پکھۍ پانژھ کیوب۔\n12.\\tوۅنۍ سۅ عمارت یۅسہ مغرب کُن اندس پیٹھ الگ جایہ برونہہ ٲس، سۅ ٲس ستتھ کیوبٹ کھُلہٕ۔ تہٕ عمارتچ دیوار ٲس پانژھ کیوبٹ موٚٹ تہٕ امیک زیچھر اوس نتھ کیوبٹ۔\n13.\\tیێمہِ کٔر مکانہٕ ہتھ ہتھ ہُند زیوٹھ ۔ تہٕ الگ جاے، تہٕ عمارت، دیوارن سٔتۍ، اکھ ہتھ کیوبٹ زیوٹھ۔\n14.\\tمکانہ کس بُتھس تہ مشرقس کُن الگ جایہ تہِ اکھ ہتھ کیوبٹ۔\n15.\\tتہٕ تٔمۍ پیمُت عمارتُک زیچھر الگ الگ جایہ یُس اتھ پٔتۍ کُن اوس، تہٕ اَمہ چہ گیلریہٕ اَکہِ طرفہٕ تہٕ دوٚیمہِ طرفہٕ اکھ ہتھ کیوبِٹ، أنٛدرِم مندر تہٕ دربارٕکۍ دٲر۔ {گیلری: یا، واریاہ واک، یا، ستونن سۭتۍ واک}\n16.\\tدروازن ہٕندِس کھورِ تہٕ تنگ دارِ تہٕ گیلریہٕ اندۍ پکھۍ، اندۍ پکھۍ لٔکرِ سٍتۍ، تہٕ زمینہٕ پیٹھٕ دارِ تام، تہٕ دارِ آسہٕ ؤلِتھ۔ {cieled...: Heb. لٔکرِ ہٕنز چھت} {تہٕ پیٹھ...: یا، تہٕ دٲرن تام زٔمیٖن}\n17.\\tدروازس پیٹھمہِ کُن، اندرمس مکانس تام، تہٕ نیبرِم، تہٕ اندۍ دیوارس منز، پیمائش مطٲبق۔ {پیمائش: ہیب۔ اقدامات}\n18.\\tتہٕ {یہ} اوس کروبِم تہٕ کھجور کُلٮ۪و سٍتۍ بناونہٕ آمُت، یُتھ کھجورُک کُل اوس کروبس تہٕ کروبس درمیان آسان۔ تہٕ {پرٮ۪تھ} کروبس ٲسۍ زٕ بُتھۍ۔\n19.\\tتہ اکہ طرفہ کھجور کُلِس کُن تہ دوٚیمہِ طرفہ کھجور کُلِس کُن اوس انسان سُند بُتھ تہ دوٚیمہِ طرفہ کھجور کُلِس کُن بُتھ تہ دوٚیمہِ طرفہ کھجور کُلِس کُن بُتھ تہ دوٚیمہِ طرفہ کھجور کُلِس کُن بُتھ تہ یہ اوس اندۍ پکھۍ سٲرۍسٕے گرس منز بناونہ آمت۔\n20.\\tزمینہٕ پیٹھٕ دروازس تام آیہ کروبی تہٕ کھجور کُلۍ بناونہٕ، تہٕ مندرٕچ دیوارس پیٹھ۔\n21. مندرٕچ پوسٹ ٲس مربعہٕ، {تہٕ} مقدس مقامُک بُتھ؛ ظہور {اَکہِ} ظہور {بییِس سٕندِ} کِس طورس پیٹھ۔ {پوسٹس: ہیب۔ پوسٹ}\n22. لٔکرِ ہُند قربان گاہ اوس تریہ ہُند تھوٚد تہٕ زیچھر اوس زٕ کیوبٹ۔ تہٕ اَمہ کُن تہٕ زیچھر تہٕ دیوارٕ آسہٕ لٔکرِ ہٕندِس سٍتـ̡ تہٕ تٔمۍ ووٚن مے زِ یہِ {چُھ} سُہ میز یُس خداوند سٕندِ برونہہ کُن چُھ۔\n23. تہٕ مندرس تہٕ مقدس مقامس ٲسۍ زٕ دروازٕ۔\n24.\\tتہٕ دروازن منز ٲسۍ زٕ پنہٕ وتھٕر، زٕ پھیرن پنہٕ۔ أکِس دروازٕ خٲطرٕ زٕ {پنہٕ} تہٕ بیٚیِس {دروازٕ} خٲطرٕ زٕ پنہٕ۔\n25.\\tتہٕ یِمن پیٹھ ٲسٕکھ مندرٕ کِس دروازس پیٹھ، کروبِم تہٕ کھجور کُلۍ بناونہٕ آمٕتۍ، یِتھ کٔنۍ زَن دیوارن پیٹھ بناونہٕ آمٕتۍ ٲسۍ۔ تہٕ نیبر کِس برآمدس بُتھِس پیٹھ ٲسۍ موٚٹ تخت۔\n26. تہٕ اَکہِ طرفہٕ تہٕ دوٚیمہِ طرفہٕ آسہٕ تنگ دارِ تہٕ کھجور کُلۍ تہٕ مکانہٕ کِس اندۍ پکھۍ تہٕ موٚٹ تخت۔","1.\\tتمہ پتہ نیو میہ پورہ دربارس منز، شمالس کُن وتہِ: تہٕ سُہ أنۍ میہ تتھ کمرس منز یُس {اوس} الگ جایہ اوس، تہٕ یُس {اوس} شمالس کُن عمارتس برونہہ کُن۔\n2.\\tاکھ ہتھ ہاتھ زیچھر برونہہ اوس شمٲلی دروازہ تہ کھجر اوس پنژاہ کیوبٹ۔\n3.\\tوُہن {cubits} خلاف یُس {ٲس} اندرم صحنہٕ خٲطرٕ، تہٕ اتھ فٹ پاتھس خلاف یُس {اوس} مکمل دربارس خٲطرٕ، {was} گیلری خلاف ترین {داستان} منز۔\n4.\\tتہ کمرس برونہہ کنہِ اوس دہن ہاتھ کھجرس اندر کُن اکھ وتھ، اکھ کیوبٹ وتھ۔ تہٕ شمالس کُن تہندٕ دروازٕ۔\n5. وۅنۍ ٲس پیٹھم چیمبر ژھوٚٹ: تکیازِ گیلریہٕ آسہٕ یمو کھوتہٕ تھزر، بنمہٕ کھوتہٕ تہٕ عمارتہٕ کس درمیانی حصہٕ کھوتہٕ زیادٕ۔ {زیادہ ٲس...: یا، کیا کھیوٚو یمو منز} {بنمہٕ کھوتہٕ زیادٕ...: یا، تہٕ عمارت ٲس بنم تہٕ درمیانی حصہٕ پیٹھ مشتمل}\n6.\\tتکیازِ تِم ٲسۍ ترٮن {منزلن} منز، مگر دربارن ہندۍ ستون ٲسۍ نہٕ تھم: امہ کنۍ ٲس {عمارت} زمینہٕ پیٹھٕ بٔنِتھ تہٕ درمیانی کھوتہٕ زیادٕ دباونہٕ آمٕژ۔\n7.\\tتہ دیوار یُس کمرس برونہہ کُن اوس، کمرن ہندس برونہمس حصس کُن اوس، امیک زیچھر اوس پنژاہ کیوبٹ۔\n8.\\tتِمن خانن ہٕندِس زیچھرس خٲطرٕ یُس {ٲس} پورٕ دربارس منز {ٲس} پنژاہ کیوبٹ: تہٕ لو، مندرس برونہہ کُن {ٲس} ہتھ کیوبٹ۔\n9.\\tتہٕ یِمن خانن تلہ کنہِ اوس مشرقس کُن دٲخل گژھان، یُتھ زن یِمن منز اژان چھُ۔ {بۄنہٕ کَنہِ: یا، جایہِ پیٹھ} {اندراج: یا، سُہ یُس مے أن} {as...: یا، یتھ کٔنۍ سہ آو آو}\n10.\\tچیمبر ٲسۍ مشرقس کُن دربار کس دیوارس موٚٹۍ منز، الگ جایہ تہ عمارتس برونہہ کُن۔\n11.\\tتہٕ یِمن برونہہ کُن وتھ ٲس تِمن خانن ہٕندِ ظاہری شکلہٕ ہٕندۍ پٲٹھۍ، یوت تام تِم {تہٕ} تِمن ہٕندِس طریقس مطٲبق تہٕ تِمن ہٕندِس دروازس مطٲبق ٲسۍ۔\n12.\\tتہ یمن کمرن ہندِ دروازہ مطابق یم {جنوبس کُن} ٲسۍ، وتہِ ہندس سرس منز اوس اکھ دروازہ، {حتیٰ کہ} وتھ ٲس سیدِ سیود مشرقس کُن دیوارس برونہہ کُن، ییلہ تمن منز اژان چھہ۔\n13.\\tتێلہِ وۆن میہ زِ شُمٲلی کمرہٕ تہٕ جنوبٕکۍ خانہٕ، یِم الگ الگ جایہ برونہہ کنہِ چھِ، تِم چھِ مقدس خانہٕ، یێتہِ پادٕرۍ یِم خداوند نِش یِن یِم سارِوٕے کھۄتہٕ مُقدس چیز کھٮ۪ن، اَتہِ گژھن تِم سارِوٕے کھۄتہٕ مُقدس چیز، تہٕ مازٕچ نذرانہ تہٕ گۅناہ ہٕنز نذرانہ تہٕ ناجائز نذرانہٕ دِنہٕ۔ تِکیازِ جاے {چُھ} مُقدس۔\n14.\\tییلہ پادٕرۍ اَتھ مَنٛز اژان چھِ، تِم گژھن نہٕ مقدس جایہِ منزٕ نیرِتھ، مگر تتہِ گژھن تِم پَنٕنۍ پوشاک یَتھ مَنٛز تِم خدمت کران چھِ۔ تِکیازِ تِم {چھِ} مُقدس؛ تہٕ باقی پلو لاگُن، تہٕ تِمن چیزن نِش گژھن یِم {لوکن ہٕندِ خٲطرٕ} چھِ۔\n15.\\tوۅنۍ ییلہ تمۍ اندرمس مکانس پیمائش ختم کٔر، سہ نیو میہ تتھ دروازس کُن ییمک امکان مشرقس کُن اوس، تہ اندۍ پکھۍ پیمائش کٔرتھ۔\n16.\\tتٔمۍ پیمُت مشرِقس کُن پیمائش کٔرِتھ پانژھ ہتھ سرۍ، اندۍ پیماونہٕ آمٕژ نِلہٕ سٍتۍ۔ {سائیڈ: ہیب۔ ہوا}\n17.\\tتٔمۍ کٔر شمالس کُن پانژھ ہتھ سرۍ، اندۍ پیماونہٕ آمٕژ نٔلۍ۔\n18.\\tتٔمۍ پیمُت جنوبُک طرف، پانژھ ہتھ سرۍ، پیمائش کٔرِتھ۔\n19.\\tسہ پھیر مغرب کُن، {تہٕ} پیمائش کٔرِتھ پانژھ ہتھ سرۍ۔\n20.\\tتٔمۍ کٔر اتھ ژۅشونی طرفو سٍتـ̡ میننہٕ: اتھ ٲس اندۍ پکھۍ اکھ دیوار، پانژھ ہتھ زیوٗٹھ تہٕ پانژھ ہتھ کھُلہٕ، یُس مقدس مقامس تہٕ ناپاک جایہِ درمیان الگ کرنہٕ ییہِ۔","1. امہ پتہ اوٚن میہ دروازس پیٹھ، {حتیٰ کہ} دروازہ یُس مشرقس کُن وچھان چھُ:\n2. تہٕ وُچھِو اسرٲیلِکِس خدایہِ سُند جلال مشرق کِس وتہٕ سٍتـ̡ تہٕ تٔمۍ سٕنز آواز ٲس واریاہن آبن ہٕندِ شورٕکۍ پٲٹھۍ، تہٕ زمین گٔیہِ تٔمۍ سٕندِ جلال سٍتـ̡ چمک۔\n3.\\tتہٕ {یہ} اوس تمہِ وژنس مطٲبق یُس میہ وُچھمُت اوس، {حتیٰ کہ} تمہ وژنس مطٲبق یُس میہ شہر تباہ کرنہٕ خٲطرٕ وُچھمُت اوس: تہٕ وژن {ٲس} تِتھۍ وژنٕکۍ پٲٹھۍ یُس میہ دریائے چیبر کِس بٔٹھۍ وُچھمُت۔ تہٕ بہٕ پیوٚو بُتھِس پیٹھ۔ {ییلہ ...: یا، ییلہ میہ پیشن گویی کرنہِ آو زِ شہر گژھہِ تباہ کرنہٕ یُن}\n4. تہٕ خداوند سُند جلال آو اَتھ دروازٕ کِس وتہٕ سٍتـ̡ گرس مَنٛز یێمِس مشرقس کُن چُھ۔\n5. یێمہِ کِنۍ رٔٹِتھ رٔٹِتھ تہٕ أنِن میہ أنٛدرِمِس صحنَس مَنٛز۔ تہٕ وُچھِو خداوند سٕندِ جلال سٍتـ̡ گرس بٔرِتھ۔\n6.\\tتہٕ بوز میہ گرٕ نیبر کُن کتھ کرنہٕ۔ تہٕ مرد اوس میہ سیتۍ کھڑا۔\n7. تہٕ تٔمۍ ووٚن مےٚ، اے انسان سٕندِس نیٚچو، میانہِ تختٕچ جاے تہٕ میانین قدمن ہٕنزِ تلپٕچ جاے، یَتھ مَنٛز بہٕ ہمیشہٕ خٲطرٕ بنی اسرٲیلِس مَنٛز روزُن، تہٕ میون مقدس ناو، اسرٲیلُک گرٕ گژھِ نہٕ تِمن تہٕ تِہٕندِس بادشاہس تہٕ تِمن ہٕنزِ بدکٲری سٍتـ̡ ناپاک کرنہٕ۔  تہندٮ۪ن بادشاہن ہٕندِس تھدٮ۪ن مقامن پیٹھ لاشہٕ سٍتۍ تہِ۔\n8.\\tمیانہِ دروازہ سٍتـ̡ تِمن ہٕندِس دروازس سٍتـ̡ تہٕ میانین عہدن سٍتـ̡ تہٕ میانہِ تہٕ تِمن درمِیان دیوار سٍتـ̡ چُھہ تِمو میون مقدس ناو تہِ ناپاک کورمُت یُس تمو کٔرمُت چُھ، اَمہِ مۄکھٕ چُھس مے تِم پننہِ شرارتس منز کھٮ۪ومُت۔ {تہٕ دی...: یا، تکیازِ میہ تہٕ تمن درمیان اوس صرف اکھ دیوار}\n9. وۅنۍ گژھن تِم پنٕنۍ بدکاری تہٕ پننین بادشاہن ہٕنز لاشہٕ میانہِ نِش دور تہٕ بہٕ روزٕ تمن منز ہمیشہٕ روزُن۔\n10.\\tاے انسان سٕندِس نیچو، ہٲوِو گرٕ اسرٲیلِس کِس گرس کُن، یُتھ تِم گژھن پننین گناہوں پیٹھ شرمندہ گژھن، تہٕ تِم گژھن نمونہٕ ہُند پیمائش۔ {پیٹرن: یا، سم، یا، نمبر}\n11.\\tتہٕ یێلہِ تِمن سارِنٕے کُنہِ کُنہِ چیزس پیٹھ شرم آسہِ، تِمن ہٲوِو گرٕچ شکلہٕ، تہٕ اَمہِ سٍتـ̡ یِمن ہٕنزِ سارِنٕے شکلہٕ، تہٕ اَمہ ہٕنزِ سارِنٕے شکلہٕ تہٕ تِمن ہٕنزِ سارِنٕے شکلہٕ تہٕ تِمن ہٕندِس سارِنٕے قوانین، تہٕ تِمن ہٕندِس نظرس مَنٛز لیکھِو {یہ}۔  تاکہ تم ہیکن امچ پورٕ شکلہٕ، تہٕ امہٕ کین تمام آرڈیننس برقرار تھٲوتھ، تہٕ تم کرن تم کرنہٕ۔\n12.\\tیہ چھہ گرُک قانون۔ بالہٕ کِس تینتٲلِس پیٹھ چھُ اَمہ کِس اندۍ پکھۍ اَمہ کِس سورے حدس مُقدس آسُن۔ وچھو یہ {چُھ} گرُک قانون۔\n13.\\tتہٕ یِم چھِ کیوبٹس پَتہٕ قربان گاہٕچ پیمائش: کُبِٹ {چُھ} اکھ کیوبِٹ تہٕ اَتھُک کھجر۔ حتیٰ کہ بونہٕ کُن آسہِ اکھ کیوبِٹ، تہٕ کھجر اکھ کیوبِٹ، تہٕ امِچ سرحد آسہِ اندۍ پکھۍ اکھ وقفہٕ: تہٕ یہِ آسہِ قربان گاہُک تھوٚد جاے۔ {بونہٕ: ہیب۔ بوسوم} {ایج: ہیب۔ لپ}\n14.\\tتہ بونہِ پیٹھہ بۅنہ کنہِ زمینہِ {حتی} پیٹھہ بنمس بستس تام {گژھہِ} زہ کیوبٹ تہ کھجر اکھ کیوبٹ۔ تہٕ لۄکٹۍ آباد {حتی} پیٹھہٕ بٔڑس بستس تام {گژھہٕ} ژور کیوبٹ، تہٕ کھجر {ایک} کیوبٹ۔\n15.\\tیێلہِ چُھہ قربان گاہ ژور کیوبِٹ۔ تہٕ قربان گاہ پیٹھہٕ تہٕ ہیرِ کُن گژھن ژور سینگ۔ {قربان گاہ (گۄڈٕنِک): ہیب۔ ہاریل، یعنی خدایہ سُند پہاڑ} {قربان گاہ (دویم): حب۔ ایریئل، یعنی خدایہ سُند شیر}\n16.\\tتہٕ قربان گاہ آسہِ ژۅن چوکن منز باہ {کیوبٹ} زیوٹھ، بارہ کھُلہٕ تہٕ مربع۔\n17.\\tتہِ آسہِ ژۅداہ {کیوبٹ} زیوٹھ تہ ژۅداہ کھُلہِ ژۅداہ ژۅداہ چوکن منز۔ تہٕ اتھ اندۍ پکھۍ سرحد آسہِ نصف کیوبٹ۔ تہٕ اَمہ کِس بونہٕ کِس حصس منز آسہِ اکھ کیوبِٹ؛ تہٕ تٔمۍ سٕنز ہیرٕ گژھن مشرقس کُن نظر۔\n18.\\tتہٕ تٔمۍ ووٚن مے، انسان سُند فرزند، یِتھٕ پٲٹھۍ چُھ خداوند خدایہ وَنان۔ یِم چِھہ قربان گاہٕکۍ احکام ییمہِ دۅہہ تم یہ بناوِ، اتھ پیٹھ زالنہٕ خٲطرٕ تہٕ اتھ پیٹھ خون چھکاونہٕ خٲطرٕ۔\n19.\\tتہٕ تُہۍ دِیُن پادٕرٮ۪ن یِم صَدوق سٕندِس بُلِس سٍتـ̡ آسہِ، یُس میانہِ نِش یِوان چھُ، یُس میانہِ خدمت کرنہٕ خٲطرٕ یِوان چھُ، خداوند خدایہِ چُھہ ونان زِ گۅنہٕ ہٕندِس نذرانہ خٲطرٕ چھُ اکھ جوان دانٛد۔\n20.\\tتہٕ تُہۍ کٔرِو اَمہِ کِس ژۅشونی سینٛگن پیٹھ، تہٕ ژۅشونی کونن پیٹھ، تہٕ اندۍ پکھۍ اندۍ پکھِس پیٹھ، یِتھٕ پٲٹھۍ کٔرِو تُہۍ اتھ صاف تہٕ صاف کٔرِتھ۔\n21.\\tژے نِیُن گۅنہٕ ہٕندِس نذرانہٕ سٍتـ̡ تہٕ سُہ زالُن گرٕ کِس مُقرر مقامس پیٹھ، مقدس جایہِ ورٲے۔\n22. تہٕ دٔیمہِ دۅہہ کٔرِو ژے ژھاوُل ہُند اکھ بچہٕ گۅنہٕ کِس نذرانہ خٲطرٕ پیش کرنہٕ۔ تہٕ تِم کرِ قربان گاہٕچ صفائی، یِتھ کٔنۍ تمو داند سٍتـ̡ صاف کٔر۔\n23.\\tییلہ ژے صفایی ختم کرِ، تہٕ ژے کٔرِو اکھ بچہٕ دانٛد بغٲر داغ تہٕ روٚس کُنہِ\n24. تہٕ تُہۍ کرِ تِم خداوند سٕندِ برونہہ کُن پیش کرنہٕ، تہٕ پادٕرۍ تراوَن تِمن پیٹھ نوٗن، تہٕ تِم دِیِن خداوند سٕندِ خٲطرٕ زالنہٕ خٲطرٕ پیش کرنہٕ۔\n25.\\tسَتھ دۅہہٕ گژھِ ژے پریتھ دۅہہ اکھ ژھاوُل تیار کٔرِتھ گۅنہٕ نِش نذرانہٕ خٲطرٕ۔\n26. سَتھ دۅہہٕ گژھن تِم قربان گاہ صاف کٔرِتھ پاک کٔرِتھ۔ تہٕ تِم کرِ پنُن پان پاک۔ {مقدس کرُن...: ہیب۔ تِمن ہٕندۍ اتھہٕ بٔرِتھ}\n27. تہٕ یێلہِ یِم دۅہ مۄکلیو، سُہ گژھہِ ٲٹھمہِ دۅہہٕ تہٕ {یێلہِ} برونہہ کُن پادٕرۍ تُہٕندِس دَزنہٕ نذرانہ تہٕ تُہٕندِس امن ہٕندِس نذرانہ دِنہٕ یِن۔ تہٕ بہٕ کٔرٕ ژےٚ قبول، خداوند خدا چُھ وَنان۔ {امن...: یا، شکریہ}","1.\\tتمہِ پتہ اوٚن میہ نیبرِم مقدس جایہِ ہندِ دروازہ کِس وتہِ پیٹھ یُس مشرقس کُن وچھان چھُ۔ تہٕ یہِ اوس {اوس} بنٛد۔\n2. اَمہِ پتہٕ ووٚن خداوند مےٚ؛ یہ دروازہ گژھہِ بند کرنہٕ، یہ گژھہِ نہ کھولنہٕ یُن، تہٕ کانہہ تہِ شخص گژھِ نہٕ اَتھ منز اژُن۔ تِکیازِ خداوند یُس اسرٲیلُک خدا چُھ، اَمہِ سٍتـ̡ چُھہ اَتھ سٍتـ̡ دٲخل گومُت، تێمہِ مۄکھٕ گژھہِ یہِ بند کرنہٕ یُن۔\n3. {یہٕ چُھ} شہزادٕ سٕندِ خٲطرٕ؛ شہزادہ، سُہ بِہتھ خداوند سٕندِ برونہہ کُن روٹی کھٮ۪نہٕ خٲطرٕ۔ سُہ گژھہِ {تَمہِ} دروازٕ کِس وتہٕ کِنۍ اژُن، تہٕ نیرِ امی وتہِ نٮ۪بر۔\n4.\\tتێلہِ اوٚن میہ مکانس برونہہ کنہِ شمٲلی دروازہ کِس وتہِ، تہٕ میہ وُچھ، تہٕ وُچھ، خداوند سُند جلال بٔرِتھ خداوند سُند گرٕ بٔرِتھ تہٕ بہٕ پیوٚو بُتھِس پیٹھ۔\n5. تہٕ خداوند ووٚن مےٚ، اِنسان سٕندِس نیٚچوِس، رٔژ پٲٹھۍ، تہٕ پَنٕنِس أچھو سٍتـ̡ وُچھِو، تہٕ بوزُن پنٕنـ̡ کَنَو سٍتـ̡ یُس بہٕ ژے خداوند سٕندِ گرٕ کِس سارِنٕے احکام تہٕ تِمن ہٕندِس سارِنٕے قوانینَس مُتعلِق وَننہٕ آمُت۔ تہٕ گرس منز اژنہٕ وِزِ تہٕ پرٮ۪تھ کُنہِ نیبر نیرنہٕ سٍتـ̡ کٔرِو نشانہٕ۔ {مارک ویل: ہیب۔ پَنُن دِل سیٹ کٔرِو} {مارک ویل: ہیب۔ پَنُن دِل سیٹ کٔرِو}\n6.\\tتہٕ تُہۍ وَنُن باغیَن سٍتـ̡ {حتی} یێلہِ تہِ چُھہ یێلہِ خداوند خدایہ ونان چُھہ ۔ اے اِسرٲیلٕکۍ گرٕ، پَنٕنـ̡ سارِوٕے گٔژھِتھ کٔرِو کافی،\n7. یێمہِ مَنٛز چُھہ ژے میٲنِس مقدس مقامس مَنٛز اَننہٕ آمٕتۍ، یِم دِلَس مَنٛز ختنہٕ تہٕ مازس مَنٛز بےٚ ختنہٕ آمٕتۍ چھِ، میانہِ مُقدس مَنٛز آسنہٕ مۅکھہٕ، یێلہِ تہٕ یێلہِ تہٕ تُہۍ میٲنۍ روٹی، چربی تہٕ خوُن پیش کٔرِو، تہٕ تِمو چُھہ میٲنۍ عہد پھُٹرٲومُت۔ {اجنبی: ہیب۔ أکس اجنبی سٕنٛد بچہٕ}\n8.\\tتہٕ تہٕ چُھہ نہٕ میٲنۍ مقدس چیزن ہٕنز ذمہ داری تھوومٕژ، مگر ژے چُھکھ میانِس مقدس مقامس مَنٛز میانہِ رٲچھ کرن وٲلِس پانس خٲطرٕ مقرر کٔرمٕتۍ۔ {میون چارج: یا، میون وارڈ، یا، آرڈیننس}\n9. یِتھٕ پٲٹھۍ چُھ خداوند خدا فرماوان۔ کانہہ تہِ اجنبی یُس دِلس منز ختنہ کرنہٕ آمُت آسہِ، تہٕ نہ ماز سٍتـ̡ کانہہ تہِ اجنبی سُند یُس بنی اسرٲیلِس مَنٛز آسہِ، میانہِ مقدس مقامس مَنٛز اژُن۔\n10.\\tتہٕ یِم لاوی یِم میانہِ نِش دور گٔیہِ، یێلہِ اسرٲیلِہ گٔیہِ گمراہ گٔیہِ، یِم تِمن ہٕندِس بُتن پَتہٕ گٔیہِ میہ نِش گٔیہِ۔ تِم گژھن پنٕنۍ بدکاری تہِ برداشت کرنہٕ۔\n11.\\tتوتہِ گژھن تِم میانہِ مقدس مقامس مَنٛز وزیر، گرٕ کِس دروازس پیٹھ تہٕ گرٕچ خدمت کرٕن: تِم مارن زٲلِتھ تہٕ لُکن ہٕندِ خٲطرٕ قربانی تہٕ تِمن ہٕنز خدمت کرنہٕ خٲطرٕ۔\n12.\\tکیازِ تِمو کٔر پننین بتن برونہہ کُن تِمن ہٕنز خدمت تہٕ اسرٲیلُک گرٕ کٔرٕکھ بدکاری ہُند شکار۔ تێمہِ کِنۍ چُھس میہ تِمن خلاف پنُن اتھہٕ تُلُمُت، خداوند خدا چُھ ونان تہٕ تِم گژھن پنُن گناہ برداش۔ {وجہ...: ہیب۔ بدکاری ہٕندِس ٹھوکر ہٕندِس رُکاوٹ خٲطرٕ، وغیرہ}\n13. تہٕ تِم گژھن نہٕ میانہِ نزدیک، کُنہِ پادٕرۍ سُند عہدٕ ادا کرنہٕ خٲطرٕ، تہٕ نہ گژھن میانہِ مقدس چیزن نِش یِن، مگر تِم گژھن پنٕنۍ شرم تہٕ تِمن ہٕنزِ بدکاری یُس تِمو کٔرمٕژ آسہِ۔\n14.\\tمگر بہٕ بناوٕ تِم گرٕچ ذمہ دار، اَمہ کِس سارِنٕے خٕدماتن خٲطرٕ، تہٕ یُس سارِنٕے کُنہِ چیزس مَنٛز کرنہٕ یِن۔\n15.\\tمگر پادٕرۍ، لاوی، زادوک سٕندِ نیچو، یِمو میانہِ مقدس مقامچ ذمہ داری تھوو، یِمو میانہِ نِش رٔٹِتھ یِم میانہِ خدمت کرنہٕ خٲطرٕ یِن تہٕ تِم گژھن میانہِ برونہہ کُن کھٔسِتھ چربی تہٕ خوُن پیش کرنہٕ خٲطرٕ، خداوند خدا چُھ فرماوان:\n16.\\tتِم گژھن میانہِ مقدس مقامس مَنٛز اژُن، تہٕ تِم گژھن میانہِ دسترِ نِش یِن، تہٕ تِم گژھن میانہِ ذمہٕ دار۔\n17.\\tتہٕ یِہ گژھہِ سپدُن، {یہِ} ییلہ تِم اندرمِس صحنٕکِس دروازس پیٹھ اژان چھِ، تِمن گژھن کُنہِ کُنہِ پوشہٕ لاگنہٕ یِن۔ تہٕ تِمن پیٹھ گژھِ نہٕ کانہہ اون یِنہٕ، ییٚلہِ زن تِم أنٛدرِم صحن ہٕندِس دروازس تہٕ انٛدر خدمت کران چھِ۔\n18.\\tتِمن ہٕندِس کلس پیٹھ گژھن کُنہِ تِم گژھن نہٕ کُنہِ تہِ چیزس سٍتۍ رٔلِتھ یُس پسینہٕ وِزِ آسہِ۔ {سۭتۍ...: یا، پسینہٕ واجنہِ جاین منٛز: ہیب۔ منز، یا، پسینہٕ سٍتۍ}\n19.\\tتہٕ ییلہ تِم پورٕ دربارس مَنٛز نیران چھِ، تِم کٔرِن پَنٕنہِ پَلَو یِمن مَنٛز تِم خدمت کٔرِتھ، تہٕ یِم لٲگِن باقٕے پَلَو۔ تہٕ تِم گژھن نہٕ لُکن پَنٕنِس پَلَو سٍتـ̡ پاک کَرٕنـ̡ ۔\n20. نہ گژھن تِم کلہٕ کھوٗر کٔرِتھ، تہٕ نہ گژھن پنٕنۍ زُلف زیٖٹھۍ گٔژھن۔ تِم گژھن صرف پننین کلن ہُند انتخاب۔\n21.\\tییلہ تم اندرمس صحنس منز اژان چھہِ تہ نہ گژھہِ کانہہ پادٕرۍ شراب چیوان۔\n22. نہ گژھن تِم پننہِ زنانہِ خٲطرٕ بیواہ تہٕ نہ یُس کُنہِ سٍتـ̡ رٔٹِتھ آسہِ۔ {پُٹ...: ہیب۔ زور دِیوُن} {یُس اوس...: ہیب۔ أکِس پادٕرۍ سٕندِ}\n23. تہٕ تِم ہیچھناوَن میانین لوکن پاک تہٕ ناپاک درمِیان فرق، تہٕ تِمن کرٕن ناپاک تہٕ پاکیزگی درمیان فرق کرن۔\n24. تہٕ تنازعس مَنٛز گژھن تِم فیصلہٕ کَرنہٕ۔ {تہٕ} تِم کرن میانین فیصلن مطٲبق فٲصلہٕ: تہٕ تِم تھاون میانین سارنٕے مجلسن مَنٛز میٲنۍ قونونن تہٕ میٲنۍ قوانین؛ تہٕ تِم کرِ میانہِ سبت مقدس ۔\n25.\\tتہٕ تِم گژھن نہٕ پانس ناپاک کرنہٕ خٲطرٕ کانہہ تہِ مُردٕ شخصس نِش یِنہٕ: مگر مٲلِس سٕندِ خٲطرٕ، یا ماجہِ، یا نیچوِس سٕندِ خٲطرٕ، یا کورِ ہٕندِ خٲطرٕ، بٲے سٕندِ خٲطرٕ، یا بینہِ ہٕندِ خٲطرٕ یُس نہٕ خانٛدار آسہِ، تِم گژھن پانس ناپاک کٔرِتھ۔\n26.\\tتہٕ یێلہِ سُہ پاک سپدِ، تِم گٔژھن أمِس سَتھ دۅہہٕ۔\n27. تہٕ ییمہِ دۅہہٕ سُہ مقدس خانس مَنٛز گژھِ، أنٛدرِمِس صحنس مَنٛز خدمت کرنہٕ خٲطرٕ، سُہ کرِ پَنُن گۅناہ پیش کرنہٕ، خداوند خدا چُھ فرماوان۔\n28.\\tتہٕ یہ گژھہِ تِمن ہُند وراثت: بہٕ چُھس تِہُند وراثت: تہٕ تُہۍ دِیہ نہٕ تِمن اسرٲیلِس مَنٛز کانہہ قبضہٕ۔\n29.\\tتِم گژھن ماز نذرانہ تہٕ گۅناہ ہٕنز نذرانہ تہٕ ناجائز قربانی کھٮ۪ن۔ تہٕ اسرٲیلِس مَنٛز گژھہِ پرٮ۪تھ کانہہ چیز تِمن ہُند آسان۔ {وقف کرنہٕ: یا، وقف کرنہٕ}\n30. تہٕ سارِنٕے چیزن ہُند گۅڈنیُک پھل تہٕ سارِنٕے سارِنٕے سٕندِس نذراتس سٍتـ̡ گۅڈنِچ قربانی تہٕ سارِنٕے سٍتـ̡ دِیُن پادٕرِس سٍتـ̡ دِیُن، یُتھ سُہ کرِ تُہٕندِس گَرَس مَنٛز برکت دِنہٕ۔ {تہٕ گۄڈنیُک: یا، تہٕ سردار}\n31.\\tپادٕرۍ گژھِ نہٕ کُنہِ تہِ چیزس کھٮ۪نہٕ یُس پانس سٍتـ̡ موٗدمُت آسہِ، یا پھٹمُت آسہِ، چاہے سُہ جاناوار آسہِ یا جانور۔","1. امہِ علاوٕ، ییلہ تم زمین وراثتس خٲطرٕ قرعہ اندازی کٔرِو، تہٕ زمینُک اکھ مقدس حصہٕ گژھہِ خداوند سٕندِ خٲطرٕ قربانی پیش کرنہٕ: زیچھر آسہِ پانژٕ تہٕ وُہ ساس تہٕ کھجر آسہِ داہ ساس۔ یہ {گژھہِ} اندۍ پکھۍ تمام سرحدن منز مقدس آسُن۔ {ییلہ...: ہیب۔ ییلہ تم زمینس وسناوان چھہِ} {اکھ مقدس...: ہیب۔ پاکیزگی}\n2.\\tاتھ منز گژھہِ پانژھ ہتھ (زیچھرس منز) پانژھ ہتھ (زیچھرس منز) تہ پانژھ ہتھ (چوڑۍ منز) آسن۔ تہٕ مضافاتی علاقن خٲطرٕ پنژاہ کیوبٹ اندۍ اند۔ {مضافات: یا، خالی مقامات}\n3. تہٕ اَمہ پیمانہٕ سٍتـ̡ گژھہِ ژیہ پانژٕ وُہ ساس زیچھر تہٕ داہ ساس کھجر۔ تہٕ اَتھ مَنٛز آسہِ مقدس مقام۔\n4. زمینُک مقدس حصہ آسہِ پادٕرین ہٕندِ خٲطرٕ، یُس خداوند سٕنزِ خدمت کرنہٕ خٲطرٕ یِنہٕ یِن، تہٕ یِہ آسہِ تِہندِ گرن ہٕنز جاے تہٕ مقدس جاۓ آسہِ۔\n5.\\tپانژھ وُہ ساس زیچھر تہٕ داہ ساس کھجر، لیوی یُس گرٕ کین وزیرن تہِ آسہِ پانس خٲطرٕ، وُہن خانن ہُند قبضہ۔\n6. تہٕ تُہۍ کٔرِو پانٛژ ساس کھُلہٕ تہٕ پانژھ ساس زیوٹھ شہرُک قبضہ مُقدس، یُس پورٕ اسرٲیلِس خٲطرٕ آسہِ۔\n7. تہٕ اَکھ {حصہ} آسہِ شہزادٕ سٕندِ خٲطرٕ، اَکہِ طرفہٕ تہٕ دوٚیمہِ طرفہٕ مُقدس {حصہ} کِس نذرٕ کرنہٕ برونہہ، تہٕ شہرٕ کِس قبضس برونہہ، مغرب طرفہٕ مغرب کُن تہٕ مشرقس کُن مشرقس کُن۔  تہٕ زیچھر آسہِ مغرب سرحد پیٹھہ مشرقی سرحدس تام اکس حصس خلاف۔\n8.\\tزمینس مَنٛز آسہِ تٔمۍ سُند قبضہ اسرٲیلِس مَنٛز۔ تہٕ میٲنۍ شہزادٕ گژھن نہٕ میانین لوکن پیٹھ ظُلم کرنہٕ۔ تہٕ باقٕے زمین دِن تِم پننین قبیلن مطٲبق اسرٲیلِس گرس دِنہٕ۔\n9. یِتھٕ پٲٹھۍ چُھ خداوند خدا فرماوان۔ اے اسرٲیلٕکۍ شہزادو، تشددٕ تہٕ غنیمت ہٹٲوِو، تہٕ فیصلہٕ تہٕ انصاف کٔرِو میانین لوکن نِش نِش پنٕنۍ سزا نِن، خداوند خدا چُھ ونان ۔ {exactions: Heb. اخراج }\n10.\\tتۅہہِ گژھہِ عادل توازن تہٕ عادل عفہ تہٕ اکھ منصفانہ غسل تہِ۔\n11.\\tایفا تہٕ غسل گژھہِ اکۍ سے پیمانس پیٹھ آسُن، یُتھ زِ باتھ گژھہِ ہومرُک دٔہِم حصہ تہٕ ایفا ہومرُک دٔہِم حصہٕ آسُن: امیک پیمائش گژھہِ ہومرس پتہٕ آسُن۔\n12.\\tتہٕ شیکل آسہِ وُہ شیکل، پانژھ تہٕ وُہ شیکل، پندہ شیکل، تُہند مانہ۔\n13. یہِ {چُھ} سُہ قربانی یُس تُہۍ پیش کرِو۔ کٕنکہِ ہومرُک شیٚیِم حصہٕ تہٕ تُہۍ دِیُو شیٚیِم حِصہٕ أکِس ہومر سٕندِس ایفاہُک شیٚیِم حصہٕ:\n14.\\tتیٖل کِس حکمس متعلق، تیلُک غسل خانہٕ، {یُس} دَہن باتھَن ہُند ہومر چُھ۔ دہن باتھن خٲطرٕ {are} اکھ ہومر:\n15.\\tتہٕ اِسرٲیلٕچ چربی چراگاہٕ منزٕ زٕ ہتھ منزٕ اکھ کٹہٕ کُن۔ خداوند خدا چُھ ونان زِ مازٕچ نذرانہ خٲطرٕ، تہٕ دزنہٕ خٲطرٕ، تہٕ امن ہٕندِ خٲطرٕ صلح کرنہٕ خٲطرٕ۔ {لیمب: یا، بچہ} {امن...: یا، شکریہ}\n16.\\tزمینٕکۍ سارِنٕے لُکھ دِن اِسرٲیلِس مَنٛز شہزادٕ سٕندِ خٲطرٕ یہِ نذرانہٕ۔ {شال...: ہیب۔ {for: or, with}\n17. تہٕ شہزادٕ سُند حصہٕ آسہِ زٲلِتھ نذرانہٕ تہٕ مازٕچ نذرانہ تہٕ شرابٕچ نذرانہ دِنہٕ، تہٕ نوِ زونن مَنٛز، تہٕ سبت دۅہہٕ، اسرٲیلِک گرٕ کِس سارِنٕے تقریبن مَنٛز، سُہ کرِ گۅنہٕ نذرانہٕ، تہٕ مازٕچ نذرانہ تہٕ دزنہٕ نذرانہ تہٕ امن ہٕنز نذرانہ تیار کرٕنۍ۔  اسرٲیلِس کِس گرس خٲطرٕ صلح کرنہٕ خٲطرٕ۔ {امن...: یا، شکریہ}\n18.\\tیِتھٕ پٲٹھۍ چُھ خداوند خدایہ فرماوان۔ گۅڈنِکِس {ریت} منز، ریتہٕ کِس گۄڈنِکِس دۅہس منز، تُہۍ کٔرِو اکھ جوان دانٛد بے داغ روٚس، تہٕ مقدس مقامس صاف کرُن:\n19.\\tتہٕ پادٕرۍ نِیہِ گۅنہٕ ہٕندِس نذرانہ سٍتـ̡ خوُن، تہٕ گرٕ کِس کھورِ پیٹھ، تہٕ قربان گاہ ہٕندِس ژۄن کونن پیٹھ، تہٕ اندرمِس صحنہٕ کِس دروازس پیٹھ۔\n20. تہٕ یِتھٕ پٲٹھۍ کٔرِو تُہۍ ریتُک سٔتِم دۅہہٕ یُس غلطی کرِ، تہٕ یُس آسان آسہِ، تہٕ یِتھٕ پٲٹھۍ کٔرِو تُہۍ گرٕ صلح کٔرِتھ۔\n21.\\tگۅڈنِکِس ریتس مَنٛز، ژۄدٲہمہِ دۅہہٕ چُھہ تہٕ سَتن دۅہن ہُند عید میلہِ۔ خمیر روٚس روٹی یِن کھٮ۪نہٕ۔\n22. تہٕ اَمہِ دۅہہٕ کرِ شہزادٕ پانس تہٕ سارنٕے زمینہٕ کین لوکن ہٕندِ خٲطرٕ گۅناہ ہٕندِ قربانی خٲطرٕ اکھ بیل تیار۔\n23. تہٕ سَتھ دۅہہٕ چُھ سُہ خدایہِ سٕندِ خٲطرٕ زٲلِتھ نذرانہ تیار کَرُن، سَتھ بیل تہٕ سَتھ دۅہہٕ روزِ سَتھ دۅہہٕ سَتھ دۅہہٕ دِنہٕ یِنہٕ خٲطرٕ۔ تہٕ ژھاوُن ہُند اکھ شُر روزانہٕ {خٲطرٕ} گۅنہٕ ہُند نذرانہ دِنہٕ۔\n24.\\tتہٕ سُہ کرِ بیلہٕ خٲطرٕ ایفاہُک ماز نذرانہ تہٕ مینڈٕ خٲطرٕ ایفاہ تہٕ ایفہ خٲطرٕ اکھ ہِن تیلُک نذرانہ تیار۔\n25.\\tسٔتِمہِ ریتس مَنٛز، ریتہٕ کِس پنٛدٲہِمِس دۅہہٕ سٍتـ̡ سُہ سَتَن دۅہن ہٕندِس عیدس مَنٛز یِتھُے کٔرِتھ، گۅنہٕ نذرانہٕ مُطٲبق، دزنہٕ مُطٲبق، تہٕ مازٕچ نذرانہٕ مُطٲبق تہٕ تیٖل مُطٲبق۔","1. یِتھٕ پٲٹھۍ چُھ خداوند خدا فرماوان۔ أنٛدرِم صحنُک دروازٕ یُس مشرقس کُن نظر چُھ تھاوان سُہ گژھِ شیٚن کامہِ دۄہن بند کرنہٕ۔ مگر سبت دوہ ییہ یہ کھولنہٕ، تہٕ نوِ زونہِ ہندِ دۅہہ ییہ یہ کھولنہٕ۔\n2. تہٕ شہزادٕ گژھہِ نیبر کِس دروازٕ کِس دٲرِ کِنۍ اژُن، تہٕ دروازٕ کِس چوکہِ پیٹھ کھڑا روزُن، تہٕ پادٕرۍ کرِ پنُن زٲلِتھ نذرانہ تہٕ امن ہٕنز نذرانہ تیار، تہٕ سُہ کرِ دروازٕ کِس دروازس پیٹھ عبادت کرنہٕ۔ مگر دروازہ گژھہِ نہ شامس تام بند کرنہ۔\n3. یِتھے پٲٹھـ̡ پٲٹھـ̡ گژھن زمینہٕ کِس دروازس پیٹھ خداوند سٕندِ برونہہ کُن سبت تہٕ نوِ زونہِ مَنٛز عبادت کرنہٕ۔\n4. تہٕ سُہ زالُن قربان یُس شہزادٕ سبت دۅہہٕ خداوند سٕندِ خٲطرٕ پیش کرِ، سُہ آسہِ شیہ کٹہٕ بچہٕ بغٲر داغ تہٕ اکھ مینڈٕ بےٚ داغ۔\n5.\\tتہٕ مازُک نذرانہ گژھہِ مینڈٕ خٲطرٕ ایفا تہٕ ماز نذرانہ یُس سُہ دِنس لایق آسہِ، تہٕ ایفاہس خٲطرٕ اکھ ہِن تیل۔ {یتھ کٔنۍ سُہ...: ہیب۔ تٔمۍ سٕنٛدِ اتھُک تحفہٕ}\n6.\\tتہٕ نوِ زوٗنہِ ہٕندِس دۅہہَس مَنٛز آسہِ اَکھ بچہٕ دانٛد تہٕ شیٚہ دانٛد تہٕ اکھ کۅکرٕ تہٕ اکھ کۅکر۔\n7. تہٕ سُہ کرِ ماز ہُند نذرانہ تیار، دانٛد خٲطرٕ اکھ ایفاہ، تہٕ کۅکرِ ہٕندِ خٲطرٕ تہٕ کۅکرِ ہٕندِ خٲطرٕ تہٕ اکھ ہِن تیلُک اکھ ہِن، تہٕ اکھ ہِن تیلُک اکھ ہِن۔\n8.\\tتہٕ ییلہ شہزادہ اژِ، سُہ گژھہِ تمہِ دروازہ کِس وتہِ کِنۍ اژُن، تہٕ سُہ گژھہِ تمہِ وتہِ کِنۍ نیرُن۔\n9. مگر یێلہِ یێلہِ ملکٕکۍ لُکھ مقدس تہوارن مَنٛز خداوند سٕندِ برونہہ کُن یِن، یُس شُمٲلی دروازٕ کِس وتہِ سٍتـ̡ عبادت کرنہٕ خٲطرٕ اژان چُھ، سُہ گژھہِ جنوبی دروازٕ کِس وتہِ سٍتـ̡ نیرُن۔ تہٕ یُس جنوبی دروازہ کِنۍ اژان چُھہ سُہ گژھہِ شمٲلی دروازہ کِنۍ نیرُن: سُہ گژھِ نہٕ تمہِ دروازہ کِس وتہِ سٍتۍ واپس، بلکہ گژھہِ اتھ خلاف نیرُن۔\n10.\\tتہٕ یِمن منزٕ شہزادٕ ییلہ تم اژان چھِ، سُہ گژھہِ اژُن۔ تہٕ ییلہ تم نیرِ، نیرن نیران۔\n11. تہٕ دعوتن تہٕ رسمن مَنٛز گژھِ ماز ہُند نذرانہ أکِس داندس خٲطرٕ ایفاہ، تہٕ کۅکرِ ہٕندِ خٲطرٕ یُتھ سُہ دِنس قٲبل آسہِ، تہٕ ایفاہَس خٲطرٕ تیلُک ہِن آسہِ۔\n12.\\tیێلہِ ییلہ شہزادہ رضاکارانہٕ طور خداوند سٕندِ خٲطرٕ رضاکارانہٕ طور دزنہٕ نذرانہ یا امن ہٕنز پیش کش تیار کرِ، تیلہِ گژھہِ أمِس سُہ دروازٕ یُس مشرقس کُن نظر تھاوان چُھ، تہٕ سُہ کرِ پنٕنۍ دزنہٕ نذرانہ تہٕ امن ہٕنز نذرانہ تیار، یِتھ کٔنۍ تٔمۍ سبت دۅہہٕ کٔرِتھ، تیلہِ گژھہِ سُہ نیرُن۔ تہٕ تٔمۍ سٕندِ نیرنہٕ پتہٕ گژھِ دروازٕ بند۔\n13.\\tژے روزِ روزِ خداوند سٕندِ خٲطرٕ دزنہٕ آمُت نذرانہ تیار کٔرِتھ یُس گۅڈنچہ ؤری ہٕندِس کۅکرِ ہٕندِس کۅکرِ ہٕندِس کُنہِ {منز...: ہیب۔ تٔمۍ سٕنٛدِ ؤرۍ یُک اکھ نیٚچُو} {پرٮ۪تھ ...: ہیب۔ صُبح بذریعہ صُبح}\n14.\\tتہٕ تُہۍ کٔرِو پرٮ۪تھ صُبحَس اَمہِ خٲطرٕ ماز ہُند نذرانہ تیار، یُس ایفاہُک شیٚیِم حصہٕ تہٕ تیٖلُک تریم حصہٕ چُھ، یُس بارٕ آٹہٕ سٍتـ̡ رٔٹِتھ رٔٹِتھ دِنہٕ یِوان۔ اکھ ماز پیش یُس خداوند سٕندِ خٲطرٕ دٲیمی حکم نامہٕ سٍتـ̡ مُسلسل چُھ۔\n15.\\tیِتھٕ پٲٹھـ̡ کٔرِن تِم کۅکرِ تہٕ مازٕچ نذرانہ تہٕ تیٖل تیار کٔرِتھ پرٮ۪تھ صُبحَس لگاتار زالنہٕ یِنہٕ خٲطرٕ۔\n16. یِتھٕ پٲٹھۍ چُھ خداوند خدا فرماوان۔ اگر شہزادٕ پننِس کُنہِ نیچوِس تحفہٕ دِیہ، تیٚلہِ آسہِ تٔمۍ سٕندِس نیچوِس ہُند وراثت۔ یہٕ آسہٕ وراثتس ذریعہٕ تہند قبضہٕ۔\n17.\\tمگر اگر سُہ پننِس خادمَس وَرثُک تحفہٕ دِیہِ، تیلہِ گژھہِ سُہ أمِس آزادی ہٕندِس ؤریس تام دِنہٕ۔ امہ پتہ گژھہِ یہ شہزادس واپس: مگر تٔمۍ سُند وراثت آسہِ تمن ہٕندِ خٲطرٕ تٔمۍ سٕندٮ۪ن نیچوین ہُند۔\n18.\\tامہِ علاوٕ گژھِ نہٕ شہزادٕ ظلمہٕ سٍتۍ عوامٕچ وراثت نِش تِمن ہٕندِس قبضس نِش کڑنہٕ خٲطرٕ۔ {مگر} سُہ دِیہ پننین نیچوین پننہِ ملکیت منزٕ وراثت: یُتھ میٲنۍ لُکھ گژھن نہ پرٮ۪تھ کانہہ انسان پننہِ ملکیت نِش منتشر کرنہٕ۔\n19.\\tییلہ سہ میہ دروازہ کِس اندۍ پکھۍ پادٕرین ہٕندِس مقدس کمرس منز، یُس شمالس کُن وچھان اوس، تہٕ وچھ دۅشوٕنۍ طرفن مغرب کُن اکھ جاے۔\n20.\\tاَمہِ پتہٕ ووٚن تٔمۍ مےٚ زِ یہِ چھُ سُہ جاے ییتہِ پادٕرۍ گۅنہٕ نِش نذرانہٕ تہٕ گۅنہٕ ہُند نذرانہ دِنہٕ یِن، یتہِ تِم مازٕچ نذرانہ بناوٕنۍ۔ زِ تِم گژھن نہٕ پوٗرٕ دربارس مَنٛز، لوٗکن پاک کرنہٕ خٲطرٕ۔\n21.\\tتمہ پتہ اوٚن میہ پورٕ دربارس منز، تہٕ کوٚرُن میہ صحن ہٕندِس ژۅشونی کونو کِنۍ نیران۔ تہٕ وُچھ، عدالتہٕ کس ہر کونس منٛز اوس اکھ عدالت۔ {پریتھ منز...: ہیب۔ عدالتہٕ کس أکس کونس منٛز اکھ عدالت، تہٕ عدالت کس أکس کونس منٛز اکھ عدالت}\n22.\\tدربار کِس ژۅشونی کونس منز ٲسۍ ژتٲجی {کیوبٹ} زیوٹھ تہٕ ترہ کھُلہِ ہٕندۍ دربار رٔلِتھ: یِم ژۅشونی کُن ٲسۍ اکۍ سے پیمانس پیٹھ۔ {شٲمل: یا، چمنیہٕ سۭتۍ بناونہٕ} {کونر ٲسۍ...: ہیب۔ کونر، وغیرہ}\n23.\\tتہٕ {تِمن اندۍ ٲس اکھ قطار {عمارت}، اندۍ ژور، تہٕ {یہ} ٲس اندۍ قطارن تلہ کنہِ ابلنہٕ واجنہِ جایہِ سٍتۍ بناونہٕ آمٕژ۔\n24.\\tاَمہِ پتہٕ ووٚن تٔمۍ مے زِ یِم چھِ تِمن ہٕنزِ جایہِ یِم دِوان چھِ، ییتہِ گرٕکۍ وزیرن لُکن ہٕنزِ قربانی دِنہٕ یِن۔","1.\\tامہ پتہ اوٚن میہ بییہ مکانہ کس دروازس پیٹھ۔ تہٕ وُچھ، مکانہٕ کس دروازس تل دراو آب مشرقس کُن: تکیازِ مکانک برونٛہہ کُن اوس مشرقس کُن، تہٕ آب آو مکانہٕ کس دچھنہٕ طرفہٕ بونہٕ پیٹھ، قربان گاہ کس جنوبس کُن۔\n2.\\tتمہ پتہ نیو میہ دروازہ نش شمالس کُن تہ وتہِ کُن یُس مشرقس کُن وچھان اوس۔ تہٕ وچھ دچھنہِ طرفہٕ آب ژوٚلان۔\n3.\\tییلہ یُس لٲنہِ اتھس منز ٲس، سہ اوس مشرقس کُن نیران، تمٔۍ پیوو اکھ ساس کیوبِٹ، تہٕ سُہ أنۍ میہ آبس منز۔ آب اوس گوڑن تام۔ {آب ٲس...: ہیب۔ گۄڑن ہُنٛد آب}\n4.\\tبییہِ ہیوٚت ساس تہ أنِن میہ آبس منز۔ آب اوس کۅٹھن تام۔ بییہِ کٔر تٔمۍ ساس تہٕ أنِن میہ اَتھ کُن۔ آب اوس کمرس تام۔\n5. امہ پتہ کٔر تمۍ اکھ ساس۔ {تہٕ یہ} اوس اکھ دریاو یُس بہٕ ہیوٚک نہٕ اپارِ نیرِتھ: تکیازِ آب اوس تھوٚد، آبس منز ژھارنہٕ خٲطرٕ، اکھ دریاو یُس نہٕ اپارِ نیرِتھ ہیوٚک نہٕ۔ {آبس کُن...: ہیب۔ ژھانٛٹھ وایِنُک آب}\n6.\\tتہٕ تٔمۍ ووٚن میہ زِ اِنسان سٕندِس فرزندس کیا ژے وُچھمُت؟ تمہ پتہ اوٚن میہ تہ دِژُن میہ دریاو کِس بٹھس پیٹھ واپس۔\n7.\\tوۅنۍ ییلہ بہٕ واپس، وچھ دریاو کِس بٹھس پیٹھ ٲسۍ اکہ طرفہ تہ دوٚیمہِ طرفہ واریاہ کُلۍ آسان۔ {بینک: ہیب۔ لپ}\n8.\\tاَمہ پتہٕ ووٚن میہ زِ یِم آب چھِ مشرقس کُن نیران، تہٕ ریگستانس مَنٛز وسان تہٕ سمندرس مَنٛز گژان: {یُس وجود} سمندرس مَنٛز اننہٕ آمُت چھُ، آب گژھہِ شفا بخشنہٕ۔ {صحرا: یا، سادہ}\n9. تہٕ یہِ سپدِ، {یہ} یُس زِندٕ روزان چُھ، یُس کُنہِ تہِ دریاو یِن، سُہ گژھہِ زندٕ: تہٕ گاڈَن ہُند واریاہ بٔڑ تعداد آسہِ، کیازِ یِم آب یِن تتہِ یِنہٕ: تِم گژھن شفا دِنہٕ۔ تہٕ پرٮ۪تھ کانہہ چیز روزِ ییتہِ دریاو یِیہ۔ {دریاو: ہیب۔ زٕ دریاو}\n10. تہٕ یہٕ گژھہِ سپدُن، {یہ} گاڈٕ رٔٹِن اَتھ پیٹھ اینگیڈی پیٹھٕ اینگلیم تام تہِ۔ تم گژھن جال پھہلاونہٕ خٲطرٕ اکھ {جاے}؛ تِہٕنزِ گاڈٕ آسہِ پننہ قٕسمٕکۍ مطٲبق، عظیم سمندرٕچ گاڈٕ ہٕندۍ پٲٹھۍ، واریہن کھوتہٕ زیادٕ۔\n11.\\tمگر یِمن ہٕندِس گۅپھ تہٕ یِمن ہٕندِس مٔرِس گٔژھِتھ گژھِ نہٕ شفا سپدِ۔ تِم یِن نوٗنس دِنہٕ۔ {گژھِ نہٕ...: یا، تہٕ سُہ یُس نہٕ شفا گژھِ}\n12.\\tتہٕ دریاو کِس بٹھس پیٹھ، اَتھ اندٕ تہٕ اَتھ طرفہٕ گژھن ماز خٲطرٕ سارِنٕے کُلۍ وۄپداونہٕ، یِمن ہٕندِ پنہٕ وُنہٕ تہٕ یِمن ہُند پھل گژھہِ نہٕ کھٮ۪نہٕ، تہٕ یِمن ہُند پھل گژھہِ نہٕ تٔمۍ سٕندِ ریتہٕ مُطٲبق نوو مٮ۪وٕ نیران، تکیازِ تِہُند آب چُھ یِمن ہُند آب یِم مقدس مقامہٕ منزٕ نیران چھِ، تہٕ اَمہ ہُند پھل گژھہِ مازٕ خٲطرٕ۔  تہٕ دواہٕ خٲطرٕ امیک پنہٕ۔ {گژھ بڑان: ہیب۔ {نٔو: یا، پرنسپل} {دواہ خٲطرٕ: یا، زخمن تہٕ زخمن خٲطرٕ}\n13. خداوند خدا چُھ یِتھٕ پٲٹھۍ وَنان۔ یہِ آسہِ سرحد یَتھ مَنٛز اسرٲیلٕکؠن بہن قبیلن ہٕندِ مُطٲبِق یِیہِ زمینُک وَرث حٲصِل کرنہٕ: یوسفَس آسہِ زٕ حِصہٕ۔\n14.\\tتہٕ یێمہِ سٍتـ̡ میہ تُلِتھ تہٕ یێمہِ سٍتـ̡ یێلہِ سٍتـ̡ تُلِتھ تہٕ یێمہِ سٍتـ̡ یێلہِ چُھہ یێمہِ سٍتـ {تُلتھ...: یا، قسم}\n15.\\tتہٕ یہِ آسہِ زمینُک سرحد شمالس کُن، عظیم سمندرٕ پیٹھ، ہیتھلون کِس وتہِ، یِتھٕ پٲٹھۍ انسان زادس کُن گژھان چھِ۔\n16. حمت، بیروتھا، سبریم، یُس دمشق کِس سرحدس تہٕ حمتھ کِس سرحدس درمیان چھُ۔ Hazarhatticon، یُس {چُھ} ہوران کِس ساحلس نِش۔ {Hazarhatticon: یا، درمیانی گام}\n17. تہٕ سمندرُک سرحد آسہِ حزرنان، دمشقُک سرحد تہٕ شمالس کُن تہٕ حمتھ کُن سرحد۔ تہٕ {یہ} چُھ شمالس طرف۔\n18.\\tتہٕ مشرق کُن پییہِ حوران تہٕ دمشقس پیٹھ، تہٕ جلعاد پیٹھ، تہٕ اردن کِس سرزمینہٕ پیٹھٕ مشرقی سمندرس تام۔ تہٕ {یہ} چُھ مشرقس طرف۔ {پیٹھہٕ (ہوران، دمشق، جلعاد، زمین): ہیب۔ درمِیان پیٹھ}\n19.\\tتہٕ جنوبُک طرف، تمر پیٹھٕ کٔرِتھ دٔریاوٕ کِس آبس تام۔ تہٕ {یہ} چُھ جنوبُک طرفہٕ۔ {جھگڑا: یا، میریبہ} {دریا: یا، وادی} {کیا جنوب طرفہٕ چُھ: یا، کیا جنوب طرفہٕ چُھ تیمان کُن}\n20.\\tمغرب طرفہ تہِ آسہِ سرحد پیٹھہ بٔڈ سمندر، یوٚت تام اکھ انسان حمتس خلاف یِن۔ یہِ چھُ مغرِب طرفہٕ۔\n21. یِتھٕ کٔنۍ کٔرِو یہِ زمین اسرٲیلِکۍ قبیلہٕ مُطٲبِق پانس سٍتـ̡ تقسیٖم۔\n22. تہٕ یێلہِ گژھہِ یہِ پانس تہٕ پانس مَنٛز روزن وٲلِس اجنبی سٍتـ̡ وَرثہٕ خٲطرٕ قرعہٕ سٍتـ̡ تقسیٖم کرنہٕ، یِم تہٕ تِم گژھن تۅہہِ سٍتـ̡ یِتھٕ پٲٹھـ̡ اِسرٲیلـ̡ کِس مُلکَس مَنٛز زامٕتـ̡ ۔ تِمن میلہِ اسرٲیلِس قبیلن مَنٛز توے سٍتـ̡ وَرث۔\n23. تہٕ یہِ سپدِ، کُنہِ قبیلس مَنٛز اجنبی روزان چُھ، تتہِ دِیِو تٔمِس سُند وٲرث، خداوند خدا چُھ فرماوان۔","1.\\tوۅنۍ چھہِ یم {چھہِ} قبیلن ہندۍ ناو۔ شمالہٕ سرٕ پیٹھہٕ ہیتھلون کس وتہٕ کس ساحلس تام، یتھ کٔنۍ اکھ ہمتھ، ہزارنان، شمالس منٛز دمشقک سرحدس تام، حمتھ کس ساحلس تام چُھ گژھان۔ تکیازِ یم چھہِ تسند طرف، مشرق {تہ} مغرب؛ اکھ {حصہٕ for} Dan. {a حصہٕ: Heb. اکھ حصہ}\n2. تہٕ ڈین سٕندِس سرحدس سٍتۍ، مشرِق طرفہٕ مغربس تام، اکھ {حصہٕ} آشر۔\n3. تہٕ آشر کِس سرحدس پیٹھ، مشرق طرفہٕ مغرب طرفہٕ تہِ، اکھ {حصہٕ} نفتالی۔\n4.\\tنفتالی کِس سرحدس سٍتـ̡ مشرق پیٹھہٕ مغرب طرفہٕ چُھہ منسیہس خٲطرٕ اکھ {حصہٕ}۔\n5.\\tتہٕ منسیٰ کِس سرحدس نِش مشرِق طرفہٕ مغرب طرفہٕ اَفرائیم سٕندِ خٲطرٕ اکھ {حصہٕ}۔\n6. تہٕ افرائیم کِس سرحدس پیٹھ، مشرق طرفہٕ مغرب طرفہٕ تہِ، روبن سٕندِ خٲطرٕ اکھ {حصہٕ}۔\n7. تہٕ روبن سٕندِس سرحدس سٍتـ̡ مشرقس پیٹھٕ مغرب طرفہٕ یہوداہ خٲطرٕ اکھ {حصہٕ}۔\n8. تہٕ یہوداہ کِس سرحدس سٍتـ̡ مشرِق طرفہٕ مغرب طرفہٕ گژھہِ سُہ قربانی یُس ژیہ پانژھ تہٕ وُہ ساس کھجر، تہٕ زیچھر یُس مشرِق طرفہٕ مغرب کُن آسہِ۔\n9.\\tیُس قربانی یُس تۅہہ خداوند سٕندِ خٲطرٕ پیش کرُن آسہِ سُہ آسہِ پانژھ تہٕ وُہ ساس زیچھر تہٕ داہ ساس کھجر۔\n10. تہٕ تِمن ہٕندِ خٲطرٕ، {حتیٰ کہ} پادٕرین ہٕندِ خٲطرٕ، گژھہِ {یہ} مقدس قربان۔ شمالس کُن پانژھ تہٕ وُہ ساس تہٕ مغربس کُن داہ ساس کھجر، تہٕ مشرقس کُن داہ ساس کھجر، تہٕ جنوبس کُن پانژھ تہٕ وُہ ساس زیچھر۔\n11.\\t{یہِ گژھہِ پادٕرین ہٕندِ خٲطرٕ یُس زادوک سٕندِس نیچوِس مُقدس آسہِ۔ یِمو چُھ میٲنۍ ذمہ داری تھومٕژ، یُس نہٕ گٔیہٕ نہٕ گٔمٕژ ییلہٕ بنی اسرٲیلِچ گٔیہ، یِتھ کٔنۍ لاوی گٔیہٕ گمراہ گٔیہٕ۔ {یہ...: یا، مقدس حصہ گژھہِ پادٕرین ہٕندِ خٲطرٕ} {چارج: یا، وارڈ، یا، آرڈیننس}\n12. تہٕ یُس زمینہٕ پیش کرنہٕ ییہِ تِمن ہٕندِ خٲطرٕ یُس لاوِین ہٕندِس سرحدس سٍتـ̡ مقدس چیز آسہِ۔\n13.\\tتہٕ پادٕرین ہٕندِس اندس پیٹھ آسہِ لاوِین پانژھ وُہ ساس زیچھر تہٕ داہ ساس کھجر۔\n14.\\tتہٕ تِم گژھن نہٕ اتھ کٕنُن، نہ بدلہٕ، تہٕ نہ کرِ زمینہٕ کِس گۄڈنِکِس پھلَس کُن، کیازِکہِ یہِ چُھ خداوند سٕندِ خٲطرٕ پاک۔\n15. تہٕ پانژٕ ساس یُس پانژَن تہٕ وُہن ساسن ہٕندِس مقابلس مَنٛز باقٕے روزان چُھ، سُہ آسہِ شہر، روزن خٲطرٕ تہٕ مضافاتی علاقن خٲطرٕ اکھ ناپاک جاے: تہٕ شہر آسہِ اَتھ مَنٛز درمِیان ۔\n16.\\tتہٕ یِم آسن اَمہ کِس پیمانہٕ۔ شمالس طرفہٕ ژور ساس پانژھ ہتھ تہٕ جنوبس طرفہٕ ژور ساس پانژھ ہتھ تہٕ مشرقس طرفہٕ ژور ساس پانژھ ہتھ تہٕ مغرب طرفہٕ ژور ساس پانژھ ہتھ۔\n17. تہٕ شہرک مضافاتی علاقہٕ گژھن شمالس کُن زٕ ہتھ پنژاہ تہٕ جنوبس طرفہٕ زٕ ہتھ پنژاہ تہٕ مشرقس طرفہٕ زٕ ہتھ پنژاہ تہٕ مغربس کُن زٕ ہتھ پنژاہ۔\n18.\\tتہٕ مقدس {حصہٕ} کِس نذرس سٍتـ̡ زیچھرس سٍتـ̡ گژھہِ دَہ ساس مشرقس کُن تہٕ دَہ ساس مغربس کُنـ̡ تہٕ یێلہِ گژھہِ مقدس {حصہ} سٕندِس نذرس سٍتـ̡ ختم سپدُن۔ تہٕ امیک اضافہٕ گژھہٕ تمن لوکن خٲطرٕ کھیٛنہٕ خٲطرٕ یُس شہرچ خدمت کران چِھ۔\n19. تہٕ یُس شہرٕچ خدمت کران چُھ، تِم گژھن اِسرٲیلِس سٍتـ̡ سارِنٕے قبیلن مَنٛز اَمِچ خدمت کَرٕنـ̡۔\n20.\\tسارِنٕے نذرٕ گژھن پانژٕ وُہ ساس تہٕ پانژٕ ساس تہٕ وُہ ساس تہٕ تُہۍ کرِ شہرس ہٕندِس قبضس سٍتـ̡ ژور ساس مقدس قربانی پیش کرنہٕ۔\n21.\\tتہٕ باقیات آسہِ شہزادٕ سٕندِ خٲطرٕ، اَکہِ طرفہٕ تہٕ دوٚیمہِ طرفہٕ مقدس قربانیُک تہٕ شہرٕچ قبضہٕ کِس قبضس منز، مشرقی سرحدس کُن پانژٕ تہٕ وُہن ساس ساس خٕلاف، تہٕ مغرب کُن پانژَن تہٕ وُہن ساس ساس خٕلاف، شہزادٕ سٕندِ خٲطرٕ حصن خٕلاف:  تہٕ یہِ آسہِ مقدس نذرانہٕ؛ تہٕ گرُک مقدس مقام آسہِ اَتھ منز۔\n22.\\tامہِ علاوہ گژھہِ لاوی سٕندِ قبضہٕ سٍتـ̡ تہٕ شہرٕ کِس قبضس منز، یُس یہوداہ کِس سرحدس تہٕ بنیامین سٕندِس سرحدس درمِیان شہزادٕ سٕندِ خٲطرٕ آسہِ۔\n23. باقٕے قبیلن ہُند تعلق چُھ، مشرِق طرفہٕ مغربس تام، بنیامین {گژھہِ اَکھ {حصہ}۔ {اکھ حصہ: ہیب۔ اکھ حصہ}\n24.\\tتہٕ بنیامین سٕندِس سرحدس سٍتـ̡ مشرقہٕ پیٹھہٕ مغرب کُن شمعون {حصہ} آسہِ۔\n25.\\tتہٕ شمعون سٕندِس سرحدس سٍتـ̡ مشرق کہِ طرفہٕ مغرب کُن اِساکرُک اکھ {حصہ}۔\n26.\\tتہٕ اِساکار کِس سرحدس نِش مشرِق طرفہٕ مغرب کُن زبولُن اکھ {حصہ}۔\n27. تہٕ زبولون کِس سرحدس پیٹھ، مشرقہٕ پیٹھہٕ مغرب کُن گاڈ اکھ {حصہ}۔\n28.\\tتہٕ گاڈ کِس سرحدس سٍتـ̡ جنوبس کُن آسہِ سرحد تامار پیٹھہٕ کشمکش کِس آبس تام، {تہٕ} دریاوس تام عظیم سمندرس کُن۔ {جھگڑ...: یا، میری بہکادیش}\n29.\\tیہِ چھُ سُہ زمین یُس تُہۍ وراثتس مۅکھہٕ اسرٲیلِس قبیلن مَنٛز قرعہ اندازی کٔرِو، تہٕ یِم چھِ تِہُند حصہٕ، خداوند خدا چُھ فرماوان۔\n30.\\tتہٕ یِم چھِ شُمالہٕ کُن شہرٕ نیبر نیران، ژور ساس پانژھ ہتھ پیمانہٕ۔\n31.\\tتہٕ شہرٕکۍ دروازٕ گژھن اسرٲیلٕکۍ قبیلن ہٕندِس ناون پٲٹھۍ: تریہ دروازٕ شمالس کُن۔ روبن سُند اکھ دروازٕ، یہوداہُک اکھ دروازٕ، لاوی سُند اکھ دروازٕ۔\n32. تہٕ مشرقس طرفہٕ ژور ساس پانژھ ہتھ: تہٕ ترے دروازٕ۔ تہٕ یوسف سُند اکھ دروازٕ، بنیامین سُند اکھ دروازٕ، دانن سُند اکھ دروازٕ۔\n33.\\tتہٕ جنوبس طرفہٕ ژور ساس پانژھ ہتھ پیمانہٕ: تہٕ تریہ دروازٕ۔ شمعون سُند اکھ دروازٕ، اِساکرُک اکھ دروازٕ، زبولُن سُند اکھ دروازٕ۔\n34.\\tمغرب طرفہٕ ژور ساس پانژھ ہتھ، تہندِ تریہ دروازہٕ۔ گاڈُک اکھ دروازٕ، آشرُک اکھ دروازٕ، نفتالی ہُند اکھ دروازٕ۔\n35.\\t{یہ اوس} لگ بھگ ارداہ ساس {پیمائش}: تہٕ شہرُک ناو {تمہِ دۅہہ} پیٹھ، خداوند {چُھ} تتہِ۔ {خداوند...: ہیب۔ یہوواہشمہ}"];
